window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["同音異義語"]={
"_note": "04. 同音異義語 — mỗi nhóm so sánh một dòng. ĐỊNH DẠNG MỖI NHÓM: label, note, items [word, reading, meaning, example, example_reading, example_meaning, examples]. TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: 200 nhóm / 528 từ.",
"id": "4. 同音異義語",
"title": "同音異義語",
"icon": "🔀",
"category": "ref",
"kind": "compare",
"compare": [
{"label":"変わる／代わる／替わる","note":"変わる: trạng thái/tính chất TỰ thay đổi. 代わる: một NGƯỜI/VAI TRÒ thay thế cho người khác. 替わる: đổi CHỖ, luân phiên vị trí.","items":[{"word":"変わる","reading":"かわる","meaning":"thay đổi (trạng thái)","example":"信号が赤から青に変わった。","example_reading":"しんごうがあかからあおにかわった。","example_meaning":"Đèn tín hiệu đã chuyển từ đỏ sang xanh.","examples":[{"example":"町の様子がすっかり変わりました。","example_reading":"まちのようすがすっかりかわりました。","example_meaning":"cảnh tượng của thị trấn đã thay đổi hoàn toàn."},{"example":"秋になると、葉の色が変わります。","example_reading":"あきになると、はのいろがかわります。","example_meaning":"Cứ đến mùa thu là màu lá lại đổi."}]},{"word":"代わる","reading":"かわる","meaning":"thay thế (vai trò, người)","example":"部長の代わりに私が出席します。","example_reading":"ぶちょうのかわりにわたしがしゅっせきします。","example_meaning":"Tôi sẽ tham dự thay cho trưởng phòng.","examples":[{"example":"病気の先生に代わって、山田先生が授業をします。","example_reading":"びょうきのせんせいにかわって、やまだせんせいがじゅぎょうをします。","example_meaning":"Thầy Yamada dạy thay cho thầy giáo bị bệnh."},{"example":"今日は母に代わって、私が夕飯を作ります。","example_reading":"きょうははにかわって、わたしがゆうはんをつくります。","example_meaning":"Hôm nay con nấu cơm tối thay mẹ."}]},{"word":"替わる","reading":"かわる","meaning":"đổi chỗ, luân phiên","example":"電池が新しいものに替わった。","example_reading":"でんちがあたらしいものにかわった。","example_meaning":"Pin đã được thay bằng cái mới.","examples":[{"example":"席が替わって、窓の近くに座りました。","example_reading":"せきがかわって、まどのちかくにすわりました。","example_meaning":"Đổi chỗ ngồi nên tôi ngồi gần cửa sổ."},{"example":"運転手が途中で替わりました。","example_reading":"うんてんしゅがとちゅうでかわりました。","example_meaning":"Tài xế đã đổi người giữa đường."}]}]},
{"label":"空く／開く／明く","note":"空く(あく): trở nên TRỐNG, RẢNH (chỗ trống, thời gian rảnh). 開く(あく): MỞ ra (cửa, cửa hàng). 明く(あく): hiếm dùng, nghĩa 'sáng tỏ ra' (thường viết là 開く trong thực tế).","items":[{"word":"空く","reading":"あく","meaning":"trống, rảnh","example":"席が空きました。","example_reading":"せきがあきました。","example_meaning":"Chỗ ngồi đã trống.","examples":[{"example":"電車が空いていたので、座れました。","example_reading":"でんしゃがすいていたので、すわれました。","example_meaning":"Tàu điện vắng nên tôi đã ngồi được."},{"example":"明日の午後は手が空いています。","example_reading":"あしたのごごはてがあいています。","example_meaning":"Chiều mai tôi rảnh tay."}]},{"word":"開く","reading":"あく","meaning":"mở ra","example":"店が九時に開きます。","example_reading":"みせがくじにあきます。","example_meaning":"Cửa hàng mở cửa lúc 9 giờ.","examples":[{"example":"ドアが急に開いて、びっくりしました。","example_reading":"どあがきゅうにあいて、びっくりしました。","example_meaning":"Cửa đột nhiên mở ra làm tôi giật mình."},{"example":"図書館は何時に開きますか。","example_reading":"としょかんはなんじにあきますか。","example_meaning":"Thư viện mở cửa lúc mấy giờ?"}]},{"word":"明く","reading":"あく","meaning":"sáng tỏ, mở (cách viết cũ, ít dùng)","example":"目が明かない赤ちゃん。","example_reading":"めがあかないあかちゃん。","example_meaning":"Em bé chưa mở được mắt.","examples":[{"example":"子猫の目がやっと明きました。","example_reading":"こねこのめがやっとあきました。","example_meaning":"Mắt của mèo con cuối cùng cũng đã mở ra."},{"example":"生まれて数日たつと、子犬の目が明きます。","example_reading":"うまれてすうじつたつと、こいぬのめがあきます。","example_meaning":"Sau khi sinh vài ngày thì mắt chó con mở ra."}]}]},
{"label":"熱い／暑い／厚い","note":"熱い(あつい): NÓNG khi sờ vào (đồ vật, nước). 暑い(あつい): NÓNG (thời tiết, không khí). 厚い(あつい): DÀY (vật thể) hoặc sâu sắc (tình cảm).","items":[{"word":"熱い","reading":"あつい","meaning":"nóng (sờ vào)","example":"このお茶は熱いです。","example_reading":"このおちゃはあついです。","example_meaning":"Trà này nóng.","examples":[{"example":"熱いお風呂に入ると、気持ちがいいです。","example_reading":"あついおふろにはいると、きもちがいいです。","example_meaning":"Ngâm mình trong bồn tắm nóng thì thấy dễ chịu."},{"example":"このスープは熱いので、気をつけてください。","example_reading":"このすーぷはあついので、きをつけてください。","example_meaning":"Món súp này nóng nên hãy cẩn thận."}]},{"word":"暑い","reading":"あつい","meaning":"nóng (thời tiết)","example":"今日はとても暑いです。","example_reading":"きょうはとてもあついです。","example_meaning":"Hôm nay trời rất nóng.","examples":[{"example":"夏の東京はむし暑いです。","example_reading":"なつのとうきょうはむしあついです。","example_meaning":"Mùa hè ở Tokyo nóng và oi bức."},{"example":"暑いので、窓を開けてもいいですか。","example_reading":"あついので、まどをあけてもいいですか。","example_meaning":"Trời nóng nên tôi mở cửa sổ được không?"}]},{"word":"厚い","reading":"あつい","meaning":"dày","example":"この本は厚いです。","example_reading":"このほんはあついです。","example_meaning":"Cuốn sách này dày.","examples":[{"example":"寒いので、厚いコートを着ます。","example_reading":"さむいので、あついこーとをきます。","example_meaning":"Trời lạnh nên tôi mặc áo khoác dày."},{"example":"厚く切ったパンにバターをぬります。","example_reading":"あつくきったぱんにばたーをぬります。","example_meaning":"Tôi phết bơ lên lát bánh mì cắt dày."}]}]},
{"label":"早い／速い","note":"早い(はやい): SỚM về mặt THỜI GIAN. 速い(はやい): NHANH về mặt TỐC ĐỘ.","items":[{"word":"早い","reading":"はやい","meaning":"sớm (thời gian)","example":"今日は早く起きました。","example_reading":"きょうははやくおきました。","example_meaning":"Hôm nay tôi dậy sớm.","examples":[{"example":"明日は朝が早いので、もう寝ます。","example_reading":"あしたはあさがはやいので、もうねます。","example_meaning":"Mai phải dậy sớm nên tôi đi ngủ đây."},{"example":"あきらめるのはまだ早いですよ。","example_reading":"あきらめるのはまだはやいですよ。","example_meaning":"Bỏ cuộc thì vẫn còn sớm đấy."}]},{"word":"速い","reading":"はやい","meaning":"nhanh (tốc độ)","example":"彼は走るのが速いです。","example_reading":"かれははしるのがはやいです。","example_meaning":"Anh ấy chạy rất nhanh.","examples":[{"example":"新幹線はとても速い電車です。","example_reading":"しんかんせんはとてもはやいでんしゃです。","example_meaning":"Shinkansen là tàu điện rất nhanh."},{"example":"この川は流れが速いので、危ないです。","example_reading":"このかわはながれがはやいので、あぶないです。","example_meaning":"Dòng sông này chảy xiết nên nguy hiểm."}]}]},
{"label":"聞く／聴く／効く／利く","note":"聞く(きく): NGHE, HỎI (thông thường). 聴く(きく): LẮNG NGHE chăm chú (nhạc). 効く(きく): CÓ TÁC DỤNG (thuốc). 利く(きく): CÓ HIỆU LỰC, hoạt động tốt (giác quan, phanh).","items":[{"word":"聞く","reading":"きく","meaning":"nghe, hỏi","example":"音楽を聞きます。","example_reading":"おんがくをききます。","example_meaning":"Tôi nghe nhạc.","examples":[{"example":"駅への行き方を人に聞きました。","example_reading":"えきへのいきかたをひとにききました。","example_meaning":"Tôi đã hỏi người ta đường đến ga."},{"example":"隣の部屋から変な音が聞こえます。","example_reading":"となりのへやからへんなおとがきこえます。","example_meaning":"Có tiếng động lạ vọng ra từ phòng bên cạnh."}]},{"word":"聴く","reading":"きく","meaning":"lắng nghe chăm chú","example":"クラシック音楽を聴きます。","example_reading":"くらしっくおんがくをききます。","example_meaning":"Tôi lắng nghe nhạc cổ điển.","examples":[{"example":"毎晩、ゆっくりジャズを聴きます。","example_reading":"まいばん、ゆっくりじゃずをききます。","example_meaning":"Mỗi tối tôi thong thả nghe nhạc jazz."},{"example":"コンサートで好きな歌手の歌を聴きました。","example_reading":"こんさーとですきなかしゅのうたをききました。","example_meaning":"Tôi đã nghe ca sĩ yêu thích hát ở buổi hòa nhạc."}]},{"word":"効く","reading":"きく","meaning":"có tác dụng (thuốc)","example":"この薬はよく効きます。","example_reading":"このくすりはよくききます。","example_meaning":"Thuốc này rất có tác dụng.","examples":[{"example":"頭が痛かったけど、薬が効いて楽になりました。","example_reading":"あたまがいたかったけど、くすりがきいてらくになりました。","example_meaning":"Tôi bị đau đầu nhưng thuốc có tác dụng nên đỡ rồi."},{"example":"この湿布は肩こりによく効きます。","example_reading":"このしっぷはかたこりによくききます。","example_meaning":"Miếng dán này rất hiệu quả với chứng mỏi vai."}]},{"word":"利く","reading":"きく","meaning":"hoạt động tốt, có hiệu lực","example":"鼻が利かなくなりました。","example_reading":"はながきかなくなりました。","example_meaning":"Mũi tôi không còn ngửi được nữa.","examples":[{"example":"自転車のブレーキが利かなくて、怖かったです。","example_reading":"じてんしゃのぶれーきがきかなくて、こわかったです。","example_meaning":"Phanh xe đạp không ăn nên tôi đã rất sợ."},{"example":"この店では、常連客は融通が利きます。","example_reading":"このみせでは、じょうれんきゃくはゆうずうがききます。","example_meaning":"Ở tiệm này, khách quen được châm chước linh hoạt."}]}]},
{"label":"見る／観る／診る","note":"見る(みる): NHÌN, XEM thông thường. 観る(みる): XEM có chủ đích thưởng thức (phim, kịch). 診る(みる): KHÁM (bệnh).","items":[{"word":"見る","reading":"みる","meaning":"nhìn, xem","example":"景色を見ます。","example_reading":"けしきをみます。","example_meaning":"Tôi ngắm phong cảnh.","examples":[{"example":"窓から外の雪を見ました。","example_reading":"まどからそとのゆきをみました。","example_meaning":"Tôi nhìn tuyết bên ngoài qua cửa sổ."},{"example":"この写真を見てください。","example_reading":"このしゃしんをみてください。","example_meaning":"Xin hãy xem bức ảnh này."}]},{"word":"観る","reading":"みる","meaning":"xem (thưởng thức)","example":"映画を観ます。","example_reading":"えいがをみます。","example_meaning":"Tôi xem phim.","examples":[{"example":"週末に友達と劇を観に行きます。","example_reading":"しゅうまつにともだちとげきをみにいきます。","example_meaning":"Cuối tuần tôi đi xem kịch với bạn."},{"example":"サッカーの試合をスタジアムで観ました。","example_reading":"さっかーのしあいをすたじあむでみました。","example_meaning":"Tôi đã xem trận bóng đá ở sân vận động."}]},{"word":"診る","reading":"みる","meaning":"khám bệnh","example":"医者に診てもらいます。","example_reading":"いしゃにみてもらいます。","example_meaning":"Tôi được bác sĩ khám.","examples":[{"example":"先生は一日に五十人の患者を診ます。","example_reading":"せんせいはいちにちにごじゅうにんのかんじゃをみます。","example_meaning":"Bác sĩ khám cho năm mươi bệnh nhân mỗi ngày."},{"example":"熱があるので、病院で診てもらいました。","example_reading":"ねつがあるので、びょういんでみてもらいました。","example_meaning":"Vì bị sốt nên tôi đã đến bệnh viện khám."}]}]},
{"label":"直す／治す","note":"直す(なおす): SỬA CHỮA đồ vật, sửa lỗi. 治す(なおす): CHỮA KHỎI bệnh.","items":[{"word":"直す","reading":"なおす","meaning":"sửa chữa","example":"パソコンを直します。","example_reading":"ぱそこんをなおします。","example_meaning":"Tôi sửa máy tính.","examples":[{"example":"壊れた自転車を父が直してくれました。","example_reading":"こわれたじてんしゃをちちがなおしてくれました。","example_meaning":"Bố đã sửa giúp tôi chiếc xe đạp bị hỏng."},{"example":"作文の間違いを直してください。","example_reading":"さくぶんのまちがいをなおしてください。","example_meaning":"Hãy sửa lỗi sai trong bài văn."}]},{"word":"治す","reading":"なおす","meaning":"chữa khỏi bệnh","example":"風邪を治します。","example_reading":"かぜをなおします。","example_meaning":"Tôi chữa khỏi cảm cúm.","examples":[{"example":"早く病気を治して、学校に行きたいです。","example_reading":"はやくびょうきをなおして、がっこうにいきたいです。","example_meaning":"Tôi muốn mau chữa khỏi bệnh để đi học."},{"example":"ゆっくり休んで、けがを治しましょう。","example_reading":"ゆっくりやすんで、けがをなおしましょう。","example_meaning":"Hãy nghỉ ngơi thong thả để chữa lành vết thương."}]}]},
{"label":"作る／創る／造る","note":"作る(つくる): LÀM ra (thông thường, phổ biến nhất). 創る(つくる): SÁNG TẠO ra cái mới (mang tính nghệ thuật). 造る(つくる): CHẾ TẠO quy mô lớn (nhà máy, tàu, rượu).","items":[{"word":"作る","reading":"つくる","meaning":"làm, chế tạo (thông thường)","example":"料理を作ります。","example_reading":"りょうりをつくります。","example_meaning":"Tôi nấu ăn.","examples":[{"example":"母と一緒にケーキを作りました。","example_reading":"はははといっしょにけーきをつくりました。","example_meaning":"Tôi đã làm bánh kem cùng mẹ."},{"example":"友達をたくさん作りたいです。","example_reading":"ともだちをたくさんつくりたいです。","example_meaning":"Tôi muốn kết thật nhiều bạn."}]},{"word":"創る","reading":"つくる","meaning":"sáng tạo ra","example":"新しい文化を創ります。","example_reading":"あたらしいぶんかをつくります。","example_meaning":"Tạo ra một nền văn hóa mới.","examples":[{"example":"若い人たちが新しい音楽を創っています。","example_reading":"わかいひとたちがあたらしいおんがくをつくっています。","example_meaning":"Những người trẻ đang sáng tạo ra âm nhạc mới."},{"example":"自分の力で未来を創りたいです。","example_reading":"じぶんのちからでみらいをつくりたいです。","example_meaning":"Tôi muốn tự sức mình tạo dựng tương lai."}]},{"word":"造る","reading":"つくる","meaning":"chế tạo quy mô lớn","example":"船を造ります。","example_reading":"ふねをつくります。","example_meaning":"Người ta đóng tàu.","examples":[{"example":"この工場では大きな車を造っています。","example_reading":"このこうじょうではおおきなくるまをつくっています。","example_meaning":"Nhà máy này đang chế tạo những chiếc xe lớn."},{"example":"お酒を造る会社で働いています。","example_reading":"おさけをつくるかいしゃではたらいています。","example_meaning":"Tôi làm việc ở công ty sản xuất rượu."}]}]},
{"label":"上る／登る／昇る","note":"上る(のぼる): ĐI LÊN nói chung (bậc thang, dòng sông ngược lên). 登る(のぼる): TRÈO LÊN (núi, cây - cần dùng sức). 昇る(のぼる): MỌC LÊN, THĂNG (mặt trời, chức vụ).","items":[{"word":"上る","reading":"のぼる","meaning":"đi lên (nói chung)","example":"階段を上ります。","example_reading":"かいだんをのぼります。","example_meaning":"Tôi đi lên cầu thang.","examples":[{"example":"坂道をゆっくり上りました。","example_reading":"さかみちをゆっくりのぼりました。","example_meaning":"Tôi đã đi chậm lên con dốc."},{"example":"二階に上って、荷物を置きます。","example_reading":"にかいにのぼって、にもつをおきます。","example_meaning":"Tôi lên tầng hai để đặt đồ."}]},{"word":"登る","reading":"のぼる","meaning":"trèo lên (núi, cây)","example":"山に登ります。","example_reading":"やまにのぼります。","example_meaning":"Tôi leo núi.","examples":[{"example":"夏休みに家族で富士山に登りました。","example_reading":"なつやすみにかぞくでふじさんにのぼりました。","example_meaning":"Kỳ nghỉ hè cả nhà tôi đã leo núi Phú Sĩ."},{"example":"子供が木に登って、降りられなくなりました。","example_reading":"こどもがきにのぼって、おりられなくなりました。","example_meaning":"Đứa trẻ trèo lên cây rồi không xuống được."}]},{"word":"昇る","reading":"のぼる","meaning":"mọc lên, thăng chức","example":"太陽が昇ります。","example_reading":"たいようがのぼります。","example_meaning":"Mặt trời mọc lên.","examples":[{"example":"初日の出が山の向こうから昇ります。","example_reading":"はつひのでがやまのむこうからのぼります。","example_meaning":"Mặt trời đầu năm mọc lên từ phía sau ngọn núi."},{"example":"彼は三年で課長に昇りました。","example_reading":"かれはさんねんでかちょうにのぼりました。","example_meaning":"Anh ấy được thăng lên trưởng phòng sau ba năm."}]}]},
{"label":"会う／合う／遭う","note":"会う(あう): GẶP người. 合う(あう): PHÙ HỢP, KHỚP (kích cỡ, ý kiến). 遭う(あう): GẶP PHẢI việc không may (tai nạn, gặp mưa).","items":[{"word":"会う","reading":"あう","meaning":"gặp (người)","example":"友達に会います。","example_reading":"ともだちにあいます。","example_meaning":"Tôi gặp bạn.","examples":[{"example":"明日、駅で田中さんに会います。","example_reading":"あした、えきでたなかさんにあいます。","example_meaning":"Ngày mai tôi sẽ gặp anh Tanaka ở ga."},{"example":"久しぶりに高校の友達に会いました。","example_reading":"ひさしぶりにこうこうのともだちにあいました。","example_meaning":"Lâu lắm rồi tôi mới gặp lại bạn cấp ba."}]},{"word":"合う","reading":"あう","meaning":"phù hợp, khớp","example":"サイズが合います。","example_reading":"さいずがあいます。","example_meaning":"Kích cỡ vừa vặn.","examples":[{"example":"この靴は足にぴったり合います。","example_reading":"このくつはあしにぴったりあいます。","example_meaning":"Đôi giày này vừa khít với chân tôi."},{"example":"時計の時間が合っていません。","example_reading":"とけいのじかんがあっていません。","example_meaning":"Giờ trên đồng hồ không khớp."}]},{"word":"遭う","reading":"あう","meaning":"gặp phải (việc không may)","example":"事故に遭いました。","example_reading":"じこにあいました。","example_meaning":"Tôi đã gặp phải tai nạn.","examples":[{"example":"帰り道で、急に雨に遭いました。","example_reading":"かえりみちで、きゅうにあめにあいました。","example_meaning":"Trên đường về tôi bị mắc mưa bất ngờ."},{"example":"旅行中にどろぼうに遭って、困りました。","example_reading":"りょこうちゅうにどろぼうにあって、こまりました。","example_meaning":"Trong chuyến du lịch tôi gặp trộm nên rất khổ sở."}]}]},
{"label":"収める／納める／治める／修める","note":"収める(おさめる): THU LẠI, đạt được (thành công, lợi nhuận). 納める(おさめる): NỘP (tiền, thuế). 治める(おさめる): CAI TRỊ, quản lý (đất nước, tổ chức). 修める(おさめる): TU DƯỠNG, học tập hoàn thiện.","items":[{"word":"収める","reading":"おさめる","meaning":"thu được, đạt được","example":"成功を収めました。","example_reading":"せいこうをおさめました。","example_meaning":"Đã đạt được thành công.","examples":[{"example":"その映画は大きな成功を収めました。","example_reading":"そのえいがはおおきなせいこうをおさめました。","example_meaning":"Bộ phim đó đã gặt hái thành công lớn."},{"example":"本を箱に収めて、押し入れにしまいます。","example_reading":"ほんをはこにおさめて、おしいれにしまいます。","example_meaning":"Tôi cho sách vào hộp rồi cất vào tủ âm tường."}]},{"word":"納める","reading":"おさめる","meaning":"nộp (tiền, thuế)","example":"税金を納めます。","example_reading":"ぜいきんをおさめます。","example_meaning":"Tôi nộp thuế.","examples":[{"example":"毎月、家賃を大家さんに納めます。","example_reading":"まいつき、やちんをおおやさんにおさめます。","example_meaning":"Mỗi tháng tôi nộp tiền nhà cho chủ nhà."},{"example":"できた商品を、お客さんに納めに行きます。","example_reading":"できたしょうひんを、おきゃくさんにおさめにいきます。","example_meaning":"Tôi đi giao hàng đã làm xong cho khách."}]},{"word":"治める","reading":"おさめる","meaning":"cai trị, quản lý","example":"国を治めます。","example_reading":"くにをおさめます。","example_meaning":"Cai trị đất nước.","examples":[{"example":"昔、この町は一人の王様が治めていました。","example_reading":"むかし、このまちはひとりのおうさまがおさめていました。","example_meaning":"Ngày xưa thị trấn này do một vị vua cai trị."},{"example":"市長は町をうまく治めています。","example_reading":"しちょうはまちをうまくおさめています。","example_meaning":"Thị trưởng quản lý thị trấn rất tốt."}]},{"word":"修める","reading":"おさめる","meaning":"tu dưỡng, học hoàn thiện","example":"学問を修めます。","example_reading":"がくもんをおさめます。","example_meaning":"Tu dưỡng học vấn.","examples":[{"example":"彼は大学で経済学を修めました。","example_reading":"かれはだいがくでけいざいがくをおさめました。","example_meaning":"Anh ấy đã học xong ngành kinh tế ở đại học."},{"example":"若い時に礼儀作法を修めておくと、役に立ちます。","example_reading":"わかいときにれいぎさほうをおさめておくと、やくにたちます。","example_meaning":"Học lễ nghi từ khi còn trẻ sẽ có ích."}]}]},
{"label":"移す／写す／映す","note":"移す(うつす): DI CHUYỂN, chuyển vị trí. 写す(うつす): SAO CHÉP, CHỤP (ảnh, chép bài). 映す(うつす): PHẢN CHIẾU, CHIẾU lên (gương, màn hình).","items":[{"word":"移す","reading":"うつす","meaning":"di chuyển, chuyển","example":"荷物を隣の部屋に移します。","example_reading":"にもつをとなりのへやにうつします。","example_meaning":"Chuyển đồ sang phòng bên cạnh.","examples":[{"example":"花を庭からベランダに移しました。","example_reading":"はなをにわからべらんだにうつしました。","example_meaning":"Tôi đã chuyển chậu hoa từ vườn ra ban công."},{"example":"会社は事務所を新しいビルに移します。","example_reading":"かいしゃはじむしょをあたらしいびるにうつします。","example_meaning":"Công ty sẽ chuyển văn phòng sang tòa nhà mới."}]},{"word":"写す","reading":"うつす","meaning":"sao chép, chụp","example":"ノートを写します。","example_reading":"のーとをうつします。","example_meaning":"Tôi chép lại vở.","examples":[{"example":"黒板の字をノートに写しました。","example_reading":"こくばんのじをのーとにうつしました。","example_meaning":"Tôi đã chép chữ trên bảng vào vở."},{"example":"旅行で、きれいな景色の写真を写しました。","example_reading":"りょこうで、きれいなけしきのしゃしんをうつしました。","example_meaning":"Trong chuyến du lịch tôi đã chụp ảnh phong cảnh đẹp."}]},{"word":"映す","reading":"うつす","meaning":"phản chiếu, chiếu","example":"鏡に顔を映します。","example_reading":"かがみにかおをうつします。","example_meaning":"Soi mặt vào gương.","examples":[{"example":"プロジェクターで資料をスクリーンに映します。","example_reading":"ぷろじぇくたーでしりょうをすくりーんにうつします。","example_meaning":"Tôi chiếu tài liệu lên màn hình bằng máy chiếu."},{"example":"湖が青い空を映しています。","example_reading":"みずうみがあおいそらをうつしています。","example_meaning":"Mặt hồ phản chiếu bầu trời xanh."}]}]},
{"label":"図る／計る／測る／量る","note":"図る(はかる): MƯU CẦU, hoạch định (giải quyết, mưu tính). 計る(はかる): ĐO THỜI GIAN, đếm số. 測る(はかる): ĐO KÍCH THƯỚC, khoảng cách, độ cao. 量る(はかる): ĐO KHỐI LƯỢNG, cân nặng.","items":[{"word":"図る","reading":"はかる","meaning":"mưu cầu, hoạch định","example":"解決を図ります。","example_reading":"かいけつをはかります。","example_meaning":"Mưu cầu giải quyết vấn đề.","examples":[{"example":"会社は経費の削減を図っています。","example_reading":"かいしゃはけいひのさくげんをはかっています。","example_meaning":"Công ty đang tìm cách cắt giảm chi phí."},{"example":"彼は自分だけの利益を図る人です。","example_reading":"かれはじぶんだけのりえきをはかるひとです。","example_meaning":"Anh ta là người chỉ mưu cầu lợi ích cho riêng mình."}]},{"word":"計る","reading":"はかる","meaning":"đo thời gian, đếm","example":"時間を計ります。","example_reading":"じかんをはかります。","example_meaning":"Đo thời gian.","examples":[{"example":"ストップウォッチで走る時間を計ります。","example_reading":"すとっぷうぉっちではしるじかんをはかります。","example_meaning":"Tôi bấm đồng hồ để đo thời gian chạy."},{"example":"卵をゆでる時間を計って、タイマーをかけます。","example_reading":"たまごをゆでるじかんをはかって、たいまーをかけます。","example_meaning":"Tôi tính thời gian luộc trứng rồi đặt hẹn giờ."}]},{"word":"測る","reading":"はかる","meaning":"đo kích thước, khoảng cách","example":"距離を測ります。","example_reading":"きょりをはかります。","example_meaning":"Đo khoảng cách.","examples":[{"example":"メジャーで部屋の広さを測りました。","example_reading":"めじゃーでへやのひろさをはかりました。","example_meaning":"Tôi đã đo diện tích căn phòng bằng thước cuộn."},{"example":"保健室で身長を測ってもらいました。","example_reading":"ほけんしつでしんちょうをはかってもらいました。","example_meaning":"Tôi được đo chiều cao ở phòng y tế."}]},{"word":"量る","reading":"はかる","meaning":"đo khối lượng, cân","example":"重さを量ります。","example_reading":"おもさをはかります。","example_meaning":"Cân trọng lượng.","examples":[{"example":"お菓子を作るために、小麦粉を量ります。","example_reading":"おかしをつくるために、こむぎこをはかります。","example_meaning":"Tôi cân bột mì để làm bánh kẹo."},{"example":"郵便局で荷物の重さを量ってもらいました。","example_reading":"ゆうびんきょくでにもつのおもさをはかってもらいました。","example_meaning":"Tôi nhờ bưu điện cân giúp trọng lượng gói hàng."}]}]},
{"label":"説く／解く／溶く","note":"説く(とく): THUYẾT GIẢNG, giải thích đạo lý. 解く(とく): GIẢI (bài toán), tháo (nút thắt). 溶く(とく): HÒA TAN (bột, màu vào nước).","items":[{"word":"説く","reading":"とく","meaning":"thuyết giảng, giải thích","example":"道徳を説きます。","example_reading":"どうとくをときます。","example_meaning":"Thuyết giảng về đạo đức.","examples":[{"example":"お坊さんが人々に優しさの大切さを説きます。","example_reading":"おぼうさんがひとびとにやさしさのたいせつさをといます。","example_meaning":"Nhà sư thuyết giảng cho mọi người về tầm quan trọng của lòng tốt."},{"example":"先生は環境を守る必要性を説きました。","example_reading":"せんせいはかんきょうをまもるひつようせいをときました。","example_meaning":"Thầy đã giảng giải về sự cần thiết của việc bảo vệ môi trường."}]},{"word":"解く","reading":"とく","meaning":"giải (bài toán), tháo","example":"問題を解きます。","example_reading":"もんだいをときます。","example_meaning":"Tôi giải bài toán.","examples":[{"example":"試験で難しいなぞなぞを解きました。","example_reading":"しけんでむずかしいなぞなぞをときました。","example_meaning":"Tôi đã giải câu đố khó trong bài thi."},{"example":"靴のひもを解いて、靴を脱ぎます。","example_reading":"くつのひもをといて、くつをぬぎます。","example_meaning":"Tôi cởi dây giày rồi tháo giày ra."}]},{"word":"溶く","reading":"とく","meaning":"hòa tan","example":"絵の具を水で溶きます。","example_reading":"えのぐをみずでときます。","example_meaning":"Hòa màu vẽ với nước.","examples":[{"example":"ボウルに卵を溶いて、砂糖を入れます。","example_reading":"ぼうるにたまごをといて、さとうをいれます。","example_meaning":"Đánh tan trứng trong tô rồi cho đường vào."},{"example":"粉を水で溶いて、生地を作ります。","example_reading":"こなをみずでといて、きじをつくります。","example_meaning":"Hòa bột với nước để làm bột nhào."}]}]},
{"label":"勧める／薦める／進める","note":"勧める(すすめる): KHUYÊN, khuyến khích ai làm gì. 薦める(すすめる): GIỚI THIỆU, tiến cử (sách, người). 進める(すすめる): TIẾN HÀNH, đẩy tới (công việc, kế hoạch).","items":[{"word":"勧める","reading":"すすめる","meaning":"khuyên, khuyến khích","example":"運動を勧めます。","example_reading":"うんどうをすすめます。","example_meaning":"Khuyên nên tập thể dục.","examples":[{"example":"医者は私に禁煙を勧めました。","example_reading":"いしゃはわたしにきんえんをすすめました。","example_meaning":"Bác sĩ khuyên tôi bỏ thuốc lá."},{"example":"友達にお茶を勧められて、一杯いただきました。","example_reading":"ともだちにおちゃをすすめられて、いっぱいいただきました。","example_meaning":"Bạn mời trà nên tôi đã uống một tách."}]},{"word":"薦める","reading":"すすめる","meaning":"giới thiệu, tiến cử","example":"この本を薦めます。","example_reading":"このほんをすすめます。","example_meaning":"Giới thiệu cuốn sách này.","examples":[{"example":"先生は私をこの大学に薦めてくれました。","example_reading":"せんせいはわたしをこのだいがくにすすめてくれました。","example_meaning":"Thầy đã tiến cử tôi vào trường đại học này."},{"example":"おもしろい映画を友達に薦めました。","example_reading":"おもしろいえいがをともだちにすすめました。","example_meaning":"Tôi đã giới thiệu bộ phim hay cho bạn."}]},{"word":"進める","reading":"すすめる","meaning":"tiến hành, đẩy tới","example":"計画を進めます。","example_reading":"けいかくをすすめます。","example_meaning":"Tiến hành kế hoạch.","examples":[{"example":"会議を予定どおりに進めましょう。","example_reading":"かいぎをよていどおりにすすめましょう。","example_meaning":"Hãy tiến hành cuộc họp đúng như dự định."},{"example":"時計を十分進めておきました。","example_reading":"とけいをじゅっぷんすすめておきました。","example_meaning":"Tôi đã vặn đồng hồ nhanh lên mười phút."}]}]},
{"label":"掛ける／欠ける／駆ける","note":"掛ける(かける): TREO, gọi (điện thoại), ngồi xuống — nghĩa rất rộng. 欠ける(かける): THIẾU, SỨT MẺ. 駆ける(かける): CHẠY NHANH (như phi nước đại).","items":[{"word":"掛ける","reading":"かける","meaning":"treo, gọi (điện), ngồi","example":"電話を掛けます。","example_reading":"でんわをかけます。","example_meaning":"Tôi gọi điện thoại.","examples":[{"example":"壁に絵を掛けました。","example_reading":"かべにえをかけました。","example_meaning":"Tôi đã treo bức tranh lên tường."},{"example":"出かける前に、ドアに鍵を掛けます。","example_reading":"でかけるまえに、どあにかぎをかけます。","example_meaning":"Trước khi ra ngoài tôi khóa cửa lại."}]},{"word":"欠ける","reading":"かける","meaning":"thiếu, sứt mẻ","example":"お皿が欠けました。","example_reading":"おさらがかけました。","example_meaning":"Cái đĩa đã bị sứt.","examples":[{"example":"コップの縁が少し欠けています。","example_reading":"こっぷのふちがすこしかけています。","example_meaning":"Miệng cốc bị sứt một chút."},{"example":"この計画には、大切なものが欠けています。","example_reading":"このけいかくには、たいせつなものがかけています。","example_meaning":"Kế hoạch này còn thiếu một thứ quan trọng."}]},{"word":"駆ける","reading":"かける","meaning":"chạy nhanh","example":"馬が駆けます。","example_reading":"うまがかけます。","example_meaning":"Con ngựa phi nhanh.","examples":[{"example":"子供たちが野原を駆けていきます。","example_reading":"こどもたちがのはらをかけていきます。","example_meaning":"Bọn trẻ chạy băng băng qua cánh đồng."},{"example":"彼は急いで階段を駆け上がりました。","example_reading":"かれはいそいでかいだんをかけあがりました。","example_meaning":"Anh ấy vội vã chạy lên cầu thang."}]}]},
{"label":"破れる／敗れる","note":"破れる(やぶれる): RÁCH (giấy, vải, vật thể). 敗れる(やぶれる): THUA (trận đấu, thất bại).","items":[{"word":"破れる","reading":"やぶれる","meaning":"rách","example":"紙が破れました。","example_reading":"かみがやぶれました。","example_meaning":"Tờ giấy đã bị rách.","examples":[{"example":"ズボンが破れてしまいました。","example_reading":"ずぼんがやぶれてしまいました。","example_meaning":"Quần của tôi bị rách mất rồi."},{"example":"古い障子が破れたので、張りかえました。","example_reading":"ふるいしょうじがやぶれたので、はりかえました。","example_meaning":"Cửa giấy cũ bị rách nên tôi đã dán lại."}]},{"word":"敗れる","reading":"やぶれる","meaning":"thua (thi đấu)","example":"試合に敗れました。","example_reading":"しあいにやぶれました。","example_meaning":"Đã thua trận đấu.","examples":[{"example":"日本チームは決勝で敗れました。","example_reading":"にほんちーむはけっしょうでやぶれました。","example_meaning":"Đội Nhật Bản đã thua ở trận chung kết."},{"example":"選挙に敗れて、彼は政治をやめました。","example_reading":"せんきょにやぶれて、かれはせいじをやめました。","example_meaning":"Thua trong cuộc bầu cử, ông ấy đã giã từ chính trường."}]}]},
{"label":"空ける／開ける／明ける","note":"空ける(あける): LÀM TRỐNG (chỗ, thời gian). 開ける(あける): MỞ (cửa, nắp). 明ける(あける): SÁNG RA (trời sáng), KẾT THÚC (năm mới đến, hết kỳ nghỉ).","items":[{"word":"空ける","reading":"あける","meaning":"làm trống","example":"時間を空けます。","example_reading":"じかんをあけます。","example_meaning":"Sắp xếp thời gian trống.","examples":[{"example":"友達が来るので、部屋を空けておきます。","example_reading":"ともだちがくるので、へやをあけておきます。","example_meaning":"Vì bạn sẽ đến nên tôi để trống phòng sẵn."},{"example":"来週の金曜日を空けておいてください。","example_reading":"らいしゅうのきんようびをあけておいてください。","example_meaning":"Xin hãy để trống thứ Sáu tuần sau."}]},{"word":"開ける","reading":"あける","meaning":"mở","example":"窓を開けます。","example_reading":"まどをあけます。","example_meaning":"Tôi mở cửa sổ.","examples":[{"example":"プレゼントの箱を開けてみました。","example_reading":"ぷれぜんとのはこをあけてみました。","example_meaning":"Tôi đã thử mở hộp quà."},{"example":"暑いので、ドアを開けたままにします。","example_reading":"あついので、どあをあけたままにします。","example_meaning":"Trời nóng nên tôi để cửa mở."}]},{"word":"明ける","reading":"あける","meaning":"trời sáng ra, hết (năm, kỳ nghỉ)","example":"夜が明けます。","example_reading":"よがあけます。","example_meaning":"Trời sáng dần.","examples":[{"example":"新しい年が明けました。","example_reading":"あたらしいとしがあけました。","example_meaning":"Năm mới đã đến."},{"example":"梅雨が明けて、夏が始まりました。","example_reading":"つゆがあけて、なつがはじまりました。","example_meaning":"Mùa mưa đã kết thúc và mùa hè bắt đầu."}]}]},
{"label":"差す／刺す／指す","note":"差す(さす): CHE (ô), CHIẾU (ánh sáng). 刺す(さす): ĐÂM, CHÍCH. 指す(さす): CHỈ (tay), NHẮM ĐẾN.","items":[{"word":"差す","reading":"さす","meaning":"che (ô), chiếu (ánh sáng)","example":"傘を差します。","example_reading":"かさをさします。","example_meaning":"Che ô.","examples":[{"example":"雨が降ってきたので、傘を差しました。","example_reading":"あめがふってきたので、かさをさしました。","example_meaning":"Trời mưa nên tôi đã che ô."},{"example":"朝日が部屋に差し込んでいます。","example_reading":"あさひがへやにさしこんでいます。","example_meaning":"Ánh nắng ban mai chiếu vào phòng."}]},{"word":"刺す","reading":"さす","meaning":"đâm, chích","example":"蚊に刺されました。","example_reading":"かにさされました。","example_meaning":"Tôi bị muỗi chích.","examples":[{"example":"ハチに腕を刺されて、腫れました。","example_reading":"はちにうでをさされて、はれました。","example_meaning":"Tôi bị ong đốt vào tay nên bị sưng."},{"example":"魚にフォークを刺して食べます。","example_reading":"さかなにふぉーくをさしてたべます。","example_meaning":"Tôi ghim nĩa vào miếng cá rồi ăn."}]},{"word":"指す","reading":"さす","meaning":"chỉ tay, nhắm đến","example":"方向を指します。","example_reading":"ほうこうをさします。","example_meaning":"Chỉ hướng.","examples":[{"example":"時計の針は、ちょうど十二時を指しています。","example_reading":"とけいのはりは、ちょうどじゅうにじをさしています。","example_meaning":"Kim đồng hồ đang chỉ đúng mười hai giờ."},{"example":"私たちは優勝を指して、毎日練習しています。","example_reading":"わたしたちはゆうしょうをさして、まいにちれんしゅうしています。","example_meaning":"Chúng tôi luyện tập mỗi ngày nhắm tới chức vô địch."}]}]},
{"label":"暖かい／温かい","note":"暖かい: nhiệt độ không khí, thời tiết, căn phòng, quần áo ấm áp (ấm do khí hậu). 温かい: vật thể có thể chạm vào/ăn uống ấm (canh, tay) hoặc tình cảm ấm áp.","items":[{"word":"暖かい","reading":"あたたかい","meaning":"ấm (thời tiết, không khí)","example":"今日は暖かいですね。","example_reading":"きょうはあたたかいですね。","example_meaning":"Hôm nay trời ấm nhỉ.","examples":[{"example":"春になって、だんだん暖かくなりました。","example_reading":"はるになって、だんだんあたたかくなりました。","example_meaning":"Sang xuân, trời dần ấm lên."},{"example":"暖かい服を着て出かけます。","example_reading":"あたたかいふくをきてでかけます。","example_meaning":"Tôi mặc quần áo ấm rồi ra ngoài."}]},{"word":"温かい","reading":"あたたかい","meaning":"ấm (đồ ăn, vật; tình cảm)","example":"温かいスープを飲みました。","example_reading":"あたたかいスープをのみました。","example_meaning":"Tôi đã uống món súp nóng ấm.","examples":[{"example":"母の温かい手が好きです。","example_reading":"ははのあたたかいてがすきです。","example_meaning":"Tôi thích đôi bàn tay ấm áp của mẹ."},{"example":"この店は温かいご飯を出してくれます。","example_reading":"このみせはあたたかいごはんをだしてくれます。","example_meaning":"Quán này phục vụ cơm nóng ấm."}]}]},
{"label":"固い／硬い／堅い","note":"固い: chắc, rắn không dễ biến dạng; kiên quyết, cứng nhắc (約束, 決意, 握手). 硬い: cứng như vật liệu (đá, kim loại), vẻ mặt/văn phong cứng. 堅い: vững chắc, đáng tin, nghiêm túc (堅い仕事, 口が堅い).","items":[{"word":"固い","reading":"かたい","meaning":"chắc, rắn; vững chắc, kiên quyết","example":"このパンは固くて食べにくいです。","example_reading":"このパンはかたくてたべにくいです。","example_meaning":"Bánh mì này cứng nên khó ăn.","examples":[{"example":"二人は固く握手をしました。","example_reading":"ふたりはかたくあくしゅをしました。","example_meaning":"Hai người bắt tay thật chặt."},{"example":"固い約束を守ります。","example_reading":"かたいやくそくをまもります。","example_meaning":"Tôi sẽ giữ lời hứa chắc chắn."}]},{"word":"硬い","reading":"かたい","meaning":"cứng (vật liệu); cứng nhắc","example":"ダイヤモンドは世界で一番硬い物質です。","example_reading":"ダイヤモンドはせかいでいちばんかたいぶっしつです。","example_meaning":"Kim cương là chất cứng nhất thế giới.","examples":[{"example":"この石はとても硬いです。","example_reading":"このいしはとてもかたいです。","example_meaning":"Hòn đá này rất cứng."},{"example":"彼は硬い表情で話しました。","example_reading":"かれはかたいひょうじょうではなしました。","example_meaning":"Anh ấy nói với vẻ mặt cứng đờ."}]},{"word":"堅い","reading":"かたい","meaning":"vững chắc, đáng tin; nghiêm túc","example":"父は堅い会社で働いています。","example_reading":"ちちはかたいかいしゃではたらいています。","example_meaning":"Bố tôi làm ở một công ty vững chắc, ổn định.","examples":[{"example":"彼は口が堅いので、秘密を話しても大丈夫です。","example_reading":"かれはくちがかたいので、ひみつをはなしてもだいじょうぶです。","example_meaning":"Anh ấy kín miệng nên kể bí mật cũng không sao."},{"example":"彼は堅い人で、冗談を言いません。","example_reading":"かれはかたいひとで、じょうだんをいいません。","example_meaning":"Anh ấy là người nghiêm túc, không nói đùa."}]}]},
{"label":"柔らかい／軟らかい","note":"柔らかい: mềm mại nói chung (khăn, ánh sáng, giọng nói, thái độ). 軟らかい: mềm về mặt vật chất như thức ăn đã nấu, đất, thịt (đối lập với 硬い).","items":[{"word":"柔らかい","reading":"やわらかい","meaning":"mềm mại, dịu","example":"このタオルは柔らかくて気持ちがいいです。","example_reading":"このタオルはやわらかくてきもちがいいです。","example_meaning":"Chiếc khăn này mềm nên dùng rất dễ chịu.","examples":[{"example":"彼女は柔らかい声で話します。","example_reading":"かのじょはやわらかいこえではなします。","example_meaning":"Cô ấy nói bằng giọng dịu dàng."},{"example":"柔らかい日の光が部屋に入ってきました。","example_reading":"やわらかいひのひかりがへやにはいってきました。","example_meaning":"Ánh nắng dịu chiếu vào phòng."}]},{"word":"軟らかい","reading":"やわらかい","meaning":"mềm (thức ăn, đất)","example":"肉を煮て軟らかくしました。","example_reading":"にくをにてやわらかくしました。","example_meaning":"Tôi hầm thịt cho mềm.","examples":[{"example":"赤ちゃんには軟らかいご飯を食べさせます。","example_reading":"あかちゃんにはやわらかいごはんをたべさせます。","example_meaning":"Tôi cho em bé ăn cơm mềm."},{"example":"雨で土が軟らかくなりました。","example_reading":"あめでつちがやわらかくなりました。","example_meaning":"Vì mưa nên đất trở nên mềm."}]}]},
{"label":"帰る／返る","note":"帰る: trở về nơi vốn thuộc về (nhà, quê hương, nước). 返る: trở lại trạng thái ban đầu, được trả lại (我に返る, 初心に返る, 貸したものが返る).","items":[{"word":"帰る","reading":"かえる","meaning":"về (nhà, nước)","example":"六時に家に帰ります。","example_reading":"ろくじにいえにかえります。","example_meaning":"Tôi về nhà lúc 6 giờ.","examples":[{"example":"友達は国へ帰りました。","example_reading":"ともだちはくにへかえりました。","example_meaning":"Bạn tôi đã về nước."},{"example":"もう遅いから、帰りましょう。","example_reading":"もうおそいから、かえりましょう。","example_meaning":"Muộn rồi, chúng ta về thôi."}]},{"word":"返る","reading":"かえる","meaning":"trở lại, quay lại (trạng thái ban đầu); được trả lại","example":"貸したお金が返ってきました。","example_reading":"かしたおかねがかえってきました。","example_meaning":"Số tiền cho mượn đã được trả lại.","examples":[{"example":"大きな音で我に返りました。","example_reading":"おおきなおとでわれにかえりました。","example_meaning":"Tiếng động lớn khiến tôi sực tỉnh."},{"example":"初心に返って、もう一度勉強します。","example_reading":"しょしんにかえって、もういちどべんきょうします。","example_meaning":"Quay về tâm thế ban đầu, tôi sẽ học lại lần nữa."}]}]},
{"label":"変える／換える／替える／代える","note":"変える: thay đổi, làm cho khác đi (kế hoạch, màu sắc). 換える: đổi vật này lấy vật khác tương đương (đổi tiền, đổi không khí, đổi tàu). 替える: thay mới, thay thế cái cùng loại (pin, áo, nước). 代える: dùng cái này thay cho cái kia (命に代えても, 〜に代えて).","items":[{"word":"変える","reading":"かえる","meaning":"thay đổi","example":"計画を変えることにしました。","example_reading":"けいかくをかえることにしました。","example_meaning":"Tôi quyết định thay đổi kế hoạch.","examples":[{"example":"髪の色を変えました。","example_reading":"かみのいろをかえました。","example_meaning":"Tôi đã đổi màu tóc."},{"example":"部屋の雰囲気を変えたいです。","example_reading":"へやのふんいきをかえたいです。","example_meaning":"Tôi muốn thay đổi không khí căn phòng."}]},{"word":"換える","reading":"かえる","meaning":"đổi (tiền, không khí, phương tiện)","example":"空港で円をドルに換えました。","example_reading":"くうこうでえんをドルにかえました。","example_meaning":"Tôi đã đổi yên sang đô la ở sân bay.","examples":[{"example":"窓を開けて部屋の空気を換えます。","example_reading":"まどをあけてへやのくうきをかえます。","example_meaning":"Tôi mở cửa sổ để đổi không khí trong phòng."},{"example":"駅で電車を乗り換えます。","example_reading":"えきででんしゃをのりかえます。","example_meaning":"Tôi đổi tàu ở ga."}]},{"word":"替える","reading":"かえる","meaning":"thay (bằng cái mới cùng loại)","example":"電球を新しいものに替えました。","example_reading":"でんきゅうをあたらしいものにかえました。","example_meaning":"Tôi đã thay bóng đèn mới.","examples":[{"example":"汚れたシャツを替えてください。","example_reading":"よごれたシャツをかえてください。","example_meaning":"Hãy thay chiếc áo sơ mi bẩn đi."},{"example":"水槽の水を替えます。","example_reading":"すいそうのみずをかえます。","example_meaning":"Tôi thay nước trong bể cá."}]},{"word":"代える","reading":"かえる","meaning":"thay cho, đánh đổi bằng","example":"命に代えても家族を守ります。","example_reading":"いのちにかえてもかぞくをまもります。","example_meaning":"Dù phải đánh đổi mạng sống, tôi cũng bảo vệ gia đình.","examples":[{"example":"お礼の言葉に代えて、花を贈りました。","example_reading":"おれいのことばにかえて、はなをおくりました。","example_meaning":"Thay cho lời cảm ơn, tôi đã tặng hoa."},{"example":"メールで挨拶に代えます。","example_reading":"メールであいさつにかえます。","example_meaning":"Tôi xin thay lời chào bằng email."}]}]},
{"label":"勤める／務める／努める","note":"勤める: làm việc cho công ty/cơ quan (会社に勤める). 務める: đảm nhận vai trò, nhiệm vụ (司会, 主役, 委員長). 努める: cố gắng, nỗ lực làm việc gì (解決に努める).","items":[{"word":"勤める","reading":"つとめる","meaning":"làm việc (ở công ty, cơ quan)","example":"兄は銀行に勤めています。","example_reading":"あにはぎんこうにつとめています。","example_meaning":"Anh trai tôi làm ở ngân hàng.","examples":[{"example":"父は三十年、同じ会社に勤めています。","example_reading":"ちちはさんじゅうねん、おなじかいしゃにつとめています。","example_meaning":"Bố tôi làm ở cùng một công ty đã 30 năm."},{"example":"病院に勤めて五年になります。","example_reading":"びょういんにつとめてごねんになります。","example_meaning":"Tôi làm ở bệnh viện được 5 năm rồi."}]},{"word":"務める","reading":"つとめる","meaning":"đảm nhiệm (vai trò, nhiệm vụ)","example":"私が会議の司会を務めます。","example_reading":"わたしがかいぎのしかいをつとめます。","example_meaning":"Tôi sẽ làm người dẫn chương trình cuộc họp.","examples":[{"example":"彼は映画で主役を務めました。","example_reading":"かれはえいがでしゅやくをつとめました。","example_meaning":"Anh ấy đã đảm nhận vai chính trong phim."},{"example":"姉はクラスの委員長を務めています。","example_reading":"あねはクラスのいいんちょうをつとめています。","example_meaning":"Chị tôi đang làm lớp trưởng."}]},{"word":"努める","reading":"つとめる","meaning":"cố gắng, nỗ lực","example":"毎日、早く起きるように努めています。","example_reading":"まいにち、はやくおきるようにつとめています。","example_meaning":"Mỗi ngày tôi cố gắng dậy sớm.","examples":[{"example":"問題の解決に努めます。","example_reading":"もんだいのかいけつにつとめます。","example_meaning":"Tôi sẽ nỗ lực giải quyết vấn đề."},{"example":"彼は明るく振る舞うよう努めました。","example_reading":"かれはあかるくふるまうようつとめました。","example_meaning":"Anh ấy cố gắng cư xử vui vẻ."}]}]},
{"label":"探す／捜す","note":"探す: tìm thứ mình muốn, chưa có (nhà, việc làm) hoặc tìm đồ nói chung. 捜す: tìm thứ bị mất, người mất tích, tội phạm (thường là cảnh sát, tìm kiếm cứu nạn).","items":[{"word":"探す","reading":"さがす","meaning":"tìm (thứ mình cần, muốn)","example":"新しいアパートを探しています。","example_reading":"あたらしいアパートをさがしています。","example_meaning":"Tôi đang tìm căn hộ mới.","examples":[{"example":"かばんの中で鍵を探しました。","example_reading":"かばんのなかでかぎをさがしました。","example_meaning":"Tôi đã tìm chìa khóa trong cặp."},{"example":"いい仕事を探すのは大変です。","example_reading":"いいしごとをさがすのはたいへんです。","example_meaning":"Tìm được công việc tốt thật vất vả."}]},{"word":"捜す","reading":"さがす","meaning":"tìm kiếm (người mất tích, tội phạm, đồ bị mất)","example":"警察は逃げた犯人を捜しています。","example_reading":"けいさつはにげたはんにんをさがしています。","example_meaning":"Cảnh sát đang truy tìm tên tội phạm bỏ trốn.","examples":[{"example":"山で行方不明になった人を捜します。","example_reading":"やまでゆくえふめいになったひとをさがします。","example_meaning":"Họ tìm người mất tích trên núi."},{"example":"迷子になった犬を捜しています。","example_reading":"まいごになったいぬをさがしています。","example_meaning":"Tôi đang tìm con chó bị lạc."}]}]},
{"label":"泊まる／止まる／停まる","note":"泊まる: ngủ lại, trọ (khách sạn, nhà bạn). 止まる: dừng, ngừng chuyển động/hoạt động (đồng hồ, nước, xe điện). 停まる: (xe cộ) đỗ, dừng tại một chỗ (車が停まる).","items":[{"word":"泊まる","reading":"とまる","meaning":"trọ, ngủ lại","example":"今夜は友達の家に泊まります。","example_reading":"こんやはともだちのいえにとまります。","example_meaning":"Tối nay tôi ngủ lại nhà bạn.","examples":[{"example":"京都のホテルに二日泊まりました。","example_reading":"きょうとのホテルにふつかとまりました。","example_meaning":"Tôi đã ở khách sạn ở Kyoto hai ngày."},{"example":"今夜はどこに泊まりますか。","example_reading":"こんやはどこにとまりますか。","example_meaning":"Tối nay bạn trọ ở đâu?"}]},{"word":"止まる","reading":"とまる","meaning":"dừng, ngừng","example":"時計が止まっています。","example_reading":"とけいがとまっています。","example_meaning":"Đồng hồ đã ngừng chạy.","examples":[{"example":"水が止まりました。","example_reading":"みずがとまりました。","example_meaning":"Nước bị ngừng."},{"example":"電車が急に止まりました。","example_reading":"でんしゃがきゅうにとまりました。","example_meaning":"Tàu điện đột nhiên dừng lại."}]},{"word":"停まる","reading":"とまる","meaning":"đỗ, dừng (xe cộ)","example":"家の前に黒い車が停まっています。","example_reading":"いえのまえにくろいくるまがとまっています。","example_meaning":"Có chiếc xe đen đỗ trước nhà.","examples":[{"example":"バスが駅前に停まりました。","example_reading":"バスがえきまえにとまりました。","example_meaning":"Xe buýt đã dừng trước ga."},{"example":"タクシーが店の前に停まりました。","example_reading":"タクシーがみせのまえにとまりました。","example_meaning":"Taxi dừng trước cửa tiệm."}]}]},
{"label":"付く／着く／就く","note":"付く: dính, gắn vào, đi kèm (しみが付く, 気が付く). 着く: đến nơi, chạm tới (駅に着く). 就く: đảm nhận chức vụ, nghề nghiệp; đi vào (床に就く).","items":[{"word":"付く","reading":"つく","meaning":"dính, gắn, kèm theo","example":"服にコーヒーのしみが付きました。","example_reading":"ふくにコーヒーのしみがつきました。","example_meaning":"Áo bị dính vết cà phê.","examples":[{"example":"このシャツには名前が付いています。","example_reading":"このシャツにはなまえがついています。","example_meaning":"Chiếc áo này có gắn tên."},{"example":"気が付くと、もう朝でした。","example_reading":"きがつくと、もうあさでした。","example_meaning":"Khi nhận ra thì đã là buổi sáng."}]},{"word":"着く","reading":"つく","meaning":"đến nơi","example":"電車は九時に東京駅に着きます。","example_reading":"でんしゃはくじにとうきょうえきにつきます。","example_meaning":"Tàu sẽ đến ga Tokyo lúc 9 giờ.","examples":[{"example":"やっと家に着きました。","example_reading":"やっといえにつきました。","example_meaning":"Cuối cùng tôi cũng về đến nhà."},{"example":"荷物は明日着きます。","example_reading":"にもつはあしたつきます。","example_meaning":"Hành lý ngày mai sẽ đến."}]},{"word":"就く","reading":"つく","meaning":"nhận (việc, chức vụ); đi (ngủ)","example":"兄は先月から新しい仕事に就きました。","example_reading":"あにはせんげつからあたらしいしごとにつきました。","example_meaning":"Anh tôi đã nhận công việc mới từ tháng trước.","examples":[{"example":"彼は教師の職に就いています。","example_reading":"かれはきょうしのしょくについています。","example_meaning":"Anh ấy làm nghề giáo viên."},{"example":"十一時には床に就きます。","example_reading":"じゅういちじにはとこにつきます。","example_meaning":"Tôi đi ngủ lúc 11 giờ."}]}]},
{"label":"取る／採る／撮る／捕る","note":"取る: lấy, cầm, giành (塩を取る, 点を取る, 休みを取る). 採る: thu hái, tuyển dụng, lấy mẫu (きのこを採る, 人を採る). 撮る: chụp, quay (写真, 動画). 捕る: bắt động vật sống (魚, 虫).","items":[{"word":"取る","reading":"とる","meaning":"lấy, cầm, giành","example":"塩を取ってください。","example_reading":"しおをとってください。","example_meaning":"Làm ơn lấy giúp tôi lọ muối.","examples":[{"example":"テストでいい点を取りました。","example_reading":"テストでいいてんをとりました。","example_meaning":"Tôi đã đạt điểm cao trong bài kiểm tra."},{"example":"休みを取って旅行します。","example_reading":"やすみをとってりょこうします。","example_meaning":"Tôi xin nghỉ để đi du lịch."}]},{"word":"採る","reading":"とる","meaning":"hái, tuyển, lấy mẫu","example":"山できのこを採りました。","example_reading":"やまできのこをとりました。","example_meaning":"Tôi đã hái nấm trên núi.","examples":[{"example":"会社は今年、新入社員を二十人採ります。","example_reading":"かいしゃはことし、しんにゅうしゃいんをにじゅうにんとります。","example_meaning":"Năm nay công ty tuyển 20 nhân viên mới."},{"example":"検査のために血を採ります。","example_reading":"けんさのためにちをとります。","example_meaning":"Họ lấy máu để xét nghiệm."}]},{"word":"撮る","reading":"とる","meaning":"chụp, quay","example":"公園で家族の写真を撮りました。","example_reading":"こうえんでかぞくのしゃしんをとりました。","example_meaning":"Tôi đã chụp ảnh gia đình ở công viên.","examples":[{"example":"スマホで動画を撮ります。","example_reading":"スマホでどうがをとります。","example_meaning":"Tôi quay video bằng điện thoại."},{"example":"この映画は京都で撮られました。","example_reading":"このえいがはきょうとでとられました。","example_meaning":"Bộ phim này được quay ở Kyoto."}]},{"word":"捕る","reading":"とる","meaning":"bắt (cá, côn trùng, thú)","example":"川で魚を捕りました。","example_reading":"かわでさかなをとりました。","example_meaning":"Tôi đã bắt cá ở sông.","examples":[{"example":"猫がネズミを捕りました。","example_reading":"ねこがネズミをとりました。","example_meaning":"Con mèo đã bắt được con chuột."},{"example":"子どもたちは虫を捕るのが好きです。","example_reading":"こどもたちはむしをとるのがすきです。","example_meaning":"Bọn trẻ thích bắt côn trùng."}]}]},
{"label":"絞る／搾る","note":"絞る: vắt, siết, thu hẹp (絞る khăn, 範囲を絞る, 知恵を絞る). 搾る: ép/vắt lấy chất lỏng ra (vắt sữa bò, ép dầu, ép nước trái cây).","items":[{"word":"絞る","reading":"しぼる","meaning":"vắt, siết; thu hẹp; vắt óc","example":"濡れたタオルを絞ってください。","example_reading":"ぬれたタオルをしぼってください。","example_meaning":"Hãy vắt chiếc khăn ướt đi.","examples":[{"example":"候補を三人に絞りました。","example_reading":"こうほをさんにんにしぼりました。","example_meaning":"Chúng tôi đã thu hẹp ứng viên còn ba người."},{"example":"みんなで知恵を絞って案を考えました。","example_reading":"みんなでちえをしぼってあんをかんがえました。","example_meaning":"Mọi người cùng vắt óc nghĩ ra phương án."}]},{"word":"搾る","reading":"しぼる","meaning":"ép, vắt (lấy sữa, dầu, nước)","example":"農家の人が牛の乳を搾っています。","example_reading":"のうかのひとがうしのちちをしぼっています。","example_meaning":"Người nông dân đang vắt sữa bò.","examples":[{"example":"菜種から油を搾ります。","example_reading":"なたねからあぶらをしぼります。","example_meaning":"Người ta ép dầu từ hạt cải."},{"example":"オレンジを搾ってジュースを作ります。","example_reading":"オレンジをしぼってジュースをつくります。","example_meaning":"Tôi vắt cam để làm nước ép."}]}]},
{"label":"押さえる／抑える","note":"押さえる: giữ chặt, đè bằng tay; nắm chắc (要点を押さえる). 抑える: kìm nén, hạn chế mức độ (怒り, 物価, 音).","items":[{"word":"押さえる","reading":"おさえる","meaning":"giữ chặt, đè; nắm bắt","example":"風で紙が飛ばないように手で押さえました。","example_reading":"かぜでかみがとばないようにてでおさえました。","example_meaning":"Tôi lấy tay giữ tờ giấy để gió không thổi bay.","examples":[{"example":"ポイントを押さえて説明します。","example_reading":"ポイントをおさえてせつめいします。","example_meaning":"Tôi sẽ giải thích nắm chắc các điểm chính."},{"example":"転んで、痛い足を押さえました。","example_reading":"ころんで、いたいあしをおさえました。","example_meaning":"Tôi bị ngã và ôm lấy cái chân đau."}]},{"word":"抑える","reading":"おさえる","meaning":"kìm nén, hạn chế","example":"怒りを抑えて話しました。","example_reading":"いかりをおさえてはなしました。","example_meaning":"Tôi nói chuyện trong khi kìm nén cơn giận.","examples":[{"example":"政府は物価の上昇を抑えようとしています。","example_reading":"せいふはぶっかのじょうしょうをおさえようとしています。","example_meaning":"Chính phủ đang cố kìm hãm đà tăng của vật giá."},{"example":"夜は音を抑えてください。","example_reading":"よるはおとをおさえてください。","example_meaning":"Ban đêm hãy giữ âm thanh nhỏ lại."}]}]},
{"label":"越える／超える","note":"越える: vượt qua một ranh giới, chướng ngại, địa điểm (山, 国境, 年). 超える: vượt quá mức, con số, tiêu chuẩn (35度を超える, 予想を超える).","items":[{"word":"越える","reading":"こえる","meaning":"vượt qua (núi, sông, biên giới)","example":"電車は山を越えて、海が見えてきました。","example_reading":"でんしゃはやまをこえて、うみがみえてきました。","example_meaning":"Tàu vượt qua núi, rồi biển hiện ra.","examples":[{"example":"国境を越えて、隣の国へ行きました。","example_reading":"こっきょうをこえて、となりのくにへいきました。","example_meaning":"Tôi vượt biên giới sang nước bên cạnh."},{"example":"川を越えると、小さな町があります。","example_reading":"かわをこえると、ちいさなまちがあります。","example_meaning":"Qua khỏi con sông là có một thị trấn nhỏ."}]},{"word":"超える","reading":"こえる","meaning":"vượt quá (mức, số lượng)","example":"気温が三十五度を超えました。","example_reading":"きおんがさんじゅうごどをこえました。","example_meaning":"Nhiệt độ đã vượt quá 35 độ.","examples":[{"example":"参加者は百人を超えています。","example_reading":"さんかしゃはひゃくにんをこえています。","example_meaning":"Số người tham gia đã vượt quá 100."},{"example":"予想を超える人が集まりました。","example_reading":"よそうをこえるひとがあつまりました。","example_meaning":"Số người tụ tập vượt ngoài dự đoán."}]}]},
{"label":"追う／負う","note":"追う: đuổi theo, theo đuổi (犯人, 夢, 流行). 負う: gánh vác, chịu (責任, けが, 借金).","items":[{"word":"追う","reading":"おう","meaning":"đuổi theo, theo đuổi","example":"犬がボールを追って走っています。","example_reading":"いぬがボールをおってはしっています。","example_meaning":"Con chó chạy đuổi theo quả bóng.","examples":[{"example":"警察官が犯人を追いました。","example_reading":"けいさつかんがはんにんをおいました。","example_meaning":"Viên cảnh sát đã đuổi theo tên tội phạm."},{"example":"彼は夢を追って東京へ来ました。","example_reading":"かれはゆめをおってとうきょうへきました。","example_meaning":"Anh ấy theo đuổi ước mơ nên đã đến Tokyo."}]},{"word":"負う","reading":"おう","meaning":"gánh, chịu (trách nhiệm, thương tích)","example":"社長は事故の責任を負いました。","example_reading":"しゃちょうはじこのせきにんをおいました。","example_meaning":"Giám đốc đã chịu trách nhiệm về vụ tai nạn.","examples":[{"example":"彼は事故で大けがを負いました。","example_reading":"かれはじこでおおけがをおいました。","example_meaning":"Anh ấy bị thương nặng trong vụ tai nạn."},{"example":"彼は大きな借金を負っています。","example_reading":"かれはおおきなしゃっきんをおっています。","example_meaning":"Anh ấy đang gánh một khoản nợ lớn."}]}]},
{"label":"立つ／建つ／経つ／発つ","note":"立つ: đứng, dựng đứng lên (人が立つ). 建つ: (công trình) được xây dựng (家, ビルが建つ). 経つ: thời gian trôi qua (時間が経つ). 発つ: khởi hành, xuất phát (東京を発つ).","items":[{"word":"立つ","reading":"たつ","meaning":"đứng","example":"駅で三十分立って待ちました。","example_reading":"えきでさんじゅっぷんたってまちました。","example_meaning":"Tôi đứng đợi ở ga 30 phút.","examples":[{"example":"先生は黒板の前に立っています。","example_reading":"せんせいはこくばんのまえにたっています。","example_meaning":"Thầy giáo đang đứng trước bảng đen."},{"example":"電車の中は立っている人が多いです。","example_reading":"でんしゃのなかはたっているひとがおおいです。","example_meaning":"Trong tàu có nhiều người đứng."}]},{"word":"建つ","reading":"たつ","meaning":"được xây (công trình)","example":"あそこに新しい学校が建ちます。","example_reading":"あそこにあたらしいがっこうがたちます。","example_meaning":"Ở đằng kia sẽ xây một ngôi trường mới.","examples":[{"example":"駅の前に高いビルが建ちました。","example_reading":"えきのまえにたかいビルがたちました。","example_meaning":"Một tòa nhà cao đã được xây trước ga."},{"example":"家が建つまで、アパートに住みます。","example_reading":"いえがたつまで、アパートにすみます。","example_meaning":"Tôi sẽ ở căn hộ cho đến khi nhà được xây xong."}]},{"word":"経つ","reading":"たつ","meaning":"(thời gian) trôi qua","example":"日本に来てから、三年が経ちました。","example_reading":"にほんにきてから、さんねんがたちました。","example_meaning":"Từ khi đến Nhật đã 3 năm trôi qua.","examples":[{"example":"時間が経つのは早いですね。","example_reading":"じかんがたつのははやいですね。","example_meaning":"Thời gian trôi nhanh thật nhỉ."},{"example":"あれから一か月経ちました。","example_reading":"あれからいっかげつたちました。","example_meaning":"Từ hồi đó đã trôi qua một tháng."}]},{"word":"発つ","reading":"たつ","meaning":"khởi hành, xuất phát","example":"明日の朝、東京を発ちます。","example_reading":"あしたのあさ、とうきょうをたちます。","example_meaning":"Sáng mai tôi rời Tokyo.","examples":[{"example":"父は今朝、大阪へ発ちました。","example_reading":"ちちはけさ、おおさかへたちました。","example_meaning":"Bố tôi đã lên đường đi Osaka sáng nay."},{"example":"飛行機は十時にパリを発ちます。","example_reading":"ひこうきはじゅうじにパリをたちます。","example_meaning":"Máy bay rời Paris lúc 10 giờ."}]}]},
{"label":"鳴く／泣く","note":"鳴く: chim, thú, côn trùng kêu. 泣く: con người khóc (rơi nước mắt).","items":[{"word":"鳴く","reading":"なく","meaning":"kêu (chim, thú, côn trùng)","example":"朝、庭で鳥が鳴いています。","example_reading":"あさ、にわでとりがないています。","example_meaning":"Buổi sáng, chim đang hót ngoài vườn.","examples":[{"example":"夜に猫が鳴いて、眠れませんでした。","example_reading":"よるにねこがないて、ねむれませんでした。","example_meaning":"Ban đêm mèo kêu nên tôi không ngủ được."},{"example":"秋になると、虫が鳴きます。","example_reading":"あきになると、むしがなきます。","example_meaning":"Sang thu, côn trùng kêu."}]},{"word":"泣く","reading":"なく","meaning":"khóc","example":"赤ちゃんが大きな声で泣いています。","example_reading":"あかちゃんがおおきなこえでないています。","example_meaning":"Em bé đang khóc to.","examples":[{"example":"悲しい映画を見て、泣きました。","example_reading":"かなしいえいがをみて、なきました。","example_meaning":"Xem phim buồn nên tôi đã khóc."},{"example":"泣かないで、もう大丈夫です。","example_reading":"なかないで、もうだいじょうぶです。","example_meaning":"Đừng khóc nữa, ổn rồi."}]}]},
{"label":"断つ／絶つ／裁つ","note":"断つ: cắt đứt/ngừng hẳn một thói quen, chặn một đường (酒を断つ, 退路を断つ). 絶つ: làm cho không còn tiếp tục, chấm dứt quan hệ hay sự tồn tại (連絡を絶つ, 命を絶つ, 後を絶たない). 裁つ: cắt vải, giấy theo kích thước may mặc (布を裁つ).","items":[{"word":"断つ","reading":"たつ","meaning":"cắt đứt, từ bỏ hẳn, chặn đứng","example":"彼は健康のために酒を断った。","example_reading":"かれはけんこうのためにさけをたった。","example_meaning":"Anh ấy bỏ hẳn rượu vì sức khỏe.","examples":[{"example":"医者に言われて、たばこを断つことにした。","example_reading":"いしゃにいわれて、たばこをたつことにした。","example_meaning":"Nghe bác sĩ nói, tôi quyết định bỏ thuốc lá."},{"example":"敵の退路を断って、戦いに勝った。","example_reading":"てきのたいろをたって、たたかいにかった。","example_meaning":"Chặn đường lui của địch và thắng trận."}]},{"word":"絶つ","reading":"たつ","meaning":"chấm dứt hoàn toàn (quan hệ, liên lạc, mạng sống)","example":"彼とは三年前に連絡を絶った。","example_reading":"かれとはさんねんまえにれんらくをたった。","example_meaning":"Tôi đã cắt đứt liên lạc với anh ấy từ ba năm trước.","examples":[{"example":"この町では交通事故が後を絶たない。","example_reading":"このまちではこうつうじこがあとをたたない。","example_meaning":"Ở thị trấn này tai nạn giao thông không ngừng xảy ra."},{"example":"二つの国は長い間、国交を絶っていた。","example_reading":"ふたつのくには、ながいあいだ、こっこうをたっていた。","example_meaning":"Hai nước đã đoạn giao trong thời gian dài."}]},{"word":"裁つ","reading":"たつ","meaning":"cắt (vải, giấy) theo khuôn may","example":"母は型紙に合わせて布を裁った。","example_reading":"はははかたがみにあわせてぬのをたった。","example_meaning":"Mẹ cắt vải theo mẫu giấy.","examples":[{"example":"この生地は大きいので、二つに裁って使う。","example_reading":"このきじはおおきいので、ふたつにたってつかう。","example_meaning":"Tấm vải này to nên cắt làm đôi để dùng."},{"example":"祖母は着物を裁つのが上手だった。","example_reading":"そぼはきものをたつのがじょうずだった。","example_meaning":"Bà tôi cắt may kimono rất giỏi."}]}]},
{"label":"話す／離す／放す","note":"話す: nói, trò chuyện. 離す: làm cho tách rời, buông, giữ khoảng cách (手を離す, 目を離す). 放す: thả cho tự do, phóng thích (鳥を放す, 犬を放す).","items":[{"word":"話す","reading":"はなす","meaning":"nói, nói chuyện","example":"友達と日本語で話すのが好きです。","example_reading":"ともだちとにほんごではなすのがすきです。","example_meaning":"Tôi thích nói chuyện bằng tiếng Nhật với bạn.","examples":[{"example":"先生に悩みを話したら、気持ちが楽になった。","example_reading":"せんせいになやみをはなしたら、きもちがらくになった。","example_meaning":"Kể nỗi lo với thầy xong, tôi thấy nhẹ lòng."},{"example":"もう少しゆっくり話してください。","example_reading":"もうすこしゆっくりはなしてください。","example_meaning":"Xin hãy nói chậm hơn một chút."}]},{"word":"離す","reading":"はなす","meaning":"tách ra, buông ra, để cách xa","example":"危ないから、手を離さないでください。","example_reading":"あぶないから、てをはなさないでください。","example_meaning":"Nguy hiểm nên xin đừng buông tay.","examples":[{"example":"小さい子どもから目を離してはいけません。","example_reading":"ちいさいこどもからめをはなしてはいけません。","example_meaning":"Không được rời mắt khỏi trẻ nhỏ."},{"example":"机を壁から少し離して置いた。","example_reading":"つくえをかべからすこしはなしておいた。","example_meaning":"Tôi đặt cái bàn cách tường một chút."}]},{"word":"放す","reading":"はなす","meaning":"thả ra, phóng thích","example":"捕まえた鳥を空に放した。","example_reading":"つかまえたとりをそらにはなした。","example_meaning":"Tôi thả con chim bắt được lên trời.","examples":[{"example":"犬を庭に放して遊ばせる。","example_reading":"いぬをにわにはなしてあそばせる。","example_meaning":"Thả chó ra vườn cho chơi."},{"example":"釣った小さい魚は川に放した。","example_reading":"つったちいさいさかなはかわにはなした。","example_meaning":"Cá nhỏ câu được tôi đã thả xuống sông."}]}]},
{"label":"伸びる／延びる","note":"伸びる: vật dài ra, phát triển, tăng lên (背が伸びる, 髪が伸びる, 成績が伸びる). 延びる: thời hạn/thời gian/tuyến đường bị kéo dài hay dời lại (期日が延びる, 会議が延びる, 地下鉄が延びる).","items":[{"word":"伸びる","reading":"のびる","meaning":"dài ra, lớn lên, tăng trưởng, giãn ra","example":"弟は去年からずいぶん背が伸びた。","example_reading":"おとうとはきょねんからずいぶんせがのびた。","example_meaning":"Em trai tôi cao lên nhiều từ năm ngoái.","examples":[{"example":"髪が伸びたので、美容院に行く。","example_reading":"かみがのびたので、びよういんにいく。","example_meaning":"Tóc dài ra rồi nên tôi đi tiệm làm tóc."},{"example":"この会社は売り上げが伸びている。","example_reading":"このかいしゃはうりあげがのびている。","example_meaning":"Công ty này doanh thu đang tăng."}]},{"word":"延びる","reading":"のびる","meaning":"bị kéo dài thời gian, hoãn lại, nối dài (đường)","example":"雨のため、運動会が来週に延びた。","example_reading":"あめのため、うんどうかいがらいしゅうにのびた。","example_meaning":"Vì mưa nên hội thao bị hoãn sang tuần sau.","examples":[{"example":"会議の時間が三十分延びてしまった。","example_reading":"かいぎのじかんがさんじゅっぷんのびてしまった。","example_meaning":"Giờ họp bị kéo dài thêm ba mươi phút."},{"example":"地下鉄が空港まで延びる予定だ。","example_reading":"ちかてつがくうこうまでのびるよていだ。","example_meaning":"Tàu điện ngầm dự định được nối dài đến sân bay."}]}]},
{"label":"犯す／侵す／冒す","note":"犯す: phạm tội, phạm lỗi, vi phạm luật (罪を犯す, 過ちを犯す). 侵す: xâm phạm ranh giới, quyền lợi của người khác (領土を侵す, 権利を侵す). 冒す: bất chấp rủi ro, hoặc bị bệnh tật tấn công (危険を冒す, 病に冒される).","items":[{"word":"犯す","reading":"おかす","meaning":"phạm (tội, lỗi, luật)","example":"彼は若いころ大きな罪を犯した。","example_reading":"かれはわかいころおおきなつみをおかした。","example_meaning":"Hồi trẻ anh ấy đã phạm một tội lớn.","examples":[{"example":"同じ過ちを犯さないように気をつけます。","example_reading":"おなじあやまちをおかさないようにきをつけます。","example_meaning":"Tôi sẽ cẩn thận để không phạm lại lỗi giống vậy."},{"example":"法を犯した人は罰を受ける。","example_reading":"ほうをおかしたひとはばつをうける。","example_meaning":"Người phạm luật sẽ bị phạt."}]},{"word":"侵す","reading":"おかす","meaning":"xâm phạm (lãnh thổ, quyền lợi)","example":"他の国の領土を侵してはいけない。","example_reading":"ほかのくにのりょうどをおかしてはいけない。","example_meaning":"Không được xâm phạm lãnh thổ nước khác.","examples":[{"example":"人の権利を侵してはならない。","example_reading":"ひとのけんりをおかしてはならない。","example_meaning":"Không được xâm phạm quyền lợi của người khác."},{"example":"ネットでプライバシーを侵す行為が問題になっている。","example_reading":"ねっとでぷらいばしーをおかすこういがもんだいになっている。","example_meaning":"Hành vi xâm phạm quyền riêng tư trên mạng đang thành vấn đề."}]},{"word":"冒す","reading":"おかす","meaning":"liều (nguy hiểm), bất chấp; bị bệnh xâm nhập","example":"彼は危険を冒して子どもを助けた。","example_reading":"かれはきけんをおかしてこどもをたすけた。","example_meaning":"Anh ấy liều nguy hiểm cứu đứa trẻ.","examples":[{"example":"失敗の危険を冒しても、挑戦したい。","example_reading":"しっぱいのきけんをおかしても、ちょうせんしたい。","example_meaning":"Dù liều có thể thất bại, tôi vẫn muốn thử thách."},{"example":"祖父は重い病気に冒されている。","example_reading":"そふはおもいびょうきにおかされている。","example_meaning":"Ông tôi đang bị bệnh nặng hành hạ."}]}]},
{"label":"生む／産む","note":"生む: sinh ra, tạo ra điều trừu tượng hoặc kết quả (利益を生む, 誤解を生む). 産む: người/động vật đẻ con, đẻ trứng (子を産む, 卵を産む).","items":[{"word":"生む","reading":"うむ","meaning":"sinh ra, tạo ra (kết quả, lợi nhuận, hiểu lầm)","example":"この計画は大きな利益を生んだ。","example_reading":"このけいかくはおおきなりえきをうんだ。","example_meaning":"Kế hoạch này đã tạo ra lợi nhuận lớn.","examples":[{"example":"小さな誤解が争いを生むことがある。","example_reading":"ちいさなごかいがあらそいをうむことがある。","example_meaning":"Một hiểu lầm nhỏ đôi khi gây ra tranh cãi."},{"example":"彼の努力が良い結果を生んだ。","example_reading":"かれのどりょくがよいけっかをうんだ。","example_meaning":"Nỗ lực của anh ấy đã tạo nên kết quả tốt."}]},{"word":"産む","reading":"うむ","meaning":"đẻ (con, trứng)","example":"姉は先月、男の子を産んだ。","example_reading":"あねはせんげつ、おとこのこをうんだ。","example_meaning":"Chị tôi tháng trước đã sinh con trai.","examples":[{"example":"にわとりは毎日卵を産む。","example_reading":"にわとりはまいにちたまごをうむ。","example_meaning":"Gà mái đẻ trứng mỗi ngày."},{"example":"この病院で子どもを産みたいと思っている。","example_reading":"このびょういんでこどもをうみたいとおもっている。","example_meaning":"Tôi định sinh con ở bệnh viện này."}]}]},
{"label":"荒い／粗い","note":"荒い: tính chất mạnh bạo, dữ dội (波が荒い, 気が荒い, 息が荒い, 言葉づかいが荒い). 粗い: bề mặt/hạt/mắt lưới thô, không mịn, không tỉ mỉ (網目が粗い, 粒が粗い, 仕事が粗い).","items":[{"word":"荒い","reading":"あらい","meaning":"dữ dội, thô bạo, mạnh","example":"今日は海の波が荒いので、船は出ない。","example_reading":"きょうはうみのなみがあらいので、ふねはでない。","example_meaning":"Hôm nay sóng biển dữ nên tàu không chạy.","examples":[{"example":"彼は言葉づかいが荒い。","example_reading":"かれはことばづかいがあらい。","example_meaning":"Anh ấy ăn nói thô lỗ."},{"example":"走ったあとで息が荒くなった。","example_reading":"はしったあとでいきがあらくなった。","example_meaning":"Chạy xong tôi thở dốc."}]},{"word":"粗い","reading":"あらい","meaning":"thô, thưa, không mịn, sơ sài","example":"このセーターは編み目が粗い。","example_reading":"このせーたーはあみめがあらい。","example_meaning":"Cái áo len này mắt đan thưa.","examples":[{"example":"画像が粗くて、文字が読みにくい。","example_reading":"がぞうがあらくて、もじがよみにくい。","example_meaning":"Hình ảnh thô nên khó đọc chữ."},{"example":"粒の粗い砂で子どもが遊んでいる。","example_reading":"つぶのあらいすなでこどもがあそんでいる。","example_meaning":"Bọn trẻ đang chơi với cát hạt thô."}]}]},
{"label":"以外／意外","note":"以外: 'ngoài ... ra', chỉ phạm vi loại trừ (私以外). 意外: 'bất ngờ, không ngờ', trái với dự đoán (意外な結果, 意外に簡単).","items":[{"word":"以外","reading":"いがい","meaning":"ngoài ra, ngoại trừ","example":"日曜日以外は毎日働いています。","example_reading":"にちようびいがいはまいにちはたらいています。","example_meaning":"Ngoài Chủ nhật, ngày nào tôi cũng làm việc.","examples":[{"example":"私以外の人は全員来ました。","example_reading":"わたしいがいのひとはぜんいんきました。","example_meaning":"Ngoài tôi ra, mọi người đều đã đến."},{"example":"肉以外なら何でも食べられます。","example_reading":"にくいがいならなんでもたべられます。","example_meaning":"Ngoài thịt ra thì món gì tôi cũng ăn được."}]},{"word":"意外","reading":"いがい","meaning":"bất ngờ, ngoài dự đoán","example":"試験は意外に簡単だった。","example_reading":"しけんはいがいにかんたんだった。","example_meaning":"Bài thi dễ hơn tôi tưởng.","examples":[{"example":"彼が歌がうまいとは意外だ。","example_reading":"かれがうたがうまいとはいがいだ。","example_meaning":"Thật bất ngờ là anh ấy hát hay."},{"example":"意外な人から電話があった。","example_reading":"いがいなひとからでんわがあった。","example_meaning":"Tôi nhận được điện thoại từ một người không ngờ tới."}]}]},
{"label":"異常／以上","note":"異常: trạng thái khác thường, không bình thường (異常な天気, 異常なし). 以上: mức từ ... trở lên, 'trên đây/hết', hoặc 'một khi đã ... thì' (18歳以上, 以上です, 約束した以上).","items":[{"word":"異常","reading":"いじょう","meaning":"bất thường, dị thường","example":"機械の音が異常だから、止めてください。","example_reading":"きかいのおとがいじょうだから、とめてください。","example_meaning":"Tiếng máy bất thường nên hãy dừng lại.","examples":[{"example":"今年の夏は異常に暑い。","example_reading":"ことしのなつはいじょうにあつい。","example_meaning":"Mùa hè năm nay nóng bất thường."},{"example":"検査で異常は見つかりませんでした。","example_reading":"けんさでいじょうはみつかりませんでした。","example_meaning":"Kết quả kiểm tra không phát hiện gì bất thường."}]},{"word":"以上","reading":"いじょう","meaning":"từ ... trở lên; hết; đã ... thì","example":"十八歳以上の方が対象です。","example_reading":"じゅうはっさいいじょうのかたがたいしょうです。","example_meaning":"Đối tượng là người từ 18 tuổi trở lên.","examples":[{"example":"以上で今日の説明を終わります。","example_reading":"いじょうできょうのせつめいをおわります。","example_meaning":"Phần giải thích hôm nay đến đây là hết."},{"example":"約束した以上、守らなければならない。","example_reading":"やくそくしたいじょう、まもらなければならない。","example_meaning":"Đã hứa thì phải giữ lời."}]}]},
{"label":"意志／意思／医師","note":"意志: ý chí, sức mạnh tinh thần để làm cho bằng được (意志が強い). 意思: ý muốn, ý định, điều mình nghĩ và muốn truyền đạt (意思表示, 意思の疎通). 医師: bác sĩ (nghề nghiệp).","items":[{"word":"意志","reading":"いし","meaning":"ý chí","example":"彼は意志が強いから、きっと続けられる。","example_reading":"かれはいしがつよいから、きっとつづけられる。","example_meaning":"Anh ấy ý chí mạnh nên chắc chắn sẽ theo được.","examples":[{"example":"私は自分の意志で留学を決めた。","example_reading":"わたしはじぶんのいしでりゅうがくをきめた。","example_meaning":"Tôi quyết định du học theo ý chí của mình."},{"example":"意志の弱い人は禁煙が難しい。","example_reading":"いしのよわいひとはきんえんがむずかしい。","example_meaning":"Người ý chí yếu thì khó bỏ thuốc."}]},{"word":"意思","reading":"いし","meaning":"ý định, ý muốn, ý kiến","example":"相手に自分の意思をはっきり伝えた。","example_reading":"あいてにじぶんのいしをはっきりつたえた。","example_meaning":"Tôi đã truyền đạt rõ ý muốn của mình cho đối phương.","examples":[{"example":"会議で意思の疎通がうまくいかなかった。","example_reading":"かいぎでいしのそつうがうまくいかなかった。","example_meaning":"Trong cuộc họp việc truyền đạt ý kiến không suôn sẻ."},{"example":"彼には会社を辞める意思はないようだ。","example_reading":"かれにはかいしゃをやめるいしはないようだ。","example_meaning":"Có vẻ anh ấy không có ý định nghỉ việc."}]},{"word":"医師","reading":"いし","meaning":"bác sĩ","example":"姉は病院で医師として働いている。","example_reading":"あねはびょういんでいしとしてはたらいている。","example_meaning":"Chị tôi làm bác sĩ ở bệnh viện.","examples":[{"example":"医師に薬の飲み方を聞いた。","example_reading":"いしにくすりののみかたをきいた。","example_meaning":"Tôi hỏi bác sĩ cách uống thuốc."},{"example":"将来は医師になりたいです。","example_reading":"しょうらいはいしになりたいです。","example_meaning":"Tương lai tôi muốn trở thành bác sĩ."}]}]},
{"label":"機会／機械／器械","note":"機会: cơ hội, dịp (機会がある). 機械: máy móc có cấu tạo phức tạp, chạy bằng động lực (機械を動かす). 器械: dụng cụ, khí cụ đơn giản, thường không có động cơ lớn (医療器械, 器械体操).","items":[{"word":"機会","reading":"きかい","meaning":"cơ hội, dịp","example":"いい機会だから、日本へ行ってみたい。","example_reading":"いいきかいだから、にほんへいってみたい。","example_meaning":"Nhân dịp tốt này, tôi muốn thử đến Nhật.","examples":[{"example":"こんな機会はめったにない。","example_reading":"こんなきかいはめったにない。","example_meaning":"Cơ hội như thế này hiếm có."},{"example":"彼に会う機会があれば、よろしく伝えてください。","example_reading":"かれにあうきかいがあれば、よろしくつたえてください。","example_meaning":"Nếu có dịp gặp anh ấy, hãy gửi lời hỏi thăm giúp tôi."}]},{"word":"機械","reading":"きかい","meaning":"máy móc","example":"工場では大きな機械が動いている。","example_reading":"こうじょうではおおきなきかいがうごいている。","example_meaning":"Trong nhà máy có máy lớn đang chạy.","examples":[{"example":"この機械の使い方を教えてください。","example_reading":"このきかいのつかいかたをおしえてください。","example_meaning":"Xin chỉ cho tôi cách dùng cái máy này."},{"example":"機械が故障して、仕事が止まった。","example_reading":"きかいがこしょうして、しごとがとまった。","example_meaning":"Máy hỏng nên công việc bị đình trệ."}]},{"word":"器械","reading":"きかい","meaning":"dụng cụ, khí cụ (đơn giản, nhỏ)","example":"体育の授業で器械運動をした。","example_reading":"たいいくのじゅぎょうできかいうんどうをした。","example_meaning":"Trong giờ thể dục chúng tôi tập thể dục dụng cụ.","examples":[{"example":"医者は消毒した器械で手術をした。","example_reading":"いしゃはしょうどくしたきかいでしゅじゅつをした。","example_meaning":"Bác sĩ phẫu thuật bằng dụng cụ đã khử trùng."},{"example":"理科室で実験用の器械を使った。","example_reading":"りかしつでじっけんようのきかいをつかった。","example_meaning":"Ở phòng khoa học chúng tôi dùng dụng cụ thí nghiệm."}]}]},
{"label":"感心／関心／歓心","note":"感心: khâm phục, khen ngợi điều hay giỏi (感心する). 関心: sự quan tâm, hứng thú với một việc (関心がある). 歓心: lòng ưa thích/thiện cảm của người khác, hay dùng trong 歓心を買う (lấy lòng).","items":[{"word":"感心","reading":"かんしん","meaning":"khâm phục, thán phục","example":"彼の丁寧な仕事に感心した。","example_reading":"かれのていねいなしごとにかんしんした。","example_meaning":"Tôi khâm phục công việc tỉ mỉ của anh ấy.","examples":[{"example":"小さい子が一人でお使いに行くなんて感心だ。","example_reading":"ちいさいこがひとりでおつかいにいくなんてかんしんだ。","example_meaning":"Đứa bé nhỏ mà tự đi mua đồ, thật đáng khen."},{"example":"日本語が上手で感心しました。","example_reading":"にほんごがじょうずでかんしんしました。","example_meaning":"Bạn giỏi tiếng Nhật làm tôi thán phục."}]},{"word":"関心","reading":"かんしん","meaning":"quan tâm, hứng thú","example":"私は環境問題に関心があります。","example_reading":"わたしはかんきょうもんだいにかんしんがあります。","example_meaning":"Tôi quan tâm đến vấn đề môi trường.","examples":[{"example":"若者の政治への関心が低くなっている。","example_reading":"わかもののせいじへのかんしんがひくくなっている。","example_meaning":"Sự quan tâm của giới trẻ với chính trị đang giảm."},{"example":"彼は日本の文化に深い関心を持っている。","example_reading":"かれはにほんのぶんかにふかいかんしんをもっている。","example_meaning":"Anh ấy rất quan tâm đến văn hóa Nhật Bản."}]},{"word":"歓心","reading":"かんしん","meaning":"sự ưa thích, thiện cảm (歓心を買う)","example":"彼は社長の歓心を買おうとして、高いお土産を持ってきた。","example_reading":"かれはしゃちょうのかんしんをかおうとして、たかいおみやげをもってきた。","example_meaning":"Anh ta mang quà đắt tiền đến để lấy lòng giám đốc.","examples":[{"example":"高価なプレゼントで彼女の歓心を買おうとした。","example_reading":"こうかなぷれぜんとでかのじょのかんしんをかおうとした。","example_meaning":"Anh ấy định dùng quà đắt tiền để lấy lòng cô ấy."},{"example":"部下たちは上司の歓心を得るために一生懸命働いた。","example_reading":"ぶかたちはじょうしのかんしんをえるためにいっしょうけんめいはたらいた。","example_meaning":"Cấp dưới làm việc chăm chỉ để được lòng cấp trên."}]}]},
{"label":"公演／講演／後援","note":"公演: biểu diễn trước khán giả (演劇, コンサート). 講演: nói chuyện, thuyết trình về một chủ đề trước nhiều người. 後援: giúp đỡ, bảo trợ về tài chính hoặc danh nghĩa cho sự kiện.","items":[{"word":"公演","reading":"こうえん","meaning":"buổi biểu diễn (kịch, nhạc)","example":"劇団の公演を見に行った。","example_reading":"げきだんのこうえんをみにいった。","example_meaning":"Tôi đã đi xem buổi biểu diễn của đoàn kịch.","examples":[{"example":"来月、東京でコンサートの公演がある。","example_reading":"らいげつ、とうきょうでこんさーとのこうえんがある。","example_meaning":"Tháng sau có buổi hòa nhạc ở Tokyo."},{"example":"公演は夜七時に始まります。","example_reading":"こうえんはよるしちじにはじまります。","example_meaning":"Buổi diễn bắt đầu lúc bảy giờ tối."}]},{"word":"講演","reading":"こうえん","meaning":"bài diễn thuyết, buổi nói chuyện","example":"有名な作家の講演を聞いた。","example_reading":"ゆうめいなさっかのこうえんをきいた。","example_meaning":"Tôi đã nghe bài diễn thuyết của một nhà văn nổi tiếng.","examples":[{"example":"先生は来週、大学で講演をする予定だ。","example_reading":"せんせいはらいしゅう、だいがくでこうえんをするよていだ。","example_meaning":"Tuần sau thầy dự định diễn thuyết ở trường đại học."},{"example":"講演のあとで質問の時間があった。","example_reading":"こうえんのあとでしつもんのじかんがあった。","example_meaning":"Sau bài diễn thuyết có thời gian hỏi đáp."}]},{"word":"後援","reading":"こうえん","meaning":"hậu thuẫn, bảo trợ","example":"このイベントは市の後援で行われた。","example_reading":"このいべんとはしのこうえんでおこなわれた。","example_meaning":"Sự kiện này được tổ chức dưới sự bảo trợ của thành phố.","examples":[{"example":"新聞社が展覧会を後援している。","example_reading":"しんぶんしゃがてんらんかいをこうえんしている。","example_meaning":"Tòa soạn báo đang bảo trợ triển lãm."},{"example":"会社の後援を受けて、大会を開いた。","example_reading":"かいしゃのこうえんをうけて、たいかいをひらいた。","example_meaning":"Nhờ được công ty bảo trợ, chúng tôi đã tổ chức đại hội."}]}]},
{"label":"開放／解放","note":"開放: mở ra, để mọi người tự do ra vào/sử dụng (窓を開放, 校庭を開放). 解放: cởi bỏ sự ràng buộc, gỡ khỏi trạng thái bị trói buộc (人質を解放, 苦痛から解放).","items":[{"word":"開放","reading":"かいほう","meaning":"mở cửa, cho tự do ra vào","example":"夏は窓を開放して、風を入れる。","example_reading":"なつはまどをかいほうして、かぜをいれる。","example_meaning":"Mùa hè tôi mở toang cửa sổ cho gió vào.","examples":[{"example":"この公園は昼間、市民に開放されている。","example_reading":"このこうえんはひるま、しみんにかいほうされている。","example_meaning":"Công viên này ban ngày mở cửa cho người dân."},{"example":"学校のプールを一般の人に開放する。","example_reading":"がっこうのぷーるをいっぱんのひとにかいほうする。","example_meaning":"Trường mở hồ bơi cho người bên ngoài sử dụng."}]},{"word":"解放","reading":"かいほう","meaning":"giải phóng, thả tự do, thoát khỏi","example":"人質は三日後に解放された。","example_reading":"ひとじちはみっかごにかいほうされた。","example_meaning":"Con tin đã được thả sau ba ngày.","examples":[{"example":"試験が終わって、やっと勉強から解放された。","example_reading":"しけんがおわって、やっとべんきょうからかいほうされた。","example_meaning":"Thi xong, cuối cùng tôi cũng thoát khỏi việc học."},{"example":"彼は長い痛みから解放されて、ほっとした。","example_reading":"かれはながいいたみからかいほうされて、ほっとした。","example_meaning":"Anh ấy thoát khỏi cơn đau kéo dài nên nhẹ nhõm."}]}]},
{"label":"対象／対照／対称","note":"対象: đối tượng hướng tới (調査の対象, 子ども対象). 対照: so sánh, đối chiếu hoặc tương phản (対照的). 対称: hai bên cân xứng, đối xứng (左右対称, 点対称).","items":[{"word":"対象","reading":"たいしょう","meaning":"đối tượng, mục tiêu","example":"この本は子どもを対象にして書かれている。","example_reading":"このほんはこどもをたいしょうにしてかかれている。","example_meaning":"Cuốn sách này được viết cho đối tượng là trẻ em.","examples":[{"example":"二十歳以上の人が調査の対象です。","example_reading":"はたちいじょうのひとがちょうさのたいしょうです。","example_meaning":"Người từ 20 tuổi trở lên là đối tượng khảo sát."},{"example":"このサービスは学生が対象です。","example_reading":"このさーびすはがくせいがたいしょうです。","example_meaning":"Dịch vụ này dành cho sinh viên."}]},{"word":"対照","reading":"たいしょう","meaning":"đối chiếu, tương phản","example":"日本語と英語を対照して、違いを調べた。","example_reading":"にほんごとえいごをたいしょうして、ちがいをしらべた。","example_meaning":"Tôi đối chiếu tiếng Nhật và tiếng Anh để tìm điểm khác nhau.","examples":[{"example":"兄は明るいが、弟は対照的におとなしい。","example_reading":"あにはあかるいが、おとうとはたいしょうてきにおとなしい。","example_meaning":"Anh trai vui vẻ, còn em trai thì trái ngược, hiền lành."},{"example":"赤と白の対照が美しいポスターだ。","example_reading":"あかとしろのたいしょうがうつくしいぽすたーだ。","example_meaning":"Đây là tấm áp phích có sự tương phản đỏ trắng rất đẹp."}]},{"word":"対称","reading":"たいしょう","meaning":"đối xứng","example":"蝶の羽は左右対称になっている。","example_reading":"ちょうのはねはさゆうたいしょうになっている。","example_meaning":"Cánh bướm đối xứng trái phải.","examples":[{"example":"この図形は線対称です。","example_reading":"このずけいはせんたいしょうです。","example_meaning":"Hình này đối xứng qua một đường thẳng."},{"example":"左右対称の形を描いてください。","example_reading":"さゆうたいしょうのかたちをかいてください。","example_meaning":"Hãy vẽ một hình đối xứng trái phải."}]}]},
{"label":"保証／保障／補償","note":"保証: cam đoan, bảo đảm là chắc chắn/đúng (品質保証, 保証人, 保証書). 保障: bảo vệ để duy trì một quyền lợi hay trạng thái an toàn (社会保障, 安全保障). 補償: đền bù thiệt hại (損害を補償, 補償金).","items":[{"word":"保証","reading":"ほしょう","meaning":"bảo đảm, bảo hành, bảo lãnh","example":"この時計には一年間の保証がついている。","example_reading":"このとけいにはいちねんかんのほしょうがついている。","example_meaning":"Chiếc đồng hồ này có bảo hành một năm.","examples":[{"example":"品質は私が保証します。","example_reading":"ひんしつはわたしがほしょうします。","example_meaning":"Tôi bảo đảm về chất lượng."},{"example":"友達の保証人になるのは大変だ。","example_reading":"ともだちのほしょうにんになるのはたいへんだ。","example_meaning":"Làm người bảo lãnh cho bạn là việc nặng nề."}]},{"word":"保障","reading":"ほしょう","meaning":"bảo đảm, bảo vệ quyền lợi (an sinh, an ninh)","example":"国は国民の生活を保障する。","example_reading":"くにはこくみんのせいかつをほしょうする。","example_meaning":"Nhà nước bảo đảm đời sống của người dân.","examples":[{"example":"日本の社会保障について勉強している。","example_reading":"にほんのしゃかいほしょうについてべんきょうしている。","example_meaning":"Tôi đang học về an sinh xã hội của Nhật."},{"example":"言論の自由は憲法で保障されている。","example_reading":"げんろんのじゆうはけんぽうでほしょうされている。","example_meaning":"Tự do ngôn luận được hiến pháp bảo đảm."}]},{"word":"補償","reading":"ほしょう","meaning":"bồi thường, đền bù","example":"事故の被害者に補償金が支払われた。","example_reading":"じこのひがいしゃにほしょうきんがしはらわれた。","example_meaning":"Tiền bồi thường đã được trả cho nạn nhân vụ tai nạn.","examples":[{"example":"会社は客に与えた損害を補償した。","example_reading":"かいしゃはきゃくにあたえたそんがいをほしょうした。","example_meaning":"Công ty đã bồi thường thiệt hại gây ra cho khách."},{"example":"工事による被害の補償を求めた。","example_reading":"こうじによるひがいのほしょうをもとめた。","example_meaning":"Họ đã yêu cầu bồi thường thiệt hại do công trình gây ra."}]}]},
{"label":"上げる／挙げる／揚げる","note":"上げる(あげる): NÂNG lên, TĂNG lên (vị trí, mức độ). 挙げる(あげる): NÊU ra (ví dụ), GIƠ lên, TỔ CHỨC (lễ cưới). 揚げる(あげる): CHIÊN ngập dầu; kéo lên (cờ, bóng bay).","items":[{"word":"上げる","reading":"あげる","meaning":"nâng lên, tăng lên","example":"荷物を棚の上に上げてください。","example_reading":"にもつをたなのうえにあげてください。","example_meaning":"Hãy đặt hành lý lên giá.","examples":[{"example":"成績を上げるために、毎日勉強しています。","example_reading":"せいせきをあげるために、まいにちべんきょうしています。","example_meaning":"Tôi học mỗi ngày để nâng điểm số."},{"example":"うれしくて、思わず声を上げて笑いました。","example_reading":"うれしくて、おもわずこえをあげてわらいました。","example_meaning":"Vui quá nên tôi bật cười thành tiếng."}]},{"word":"挙げる","reading":"あげる","meaning":"nêu ra, giơ lên, tổ chức (lễ)","example":"例を挙げて説明します。","example_reading":"れいをあげてせつめいします。","example_meaning":"Tôi sẽ giải thích bằng cách nêu ví dụ.","examples":[{"example":"二人は教会で結婚式を挙げました。","example_reading":"ふたりはきょうかいでけっこんしきをあげました。","example_meaning":"Hai người đã tổ chức lễ cưới ở nhà thờ."},{"example":"質問がある人は手を挙げてください。","example_reading":"しつもんがあるひとはてをあげてください。","example_meaning":"Ai có câu hỏi xin hãy giơ tay."}]},{"word":"揚げる","reading":"あげる","meaning":"chiên ngập dầu, kéo (cờ) lên","example":"魚を油で揚げます。","example_reading":"さかなをあぶらであげます。","example_meaning":"Chiên cá bằng dầu.","examples":[{"example":"天ぷらは、揚げたてが一番おいしいです。","example_reading":"てんぷらは、あげたてがいちばんおいしいです。","example_meaning":"Tempura ngon nhất là lúc vừa chiên xong."},{"example":"運動会で国旗を揚げました。","example_reading":"うんどうかいでこっきをあげました。","example_meaning":"Đã kéo quốc kỳ lên trong hội thao."}]}]},
{"label":"下りる／降りる","note":"下りる(おりる): đi XUỐNG theo chiều thấp dần (cầu thang, núi); (giấy phép) được CẤP. 降りる(おりる): XUỐNG khỏi phương tiện giao thông; rời khỏi vị trí/vai trò.","items":[{"word":"下りる","reading":"おりる","meaning":"xuống (dốc, cầu thang); được cấp (phép)","example":"階段を下りて、一階へ行きます。","example_reading":"かいだんをおりて、いっかいへいきます。","example_meaning":"Tôi đi xuống cầu thang để xuống tầng một.","examples":[{"example":"山を下りると、小さな村がありました。","example_reading":"やまをおりると、ちいさなむらがありました。","example_meaning":"Xuống núi thì có một ngôi làng nhỏ."},{"example":"やっとビザの許可が下りました。","example_reading":"やっとビザのきょかがおりました。","example_meaning":"Cuối cùng giấy phép visa cũng được cấp."}]},{"word":"降りる","reading":"おりる","meaning":"xuống (phương tiện), rời khỏi","example":"次の駅で電車を降ります。","example_reading":"つぎのえきででんしゃをおります。","example_meaning":"Tôi xuống tàu ở ga tiếp theo.","examples":[{"example":"タクシーを降りて、店まで歩きました。","example_reading":"タクシーをおりて、みせまであるきました。","example_meaning":"Tôi xuống taxi rồi đi bộ đến cửa hàng."},{"example":"飛行機から降りると、暑い空気に包まれました。","example_reading":"ひこうきからおりると、あついくうきにつつまれました。","example_meaning":"Vừa bước xuống máy bay thì bị không khí nóng bao trùm."}]}]},
{"label":"乗る／載る","note":"乗る(のる): LÊN, ĐI bằng phương tiện; cưỡi; hòa theo (nhịp điệu). 載る(のる): được ĐỂ/CHẤT lên bề mặt; được ĐĂNG trên báo, sách.","items":[{"word":"乗る","reading":"のる","meaning":"lên, đi (phương tiện); cưỡi","example":"バスに乗って学校へ行きます。","example_reading":"バスにのってがっこうへいきます。","example_meaning":"Tôi đi xe buýt đến trường.","examples":[{"example":"やっと自転車に乗れるようになりました。","example_reading":"やっとじてんしゃにのれるようになりました。","example_meaning":"Cuối cùng tôi cũng biết đi xe đạp."},{"example":"調子に乗って、食べすぎてしまいました。","example_reading":"ちょうしにのって、たべすぎてしまいました。","example_meaning":"Hứng quá nên tôi ăn quá nhiều."}]},{"word":"載る","reading":"のる","meaning":"được để lên; được đăng (báo, sách)","example":"私の記事が新聞に載りました。","example_reading":"わたしのきじがしんぶんにのりました。","example_meaning":"Bài viết của tôi đã được đăng trên báo.","examples":[{"example":"この本には、有名な店の情報が載っています。","example_reading":"このほんには、ゆうめいなみせのじょうほうがのっています。","example_meaning":"Cuốn sách này có đăng thông tin về các cửa hàng nổi tiếng."},{"example":"机の上に載っている資料を取ってください。","example_reading":"つくえのうえにのっているしりょうをとってください。","example_meaning":"Làm ơn lấy giúp tài liệu để trên bàn."}]}]},
{"label":"怖い／恐い","note":"怖い(こわい): chữ THÔNG DỤNG nhất, 'sợ, đáng sợ' (ma, tối, chó...). 恐い(こわい): ít dùng hơn, thiên về 'e ngại, lo sợ điều xấu có thể xảy ra'. Trong thực tế hai chữ nhiều khi dùng thay thế nhau.","items":[{"word":"怖い","reading":"こわい","meaning":"sợ, đáng sợ","example":"暗い夜道は怖いです。","example_reading":"くらいよみちはこわいです。","example_meaning":"Con đường đêm tối thật đáng sợ.","examples":[{"example":"犬が怖くて、近づけません。","example_reading":"いぬがこわくて、ちかづけません。","example_meaning":"Tôi sợ chó nên không dám lại gần."},{"example":"怖い映画を見たので、眠れません。","example_reading":"こわいえいがをみたので、ねむれません。","example_meaning":"Vì xem phim kinh dị nên tôi không ngủ được."}]},{"word":"恐い","reading":"こわい","meaning":"e sợ, lo sợ (điều xấu)","example":"失敗するのが恐くて、挑戦できませんでした。","example_reading":"しっぱいするのがこわくて、ちょうせんできませんでした。","example_meaning":"Vì sợ thất bại nên tôi đã không dám thử thách.","examples":[{"example":"地震のあとの津波が恐いです。","example_reading":"じしんのあとのつなみがこわいです。","example_meaning":"Tôi lo sợ sóng thần sau động đất."},{"example":"恐い夢を見て、夜中に目が覚めました。","example_reading":"こわいゆめをみて、よなかにめがさめました。","example_meaning":"Tôi gặp ác mộng nên giữa đêm bị tỉnh giấc."}]}]},
{"label":"痛む／傷む／悼む","note":"痛む(いたむ): ĐAU (cơ thể, tâm hồn). 傷む(いたむ): HỎNG, HƯ (thực phẩm, đồ vật). 悼む(いたむ): THƯƠNG TIẾC người đã mất.","items":[{"word":"痛む","reading":"いたむ","meaning":"đau (thân thể, tâm hồn)","example":"転んだ足がまだ痛みます。","example_reading":"ころんだあしがまだいたみます。","example_meaning":"Chân bị ngã vẫn còn đau.","examples":[{"example":"虫歯が痛んで、夜も眠れません。","example_reading":"むしばがいたんで、よるもねむれません。","example_meaning":"Răng sâu đau đến mức ban đêm cũng không ngủ được."},{"example":"友達の不幸を聞いて、胸が痛みました。","example_reading":"ともだちのふこうをきいて、むねがいたみました。","example_meaning":"Nghe tin bất hạnh của bạn, lòng tôi đau xót."}]},{"word":"傷む","reading":"いたむ","meaning":"hỏng, hư (thực phẩm, đồ vật)","example":"夏は食べ物が傷みやすいです。","example_reading":"なつはたべものがいたみやすいです。","example_meaning":"Mùa hè thức ăn dễ bị hỏng.","examples":[{"example":"雨漏りで、家の屋根が傷んでしまいました。","example_reading":"あまもりで、いえのやねがいたんでしまいました。","example_meaning":"Vì dột mưa nên mái nhà bị hư hại."},{"example":"傷んだ果物は捨ててください。","example_reading":"いたんだくだものはすててください。","example_meaning":"Hãy bỏ những quả đã bị hỏng đi."}]},{"word":"悼む","reading":"いたむ","meaning":"thương tiếc, tưởng niệm","example":"亡くなった人を悼んで、黙とうをささげました。","example_reading":"なくなったひとをいたんで、もくとうをささげました。","example_meaning":"Mọi người mặc niệm để tưởng nhớ người đã khuất.","examples":[{"example":"みんなで先生の死を悼みました。","example_reading":"みんなでせんせいのしをいたみました。","example_meaning":"Mọi người cùng thương tiếc sự ra đi của thầy."},{"example":"事故の犠牲者を悼む式が行われました。","example_reading":"じこのぎせいしゃをいたむしきがおこなわれました。","example_meaning":"Buổi lễ tưởng niệm các nạn nhân của vụ tai nạn đã được tổ chức."}]}]},
{"label":"尋ねる／訪ねる","note":"尋ねる(たずねる): HỎI (thông tin, đường đi, sự tình). 訪ねる(たずねる): ĐẾN THĂM, ghé thăm (người, nơi chốn).","items":[{"word":"尋ねる","reading":"たずねる","meaning":"hỏi (để biết thông tin)","example":"駅員に道を尋ねました。","example_reading":"えきいんにみちをたずねました。","example_meaning":"Tôi đã hỏi nhân viên nhà ga đường đi.","examples":[{"example":"名前を尋ねられて、少し緊張しました。","example_reading":"なまえをたずねられて、すこしきんちょうしました。","example_meaning":"Bị hỏi tên nên tôi hơi căng thẳng."},{"example":"彼に事情を尋ねてみましょう。","example_reading":"かれにじじょうをたずねてみましょう。","example_meaning":"Hãy thử hỏi anh ấy về sự tình xem."}]},{"word":"訪ねる","reading":"たずねる","meaning":"đến thăm, ghé thăm","example":"夏休みに祖母の家を訪ねました。","example_reading":"なつやすみにそぼのいえをたずねました。","example_meaning":"Kỳ nghỉ hè tôi đã đến thăm nhà bà.","examples":[{"example":"先生を研究室に訪ねて、相談しました。","example_reading":"せんせいをけんきゅうしつにたずねて、そうだんしました。","example_meaning":"Tôi đến phòng nghiên cứu của thầy để xin tư vấn."},{"example":"古い友人を訪ねて、京都へ行きます。","example_reading":"ふるいゆうじんをたずねて、きょうとへいきます。","example_meaning":"Tôi sẽ đi Kyoto để thăm người bạn cũ."}]}]},
{"label":"誤る／謝る","note":"誤る(あやまる): SAI, NHẦM (phán đoán, thao tác). 謝る(あやまる): XIN LỖI.","items":[{"word":"誤る","reading":"あやまる","meaning":"sai, nhầm","example":"道を誤って、遠回りしてしまいました。","example_reading":"みちをあやまって、とおまわりしてしまいました。","example_meaning":"Tôi đi nhầm đường nên phải đi vòng xa.","examples":[{"example":"判断を誤ると、大きな失敗につながります。","example_reading":"はんだんをあやまると、おおきなしっぱいにつながります。","example_meaning":"Nếu phán đoán sai thì sẽ dẫn đến thất bại lớn."},{"example":"操作を誤って、データを消してしまいました。","example_reading":"そうさをあやまって、データをけしてしまいました。","example_meaning":"Tôi thao tác nhầm nên đã xóa mất dữ liệu."}]},{"word":"謝る","reading":"あやまる","meaning":"xin lỗi","example":"遅れたことを先生に謝りました。","example_reading":"おくれたことをせんせいにあやまりました。","example_meaning":"Tôi đã xin lỗi thầy vì đến muộn.","examples":[{"example":"悪いのは私なので、素直に謝ります。","example_reading":"わるいのはわたしなので、すなおにあやまります。","example_meaning":"Lỗi là ở tôi nên tôi sẽ thành thật xin lỗi."},{"example":"彼は何度も謝ったが、許してもらえなかった。","example_reading":"かれはなんどもあやまったが、ゆるしてもらえなかった。","example_meaning":"Anh ấy xin lỗi nhiều lần nhưng vẫn không được tha thứ."}]}]},
{"label":"表す／現す／著す","note":"表す(あらわす): BIỂU THỊ, DIỄN TẢ (cảm xúc, ý nghĩa, ký hiệu). 現す(あらわす): để LỘ RA, hiện ra (hình dạng, bản chất). 著す(あらわす): VIẾT, TRƯỚC TÁC (sách).","items":[{"word":"表す","reading":"あらわす","meaning":"biểu thị, diễn tả","example":"感謝の気持ちを言葉で表します。","example_reading":"かんしゃのきもちをことばであらわします。","example_meaning":"Tôi diễn tả lòng biết ơn bằng lời nói.","examples":[{"example":"この図は、売り上げの変化を表しています。","example_reading":"このずは、うりあげのへんかをあらわしています。","example_meaning":"Biểu đồ này thể hiện sự thay đổi của doanh thu."},{"example":"赤い色は危険を表します。","example_reading":"あかいいろはきけんをあらわします。","example_meaning":"Màu đỏ biểu thị sự nguy hiểm."}]},{"word":"現す","reading":"あらわす","meaning":"làm lộ ra, hiện ra","example":"太陽が雲の間から姿を現しました。","example_reading":"たいようがくものあいだからすがたをあらわしました。","example_meaning":"Mặt trời lộ diện từ giữa những đám mây.","examples":[{"example":"彼はやっと本性を現しました。","example_reading":"かれはやっとほんしょうをあらわしました。","example_meaning":"Cuối cùng anh ta cũng lộ bản chất."},{"example":"山の向こうから、大きな月が姿を現した。","example_reading":"やまのむこうから、おおきなつきがすがたをあらわした。","example_meaning":"Một vầng trăng lớn hiện ra từ phía sau dãy núi."}]},{"word":"著す","reading":"あらわす","meaning":"viết (sách), trước tác","example":"彼は江戸時代の歴史について本を著しました。","example_reading":"かれはえどじだいのれきしについてほんをあらわしました。","example_meaning":"Ông ấy đã viết sách về lịch sử thời Edo.","examples":[{"example":"先生は退職後、自伝を著すつもりです。","example_reading":"せんせいはたいしょくご、じでんをあらわすつもりです。","example_meaning":"Sau khi nghỉ hưu, thầy định viết tự truyện."},{"example":"森鷗外が著した小説を読んでいます。","example_reading":"もりおうがいがあらわしたしょうせつをよんでいます。","example_meaning":"Tôi đang đọc tiểu thuyết do Mori Ōgai viết."}]}]},
{"label":"表れる／現れる","note":"表れる(あらわれる): được BIỂU LỘ ra (cảm xúc, kết quả, đặc điểm). 現れる(あらわれる): XUẤT HIỆN (người, vật, hiện tượng, hiệu quả).","items":[{"word":"表れる","reading":"あらわれる","meaning":"được biểu lộ (cảm xúc, kết quả)","example":"顔に疲れが表れています。","example_reading":"かおにつかれがあらわれています。","example_meaning":"Sự mệt mỏi hiện rõ trên khuôn mặt.","examples":[{"example":"努力の成果が、テストの点数に表れました。","example_reading":"どりょくのせいかが、テストのてんすうにあらわれました。","example_meaning":"Thành quả nỗ lực đã thể hiện qua điểm thi."},{"example":"嬉しい気持ちが、態度に表れていますよ。","example_reading":"うれしいきもちが、たいどにあらわれていますよ。","example_meaning":"Niềm vui lộ rõ qua thái độ của bạn đấy."}]},{"word":"現れる","reading":"あらわれる","meaning":"xuất hiện","example":"暗闇の中から、突然人が現れました。","example_reading":"くらやみのなかから、とつぜんひとがあらわれました。","example_meaning":"Từ trong bóng tối, bỗng có một người xuất hiện.","examples":[{"example":"薬を飲んで、すぐに効果が現れました。","example_reading":"くすりをのんで、すぐにこうかがあらわれました。","example_meaning":"Uống thuốc xong thì hiệu quả xuất hiện ngay."},{"example":"待ち合わせの場所に、彼がやっと現れました。","example_reading":"まちあわせのばしょに、かれがやっとあらわれました。","example_meaning":"Anh ấy cuối cùng cũng xuất hiện ở chỗ hẹn."}]}]},
{"label":"回る／周る","note":"回る(まわる): QUAY, XOAY; đi VÒNG qua nhiều nơi (thông dụng). 周る(まわる): đi VÒNG QUANH một chu vi (hồ, đảo, công viên); ít dùng, thường viết là 回る.","items":[{"word":"回る","reading":"まわる","meaning":"quay, xoay; đi vòng qua các nơi","example":"地球は太陽の周りを回っています。","example_reading":"ちきゅうはたいようのまわりをまわっています。","example_meaning":"Trái đất quay quanh mặt trời.","examples":[{"example":"今日は取引先を三軒回りました。","example_reading":"きょうはとりひきさきをさんけんまわりました。","example_meaning":"Hôm nay tôi đã đi vòng qua ba khách hàng."},{"example":"風車がゆっくり回っています。","example_reading":"ふうしゃがゆっくりまわっています。","example_meaning":"Chiếc cối xay gió đang quay chậm rãi."}]},{"word":"周る","reading":"まわる","meaning":"đi vòng quanh (một chu vi)","example":"湖の周りを自転車で周りました。","example_reading":"みずうみのまわりをじてんしゃでまわりました。","example_meaning":"Tôi đã đạp xe một vòng quanh hồ.","examples":[{"example":"観光バスで島を周るツアーに参加しました。","example_reading":"かんこうバスでしまをまわるツアーにさんかしました。","example_meaning":"Tôi tham gia tour đi vòng quanh đảo bằng xe buýt du lịch."},{"example":"毎朝、公園をぐるっと周ってから出勤します。","example_reading":"まいあさ、こうえんをぐるっとまわってからしゅっきんします。","example_meaning":"Mỗi sáng tôi đi dạo một vòng công viên rồi mới đi làm."}]}]},
{"label":"降る／振る","note":"降る(ふる): RƠI từ trên trời xuống (mưa, tuyết). 振る(ふる): VẪY, LẮC, vung; (nghĩa bóng) từ chối, chia tay người yêu.","items":[{"word":"降る","reading":"ふる","meaning":"rơi (mưa, tuyết)","example":"朝から雨が降っています。","example_reading":"あさからあめがふっています。","example_meaning":"Từ sáng trời đã mưa.","examples":[{"example":"この冬は、雪がたくさん降りました。","example_reading":"このふゆは、ゆきがたくさんふりました。","example_meaning":"Mùa đông này tuyết rơi rất nhiều."},{"example":"明日は雪が降るかもしれません。","example_reading":"あしたはゆきがふるかもしれません。","example_meaning":"Ngày mai có thể sẽ có tuyết rơi."}]},{"word":"振る","reading":"ふる","meaning":"vẫy, lắc; từ chối (người yêu)","example":"駅で友達に手を振りました。","example_reading":"えきでともだちにてをふりました。","example_meaning":"Tôi vẫy tay chào bạn ở nhà ga.","examples":[{"example":"使う前に、瓶をよく振ってください。","example_reading":"つかうまえに、びんをよくふってください。","example_meaning":"Trước khi dùng hãy lắc kỹ chai."},{"example":"彼は恋人に振られて、元気がありません。","example_reading":"かれはこいびとにふられて、げんきがありません。","example_meaning":"Anh ấy bị người yêu bỏ nên không có tinh thần."}]}]},
{"label":"成る／鳴る","note":"成る(なる): THÀNH, hoàn thành; gồm có (văn viết, trang trọng). 鳴る(なる): KÊU, VANG lên (chuông, điện thoại, âm thanh).","items":[{"word":"成る","reading":"なる","meaning":"thành, hoàn thành; gồm có","example":"長年の努力が実り、ついに大事業が成りました。","example_reading":"ちょうねんのどりょくがみのり、ついにだいじぎょうがなりました。","example_meaning":"Nỗ lực nhiều năm đơm hoa kết trái, cuối cùng đại sự nghiệp đã thành.","examples":[{"example":"この組織は三つの部門から成っています。","example_reading":"このそしきはみっつのぶもんからなっています。","example_meaning":"Tổ chức này gồm ba bộ phận."},{"example":"三人から成るチームで大会に出ます。","example_reading":"さんにんからなるチームでたいかいにでます。","example_meaning":"Chúng tôi tham dự giải đấu bằng một đội gồm ba người."}]},{"word":"鳴る","reading":"なる","meaning":"kêu, vang lên","example":"電話が鳴っています。","example_reading":"でんわがなっています。","example_meaning":"Điện thoại đang reo.","examples":[{"example":"お腹が鳴って、恥ずかしかったです。","example_reading":"おなかがなって、はずかしかったです。","example_meaning":"Bụng tôi sôi lên nên tôi thấy ngượng."},{"example":"授業の終わりを告げるチャイムが鳴りました。","example_reading":"じゅぎょうのおわりをつげるチャイムがなりました。","example_meaning":"Chuông báo hết giờ học đã vang lên."}]}]},
{"label":"掛かる／係る／架かる","note":"掛かる(かかる): TỐN (thời gian, tiền), được TREO, bị KHÓA... (nghĩa rộng nhất). 係る(かかる): LIÊN QUAN đến (văn viết). 架かる(かかる): được BẮC QUA (cầu, cầu vồng).","items":[{"word":"掛かる","reading":"かかる","meaning":"tốn (thời gian, tiền); được treo; bị khóa","example":"空港まで一時間掛かります。","example_reading":"くうこうまでいちじかんかかります。","example_meaning":"Đến sân bay mất một tiếng.","examples":[{"example":"壁に大きな絵が掛かっています。","example_reading":"かべにおおきなえがかかっています。","example_meaning":"Trên tường có treo một bức tranh lớn."},{"example":"ドアに鍵が掛かっていて、入れません。","example_reading":"ドアにかぎがかかっていて、はいれません。","example_meaning":"Cửa bị khóa nên tôi không vào được."}]},{"word":"係る","reading":"かかる","meaning":"liên quan đến","example":"これは安全に係る重要な問題です。","example_reading":"これはあんぜんにかかるじゅうようなもんだいです。","example_meaning":"Đây là vấn đề quan trọng liên quan đến an toàn.","examples":[{"example":"人命に係る事故なので、慎重に調べます。","example_reading":"じんめいにかかるじこなので、しんちょうにしらべます。","example_meaning":"Vì là tai nạn liên quan đến tính mạng nên sẽ điều tra thận trọng."},{"example":"この規則は、すべての社員に係るものです。","example_reading":"このきそくは、すべてのしゃいんにかかるものです。","example_meaning":"Quy định này liên quan đến toàn bộ nhân viên."}]},{"word":"架かる","reading":"かかる","meaning":"được bắc qua (cầu, cầu vồng)","example":"この川には、古い石の橋が架かっています。","example_reading":"このかわには、ふるいいしのはしがかかっています。","example_meaning":"Trên con sông này có một cây cầu đá cũ bắc qua.","examples":[{"example":"空に大きな虹が架かりました。","example_reading":"そらにおおきなにじがかかりました。","example_meaning":"Một chiếc cầu vồng lớn đã bắc ngang bầu trời."},{"example":"新しい橋が架かって、町が便利になりました。","example_reading":"あたらしいはしがかかって、まちがべんりになりました。","example_meaning":"Cây cầu mới được bắc nên thị trấn trở nên thuận tiện hơn."}]}]},
{"label":"耐える／堪える／絶える","note":"耐える(たえる): CHỊU ĐỰNG được (sức nặng, nóng lạnh, áp lực). 堪える(たえる): CHỊU NỔI, ĐÁNG (cảm xúc; 見るに堪えない = không đáng xem). 絶える(たえる): TẮT, ĐỨT, chấm dứt.","items":[{"word":"耐える","reading":"たえる","meaning":"chịu đựng (sức nặng, nóng lạnh)","example":"この建物は地震に耐えられる設計です。","example_reading":"このたてものはじしんにたえられるせっけいです。","example_meaning":"Tòa nhà này được thiết kế để chịu được động đất.","examples":[{"example":"厳しい寒さに耐えて、冬を過ごしました。","example_reading":"きびしいさむさにたえて、ふゆをすごしました。","example_meaning":"Tôi đã chịu đựng cái lạnh khắc nghiệt để vượt qua mùa đông."},{"example":"この素材は高い温度にも耐えます。","example_reading":"このそざいはたかいおんどにもたえます。","example_meaning":"Vật liệu này chịu được cả nhiệt độ cao."}]},{"word":"堪える","reading":"たえる","meaning":"chịu nổi (cảm xúc); đáng (làm gì)","example":"悲しみに堪えられず、涙が出ました。","example_reading":"かなしみにたえられず、なみだがでました。","example_meaning":"Không chịu nổi nỗi buồn nên tôi đã rơi nước mắt.","examples":[{"example":"この映画は、見るに堪えないほどひどい内容でした。","example_reading":"このえいがは、みるにたえないほどひどいないようでした。","example_meaning":"Bộ phim này có nội dung tệ đến mức không đáng xem."},{"example":"その苦しみは、とても堪えがたいものでした。","example_reading":"そのくるしみは、とてもたえがたいものでした。","example_meaning":"Nỗi đau đó thật khó mà chịu nổi."}]},{"word":"絶える","reading":"たえる","meaning":"tắt, đứt, chấm dứt","example":"彼の店には、お客さんの出入りが絶えません。","example_reading":"かれのみせには、おきゃくさんのでいりがたえません。","example_meaning":"Cửa hàng của anh ấy khách ra vào không ngớt.","examples":[{"example":"雪のため、連絡が絶えてしまいました。","example_reading":"ゆきのため、れんらくがたえてしまいました。","example_meaning":"Vì tuyết nên liên lạc bị gián đoạn."},{"example":"家族の笑顔が絶えない、明るい家です。","example_reading":"かぞくのえがおがたえない、あかるいいえです。","example_meaning":"Đó là một ngôi nhà tươi sáng, nụ cười của gia đình không bao giờ tắt."}]}]},
{"label":"沸く／湧く","note":"沸く(わく): SÔI (nước), nóng lên; (đám đông) SÔI NỔI. 湧く(わく): TRÀO RA, PHUN RA (suối, nước) và (cảm xúc, ý tưởng) nảy sinh.","items":[{"word":"沸く","reading":"わく","meaning":"sôi (nước); sôi nổi (đám đông)","example":"お湯が沸いたら、火を止めてください。","example_reading":"おゆがわいたら、ひをとめてください。","example_meaning":"Khi nước sôi thì hãy tắt bếp.","examples":[{"example":"お風呂が沸いたので、先に入ってください。","example_reading":"おふろがわいたので、さきにはいってください。","example_meaning":"Nước tắm đã nóng rồi, mời bạn vào tắm trước."},{"example":"優勝が決まると、会場が沸きました。","example_reading":"ゆうしょうがきまると、かいじょうがわきました。","example_meaning":"Khi quyết định vô địch được công bố, cả hội trường sôi sục."}]},{"word":"湧く","reading":"わく","meaning":"trào ra, phun ra; nảy sinh (cảm xúc)","example":"この山では、きれいな水が湧いています。","example_reading":"このやまでは、きれいなみずがわいています。","example_meaning":"Ở ngọn núi này có nguồn nước sạch trào ra.","examples":[{"example":"新しい仕事に、やる気が湧いてきました。","example_reading":"あたらしいしごとに、やるきがわいてきました。","example_meaning":"Tôi đã nảy sinh động lực với công việc mới."},{"example":"この島では、温泉が湧いています。","example_reading":"このしまでは、おんせんがわいています。","example_meaning":"Trên hòn đảo này có suối nước nóng phun lên."}]}]},
{"label":"冷める／覚める／醒める","note":"冷める(さめる): NGUỘI đi; nhiệt tình NGUÔI. 覚める(さめる): TỈNH (ngủ, mơ; 目が覚める). 醒める(さめる): TỈNH (say rượu), tỉnh ngộ.","items":[{"word":"冷める","reading":"さめる","meaning":"nguội đi; nhạt đi (tình cảm)","example":"スープが冷めないうちに、飲んでください。","example_reading":"スープがさめないうちに、のんでください。","example_meaning":"Hãy uống súp trước khi nó nguội.","examples":[{"example":"彼への気持ちは、もう冷めてしまいました。","example_reading":"かれへのきもちは、もうさめてしまいました。","example_meaning":"Tình cảm của tôi dành cho anh ấy đã nguội rồi."},{"example":"コーヒーが冷めて、まずくなりました。","example_reading":"コーヒーがさめて、まずくなりました。","example_meaning":"Cà phê nguội nên trở nên dở."}]},{"word":"覚める","reading":"さめる","meaning":"tỉnh (giấc ngủ, giấc mơ)","example":"今朝は五時に目が覚めました。","example_reading":"けさはごじにめがさめました。","example_meaning":"Sáng nay tôi tỉnh dậy lúc năm giờ.","examples":[{"example":"大きな音で、びっくりして目が覚めました。","example_reading":"おおきなおとで、びっくりしてめがさめました。","example_meaning":"Vì tiếng động lớn nên tôi giật mình tỉnh giấc."},{"example":"夢から覚めたとき、朝になっていました。","example_reading":"ゆめからさめたとき、あさになっていました。","example_meaning":"Khi tỉnh khỏi giấc mơ thì trời đã sáng."}]},{"word":"醒める","reading":"さめる","meaning":"tỉnh (say), tỉnh ngộ","example":"酔いが醒めるまで、運転してはいけません。","example_reading":"よいがさめるまで、うんてんしてはいけません。","example_meaning":"Chưa hết say thì không được lái xe.","examples":[{"example":"冷たい風に当たって、酔いが醒めました。","example_reading":"つめたいかぜにあたって、よいがさめました。","example_meaning":"Hứng gió lạnh nên tôi đã tỉnh rượu."},{"example":"彼の言葉で、私は迷いから醒めました。","example_reading":"かれのことばで、わたしはまよいからさめました。","example_meaning":"Nhờ lời nói của anh ấy mà tôi tỉnh ngộ khỏi sự phân vân."}]}]},
{"label":"冷ます／覚ます","note":"冷ます(さます): làm cho NGUỘI (đồ ăn thức uống). 覚ます(さます): làm TỈNH, đánh thức (目を覚ます, 眠気を覚ます).","items":[{"word":"冷ます","reading":"さます","meaning":"làm nguội","example":"お茶を少し冷ましてから飲みます。","example_reading":"おちゃをすこしさましてからのみます。","example_meaning":"Tôi để trà nguội bớt rồi mới uống.","examples":[{"example":"熱いスープをふうふうして冷ましました。","example_reading":"あついスープをふうふうしてさましました。","example_meaning":"Tôi thổi phù phù để làm nguội món súp nóng."},{"example":"焼きたてのパンを、冷ましてから袋に入れます。","example_reading":"やきたてのパンを、さましてからふくろにいれます。","example_meaning":"Bánh mì mới nướng thì để nguội rồi mới cho vào túi."}]},{"word":"覚ます","reading":"さます","meaning":"làm tỉnh, đánh thức","example":"赤ちゃんが目を覚ましました。","example_reading":"あかちゃんがめをさましました。","example_meaning":"Em bé đã tỉnh giấc.","examples":[{"example":"コーヒーを飲んで、眠気を覚まします。","example_reading":"コーヒーをのんで、ねむけをさまします。","example_meaning":"Tôi uống cà phê để xua cơn buồn ngủ."},{"example":"大きな物音で、家族が目を覚ましました。","example_reading":"おおきなものおとで、かぞくがめをさましました。","example_meaning":"Vì tiếng động lớn mà cả nhà đã thức giấc."}]}]},
{"label":"飼う／買う","note":"飼う(かう): NUÔI (động vật, thú cưng). 買う(かう): MUA; (nghĩa bóng) đánh giá cao.","items":[{"word":"飼う","reading":"かう","meaning":"nuôi (động vật)","example":"我が家では、犬を二匹飼っています。","example_reading":"わがやでは、いぬをにひきかっています。","example_meaning":"Nhà tôi nuôi hai con chó.","examples":[{"example":"マンションなので、ペットは飼えません。","example_reading":"マンションなので、ペットはかえません。","example_meaning":"Vì là chung cư nên không nuôi được thú cưng."},{"example":"子供のころ、金魚を飼っていました。","example_reading":"こどものころ、きんぎょをかっていました。","example_meaning":"Hồi nhỏ tôi đã nuôi cá vàng."}]},{"word":"買う","reading":"かう","meaning":"mua; đánh giá cao","example":"スーパーで牛乳を買いました。","example_reading":"スーパーでぎゅうにゅうをかいました。","example_meaning":"Tôi đã mua sữa ở siêu thị.","examples":[{"example":"新しいスマホを買うために、お金を貯めています。","example_reading":"あたらしいスマホをかうために、おかねをためています。","example_meaning":"Tôi đang tiết kiệm tiền để mua điện thoại mới."},{"example":"彼の才能を買って、リーダーに選びました。","example_reading":"かれのさいのうをかって、リーダーにえらびました。","example_meaning":"Đánh giá cao tài năng của anh ấy nên chúng tôi đã chọn anh làm trưởng nhóm."}]}]},
{"label":"習う／倣う","note":"習う(ならう): HỌC (kỹ năng, môn) từ thầy. 倣う(ならう): NOI THEO, BẮT CHƯỚC, làm theo tiền lệ/tấm gương.","items":[{"word":"習う","reading":"ならう","meaning":"học (từ người dạy)","example":"子供のころ、ピアノを習っていました。","example_reading":"こどものころ、ピアノをならっていました。","example_meaning":"Hồi nhỏ tôi từng học piano.","examples":[{"example":"友達に日本料理の作り方を習いました。","example_reading":"ともだちににほんりょうりのつくりかたをならいました。","example_meaning":"Tôi đã học bạn cách nấu món Nhật."},{"example":"毎週、先生に書道を習っています。","example_reading":"まいしゅう、せんせいにしょどうをならっています。","example_meaning":"Mỗi tuần tôi học thư pháp với thầy."}]},{"word":"倣う","reading":"ならう","meaning":"noi theo, bắt chước","example":"先輩に倣って、毎朝早く出社しています。","example_reading":"せんぱいにならって、まいあさはやくしゅっしゃしています。","example_meaning":"Noi gương đàn anh, mỗi sáng tôi đều đến công ty sớm.","examples":[{"example":"前例に倣って、手続きを進めます。","example_reading":"ぜんれいにならって、てつづきをすすめます。","example_meaning":"Chúng tôi tiến hành thủ tục theo tiền lệ."},{"example":"彼の生き方に倣いたいと思います。","example_reading":"かれのいきかたにならいたいとおもいます。","example_meaning":"Tôi muốn noi theo cách sống của anh ấy."}]}]},
{"label":"治る／直る","note":"治る(なおる): KHỎI (bệnh, vết thương). 直る(なおる): được SỬA, hết hỏng; được chỉnh lại (thói quen, tâm trạng).","items":[{"word":"治る","reading":"なおる","meaning":"khỏi (bệnh, vết thương)","example":"風邪が治るまで、家で休みます。","example_reading":"かぜがなおるまで、いえでやすみます。","example_meaning":"Tôi sẽ nghỉ ở nhà cho đến khi khỏi cảm.","examples":[{"example":"けがは、一週間で治りました。","example_reading":"けがは、いっしゅうかんでなおりました。","example_meaning":"Vết thương đã lành sau một tuần."},{"example":"薬を飲めば、すぐに治りますよ。","example_reading":"くすりをのめば、すぐになおりますよ。","example_meaning":"Uống thuốc là sẽ khỏi nhanh thôi."}]},{"word":"直る","reading":"なおる","meaning":"được sửa, hết hỏng; được chỉnh lại","example":"壊れたパソコンが直りました。","example_reading":"こわれたパソコンがなおりました。","example_meaning":"Chiếc máy tính hỏng đã được sửa xong.","examples":[{"example":"機嫌が直ったら、また話しましょう。","example_reading":"きげんがなおったら、またはなしましょう。","example_meaning":"Khi nào bạn hết giận thì chúng ta nói chuyện tiếp nhé."},{"example":"彼の悪い癖は、なかなか直りません。","example_reading":"かれのわるいくせは、なかなかなおりません。","example_meaning":"Tật xấu của anh ấy mãi không sửa được."}]}]},
{"label":"吹く／拭く／噴く","note":"吹く(ふく): THỔI (gió, nhạc cụ, hơi thở). 拭く(ふく): LAU, chùi. 噴く(ふく): PHUN, PHỤT ra (núi lửa, hơi nước, nồi trào).","items":[{"word":"吹く","reading":"ふく","meaning":"thổi (gió, nhạc cụ)","example":"今日は強い風が吹いています。","example_reading":"きょうはつよいかぜがふいています。","example_meaning":"Hôm nay gió thổi rất mạnh.","examples":[{"example":"彼はトランペットを吹くのが上手です。","example_reading":"かれはトランペットをふくのがじょうずです。","example_meaning":"Anh ấy thổi kèn trumpet rất giỏi."},{"example":"熱いお茶を冷まそうと、息を吹きかけました。","example_reading":"あついおちゃをさまそうと、いきをふきかけました。","example_meaning":"Tôi thổi hơi vào tách trà nóng để làm nguội."}]},{"word":"拭く","reading":"ふく","meaning":"lau, chùi","example":"雑巾でテーブルを拭きます。","example_reading":"ぞうきんでテーブルをふきます。","example_meaning":"Tôi lau bàn bằng giẻ lau.","examples":[{"example":"濡れた手をタオルで拭きました。","example_reading":"ぬれたてをタオルでふきました。","example_meaning":"Tôi lau bàn tay ướt bằng khăn."},{"example":"窓ガラスをきれいに拭いてください。","example_reading":"まどガラスをきれいにふいてください。","example_meaning":"Hãy lau kính cửa sổ cho sạch."}]},{"word":"噴く","reading":"ふく","meaning":"phun, phụt ra","example":"火山が火を噴きました。","example_reading":"かざんがひをふきました。","example_meaning":"Núi lửa đã phun lửa.","examples":[{"example":"鍋が噴いているので、火を弱めてください。","example_reading":"なべがふいているので、ひをよわめてください。","example_meaning":"Nồi đang trào nên hãy vặn nhỏ lửa."},{"example":"クジラが潮を噴いているのが見えました。","example_reading":"クジラがしおをふいているのがみえました。","example_meaning":"Tôi đã thấy con cá voi đang phun nước."}]}]},
{"label":"張る／貼る","note":"張る(はる): CĂNG, GIĂNG (lều, dây); (băng) ĐÓNG; cố chấp, giữ (意地). 貼る(はる): DÁN (tem, giấy, miếng dán) lên bề mặt.","items":[{"word":"張る","reading":"はる","meaning":"căng, giăng; đóng (băng)","example":"公園にテントを張りました。","example_reading":"こうえんにテントをはりました。","example_meaning":"Chúng tôi đã dựng lều ở công viên.","examples":[{"example":"池に氷が張っています。","example_reading":"いけにこおりがはっています。","example_meaning":"Mặt ao đã đóng băng."},{"example":"彼は意地を張って、謝ろうとしません。","example_reading":"かれはいじをはって、あやまろうとしません。","example_meaning":"Anh ấy cứng đầu nên không chịu xin lỗi."}]},{"word":"貼る","reading":"はる","meaning":"dán","example":"封筒に切手を貼ります。","example_reading":"ふうとうにきってをはります。","example_meaning":"Tôi dán tem lên phong bì.","examples":[{"example":"壁にポスターを貼りました。","example_reading":"かべにポスターをはりました。","example_meaning":"Tôi đã dán áp phích lên tường."},{"example":"傷口に絆創膏を貼ってください。","example_reading":"きずぐちにばんそうこうをはってください。","example_meaning":"Hãy dán băng cá nhân lên vết thương."}]}]},
{"label":"刷る／擦る","note":"刷る(する): IN (ấn loát: danh thiếp, áp phích, sách). 擦る(する): CỌ, XÁT, quẹt (diêm), lê (chân) sát bề mặt.","items":[{"word":"刷る","reading":"する","meaning":"in (ấn loát)","example":"名刺を百枚刷りました。","example_reading":"めいしをひゃくまいすりました。","example_meaning":"Tôi đã in một trăm tấm danh thiếp.","examples":[{"example":"このポスターは、五色で刷られています。","example_reading":"このポスターは、ごしょくですられています。","example_meaning":"Áp phích này được in bằng năm màu."},{"example":"招待状を刷って、みんなに送ります。","example_reading":"しょうたいじょうをすって、みんなにおくります。","example_meaning":"Tôi sẽ in thiệp mời rồi gửi cho mọi người."}]},{"word":"擦る","reading":"する","meaning":"cọ, xát, quẹt","example":"寒いので、両手を擦って温めました。","example_reading":"さむいので、りょうてをすってあたためました。","example_meaning":"Vì lạnh nên tôi xoa hai bàn tay cho ấm.","examples":[{"example":"マッチを擦って、ろうそくに火をつけました。","example_reading":"マッチをすって、ろうそくにひをつけました。","example_meaning":"Tôi quẹt diêm rồi thắp nến."},{"example":"靴で床を擦って歩かないでください。","example_reading":"くつでゆかをすってあるかないでください。","example_meaning":"Xin đừng lê giày sát sàn khi đi."}]}]},
{"label":"乗せる／載せる","note":"乗せる(のせる): cho (người) LÊN xe, phương tiện; cho tham gia. 載せる(のせる): ĐẶT, CHẤT đồ vật lên; ĐĂNG (bài, ảnh) lên báo, mạng.","items":[{"word":"乗せる","reading":"のせる","meaning":"cho (người) lên xe/phương tiện","example":"子供を自転車の後ろに乗せました。","example_reading":"こどもをじてんしゃのうしろにのせました。","example_meaning":"Tôi đã chở con ngồi phía sau xe đạp.","examples":[{"example":"友達を車に乗せて、駅まで送りました。","example_reading":"ともだちをくるまにのせて、えきまでおくりました。","example_meaning":"Tôi cho bạn lên xe rồi đưa đến ga."},{"example":"お客さんをタクシーに乗せて、見送りました。","example_reading":"おきゃくさんをタクシーにのせて、みおくりました。","example_meaning":"Tôi tiễn khách lên taxi."}]},{"word":"載せる","reading":"のせる","meaning":"đặt, chất lên; đăng","example":"荷物を棚に載せてください。","example_reading":"にもつをたなにのせてください。","example_meaning":"Hãy đặt hành lý lên giá.","examples":[{"example":"旅行の写真をブログに載せました。","example_reading":"りょこうのしゃしんをブログにのせました。","example_meaning":"Tôi đã đăng ảnh du lịch lên blog."},{"example":"ケーキにいちごを載せます。","example_reading":"ケーキにいちごをのせます。","example_meaning":"Tôi đặt dâu tây lên bánh."}]}]},
{"label":"閉める／締める／絞める","note":"閉める(しめる): ĐÓNG (cửa, cửa hàng). 締める(しめる): THẮT, SIẾT CHẶT (cà vạt, ốc vít, dây an toàn). 絞める(しめる): SIẾT, BÓP (cổ).","items":[{"word":"閉める","reading":"しめる","meaning":"đóng (cửa, cửa hàng)","example":"寒いので、窓を閉めてください。","example_reading":"さむいので、まどをしめてください。","example_meaning":"Lạnh quá nên hãy đóng cửa sổ lại.","examples":[{"example":"店は夜十時に閉めます。","example_reading":"みせはよるじゅうじにしめます。","example_meaning":"Cửa hàng đóng cửa lúc mười giờ tối."},{"example":"出かけるとき、ドアを閉めるのを忘れました。","example_reading":"でかけるとき、ドアをしめるのをわすれました。","example_meaning":"Lúc ra ngoài tôi đã quên đóng cửa."}]},{"word":"締める","reading":"しめる","meaning":"thắt, siết chặt","example":"ネクタイを締めて、面接に行きました。","example_reading":"ネクタイをしめて、めんせつにいきました。","example_meaning":"Tôi thắt cà vạt rồi đi phỏng vấn.","examples":[{"example":"ネジをしっかり締めてください。","example_reading":"ネジをしっかりしめてください。","example_meaning":"Hãy siết chặt con ốc vít."},{"example":"シートベルトを締めるのを忘れないでください。","example_reading":"シートベルトをしめるのをわすれないでください。","example_meaning":"Xin đừng quên thắt dây an toàn."}]},{"word":"絞める","reading":"しめる","meaning":"siết, bóp (cổ)","example":"彼は腕で相手の首を絞めました。","example_reading":"かれはうでであいてのくびをしめました。","example_meaning":"Anh ta dùng cánh tay siết cổ đối phương.","examples":[{"example":"鶏を絞めて、料理に使います。","example_reading":"にわとりをしめて、りょうりにつかいます。","example_meaning":"Tôi giết gà rồi dùng để nấu ăn."},{"example":"首を絞められたような息苦しさを感じました。","example_reading":"くびをしめられたようないきぐるしさをかんじました。","example_meaning":"Tôi cảm thấy ngột ngạt như bị bóp cổ."}]}]},
{"label":"悲しい／哀しい","note":"悲しい(かなしい): BUỒN (thông dụng nhất). 哀しい(かなしい): BUỒN THƯƠNG, bi ai, man mác (sắc thái văn chương, sâu lắng).","items":[{"word":"悲しい","reading":"かなしい","meaning":"buồn","example":"友達と別れるのは悲しいです。","example_reading":"ともだちとわかれるのはかなしいです。","example_meaning":"Chia tay bạn bè thật buồn.","examples":[{"example":"悲しい知らせを聞いて、涙が出ました。","example_reading":"かなしいしらせをきいて、なみだがでました。","example_meaning":"Nghe tin buồn, tôi đã rơi nước mắt."},{"example":"犬が死んで、とても悲しかったです。","example_reading":"いぬがしんで、とてもかなしかったです。","example_meaning":"Con chó chết đi nên tôi rất buồn."}]},{"word":"哀しい","reading":"かなしい","meaning":"buồn thương, bi ai","example":"哀しい旋律が、静かに流れていました。","example_reading":"かなしいせんりつが、しずかにながれていました。","example_meaning":"Một giai điệu buồn thương lặng lẽ ngân lên.","examples":[{"example":"夕暮れの海は、どこか哀しい色をしていました。","example_reading":"ゆうぐれのうみは、どこかかなしいいろをしていました。","example_meaning":"Biển lúc hoàng hôn mang một sắc màu buồn man mác."},{"example":"戦争の哀しい歴史を、忘れてはいけません。","example_reading":"せんそうのかなしいれきしを、わすれてはいけません。","example_meaning":"Chúng ta không được quên lịch sử bi thương của chiến tranh."}]}]},
{"label":"易しい／優しい","note":"易しい(やさしい): DỄ, đơn giản (ngược với 難しい). 優しい(やさしい): HIỀN, TỐT BỤNG, dịu dàng (tính cách, thái độ).","items":[{"word":"易しい","reading":"やさしい","meaning":"dễ, đơn giản","example":"この問題は易しいので、すぐに解けます。","example_reading":"このもんだいはやさしいので、すぐにとけます。","example_meaning":"Bài này dễ nên giải được ngay.","examples":[{"example":"初心者向けの、易しい日本語で書かれた本です。","example_reading":"しょしんしゃむけの、やさしいにほんごでかかれたほんです。","example_meaning":"Đây là cuốn sách dành cho người mới học, viết bằng tiếng Nhật dễ hiểu."},{"example":"先生は、易しい言葉で説明してくれました。","example_reading":"せんせいは、やさしいことばでせつめいしてくれました。","example_meaning":"Thầy đã giải thích bằng những từ ngữ dễ hiểu."}]},{"word":"優しい","reading":"やさしい","meaning":"hiền, tốt bụng, dịu dàng","example":"彼女はとても優しい人です。","example_reading":"かのじょはとてもやさしいひとです。","example_meaning":"Cô ấy là người rất hiền dịu.","examples":[{"example":"優しい声で、子供に話しかけました。","example_reading":"やさしいこえで、こどもにはなしかけました。","example_meaning":"Tôi nói chuyện với đứa bé bằng giọng dịu dàng."},{"example":"友達の優しい言葉に、励まされました。","example_reading":"ともだちのやさしいことばに、はげまされました。","example_meaning":"Tôi được tiếp thêm động lực nhờ những lời dịu dàng của bạn."}]}]},
{"label":"良い／善い","note":"良い(よい): TỐT (chất lượng, trạng thái, điều kiện) — thông dụng nhất. 善い(よい): TỐT về mặt ĐẠO ĐỨC, thiện (ngược với 悪い); ít dùng, thường viết 良い hoặc よい.","items":[{"word":"良い","reading":"よい","meaning":"tốt (chất lượng, trạng thái)","example":"今日は天気が良いので、散歩に行きます。","example_reading":"きょうはてんきがよいので、さんぽにいきます。","example_meaning":"Hôm nay thời tiết đẹp nên tôi đi dạo.","examples":[{"example":"この店は、品質が良いと評判です。","example_reading":"このみせは、ひんしつがよいとひょうばんです。","example_meaning":"Cửa hàng này nổi tiếng về chất lượng tốt."},{"example":"気持ちの良い朝ですね。","example_reading":"きもちのよいあさですね。","example_meaning":"Một buổi sáng thật dễ chịu nhỉ."}]},{"word":"善い","reading":"よい","meaning":"tốt (đạo đức), thiện","example":"善い行いをすれば、必ず報われます。","example_reading":"よいおこないをすれば、かならずむくわれます。","example_meaning":"Làm việc thiện thì nhất định sẽ được báo đáp.","examples":[{"example":"何が善くて何が悪いのか、自分で考えなさい。","example_reading":"なにがよくてなにがわるいのか、じぶんでかんがえなさい。","example_meaning":"Hãy tự suy nghĩ xem điều gì tốt, điều gì xấu."},{"example":"彼は、善い人として皆に慕われています。","example_reading":"かれは、よいひととしてみんなにしたわれています。","example_meaning":"Anh ấy được mọi người quý mến vì là người lương thiện."}]}]},
{"label":"橋／箸／端","note":"橋(はし): CÂY CẦU. 箸(はし): ĐŨA. 端(はし): MÉP, RÌA, ĐẦU MÚT. (Ba từ này khác nhau về trọng âm/accent, tùy vùng.)","items":[{"word":"橋","reading":"はし","meaning":"cây cầu","example":"川に新しい橋ができました。","example_reading":"かわにあたらしいはしができました。","example_meaning":"Trên sông đã xây xong một cây cầu mới.","examples":[{"example":"あの橋を渡ると、駅があります。","example_reading":"あのはしをわたると、えきがあります。","example_meaning":"Qua cây cầu kia là có nhà ga."},{"example":"古い木の橋が、観光名所になっています。","example_reading":"ふるいきのはしが、かんこうめいしょになっています。","example_meaning":"Cây cầu gỗ cũ đã trở thành địa điểm tham quan."}]},{"word":"箸","reading":"はし","meaning":"đũa","example":"日本人は、箸でご飯を食べます。","example_reading":"にほんじんは、はしでごはんをたべます。","example_meaning":"Người Nhật ăn cơm bằng đũa.","examples":[{"example":"箸の持ち方を、母に教わりました。","example_reading":"はしのもちかたを、ははにおそわりました。","example_meaning":"Tôi được mẹ dạy cách cầm đũa."},{"example":"コンビニで、割り箸をもらいました。","example_reading":"コンビニで、わりばしをもらいました。","example_meaning":"Tôi đã xin đũa dùng một lần ở cửa hàng tiện lợi."}]},{"word":"端","reading":"はし","meaning":"mép, rìa, đầu mút","example":"道の端を歩いてください。","example_reading":"みちのはしをあるいてください。","example_meaning":"Hãy đi sát lề đường.","examples":[{"example":"机の端に、コップを置きました。","example_reading":"つくえのはしに、コップをおきました。","example_meaning":"Tôi đặt chiếc cốc ở mép bàn."},{"example":"紙の端が、少し破れています。","example_reading":"かみのはしが、すこしやぶれています。","example_meaning":"Mép tờ giấy hơi bị rách."}]}]},
{"label":"雨／飴","note":"雨(あめ): MƯA. 飴(あめ): KẸO (kẹo cứng, kẹo mạch nha). Khác nhau về trọng âm: 雨 あ↓め, 飴 あめ↓ (giọng Tokyo).","items":[{"word":"雨","reading":"あめ","meaning":"mưa","example":"昨日は一日中、雨でした。","example_reading":"きのうはいちにちじゅう、あめでした。","example_meaning":"Hôm qua cả ngày trời mưa.","examples":[{"example":"雨が止んだら、出かけましょう。","example_reading":"あめがやんだら、でかけましょう。","example_meaning":"Khi nào mưa tạnh thì chúng ta đi nhé."},{"example":"傘を忘れて、雨にぬれてしまいました。","example_reading":"かさをわすれて、あめにぬれてしまいました。","example_meaning":"Tôi quên mang ô nên bị ướt mưa."}]},{"word":"飴","reading":"あめ","meaning":"kẹo (cứng)","example":"喉が痛いので、のど飴をなめています。","example_reading":"のどがいたいので、のどあめをなめています。","example_meaning":"Vì đau họng nên tôi đang ngậm kẹo ngậm.","examples":[{"example":"おばあちゃんは、いつも飴をくれます。","example_reading":"おばあちゃんは、いつもあめをくれます。","example_meaning":"Bà lúc nào cũng cho tôi kẹo."},{"example":"子供が飴を口に入れて、にこにこしています。","example_reading":"こどもがあめをくちにいれて、にこにこしています。","example_meaning":"Đứa bé ngậm kẹo trong miệng và cười tươi."}]}]},
{"label":"神／紙／髪","note":"神(かみ): THẦN, thần linh. 紙(かみ): GIẤY. 髪(かみ): TÓC trên đầu.","items":[{"word":"神","reading":"かみ","meaning":"thần, thần linh","example":"初詣で、神に願い事をしました。","example_reading":"はつもうで、かみにねがいごとをしました。","example_meaning":"Trong lễ viếng đền đầu năm, tôi đã cầu nguyện thần linh.","examples":[{"example":"この島では、山を神として祀っています。","example_reading":"このしまでは、やまをかみとしてまつっています。","example_meaning":"Ở hòn đảo này, người ta thờ ngọn núi như một vị thần."},{"example":"日本には、八百万の神がいると言われています。","example_reading":"にほんには、やおよろずのかみがいるといわれています。","example_meaning":"Người ta nói rằng ở Nhật Bản có tám triệu vị thần."}]},{"word":"紙","reading":"かみ","meaning":"giấy","example":"紙に名前と住所を書いてください。","example_reading":"かみになまえとじゅうしょをかいてください。","example_meaning":"Hãy viết tên và địa chỉ lên giấy.","examples":[{"example":"この紙はリサイクルされたものです。","example_reading":"このかみはリサイクルされたものです。","example_meaning":"Loại giấy này được làm từ vật liệu tái chế."},{"example":"折り紙で、鶴を折りました。","example_reading":"おりがみで、つるをおりました。","example_meaning":"Tôi đã gấp con hạc bằng giấy origami."}]},{"word":"髪","reading":"かみ","meaning":"tóc","example":"美容院で髪を切りました。","example_reading":"びよういんでかみをきりました。","example_meaning":"Tôi đã cắt tóc ở tiệm làm tóc.","examples":[{"example":"彼女は長い髪を、後ろで結んでいます。","example_reading":"かのじょはながいかみを、うしろでむすんでいます。","example_meaning":"Cô ấy buộc mái tóc dài ra phía sau."},{"example":"風で髪が乱れてしまいました。","example_reading":"かぜでかみがみだれてしまいました。","example_meaning":"Tóc tôi bị gió thổi rối tung."}]}]},
{"label":"花／鼻","note":"花(はな): HOA. 鼻(はな): MŨI.","items":[{"word":"花","reading":"はな","meaning":"hoa","example":"庭に赤い花が咲いています。","example_reading":"にわにあかいはながさいています。","example_meaning":"Trong vườn có những bông hoa đỏ đang nở.","examples":[{"example":"母の日に、花をプレゼントしました。","example_reading":"ははのひに、はなをプレゼントしました。","example_meaning":"Vào Ngày của Mẹ, tôi đã tặng hoa."},{"example":"春になると、桜の花が一斉に咲きます。","example_reading":"はるになると、さくらのはながいっせいにさきます。","example_meaning":"Cứ đến mùa xuân là hoa anh đào đồng loạt nở."}]},{"word":"鼻","reading":"はな","meaning":"mũi","example":"風邪で、鼻が詰まっています。","example_reading":"かぜで、はながつまっています。","example_meaning":"Vì cảm nên tôi bị nghẹt mũi.","examples":[{"example":"彼は鼻が高くて、かっこいいです。","example_reading":"かれははながたかくて、かっこいいです。","example_meaning":"Anh ấy có sống mũi cao nên trông rất ngầu."},{"example":"花粉症で、鼻水が止まりません。","example_reading":"かふんしょうで、はなみずがとまりません。","example_meaning":"Tôi bị dị ứng phấn hoa nên chảy mũi mãi không dứt."}]}]},
{"label":"柿／垣／牡蠣","note":"柿(かき): quả HỒNG. 垣(かき): HÀNG RÀO, tường rào. 牡蠣(かき): con HÀU.","items":[{"word":"柿","reading":"かき","meaning":"quả hồng","example":"秋になると、柿がおいしくなります。","example_reading":"あきになると、かきがおいしくなります。","example_meaning":"Cứ đến mùa thu là hồng trở nên ngon.","examples":[{"example":"祖父の庭に、大きな柿の木があります。","example_reading":"そふのにわに、おおきなかきのきがあります。","example_meaning":"Trong vườn nhà ông tôi có một cây hồng lớn."},{"example":"干し柿は、日本の伝統的なお菓子です。","example_reading":"ほしがきは、にほんのでんとうてきなおかしです。","example_meaning":"Hồng khô là loại bánh kẹo truyền thống của Nhật Bản."}]},{"word":"垣","reading":"かき","meaning":"hàng rào","example":"庭の周りに、低い垣を作りました。","example_reading":"にわのまわりに、ひくいかきをつくりました。","example_meaning":"Tôi đã làm một hàng rào thấp quanh khu vườn.","examples":[{"example":"隣の家との間に、垣があります。","example_reading":"となりのいえとのあいだに、かきがあります。","example_meaning":"Giữa nhà tôi và nhà bên cạnh có một hàng rào."},{"example":"垣の向こうから、猫が顔を出しました。","example_reading":"かきのむこうから、ねこがかおをだしました。","example_meaning":"Một con mèo ló mặt ra từ phía bên kia hàng rào."}]},{"word":"牡蠣","reading":"かき","meaning":"con hàu","example":"冬は、牡蠣がおいしい季節です。","example_reading":"ふゆは、かきがおいしいきせつです。","example_meaning":"Mùa đông là mùa hàu ngon.","examples":[{"example":"広島では、牡蠣料理が有名です。","example_reading":"ひろしまでは、かきりょうりがゆうめいです。","example_meaning":"Ở Hiroshima, các món từ hàu rất nổi tiếng."},{"example":"生の牡蠣を食べて、お腹をこわしました。","example_reading":"なまのかきをたべて、おなかをこわしました。","example_meaning":"Tôi ăn hàu sống nên bị đau bụng."}]}]},
{"label":"海／膿","note":"海(うみ): BIỂN. 膿(うみ): MỦ (ở vết thương, mụn nhọt).","items":[{"word":"海","reading":"うみ","meaning":"biển","example":"夏休みに、家族で海へ行きました。","example_reading":"なつやすみに、かぞくでうみへいきました。","example_meaning":"Kỳ nghỉ hè, cả nhà tôi đã đi biển.","examples":[{"example":"この海は、とても透明できれいです。","example_reading":"このうみは、とてもとうめいできれいです。","example_meaning":"Biển này rất trong và đẹp."},{"example":"日本は、四方を海に囲まれた国です。","example_reading":"にほんは、しほうをうみにかこまれたくにです。","example_meaning":"Nhật Bản là đất nước bốn bề được biển bao quanh."}]},{"word":"膿","reading":"うみ","meaning":"mủ","example":"傷口から膿が出ています。","example_reading":"きずぐちからうみがでています。","example_meaning":"Vết thương đang chảy mủ.","examples":[{"example":"腫れた所を切って、膿を出しました。","example_reading":"はれたところをきって、うみをだしました。","example_meaning":"Bác sĩ đã rạch chỗ sưng để dẫn mủ ra."},{"example":"傷に膿がたまって、医者に診てもらいました。","example_reading":"きずにうみがたまって、いしゃにみてもらいました。","example_meaning":"Vết thương tích mủ nên tôi đã đi khám bác sĩ."}]}]},
{"label":"追求／追及／追究","note":"追求(ついきゅう): THEO ĐUỔI mục tiêu (lợi nhuận, hạnh phúc, lý tưởng). 追及(ついきゅう): TRUY CỨU, vặn hỏi trách nhiệm, truy đuổi đến cùng. 追究(ついきゅう): TRUY TÌM, nghiên cứu đến tận cùng (chân lý, nguyên nhân).","items":[{"word":"追求","reading":"ついきゅう","meaning":"theo đuổi (mục tiêu, lợi ích)","example":"彼は、利益だけを追求する経営者です。","example_reading":"かれは、りえきだけをついきゅうするけいえいしゃです。","example_meaning":"Ông ấy là nhà quản lý chỉ chạy theo lợi nhuận.","examples":[{"example":"若い人たちは、自分の幸せを追求しています。","example_reading":"わかいひとたちは、じぶんのしあわせをついきゅうしています。","example_meaning":"Những người trẻ đang theo đuổi hạnh phúc của riêng mình."},{"example":"この会社は、品質の高さを追求しています。","example_reading":"このかいしゃは、ひんしつのたかさをついきゅうしています。","example_meaning":"Công ty này theo đuổi chất lượng cao."}]},{"word":"追及","reading":"ついきゅう","meaning":"truy cứu (trách nhiệm), vặn hỏi","example":"記者は、大臣の責任を厳しく追及しました。","example_reading":"きしゃは、だいじんのせきにんをきびしくついきゅうしました。","example_meaning":"Phóng viên đã truy cứu gay gắt trách nhiệm của bộ trưởng.","examples":[{"example":"警察は、事件の犯人を追及しています。","example_reading":"けいさつは、じけんのはんにんをついきゅうしています。","example_meaning":"Cảnh sát đang truy tìm thủ phạm của vụ án."},{"example":"彼は、会議で社長に問題を追及されました。","example_reading":"かれは、かいぎでしゃちょうにもんだいをついきゅうされました。","example_meaning":"Anh ấy bị giám đốc chất vấn về vấn đề trong cuộc họp."}]},{"word":"追究","reading":"ついきゅう","meaning":"truy tìm, nghiên cứu đến cùng (chân lý)","example":"科学者は、真理を追究し続けています。","example_reading":"かがくしゃは、しんりをついきゅうしつづけています。","example_meaning":"Các nhà khoa học vẫn tiếp tục truy tìm chân lý.","examples":[{"example":"事故の原因を追究して、再発を防ぎます。","example_reading":"じこのげんいんをついきゅうして、さいはつをふせぎます。","example_meaning":"Chúng tôi tìm hiểu đến cùng nguyên nhân tai nạn để ngăn tái diễn."},{"example":"彼は、一生をかけて言語の起源を追究しました。","example_reading":"かれは、いっしょうをかけてげんごのきげんをついきゅうしました。","example_meaning":"Ông đã dành cả đời để nghiên cứu nguồn gốc của ngôn ngữ."}]}]},
{"label":"回答／解答","note":"回答(かいとう): TRẢ LỜI (câu hỏi, thư từ, khảo sát, yêu cầu). 解答(かいとう): GIẢI ĐÁP, lời giải (bài tập, đề thi).","items":[{"word":"回答","reading":"かいとう","meaning":"trả lời (thư, khảo sát, yêu cầu)","example":"アンケートに回答してください。","example_reading":"アンケートにかいとうしてください。","example_meaning":"Xin hãy trả lời bảng khảo sát.","examples":[{"example":"質問への回答は、来週までにお送りします。","example_reading":"しつもんへのかいとうは、らいしゅうまでにおくります。","example_meaning":"Chúng tôi sẽ gửi câu trả lời cho câu hỏi trước tuần sau."},{"example":"会社から、正式な回答がありました。","example_reading":"かいしゃから、せいしきなかいとうがありました。","example_meaning":"Công ty đã có phản hồi chính thức."}]},{"word":"解答","reading":"かいとう","meaning":"lời giải (bài tập, đề thi)","example":"テストの解答を、先生が配りました。","example_reading":"テストのかいとうを、せんせいがくばりました。","example_meaning":"Thầy giáo đã phát đáp án của bài kiểm tra.","examples":[{"example":"数学の問題の解答が、分かりません。","example_reading":"すうがくのもんだいのかいとうが、わかりません。","example_meaning":"Tôi không biết đáp án của bài toán."},{"example":"解答用紙に、名前を書いてください。","example_reading":"かいとうようしに、なまえをかいてください。","example_meaning":"Hãy ghi tên vào tờ giấy làm bài."}]}]},
{"label":"製作／制作","note":"製作(せいさく): CHẾ TẠO, sản xuất đồ vật, máy móc (thiên về công nghiệp, thủ công). 制作(せいさく): SÁNG TÁC, làm tác phẩm (nghệ thuật, phim, chương trình, thiết kế).","items":[{"word":"製作","reading":"せいさく","meaning":"chế tạo, sản xuất (đồ vật)","example":"工場で、自動車の部品を製作しています。","example_reading":"こうじょうで、じどうしゃのぶひんをせいさくしています。","example_meaning":"Chúng tôi chế tạo phụ tùng ô tô tại nhà máy.","examples":[{"example":"この会社は、精密機械を製作しています。","example_reading":"このかいしゃは、せいみつきかいをせいさくしています。","example_meaning":"Công ty này chế tạo máy móc chính xác."},{"example":"木で、椅子を製作しました。","example_reading":"きで、いすをせいさくしました。","example_meaning":"Tôi đã làm một chiếc ghế bằng gỗ."}]},{"word":"制作","reading":"せいさく","meaning":"sáng tác, làm (tác phẩm, phim)","example":"学生たちが、映画を制作しました。","example_reading":"がくせいたちが、えいがをせいさくしました。","example_meaning":"Các sinh viên đã làm một bộ phim.","examples":[{"example":"彼女は、絵本の制作に取り組んでいます。","example_reading":"かのじょは、えほんのせいさくにとりくんでいます。","example_meaning":"Cô ấy đang dồn sức vào việc sáng tác sách tranh."},{"example":"テレビ番組の制作に関わっています。","example_reading":"テレビばんぐみのせいさくにかかわっています。","example_meaning":"Tôi đang tham gia sản xuất chương trình truyền hình."}]}]},
{"label":"成長／生長","note":"成長(せいちょう): TRƯỞNG THÀNH, PHÁT TRIỂN (người, kinh tế, doanh nghiệp). 生長(せいちょう): SINH TRƯỞNG của thực vật (cây cối, lúa, rau).","items":[{"word":"成長","reading":"せいちょう","meaning":"trưởng thành, phát triển","example":"子供の成長は、本当に早いですね。","example_reading":"こどものせいちょうは、ほんとうにはやいですね。","example_meaning":"Trẻ con lớn nhanh thật đấy.","examples":[{"example":"この会社は、急速に成長しています。","example_reading":"このかいしゃは、きゅうそくにせいちょうしています。","example_meaning":"Công ty này đang phát triển nhanh chóng."},{"example":"経済が成長すると、仕事が増えます。","example_reading":"けいざいがせいちょうすると、しごとがふえます。","example_meaning":"Khi kinh tế tăng trưởng thì việc làm tăng lên."}]},{"word":"生長","reading":"せいちょう","meaning":"sinh trưởng (thực vật)","example":"日当たりのいい場所で、稲が生長します。","example_reading":"ひあたりのいいばしょで、いねがせいちょうします。","example_meaning":"Lúa sinh trưởng ở nơi có nhiều nắng.","examples":[{"example":"植物は、光と水で生長します。","example_reading":"しょくぶつは、ひかりとみずでせいちょうします。","example_meaning":"Thực vật sinh trưởng nhờ ánh sáng và nước."},{"example":"雨のおかげで、野菜がぐんぐん生長しました。","example_reading":"あめのおかげで、やさいがぐんぐんせいちょうしました。","example_meaning":"Nhờ có mưa, rau lớn nhanh vùn vụt."}]}]},
{"label":"異議／意義／異義","note":"異議(いぎ): Ý KIẾN PHẢN ĐỐI (異議あり!). 意義(いぎ): Ý NGHĨA, giá trị (của việc làm, sự tồn tại). 異義(いぎ): NGHĨA KHÁC (như trong 同音異義語).","items":[{"word":"異議","reading":"いぎ","meaning":"ý kiến phản đối","example":"その決定に、異議はありませんか。","example_reading":"そのけっていに、いぎはありませんか。","example_meaning":"Mọi người có phản đối quyết định đó không?","examples":[{"example":"彼は、会議で異議を唱えました。","example_reading":"かれは、かいぎでいぎをとなえました。","example_meaning":"Anh ấy đã lên tiếng phản đối trong cuộc họp."},{"example":"異議がある人は、手を挙げてください。","example_reading":"いぎがあるひとは、てをあげてください。","example_meaning":"Ai có ý kiến phản đối xin hãy giơ tay."}]},{"word":"意義","reading":"いぎ","meaning":"ý nghĩa, giá trị","example":"この研究には、大きな意義があります。","example_reading":"このけんきゅうには、おおきないぎがあります。","example_meaning":"Nghiên cứu này có ý nghĩa lớn.","examples":[{"example":"ボランティアをする意義を、考えました。","example_reading":"ボランティアをするいぎを、かんがえました。","example_meaning":"Tôi đã suy nghĩ về ý nghĩa của việc làm tình nguyện."},{"example":"オリンピックを開催する意義は何ですか。","example_reading":"オリンピックをかいさいするいぎはなんですか。","example_meaning":"Ý nghĩa của việc tổ chức Olympic là gì?"}]},{"word":"異義","reading":"いぎ","meaning":"nghĩa khác","example":"この二つの言葉は、読みが同じで異義です。","example_reading":"このふたつのことばは、よみがおなじでいぎです。","example_meaning":"Hai từ này đọc giống nhau nhưng nghĩa khác nhau.","examples":[{"example":"それぞれの異義を、辞書で調べました。","example_reading":"それぞれのいぎを、じしょでしらべました。","example_meaning":"Tôi đã tra từ điển để tìm hiểu từng nghĩa khác nhau."},{"example":"同音異義の言葉は、文脈で意味を判断します。","example_reading":"どうおんいぎのことばは、ぶんみゃくでいみをはんだんします。","example_meaning":"Với các từ đồng âm khác nghĩa, ta phán đoán nghĩa dựa vào ngữ cảnh."}]}]},
{"label":"基準／規準","note":"基準(きじゅん): TIÊU CHUẨN, mức chuẩn để so sánh, đánh giá (thông dụng nhất). 規準(きじゅん): CHUẨN MỰC, quy phạm cho hành động, phán đoán (ít dùng; thường viết 基準).","items":[{"word":"基準","reading":"きじゅん","meaning":"tiêu chuẩn, mức chuẩn","example":"合格の基準は、七十点以上です。","example_reading":"ごうかくのきじゅんは、ななじゅうてんいじょうです。","example_meaning":"Tiêu chuẩn đỗ là từ bảy mươi điểm trở lên.","examples":[{"example":"この食品は、安全基準を満たしています。","example_reading":"このしょくひんは、あんぜんきじゅんをみたしています。","example_meaning":"Thực phẩm này đáp ứng tiêu chuẩn an toàn."},{"example":"何を基準に、人を評価しますか。","example_reading":"なにをきじゅんに、ひとをひょうかしますか。","example_meaning":"Bạn đánh giá con người dựa trên tiêu chí nào?"}]},{"word":"規準","reading":"きじゅん","meaning":"chuẩn mực, quy phạm","example":"社会の規準に従って、行動しましょう。","example_reading":"しゃかいのきじゅんにしたがって、こうどうしましょう。","example_meaning":"Hãy hành động theo chuẩn mực của xã hội.","examples":[{"example":"この規準は、判断の拠りどころになります。","example_reading":"このきじゅんは、はんだんのよりどころになります。","example_meaning":"Chuẩn mực này là cơ sở để phán đoán."},{"example":"倫理的な規準を、みんなで話し合いました。","example_reading":"りんりてきなきじゅんを、みんなではなしあいました。","example_meaning":"Mọi người đã cùng thảo luận về các chuẩn mực đạo đức."}]}]},
{"label":"協力／強力","note":"協力(きょうりょく): HỢP TÁC, chung sức (danh từ, động từ する). 強力(きょうりょく): MẠNH MẼ, hùng mạnh (tính từ な; sức mạnh, hiệu lực).","items":[{"word":"協力","reading":"きょうりょく","meaning":"hợp tác, chung sức","example":"地域の人たちと協力して、祭りを開きます。","example_reading":"ちいきのひとたちときょうりょくして、まつりをひらきます。","example_meaning":"Chúng tôi hợp tác với người dân địa phương để tổ chức lễ hội.","examples":[{"example":"みなさんのご協力に、感謝します。","example_reading":"みなさんのごきょうりょくに、かんしゃします。","example_meaning":"Tôi xin cảm ơn sự hợp tác của mọi người."},{"example":"二つの会社が協力して、新しい商品を作りました。","example_reading":"ふたつのかいしゃがきょうりょくして、あたらしいしょうひんをつくりました。","example_meaning":"Hai công ty đã hợp tác làm ra sản phẩm mới."}]},{"word":"強力","reading":"きょうりょく","meaning":"mạnh mẽ, hùng mạnh","example":"この掃除機は、とても強力です。","example_reading":"このそうじきは、とてもきょうりょくです。","example_meaning":"Chiếc máy hút bụi này có sức hút rất mạnh.","examples":[{"example":"強力な台風が、日本に近づいています。","example_reading":"きょうりょくなたいふうが、にほんにちかづいています。","example_meaning":"Một cơn bão mạnh đang tiến gần Nhật Bản."},{"example":"彼は、強力なライバルです。","example_reading":"かれは、きょうりょくなライバルです。","example_meaning":"Anh ấy là một đối thủ đáng gờm."}]}]},
{"label":"週間／習慣／週刊","note":"週間(しゅうかん): TUẦN, khoảng thời gian một tuần (二週間 = hai tuần). 習慣(しゅうかん): THÓI QUEN, tập quán. 週刊(しゅうかん): PHÁT HÀNH HÀNG TUẦN (tạp chí, báo).","items":[{"word":"週間","reading":"しゅうかん","meaning":"tuần, khoảng một tuần","example":"来月から、二週間の旅行に出かけます。","example_reading":"らいげつから、にしゅうかんのりょこうにでかけます。","example_meaning":"Từ tháng sau tôi sẽ đi du lịch hai tuần.","examples":[{"example":"この薬は、一週間飲み続けてください。","example_reading":"このくすりは、いっしゅうかんのみつづけてください。","example_meaning":"Hãy tiếp tục uống thuốc này trong một tuần."},{"example":"今週は、交通安全週間です。","example_reading":"こんしゅうは、こうつうあんぜんしゅうかんです。","example_meaning":"Tuần này là tuần lễ an toàn giao thông."}]},{"word":"習慣","reading":"しゅうかん","meaning":"thói quen, tập quán","example":"毎朝、散歩する習慣があります。","example_reading":"まいあさ、さんぽするしゅうかんがあります。","example_meaning":"Tôi có thói quen đi dạo mỗi sáng.","examples":[{"example":"国によって、食事の習慣が違います。","example_reading":"くによって、しょくじのしゅうかんがちがいます。","example_meaning":"Thói quen ăn uống khác nhau tùy theo từng quốc gia."},{"example":"早寝早起きを、習慣にしましょう。","example_reading":"はやねはやおきを、しゅうかんにしましょう。","example_meaning":"Hãy tập thói quen ngủ sớm dậy sớm."}]},{"word":"週刊","reading":"しゅうかん","meaning":"phát hành hàng tuần","example":"週刊誌で、そのニュースを読みました。","example_reading":"しゅうかんしで、そのニュースをよみました。","example_meaning":"Tôi đã đọc tin đó trên tạp chí tuần san.","examples":[{"example":"この雑誌は、週刊です。","example_reading":"このざっしは、しゅうかんです。","example_meaning":"Tạp chí này phát hành hàng tuần."},{"example":"彼は、週刊の漫画雑誌に連載しています。","example_reading":"かれは、しゅうかんのまんがざっしにれんさいしています。","example_meaning":"Anh ấy đang đăng truyện dài kỳ trên tạp chí manga tuần san."}]}]},
{"label":"最後／最期","note":"最後(さいご): CUỐI CÙNG, sau cùng (thứ tự, thời điểm). 最期(さいご): LÚC LÂM CHUNG, giây phút cuối đời (cái chết).","items":[{"word":"最後","reading":"さいご","meaning":"cuối cùng, sau cùng","example":"最後まで、あきらめずに頑張ります。","example_reading":"さいごまで、あきらめずにがんばります。","example_meaning":"Tôi sẽ cố gắng đến cùng, không bỏ cuộc.","examples":[{"example":"これが、最後のチャンスです。","example_reading":"これが、さいごのチャンスです。","example_meaning":"Đây là cơ hội cuối cùng."},{"example":"列の最後に並んでください。","example_reading":"れつのさいごにならんでください。","example_meaning":"Hãy xếp vào cuối hàng."}]},{"word":"最期","reading":"さいご","meaning":"lúc lâm chung, giây phút cuối đời","example":"祖父は、家族に見守られて最期を迎えました。","example_reading":"そふは、かぞくにみまもられてさいごをむかえました。","example_meaning":"Ông tôi đã ra đi trong vòng tay gia đình.","examples":[{"example":"彼は、立派な最期を遂げました。","example_reading":"かれは、りっぱなさいごをとげました。","example_meaning":"Ông ấy đã có một cái chết đáng kính."},{"example":"母の最期の言葉を、今も覚えています。","example_reading":"ははのさいごのことばを、いまもおぼえています。","example_meaning":"Tôi vẫn nhớ những lời cuối cùng của mẹ."}]}]},
{"label":"初め／始め","note":"初め(はじめ): LÚC ĐẦU, lần đầu tiên (thời điểm/giai đoạn đầu; 初めて, 初めまして). 始め(はじめ): sự BẮT ĐẦU (hành động khởi sự); 〜を始め = đứng đầu là, ngay từ…","items":[{"word":"初め","reading":"はじめ","meaning":"lúc đầu, lần đầu","example":"今月の初めに、引っ越しました。","example_reading":"こんげつのはじめに、ひっこしました。","example_meaning":"Tôi đã chuyển nhà vào đầu tháng này.","examples":[{"example":"初めは、日本語が全然分かりませんでした。","example_reading":"はじめは、にほんごがぜんぜんわかりませんでした。","example_meaning":"Lúc đầu tôi hoàn toàn không hiểu tiếng Nhật."},{"example":"初めまして、田中と申します。","example_reading":"はじめまして、たなかともうします。","example_meaning":"Rất hân hạnh được gặp, tôi là Tanaka."}]},{"word":"始め","reading":"はじめ","meaning":"bắt đầu; đứng đầu là (〜を始め)","example":"試合の始めに、選手が挨拶をします。","example_reading":"しあいのはじめに、せんしゅがあいさつをします。","example_meaning":"Khi bắt đầu trận đấu, các cầu thủ sẽ chào hỏi.","examples":[{"example":"社長を始め、社員全員が参加しました。","example_reading":"しゃちょうをはじめ、しゃいんぜんいんがさんかしました。","example_meaning":"Từ giám đốc cho đến toàn thể nhân viên đều tham gia."},{"example":"仕事を始めるときは、まず机を片付けます。","example_reading":"しごとをはじめるときは、まずつくえをかたづけます。","example_meaning":"Khi bắt đầu làm việc, tôi trước hết dọn bàn."}]}]},
{"label":"変換／返還","note":"変換(へんかん): CHUYỂN ĐỔI (chữ, dữ liệu, dạng năng lượng). 返還(へんかん): TRẢ LẠI (tài sản, lãnh thổ, cúp) cho chủ cũ.","items":[{"word":"変換","reading":"へんかん","meaning":"chuyển đổi","example":"漢字に変換してください。","example_reading":"かんじにへんかんしてください。","example_meaning":"Hãy chuyển sang chữ Hán.","examples":[{"example":"ひらがなを、カタカナに変換します。","example_reading":"ひらがなを、カタカナにへんかんします。","example_meaning":"Tôi chuyển chữ hiragana sang katakana."},{"example":"太陽の光を電気に変換する装置です。","example_reading":"たいようのひかりをでんきにへんかんするそうちです。","example_meaning":"Đây là thiết bị chuyển ánh sáng mặt trời thành điện."}]},{"word":"返還","reading":"へんかん","meaning":"trả lại (tài sản, lãnh thổ)","example":"借りたお金を、全額返還しました。","example_reading":"かりたおかねを、ぜんがくへんかんしました。","example_meaning":"Tôi đã trả lại toàn bộ số tiền đã vay.","examples":[{"example":"優勝カップを返還する日が来ました。","example_reading":"ゆうしょうカップをへんかんするひがきました。","example_meaning":"Đã đến ngày trả lại chiếc cúp vô địch."},{"example":"沖縄は、一九七二年に日本に返還されました。","example_reading":"おきなわは、せんきゅうひゃくななじゅうにねんににほんにへんかんされました。","example_meaning":"Okinawa được trao trả về cho Nhật Bản vào năm 1972."}]}]},
{"label":"精算／清算","note":"精算(せいさん): TÍNH TOÁN CHI TIẾT, thanh toán phần chênh lệch (vé tàu, chi phí công tác). 清算(せいさん): QUYẾT TOÁN DỨT ĐIỂM, thanh lý (nợ, công ty, mối quan hệ).","items":[{"word":"精算","reading":"せいさん","meaning":"tính toán chi tiết, thanh toán chênh lệch","example":"電車で、乗り越し料金を精算しました。","example_reading":"でんしゃで、のりこしりょうきんをせいさんしました。","example_meaning":"Tôi đã thanh toán phần phí đi quá ga.","examples":[{"example":"出張の費用を、会社に精算します。","example_reading":"しゅっちょうのひようを、かいしゃにせいさんします。","example_meaning":"Tôi quyết toán chi phí công tác với công ty."},{"example":"改札の外にある機械で、運賃を精算してください。","example_reading":"かいさつのそとにあるきかいで、うんちんをせいさんしてください。","example_meaning":"Hãy thanh toán tiền vé bằng máy đặt bên ngoài cổng soát vé."}]},{"word":"清算","reading":"せいさん","meaning":"thanh lý, quyết toán dứt điểm","example":"会社を清算して、借金を返しました。","example_reading":"かいしゃをせいさんして、しゃっきんをかえしました。","example_meaning":"Tôi đã thanh lý công ty và trả hết nợ.","examples":[{"example":"過去の関係を清算して、新しい生活を始めます。","example_reading":"かこのかんけいをせいさんして、あたらしいせいかつをはじめます。","example_meaning":"Tôi sẽ chấm dứt mối quan hệ cũ để bắt đầu cuộc sống mới."},{"example":"彼は、長年の借金をようやく清算しました。","example_reading":"かれは、ながねんのしゃっきんをようやくせいさんしました。","example_meaning":"Cuối cùng anh ấy cũng trả hết khoản nợ nhiều năm."}]}]},
{"label":"回収／改修","note":"回収(かいしゅう): THU HỒI (sản phẩm lỗi, rác, tiền cho vay). 改修(かいしゅう): SỬA CHỮA, TU SỬA công trình (cầu, đường, trường học).","items":[{"word":"回収","reading":"かいしゅう","meaning":"thu hồi","example":"欠陥のある商品を、メーカーが回収しています。","example_reading":"けっかんのあるしょうひんを、メーカーがかいしゅうしています。","example_meaning":"Nhà sản xuất đang thu hồi những sản phẩm bị lỗi.","examples":[{"example":"資源ごみは、毎週水曜日に回収されます。","example_reading":"しげんごみは、まいしゅうすいようびにかいしゅうされます。","example_meaning":"Rác tái chế được thu gom vào thứ Tư hàng tuần."},{"example":"貸したお金を、やっと回収できました。","example_reading":"かしたおかねを、やっとかいしゅうできました。","example_meaning":"Cuối cùng tôi cũng thu hồi được số tiền đã cho vay."}]},{"word":"改修","reading":"かいしゅう","meaning":"sửa chữa, tu sửa (công trình)","example":"古い橋の改修工事が始まりました。","example_reading":"ふるいはしのかいしゅうこうじがはじまりました。","example_meaning":"Công trình tu sửa cây cầu cũ đã bắt đầu.","examples":[{"example":"体育館は、来月から改修のため閉まります。","example_reading":"たいいくかんは、らいげつからかいしゅうのためしまります。","example_meaning":"Từ tháng sau nhà thi đấu sẽ đóng cửa để tu sửa."},{"example":"学校の校舎を、耐震のために改修しました。","example_reading":"がっこうのこうしゃを、たいしんのためにかいしゅうしました。","example_meaning":"Dãy phòng học của trường đã được cải tạo để chống động đất."}]}]},
{"label":"決済／決裁","note":"決済(けっさい): THANH TOÁN (tiền bạc, giao dịch, thẻ). 決裁(けっさい): PHÊ DUYỆT, ra quyết định của cấp có thẩm quyền (văn bản, ngân sách).","items":[{"word":"決済","reading":"けっさい","meaning":"thanh toán","example":"クレジットカードで決済しました。","example_reading":"クレジットカードでけっさいしました。","example_meaning":"Tôi đã thanh toán bằng thẻ tín dụng.","examples":[{"example":"電子マネーで、決済することができます。","example_reading":"でんしマネーで、けっさいすることができます。","example_meaning":"Bạn có thể thanh toán bằng tiền điện tử."},{"example":"月末に、代金を決済します。","example_reading":"げつまつに、だいきんをけっさいします。","example_meaning":"Cuối tháng tôi sẽ thanh toán tiền hàng."}]},{"word":"決裁","reading":"けっさい","meaning":"phê duyệt, quyết định (cấp trên)","example":"部長の決裁を、もらってください。","example_reading":"ぶちょうのけっさいを、もらってください。","example_meaning":"Hãy xin phê duyệt của trưởng phòng.","examples":[{"example":"この書類は、社長が決裁します。","example_reading":"このしょるいは、しゃちょうがけっさいします。","example_meaning":"Tài liệu này do giám đốc phê duyệt."},{"example":"予算案は、まだ決裁されていません。","example_reading":"よさんあんは、まだけっさいされていません。","example_meaning":"Dự toán ngân sách vẫn chưa được phê duyệt."}]}]},
{"label":"回復／快復／恢復","note":"回復(かいふく): PHỤC HỒI, trở lại trạng thái cũ (kinh tế, sức khỏe, tín nhiệm, thời tiết) — thông dụng nhất. 快復(かいふく): BÌNH PHỤC hẳn sau bệnh (văn thư thăm hỏi). 恢復(かいふく): cách viết cũ/văn viết của 回復, hiếm gặp (恢 không thuộc chữ thường dụng).","items":[{"word":"回復","reading":"かいふく","meaning":"phục hồi, trở lại như cũ","example":"景気が、少しずつ回復しています。","example_reading":"けいきが、すこしずつかいふくしています。","example_meaning":"Kinh tế đang dần phục hồi.","examples":[{"example":"信頼を回復するには、時間がかかります。","example_reading":"しんらいをかいふくするには、じかんがかかります。","example_meaning":"Để lấy lại lòng tin cần phải có thời gian."},{"example":"雨が止んで、天気が回復しました。","example_reading":"あめがやんで、てんきがかいふくしました。","example_meaning":"Mưa tạnh, thời tiết đã tốt trở lại."}]},{"word":"快復","reading":"かいふく","meaning":"bình phục (sau bệnh)","example":"父は、手術のあと順調に快復しています。","example_reading":"ちちは、しゅじゅつのあとじゅんちょうにかいふくしています。","example_meaning":"Sau ca phẫu thuật, bố tôi đang hồi phục thuận lợi.","examples":[{"example":"病気が快復して、来週退院します。","example_reading":"びょうきがかいふくして、らいしゅうたいいんします。","example_meaning":"Bệnh đã bình phục nên tuần sau tôi xuất viện."},{"example":"一日も早いご快復を、お祈りしています。","example_reading":"いちにちもはやいごかいふくを、おいのりしています。","example_meaning":"Tôi cầu mong bạn sớm bình phục."}]},{"word":"恢復","reading":"かいふく","meaning":"hồi phục (cách viết cũ, văn viết)","example":"失った自信を、恢復することができました。","example_reading":"うしなったじしんを、かいふくすることができました。","example_meaning":"Tôi đã lấy lại được sự tự tin đã mất.","examples":[{"example":"国交が恢復して、貿易が再開しました。","example_reading":"こっこうがかいふくして、ぼうえきがさいかいしました。","example_meaning":"Quan hệ ngoại giao được khôi phục và hoạt động thương mại được nối lại."},{"example":"名誉を恢復するために、裁判を起こしました。","example_reading":"めいよをかいふくするために、さいばんをおこしました。","example_meaning":"Ông ấy đã khởi kiện để khôi phục danh dự."}]}]},
{"label":"期間／機関／器官","note":"期間(きかん): KHOẢNG THỜI GIAN, thời hạn. 機関(きかん): CƠ QUAN, tổ chức; cơ cấu máy (động cơ). 器官(きかん): CƠ QUAN trong cơ thể sinh vật (hô hấp, tiêu hóa, giác quan).","items":[{"word":"期間","reading":"きかん","meaning":"khoảng thời gian, thời hạn","example":"申し込みの期間は、来週までです。","example_reading":"もうしこみのきかんは、らいしゅうまでです。","example_meaning":"Thời hạn đăng ký là đến hết tuần sau.","examples":[{"example":"この商品は、期間限定で販売されます。","example_reading":"このしょうひんは、きかんげんていではんばいされます。","example_meaning":"Sản phẩm này được bán giới hạn trong một thời gian nhất định."},{"example":"一定の期間、会費を払えば、会員になれます。","example_reading":"いっていのきかん、かいひをはらえば、かいいんになれます。","example_meaning":"Chỉ cần đóng hội phí trong một khoảng thời gian nhất định là có thể thành hội viên."}]},{"word":"機関","reading":"きかん","meaning":"cơ quan, tổ chức; động cơ","example":"政府の機関が、調査を行っています。","example_reading":"せいふのきかんが、ちょうさをおこなっています。","example_meaning":"Cơ quan chính phủ đang tiến hành điều tra.","examples":[{"example":"電車は、公共の交通機関です。","example_reading":"でんしゃは、こうきょうのこうつうきかんです。","example_meaning":"Tàu điện là phương tiện giao thông công cộng."},{"example":"この研究機関では、新薬を開発しています。","example_reading":"このけんきゅうきかんでは、しんやくをかいはつしています。","example_meaning":"Viện nghiên cứu này đang phát triển thuốc mới."}]},{"word":"器官","reading":"きかん","meaning":"cơ quan (sinh học)","example":"肺は、呼吸をするための器官です。","example_reading":"はいは、こきゅうをするためのきかんです。","example_meaning":"Phổi là cơ quan dùng để hô hấp.","examples":[{"example":"目や耳は、感覚器官です。","example_reading":"めやみみは、かんかくきかんです。","example_meaning":"Mắt và tai là các cơ quan cảm giác."},{"example":"動物は、さまざまな器官が働いて生きています。","example_reading":"どうぶつは、さまざまなきかんがはたらいていきています。","example_meaning":"Động vật sống được nhờ nhiều cơ quan khác nhau cùng hoạt động."}]}]},
{"label":"切る／着る／斬る","note":"切る(きる): CẮT, ngắt, cúp (dao, kéo, điện thoại, quan hệ). 着る(きる): MẶC quần áo (từ vai xuống thân). 斬る(きる): CHÉM bằng kiếm, đao; nghĩa bóng là phê phán gay gắt.","items":[{"word":"切る","reading":"きる","meaning":"cắt, ngắt, cúp","example":"ナイフで野菜を切ります。","example_reading":"ないふでやさいをきります。","example_meaning":"Tôi cắt rau bằng dao.","examples":[{"example":"髪を短く切ってもらいました。","example_reading":"かみをみじかくきってもらいました。","example_meaning":"Tôi đã được cắt tóc ngắn."},{"example":"電話を切る前に、お礼を言いました。","example_reading":"でんわをきるまえに、おれいをいいました。","example_meaning":"Trước khi cúp máy, tôi đã nói lời cảm ơn."}]},{"word":"着る","reading":"きる","meaning":"mặc (quần áo)","example":"寒いので、コートを着ます。","example_reading":"さむいので、こーとをきます。","example_meaning":"Trời lạnh nên tôi mặc áo khoác.","examples":[{"example":"入学式で、新しいスーツを着ました。","example_reading":"にゅうがくしきで、あたらしいすーつをきました。","example_meaning":"Tôi đã mặc bộ vest mới trong lễ nhập học."},{"example":"彼女は、いつも素敵な着物を着ています。","example_reading":"かのじょは、いつもすてきなきものをきています。","example_meaning":"Cô ấy lúc nào cũng mặc những bộ kimono đẹp."}]},{"word":"斬る","reading":"きる","meaning":"chém (bằng kiếm), phê phán gay gắt","example":"侍は刀で敵を斬りました。","example_reading":"さむらいはかたなでてきをきりました。","example_meaning":"Võ sĩ samurai đã chém kẻ địch bằng kiếm.","examples":[{"example":"時代劇で、悪者が斬られる場面を見ました。","example_reading":"じだいげきで、わるものがきられるばめんをみました。","example_meaning":"Tôi đã xem cảnh kẻ xấu bị chém trong phim cổ trang."},{"example":"新聞は、政治家の発言を厳しく斬る記事を載せた。","example_reading":"しんぶんは、せいじかのはつげんをきびしくきるきじをのせた。","example_meaning":"Tờ báo đã đăng bài phê phán gay gắt phát ngôn của chính trị gia."}]}]},
{"label":"引く／弾く／挽く／轢く","note":"引く(ひく): KÉO, KẺ (đường), TRA (từ điển), BỊ (cảm). 弾く(ひく): CHƠI, GẢY nhạc cụ (đàn, piano). 挽く(ひく): XAY, CƯA (hạt, gỗ). 轢く(ひく): CÁN, ĐÂM phải (xe cán lên người, vật).","items":[{"word":"引く","reading":"ひく","meaning":"kéo, tra, kẻ, bị (cảm)","example":"辞書で意味を引きます。","example_reading":"じしょでいみをひきます。","example_meaning":"Tôi tra nghĩa trong từ điển.","examples":[{"example":"風邪を引いて、会社を休みました。","example_reading":"かぜをひいて、かいしゃをやすみました。","example_meaning":"Tôi bị cảm nên đã nghỉ làm."},{"example":"定規を使って、まっすぐな線を引きました。","example_reading":"じょうぎをつかって、まっすぐなせんをひきました。","example_meaning":"Tôi dùng thước để kẻ một đường thẳng."}]},{"word":"弾く","reading":"ひく","meaning":"chơi, gảy (nhạc cụ)","example":"妹はピアノを弾くのが上手です。","example_reading":"いもうとはぴあのをひくのがじょうずです。","example_meaning":"Em gái tôi chơi piano giỏi.","examples":[{"example":"父は、ときどきギターを弾いて歌ってくれます。","example_reading":"ちちは、ときどきぎたーをひいてうたってくれます。","example_meaning":"Thỉnh thoảng bố gảy guitar và hát cho tôi nghe."},{"example":"結婚式で、友達がバイオリンを弾きました。","example_reading":"けっこんしきで、ともだちがばいおりんをひきました。","example_meaning":"Ở đám cưới, bạn tôi đã chơi vĩ cầm."}]},{"word":"挽く","reading":"ひく","meaning":"xay, cưa","example":"コーヒー豆を挽いてから、お湯を注ぎます。","example_reading":"こーひーまめをひいてから、おゆをそそぎます。","example_meaning":"Sau khi xay hạt cà phê thì rót nước nóng vào.","examples":[{"example":"石臼で、そばの実を挽きました。","example_reading":"いしうすで、そばのみをひきました。","example_meaning":"Tôi đã xay hạt kiều mạch bằng cối đá."},{"example":"大工さんが、のこぎりで木を挽いています。","example_reading":"だいくさんが、のこぎりできをひいています。","example_meaning":"Bác thợ mộc đang cưa gỗ bằng cưa."}]},{"word":"轢く","reading":"ひく","meaning":"cán, đâm (xe)","example":"猫が車に轢かれそうになりました。","example_reading":"ねこがくるまにひかれそうになりました。","example_meaning":"Con mèo suýt bị xe cán.","examples":[{"example":"運転中に、人を轢いてしまう事故が起きました。","example_reading":"うんてんちゅうに、ひとをひいてしまうじこがおきました。","example_meaning":"Đã xảy ra vụ tai nạn xe cán phải người khi đang lái xe."},{"example":"電車に轢かれないように、線路に入ってはいけません。","example_reading":"でんしゃにひかれないように、せんろにはいってはいけません。","example_meaning":"Không được vào đường ray để khỏi bị tàu cán."}]}]},
{"label":"押す／推す／捺す","note":"押す(おす): ĐẨY, ẤN, NHẤN (nút, chuông), ép. 推す(おす): TIẾN CỬ, ỦNG HỘ, giới thiệu (ứng viên, thần tượng yêu thích). 捺す(おす): ĐÓNG (dấu, con triện); trong thực tế thường viết 押す.","items":[{"word":"押す","reading":"おす","meaning":"đẩy, ấn, nhấn","example":"ボタンを押すと、ドアが開きます。","example_reading":"ぼたんをおすと、どあがあきます。","example_meaning":"Nhấn nút thì cửa mở ra.","examples":[{"example":"満員電車で、後ろの人に押されました。","example_reading":"まんいんでんしゃで、うしろのひとにおされました。","example_meaning":"Trên chuyến tàu đông nghẹt, tôi bị người phía sau đẩy."},{"example":"玄関のチャイムを押しましたが、誰も出ませんでした。","example_reading":"げんかんのちゃいむをおしましたが、だれもでませんでした。","example_meaning":"Tôi bấm chuông cửa nhưng không có ai ra."}]},{"word":"推す","reading":"おす","meaning":"tiến cử, ủng hộ","example":"私は山田さんを委員長に推します。","example_reading":"わたしはやまださんをいいんちょうにおします。","example_meaning":"Tôi tiến cử anh Yamada làm trưởng ban.","examples":[{"example":"先生は、彼を代表に推してくれました。","example_reading":"せんせいは、かれをだいひょうにおしてくれました。","example_meaning":"Thầy giáo đã tiến cử cậu ấy làm đại diện."},{"example":"好きなアイドルを推して、毎回ライブに行きます。","example_reading":"すきなあいどるをおして、まいかいらいぶにいきます。","example_meaning":"Tôi ủng hộ thần tượng mình thích nên buổi diễn nào cũng đi."}]},{"word":"捺す","reading":"おす","meaning":"đóng (dấu, triện)","example":"書類に判子を捺してください。","example_reading":"しょるいにはんこをおしてください。","example_meaning":"Hãy đóng dấu vào hồ sơ.","examples":[{"example":"契約書に印を捺して、郵送しました。","example_reading":"けいやくしょにいんをおして、ゆうそうしました。","example_meaning":"Tôi đã đóng dấu vào hợp đồng rồi gửi qua bưu điện."},{"example":"手紙の封筒に、消印が捺してあります。","example_reading":"てがみのふうとうに、けしいんがおしてあります。","example_meaning":"Trên phong bì thư có đóng dấu bưu điện."}]}]},
{"label":"責める／攻める","note":"責める(せめる): TRÁCH, QUỞ TRÁCH, đổ lỗi cho người khác hoặc chính mình. 攻める(せめる): TẤN CÔNG (quân sự, thể thao, trò chơi); trái nghĩa là 守る.","items":[{"word":"責める","reading":"せめる","meaning":"trách, quở trách","example":"失敗した友達を責めてはいけません。","example_reading":"しっぱいしたともだちをせめてはいけません。","example_meaning":"Không được trách người bạn đã thất bại.","examples":[{"example":"約束を忘れて、彼女に責められました。","example_reading":"やくそくをわすれて、かのじょにせめられました。","example_meaning":"Tôi quên lời hẹn nên bị bạn gái trách."},{"example":"彼は、自分を責めて、とても落ち込んでいます。","example_reading":"かれは、じぶんをせめて、とてもおちこんでいます。","example_meaning":"Anh ấy tự trách mình và đang rất suy sụp."}]},{"word":"攻める","reading":"せめる","meaning":"tấn công","example":"日本のチームは、前半から積極的に攻めました。","example_reading":"にほんのちーむは、ぜんはんからせっきょくてきにせめました。","example_meaning":"Đội Nhật Bản đã tấn công tích cực ngay từ hiệp một.","examples":[{"example":"敵の城を攻めるのは、難しいです。","example_reading":"てきのしろをせめるのは、むずかしいです。","example_meaning":"Tấn công thành của địch rất khó."},{"example":"ゲームでは、守るより攻める方が好きです。","example_reading":"げーむでは、まもるよりせめるほうがすきです。","example_meaning":"Trong trò chơi, tôi thích tấn công hơn là phòng thủ."}]}]},
{"label":"付ける／着ける／点ける","note":"付ける(つける): GẮN, DÍNH, BÔI, GHI (thêm vào, phết lên). 着ける(つける): ĐEO, MẶC lên người (身に着ける), đỗ xe/cập bến sát vào. 点ける(つける): BẬT, ĐỐT, THẮP (đèn, lửa, TV, máy sưởi).","items":[{"word":"付ける","reading":"つける","meaning":"gắn, dính, bôi, ghi","example":"パンにバターを付けて食べます。","example_reading":"ぱんにばたーをつけてたべます。","example_meaning":"Tôi phết bơ lên bánh mì rồi ăn.","examples":[{"example":"日記を付ける習慣があります。","example_reading":"にっきをつけるしゅうかんがあります。","example_meaning":"Tôi có thói quen ghi nhật ký."},{"example":"服にソースを付けてしまいました。","example_reading":"ふくにそーすをつけてしまいました。","example_meaning":"Tôi lỡ làm dính nước sốt lên áo."}]},{"word":"着ける","reading":"つける","meaning":"đeo, mặc lên người; đỗ sát","example":"マスクを着けて、外出します。","example_reading":"ますくをつけて、がいしゅつします。","example_meaning":"Tôi đeo khẩu trang rồi ra ngoài.","examples":[{"example":"彼女は、大きな指輪を指に着けています。","example_reading":"かのじょは、おおきなゆびわをゆびにつけています。","example_meaning":"Cô ấy đeo một chiếc nhẫn lớn ở ngón tay."},{"example":"運転手は、車を玄関に着けました。","example_reading":"うんてんしゅは、くるまをげんかんにつけました。","example_meaning":"Tài xế đã cho xe đỗ sát cửa chính."}]},{"word":"点ける","reading":"つける","meaning":"bật, thắp, đốt","example":"部屋が暗いので、電気を点けました。","example_reading":"へやがくらいので、でんきをつけました。","example_meaning":"Phòng tối nên tôi đã bật đèn.","examples":[{"example":"寒いから、ストーブを点けましょう。","example_reading":"さむいから、すとーぶをつけましょう。","example_meaning":"Lạnh quá, chúng ta bật lò sưởi nhé."},{"example":"誕生日ケーキのろうそくに、火を点けました。","example_reading":"たんじょうびけーきのろうそくに、ひをつけました。","example_meaning":"Tôi đã thắp nến trên bánh sinh nhật."}]}]},
{"label":"合わせる／併せる／会わせる","note":"合わせる(あわせる): LÀM CHO KHỚP, GHÉP, GỘP, điều chỉnh cho hợp. 併せる(あわせる): KẾT HỢP, KIÊM, đưa cùng lúc hai việc song song. 会わせる(あわせる): CHO GẶP, sắp xếp để hai người gặp nhau.","items":[{"word":"合わせる","reading":"あわせる","meaning":"ghép, chỉnh cho khớp, hòa theo","example":"みんなで力を合わせて、荷物を運びました。","example_reading":"みんなでちからをあわせて、にもつをはこびました。","example_meaning":"Mọi người cùng chung sức khiêng hành lý.","examples":[{"example":"時計の時間を、正しい時間に合わせました。","example_reading":"とけいのじかんを、ただしいじかんにあわせました。","example_meaning":"Tôi chỉnh đồng hồ cho đúng giờ."},{"example":"音楽に合わせて、みんなで踊りました。","example_reading":"おんがくにあわせて、みんなでおどりました。","example_meaning":"Mọi người cùng nhảy theo nhạc."}]},{"word":"併せる","reading":"あわせる","meaning":"kết hợp, kiêm, đồng thời","example":"この商品は、他のサービスと併せてご利用いただけます。","example_reading":"このしょうひんは、ほかのさーびすとあわせてごりよういただけます。","example_meaning":"Sản phẩm này có thể dùng kết hợp với các dịch vụ khác.","examples":[{"example":"彼は、会社の経営と併せて、大学で教えています。","example_reading":"かれは、かいしゃのけいえいとあわせて、だいがくでおしえています。","example_meaning":"Anh ấy vừa điều hành công ty vừa dạy ở đại học."},{"example":"本文と併せて、資料もお読みください。","example_reading":"ほんぶんとあわせて、しりょうもおよみください。","example_meaning":"Xin hãy đọc cả tài liệu kèm theo phần nội dung chính."}]},{"word":"会わせる","reading":"あわせる","meaning":"cho gặp, sắp xếp cho gặp","example":"母を彼に会わせたいと思っています。","example_reading":"ははをかれにあわせたいとおもっています。","example_meaning":"Tôi muốn cho bạn trai gặp mẹ.","examples":[{"example":"離れて暮らす祖母に、孫を会わせてあげました。","example_reading":"はなれてくらすそぼに、まごをあわせてあげました。","example_meaning":"Tôi đã cho đứa cháu gặp bà đang sống xa nhà."},{"example":"社長に会わせてほしいと、秘書に頼みました。","example_reading":"しゃちょうにあわせてほしいと、ひしょにたのみました。","example_meaning":"Tôi nhờ thư ký cho tôi gặp giám đốc."}]}]},
{"label":"当てる／充てる／宛てる","note":"当てる(あてる): ÁP, CHẠM vào; ĐOÁN TRÚNG; chiếu (nắng); gọi (học sinh) trả lời. 充てる(あてる): DÙNG VÀO, PHÂN BỔ cho một mục đích (tiền, thời gian, nhân lực). 宛てる(あてる): GỬI ĐẾN người nhận (thư, email, hàng); danh từ là 宛て.","items":[{"word":"当てる","reading":"あてる","meaning":"áp vào, đoán trúng, gọi trả lời","example":"痛い所に、冷たいタオルを当てました。","example_reading":"いたいところに、つめたいたおるをあてました。","example_meaning":"Tôi áp khăn lạnh lên chỗ đau.","examples":[{"example":"クイズの答えを当てたら、賞品がもらえます。","example_reading":"くいずのこたえをあてたら、しょうひんがもらえます。","example_meaning":"Nếu đoán trúng đáp án câu đố thì sẽ nhận được quà."},{"example":"先生は、授業中に私を当てました。","example_reading":"せんせいは、じゅぎょうちゅうにわたしをあてました。","example_meaning":"Cô giáo đã gọi tôi trả lời trong giờ học."}]},{"word":"充てる","reading":"あてる","meaning":"dùng vào, phân bổ","example":"給料の一部を、貯金に充てています。","example_reading":"きゅうりょうのいちぶを、ちょきんにあてています。","example_meaning":"Tôi dùng một phần lương để tiết kiệm.","examples":[{"example":"余った時間は、勉強に充てるつもりです。","example_reading":"あまったじかんは、べんきょうにあてるつもりです。","example_meaning":"Tôi định dành thời gian còn lại cho việc học."},{"example":"会社は、新しい工場の建設に資金を充てました。","example_reading":"かいしゃは、あたらしいこうじょうのけんせつにしきんをあてました。","example_meaning":"Công ty đã dùng vốn vào việc xây nhà máy mới."}]},{"word":"宛てる","reading":"あてる","meaning":"gửi đến (người nhận)","example":"社長に宛てて、手紙を書きました。","example_reading":"しゃちょうにあてて、てがみをかきました。","example_meaning":"Tôi đã viết thư gửi cho giám đốc.","examples":[{"example":"母に宛てたメールを、間違えて父に送りました。","example_reading":"ははにあてためーるを、まちがえてちちにおくりました。","example_meaning":"Tôi lỡ gửi nhầm email dành cho mẹ sang cho bố."},{"example":"この荷物は、山田さんに宛てて送られたものです。","example_reading":"このにもつは、やまださんにあてておくられたものです。","example_meaning":"Gói hàng này được gửi đến anh Yamada."}]}]},
{"label":"返す／帰す","note":"返す(かえす): TRẢ LẠI, hoàn lại (đồ mượn, tiền); đáp lại. 帰す(かえす): CHO VỀ, cho phép ra về (người, con vật trở về chỗ cũ).","items":[{"word":"返す","reading":"かえす","meaning":"trả lại, hoàn lại","example":"図書館に本を返しに行きます。","example_reading":"としょかんにほんをかえしにいきます。","example_meaning":"Tôi đi trả sách ở thư viện.","examples":[{"example":"借りたお金は、来月までに返します。","example_reading":"かりたおかねは、らいげつまでにかえします。","example_meaning":"Số tiền đã vay tôi sẽ trả trước tháng sau."},{"example":"貸してもらった傘を、お礼を言って返しました。","example_reading":"かしてもらったかさを、おれいをいってかえしました。","example_meaning":"Tôi đã nói lời cảm ơn rồi trả lại chiếc ô được cho mượn."}]},{"word":"帰す","reading":"かえす","meaning":"cho về, thả về","example":"雨が降ってきたので、子どもたちを早く帰しました。","example_reading":"あめがふってきたので、こどもたちをはやくかえしました。","example_meaning":"Trời đổ mưa nên tôi cho bọn trẻ về sớm.","examples":[{"example":"先生は、病気の生徒を家に帰しました。","example_reading":"せんせいは、びょうきのせいとをいえにかえしました。","example_meaning":"Cô giáo cho học sinh bị bệnh về nhà."},{"example":"捕まえた魚を、川に帰してあげました。","example_reading":"つかまえたさかなを、かわにかえしてあげました。","example_meaning":"Tôi đã thả con cá bắt được trở lại sông."}]}]},
{"label":"収まる／納まる／治まる／修まる","note":"収まる(おさまる): NẰM GỌN, VỪA VẶN trong phạm vi (箱に収まる, 予算内に収まる). 納まる(おさまる): ĐƯỢC NỘP, ĐƯỢC ĐẶT vào đúng chỗ, ngồi vào vị trí (税金が納まる, 社長の座に納まる). 治まる(おさまる): DỊU XUỐNG, LẮNG DỊU (cơn đau, tranh chấp, hỗn loạn). 修まる(おさまる): ĐƯỢC SỬA ĐỔI, ngay ngắn lại (hạnh kiểm, nết na); ít dùng.","items":[{"word":"収まる","reading":"おさまる","meaning":"nằm gọn, vừa vặn","example":"荷物が全部、このかばんに収まりました。","example_reading":"にもつがぜんぶ、このかばんにおさまりました。","example_meaning":"Hành lý đều nằm gọn trong chiếc cặp này.","examples":[{"example":"写真には、全員がきれいに収まっています。","example_reading":"しゃしんには、ぜんいんがきれいにおさまっています。","example_meaning":"Trong ảnh có đủ mọi người, bố cục rất đẹp."},{"example":"予算が三万円以内に収まりました。","example_reading":"よさんがさんまんえんいないにおさまりました。","example_meaning":"Ngân sách đã nằm gọn trong 30.000 yên."}]},{"word":"納まる","reading":"おさまる","meaning":"được nộp, được đặt vào chỗ, ngồi vào vị trí","example":"税金が、期限までに納まりました。","example_reading":"ぜいきんが、きげんまでにおさまりました。","example_meaning":"Tiền thuế đã được nộp trước hạn.","examples":[{"example":"工事が終わり、機械が所定の位置に納まりました。","example_reading":"こうじがおわり、きかいがしょていのいちにおさまりました。","example_meaning":"Thi công xong, máy móc đã được đặt vào vị trí quy định."},{"example":"彼は、ついに社長の座に納まりました。","example_reading":"かれは、ついにしゃちょうのざにおさまりました。","example_meaning":"Cuối cùng anh ấy cũng ngồi vào vị trí giám đốc."}]},{"word":"治まる","reading":"おさまる","meaning":"dịu xuống, lắng xuống","example":"薬を飲んだら、痛みが治まりました。","example_reading":"くすりをのんだら、いたみがおさまりました。","example_meaning":"Uống thuốc xong thì cơn đau dịu đi.","examples":[{"example":"長い間続いた争いが、やっと治まりました。","example_reading":"ながいあいだつづいたあらそいが、やっとおさまりました。","example_meaning":"Cuộc tranh chấp kéo dài cuối cùng cũng lắng xuống."},{"example":"咳が治まらなくて、夜、眠れませんでした。","example_reading":"せきがおさまらなくて、よる、ねむれませんでした。","example_meaning":"Cơn ho không dịu nên đêm tôi không ngủ được."}]},{"word":"修まる","reading":"おさまる","meaning":"được sửa đổi, ngay ngắn lại (hạnh kiểm)","example":"彼の行いが修まったのは、先生のおかげです。","example_reading":"かれのおこないがおさまったのは、せんせいのおかげです。","example_meaning":"Hạnh kiểm của cậu ấy tốt lên là nhờ thầy.","examples":[{"example":"素行が修まらない息子を、親は心配しています。","example_reading":"そこうがおさまらないむすこを、おやはしんぱいしています。","example_meaning":"Cha mẹ lo cho cậu con trai mãi không sửa được thói hư."},{"example":"年を取って、やっと生活態度が修まってきました。","example_reading":"としをとって、やっとせいかつたいどがおさまってきました。","example_meaning":"Lớn tuổi rồi, cuối cùng lối sống của anh ấy cũng đã ngay ngắn hơn."}]}]},
{"label":"溶ける／解ける／融ける","note":"溶ける(とける): TAN, HÒA TAN, chảy ra (đường vào nước, kem, bơ). 解ける(とける): ĐƯỢC THÁO, ĐƯỢC GIẢI (dây buộc, bài toán, hiểu lầm, tuyết tan). 融ける(とける): TAN CHẢY do nhiệt (băng, kim loại); trong đời thường thường viết 溶ける.","items":[{"word":"溶ける","reading":"とける","meaning":"tan, hòa tan, chảy","example":"砂糖はお湯によく溶けます。","example_reading":"さとうはおゆによくとけます。","example_meaning":"Đường tan tốt trong nước nóng.","examples":[{"example":"アイスクリームが、暑さで溶けてしまいました。","example_reading":"あいすくりーむが、あつさでとけてしまいました。","example_meaning":"Kem đã bị chảy vì nóng."},{"example":"バターは、熱いフライパンの上で溶けます。","example_reading":"ばたーは、あついふらいぱんのうえでとけます。","example_meaning":"Bơ tan chảy trên chảo nóng."}]},{"word":"解ける","reading":"とける","meaning":"được tháo, được giải, tan (tuyết)","example":"靴のひもが解けています。","example_reading":"くつのひもがとけています。","example_meaning":"Dây giày bị tuột rồi.","examples":[{"example":"難しい問題が、やっと解けました。","example_reading":"むずかしいもんだいが、やっととけました。","example_meaning":"Cuối cùng tôi cũng giải được bài toán khó."},{"example":"話し合って、二人の誤解が解けました。","example_reading":"はなしあって、ふたりのごかいがとけました。","example_meaning":"Sau khi nói chuyện, hiểu lầm giữa hai người đã được giải tỏa."}]},{"word":"融ける","reading":"とける","meaning":"tan chảy (băng, kim loại)","example":"暖かくなって、池の氷が融けました。","example_reading":"あたたかくなって、いけのこおりがとけました。","example_meaning":"Trời ấm lên nên băng trên ao đã tan.","examples":[{"example":"鉄は、千五百度近くの高温で融けます。","example_reading":"てつは、せんごひゃくどちかくのこうおんでとけます。","example_meaning":"Sắt nóng chảy ở nhiệt độ cao, gần 1.500 độ."},{"example":"温暖化で、北極の氷が融けています。","example_reading":"おんだんかで、ほっきょくのこおりがとけています。","example_meaning":"Do trái đất nóng lên, băng ở Bắc Cực đang tan."}]}]},
{"label":"生える／映える","note":"生える(はえる): MỌC (cỏ, răng, tóc, nấm). 映える(はえる): NỔI BẬT, RỰC RỠ nhờ ánh sáng hay sự tương phản; \"インスタ映え\" là lên hình đẹp.","items":[{"word":"生える","reading":"はえる","meaning":"mọc","example":"庭に雑草が生えてきました。","example_reading":"にわにざっそうがはえてきました。","example_meaning":"Cỏ dại đã mọc lên trong vườn.","examples":[{"example":"赤ちゃんの歯が、やっと生えてきました。","example_reading":"あかちゃんのはが、やっとはえてきました。","example_meaning":"Răng của em bé cuối cùng cũng đã mọc."},{"example":"雨のあと、木の根元にきのこが生えていました。","example_reading":"あめのあと、きのねもとにきのこがはえていました。","example_meaning":"Sau cơn mưa, nấm mọc ở gốc cây."}]},{"word":"映える","reading":"はえる","meaning":"nổi bật, rực rỡ","example":"夕日に映える山が、とてもきれいでした。","example_reading":"ゆうひにはえるやまが、とてもきれいでした。","example_meaning":"Ngọn núi rực rỡ dưới nắng chiều rất đẹp.","examples":[{"example":"白い壁に、赤い花がよく映えます。","example_reading":"しろいかべに、あかいはながよくはえます。","example_meaning":"Hoa đỏ nổi bật hẳn trên bức tường trắng."},{"example":"このカフェは、写真に映える料理が人気です。","example_reading":"このかふぇは、しゃしんにはえるりょうりがにんきです。","example_meaning":"Quán cà phê này nổi tiếng với những món ăn lên hình đẹp."}]}]},
{"label":"積む／摘む／詰む","note":"積む(つむ): XẾP CHỒNG, CHẤT (hàng); TÍCH LŨY (kinh nghiệm, công đức). 摘む(つむ): HÁI, NGẮT (hoa, trà, quả). 詰む(つむ): BÍ NƯỚC, hết đường đi (cờ shogi, cờ vây); nghĩa bóng là bế tắc.","items":[{"word":"積む","reading":"つむ","meaning":"xếp chồng, chất, tích lũy","example":"トラックに荷物を積みます。","example_reading":"とらっくににもつをつみます。","example_meaning":"Chất hàng lên xe tải.","examples":[{"example":"経験を積んで、仕事が上手になりました。","example_reading":"けいけんをつんで、しごとがじょうずになりました。","example_meaning":"Tích lũy kinh nghiệm nên tôi làm việc giỏi hơn."},{"example":"子どもが、箱を高く積んで遊んでいます。","example_reading":"こどもが、はこをたかくつんであそんでいます。","example_meaning":"Đứa bé đang chơi xếp những chiếc hộp thật cao."}]},{"word":"摘む","reading":"つむ","meaning":"hái, ngắt","example":"春に、野原で花を摘みました。","example_reading":"はるに、のはらではなをつみました。","example_meaning":"Mùa xuân, tôi đã hái hoa ngoài đồng.","examples":[{"example":"祖母は、毎朝お茶の葉を摘みます。","example_reading":"そぼは、まいあさおちゃのはをつみます。","example_meaning":"Bà tôi mỗi sáng đều hái lá trà."},{"example":"いちごを摘んで、その場で食べました。","example_reading":"いちごをつんで、そのばでたべました。","example_meaning":"Tôi hái dâu rồi ăn ngay tại chỗ."}]},{"word":"詰む","reading":"つむ","meaning":"bí nước, hết đường đi","example":"将棋で、相手の王が詰みました。","example_reading":"しょうぎで、あいてのおうがつみました。","example_meaning":"Trong shogi, quân vương của đối phương đã bị chiếu bí.","examples":[{"example":"あと三手で、相手が詰みます。","example_reading":"あとさんてで、あいてがつみます。","example_meaning":"Chỉ còn ba nước nữa là đối phương bị chiếu bí."},{"example":"この局面は、もう詰んでいます。","example_reading":"このきょくめんは、もうつんでいます。","example_meaning":"Thế cờ này đã hết đường rồi."}]}]},
{"label":"汲む／組む／酌む","note":"汲む(くむ): MÚC (nước giếng, nước suối). 組む(くむ): GHÉP, KHOANH, BẮT CẶP, HỢP TÁC, lập (tay chân, đội, kế hoạch). 酌む(くむ): RÓT RƯỢU; THẤU HIỂU tâm tình, thông cảm hoàn cảnh (気持ちを酌む).","items":[{"word":"汲む","reading":"くむ","meaning":"múc (nước)","example":"井戸から水を汲みます。","example_reading":"いどからみずをくみます。","example_meaning":"Tôi múc nước từ giếng.","examples":[{"example":"川でバケツに水を汲んで、畑にまきました。","example_reading":"かわでばけつにみずをくんで、はたけにまきました。","example_meaning":"Tôi múc nước sông vào xô rồi tưới lên ruộng."},{"example":"祖父は、毎朝、湧き水を汲みに行きます。","example_reading":"そふは、まいあさ、わきみずをくみにいきます。","example_meaning":"Ông tôi mỗi sáng đều đi lấy nước suối."}]},{"word":"組む","reading":"くむ","meaning":"ghép, khoanh, bắt cặp, lập","example":"腕を組んで、じっと考えています。","example_reading":"うでをくんで、じっとかんがえています。","example_meaning":"Anh ấy khoanh tay, ngồi suy nghĩ lặng lẽ.","examples":[{"example":"友達とペアを組んで、練習しました。","example_reading":"ともだちとぺあをくんで、れんしゅうしました。","example_meaning":"Tôi đã bắt cặp với bạn để luyện tập."},{"example":"来月の旅行の予定を組みました。","example_reading":"らいげつのりょこうのよていをくみました。","example_meaning":"Tôi đã lập lịch cho chuyến du lịch tháng sau."}]},{"word":"酌む","reading":"くむ","meaning":"rót rượu; thấu hiểu, thông cảm","example":"父に、お酒を酌んであげました。","example_reading":"ちちに、おさけをくんであげました。","example_meaning":"Tôi đã rót rượu cho bố.","examples":[{"example":"社長は、社員の気持ちを酌んで、休みをくれました。","example_reading":"しゃちょうは、しゃいんのきもちをくんで、やすみをくれました。","example_meaning":"Giám đốc thấu hiểu tâm tình nhân viên nên đã cho nghỉ."},{"example":"事情を酌んで、今回は許してもらえました。","example_reading":"じじょうをくんで、こんかいはゆるしてもらえました。","example_meaning":"Họ thông cảm hoàn cảnh nên lần này đã bỏ qua cho tôi."}]}]},
{"label":"刈る／狩る／駆る","note":"刈る(かる): CẮT, GẶT (cỏ, lúa, tóc). 狩る(かる): SĂN BẮT (thú, nấm, quả: きのこ狩り, 紅葉狩り). 駆る(かる): THÚC (ngựa), LÁI (xe) hết tốc lực; bị thôi thúc bởi cảm xúc (不安に駆られる).","items":[{"word":"刈る","reading":"かる","meaning":"cắt, gặt","example":"夏は、庭の草を刈るのが大変です。","example_reading":"なつは、にわのくさをかるのがたいへんです。","example_meaning":"Mùa hè việc cắt cỏ trong vườn rất vất vả.","examples":[{"example":"秋になると、農家は稲を刈ります。","example_reading":"あきになると、のうかはいねをかります。","example_meaning":"Cứ vào mùa thu, nông dân gặt lúa."},{"example":"床屋で、髪を短く刈ってもらいました。","example_reading":"とこやで、かみをみじかくかってもらいました。","example_meaning":"Tôi đã nhờ thợ cắt tóc cắt ngắn ở tiệm."}]},{"word":"狩る","reading":"かる","meaning":"săn bắt, đi hái (nấm, quả)","example":"昔の人は、山で動物を狩って暮らしていました。","example_reading":"むかしのひとは、やまでどうぶつをかってくらしていました。","example_meaning":"Ngày xưa người ta săn thú trên núi để sinh sống.","examples":[{"example":"秋になると、山できのこを狩りに行きます。","example_reading":"あきになると、やまできのこをかりにいきます。","example_meaning":"Vào mùa thu, tôi lên núi đi hái nấm."},{"example":"猟師は、猟犬を連れて、鹿を狩ります。","example_reading":"りょうしは、りょうけんをつれて、しかをかります。","example_meaning":"Người thợ săn dẫn chó săn đi săn hươu."}]},{"word":"駆る","reading":"かる","meaning":"thúc (ngựa), lái nhanh; thôi thúc","example":"騎士は、馬を駆って戦いに向かいました。","example_reading":"きしは、うまをかってたたかいにむかいました。","example_meaning":"Hiệp sĩ thúc ngựa ra trận.","examples":[{"example":"彼は、愛車を駆って、海へドライブに行きました。","example_reading":"かれは、あいしゃをかって、うみへどらいぶにいきました。","example_meaning":"Anh ấy cầm lái chiếc xe yêu quý đi hóng gió ở biển."},{"example":"不安に駆られて、何度も確認してしまいました。","example_reading":"ふあんにかられて、なんどもかくにんしてしまいました。","example_meaning":"Bị nỗi bất an thôi thúc nên tôi đã kiểm tra nhiều lần."}]}]},
{"label":"咲く／裂く／割く","note":"咲く(さく): NỞ (hoa). 裂く(さく): XÉ, XÉ TOẠC, chia rẽ (vải, giấy, quan hệ). 割く(さく): DÀNH RA, TRÍCH RA (thời gian, trang báo, nhân lực); mổ bụng (cá).","items":[{"word":"咲く","reading":"さく","meaning":"nở (hoa)","example":"春になると、桜が咲きます。","example_reading":"はるになると、さくらがさきます。","example_meaning":"Cứ đến mùa xuân là hoa anh đào nở.","examples":[{"example":"庭に、赤いバラが咲きました。","example_reading":"にわに、あかいばらがさきました。","example_meaning":"Trong vườn đã nở những bông hồng đỏ."},{"example":"道ばたに、小さな花が咲いていました。","example_reading":"みちばたに、ちいさなはながさいていました。","example_meaning":"Bên vệ đường có những bông hoa nhỏ đang nở."}]},{"word":"裂く","reading":"さく","meaning":"xé, xé toạc, chia rẽ","example":"怒って、手紙をびりびりに裂きました。","example_reading":"おこって、てがみをびりびりにさきました。","example_meaning":"Tức giận nên tôi xé tan lá thư.","examples":[{"example":"魚を手で裂いて、骨を取りました。","example_reading":"さかなをてでさいて、ほねをとりました。","example_meaning":"Tôi xé cá bằng tay rồi lấy xương ra."},{"example":"親の反対が、二人の仲を裂きました。","example_reading":"おやのはんたいが、ふたりのなかをさきました。","example_meaning":"Sự phản đối của cha mẹ đã chia rẽ hai người."}]},{"word":"割く","reading":"さく","meaning":"dành ra, trích ra","example":"忙しいのに、時間を割いて会ってくれました。","example_reading":"いそがしいのに、じかんをさいてあってくれました。","example_meaning":"Dù bận nhưng anh ấy vẫn dành thời gian gặp tôi.","examples":[{"example":"新聞は、その事件に多くの紙面を割きました。","example_reading":"しんぶんは、そのじけんにおおくのしめんをさきました。","example_meaning":"Tờ báo đã dành nhiều trang cho vụ việc đó."},{"example":"事故の現場に、多くの人員を割きました。","example_reading":"じこのげんばに、おおくのじんいんをさきました。","example_meaning":"Họ đã điều nhiều nhân lực đến hiện trường vụ tai nạn."}]}]},
{"label":"巻く／撒く／蒔く","note":"巻く(まく): QUẤN, CUỘN, QUÀNG (khăn, băng, dây cót). 撒く(まく): RẢI, RẮC, TƯỚI, PHÁT tung ra (nước, muối, tờ rơi). 蒔く(まく): GIEO (hạt giống); nghĩa bóng là gieo mầm cho việc gì.","items":[{"word":"巻く","reading":"まく","meaning":"quấn, cuộn, lên dây","example":"寒いので、首にマフラーを巻きました。","example_reading":"さむいので、くびにまふらーをまきました。","example_meaning":"Trời lạnh nên tôi quấn khăn quàng quanh cổ.","examples":[{"example":"足にけがをして、包帯を巻いています。","example_reading":"あしにけがをして、ほうたいをまいています。","example_meaning":"Tôi bị thương ở chân nên đang quấn băng."},{"example":"時計のねじを巻くのを、忘れました。","example_reading":"とけいのねじをまくのを、わすれました。","example_meaning":"Tôi quên lên dây cót đồng hồ."}]},{"word":"撒く","reading":"まく","meaning":"rải, rắc, tưới, phát tung ra","example":"夏は、夕方に庭に水を撒きます。","example_reading":"なつは、ゆうがたににわにみずをまきます。","example_meaning":"Mùa hè, chiều tối tôi tưới nước ra vườn.","examples":[{"example":"雪の道に、塩を撒いて凍るのを防ぎます。","example_reading":"ゆきのみちに、しおをまいてこおるのをふせぎます。","example_meaning":"Người ta rải muối lên đường tuyết để chống đóng băng."},{"example":"駅前で、会社の広告のチラシを撒きました。","example_reading":"えきまえで、かいしゃのこうこくのちらしをまきました。","example_meaning":"Tôi đã phát tờ rơi quảng cáo của công ty trước nhà ga."}]},{"word":"蒔く","reading":"まく","meaning":"gieo (hạt giống)","example":"春に、畑にトマトの種を蒔きました。","example_reading":"はるに、はたけにとまとのたねをまきました。","example_meaning":"Mùa xuân, tôi đã gieo hạt cà chua ngoài ruộng.","examples":[{"example":"花壇に、ひまわりの種を蒔きます。","example_reading":"かだんに、ひまわりのたねをまきます。","example_meaning":"Tôi gieo hạt hướng dương vào bồn hoa."},{"example":"「蒔かぬ種は生えぬ」という言葉があります。","example_reading":"「まかぬたねははえぬ」ということばがあります。","example_meaning":"Có câu nói \"không gieo hạt thì không mọc\"."}]}]},
{"label":"煮る／似る","note":"煮る(にる): NẤU, HẦM, KHO trong nước hay nước dùng. 似る(にる): GIỐNG, tương tự (ngoại hình, tính cách, ý nghĩa).","items":[{"word":"煮る","reading":"にる","meaning":"nấu, hầm, kho","example":"野菜をやわらかくなるまで煮ます。","example_reading":"やさいをやわらかくなるまでにます。","example_meaning":"Nấu rau đến khi mềm.","examples":[{"example":"母は、魚を醤油と砂糖で煮ました。","example_reading":"ははは、さかなをしょうゆとさとうでにました。","example_meaning":"Mẹ đã kho cá với nước tương và đường."},{"example":"豆を一晩水につけて、ゆっくり煮ます。","example_reading":"まめをひとばんみずにつけて、ゆっくりにます。","example_meaning":"Ngâm đậu qua đêm rồi hầm từ từ."}]},{"word":"似る","reading":"にる","meaning":"giống, tương tự","example":"私は、母によく似ていると言われます。","example_reading":"わたしは、ははによくにているといわれます。","example_meaning":"Tôi hay được bảo là rất giống mẹ.","examples":[{"example":"あの二人は、顔も性格も似ています。","example_reading":"あのふたりは、かおもせいかくもにています。","example_meaning":"Hai người kia giống nhau cả khuôn mặt lẫn tính cách."},{"example":"この二つの言葉は、意味が似ています。","example_reading":"このふたつのことばは、いみがにています。","example_meaning":"Hai từ này có nghĩa gần giống nhau."}]}]},
{"label":"浸かる／漬かる","note":"浸かる(つかる): NGÂM MÌNH trong nước (bồn tắm, onsen); bị NGẬP nước. 漬かる(つかる): ĐƯỢC NGÂM, ĐƯỢC MUỐI, ngấm vị (dưa muối, ô mai, rau củ).","items":[{"word":"浸かる","reading":"つかる","meaning":"ngâm mình, bị ngập","example":"温泉にゆっくり浸かって、疲れが取れました。","example_reading":"おんせんにゆっくりつかって、つかれがとれました。","example_meaning":"Ngâm onsen thong thả giúp tôi hết mệt.","examples":[{"example":"大雨で、道路が水に浸かってしまいました。","example_reading":"おおあめで、どうろがみずにつかってしまいました。","example_meaning":"Mưa lớn khiến đường bị ngập nước."},{"example":"肩までお湯に浸かって、百まで数えました。","example_reading":"かたまでおゆにつかって、ひゃくまでかぞえました。","example_meaning":"Tôi ngâm mình đến vai trong nước nóng và đếm đến một trăm."}]},{"word":"漬かる","reading":"つかる","meaning":"được muối, được ngâm, ngấm vị","example":"このきゅうりは、よく漬かっていておいしいです。","example_reading":"このきゅうりは、よくつかっていておいしいです。","example_meaning":"Dưa chuột này muối ngấm đều nên rất ngon.","examples":[{"example":"白菜が漬かるまで、三日待ちます。","example_reading":"はくさいがつかるまで、みっかまちます。","example_meaning":"Phải đợi ba ngày cho cải thảo muối xong."},{"example":"梅干しが、いい具合に漬かりました。","example_reading":"うめぼしが、いいぐあいにつかりました。","example_meaning":"Ô mai đã ngấm vừa độ."}]}]},
{"label":"使う／遣う","note":"使う(つかう): DÙNG, SỬ DỤNG (đồ vật, tiền, thời gian, đầu óc, người). 遣う(つかう): dùng cho SỰ QUAN TÂM, TÂM TRÍ trong 気を遣う (giữ ý, để tâm); còn gặp trong 心遣い, 言葉遣い, 無駄遣い.","items":[{"word":"使う","reading":"つかう","meaning":"dùng, sử dụng","example":"このペンを使ってもいいですか。","example_reading":"このぺんをつかってもいいですか。","example_meaning":"Tôi dùng cây bút này được không?","examples":[{"example":"私は、スマホをあまり使いません。","example_reading":"わたしは、すまほをあまりつかいません。","example_meaning":"Tôi không dùng điện thoại thông minh nhiều lắm."},{"example":"彼は、頭を使う仕事が得意です。","example_reading":"かれは、あたまをつかうしごとがとくいです。","example_meaning":"Anh ấy giỏi những việc phải dùng đầu óc."}]},{"word":"遣う","reading":"つかう","meaning":"để tâm, giữ ý (気を遣う)","example":"目上の人と話すときは、気を遣います。","example_reading":"めうえのひととはなすときは、きをつかいます。","example_meaning":"Khi nói chuyện với người bề trên, tôi luôn giữ ý tứ.","examples":[{"example":"友達に気を遣って、本当のことを言えませんでした。","example_reading":"ともだちにきをつかって、ほんとうのことをいえませんでした。","example_meaning":"Vì ngại bạn nên tôi đã không nói được sự thật."},{"example":"新入社員に気を遣いすぎて、疲れてしまいました。","example_reading":"しんにゅうしゃいんにきをつかいすぎて、つかれてしまいました。","example_meaning":"Tôi giữ ý với nhân viên mới quá mức nên mệt cả người."}]}]},
{"label":"要る／居る／射る／煎る","note":"要る(いる): CẦN, CẦN THIẾT. 居る(いる): CÓ, Ở (người, động vật hiện diện); thường viết bằng kana. 射る(いる): BẮN (cung tên, tia sáng). 煎る(いる): RANG, SAO khô (mè, đậu, lá trà).","items":[{"word":"要る","reading":"いる","meaning":"cần, cần thiết","example":"旅行には、パスポートが要ります。","example_reading":"りょこうには、ぱすぽーとがいります。","example_meaning":"Đi du lịch cần có hộ chiếu.","examples":[{"example":"この仕事は、体力が要ります。","example_reading":"このしごとは、たいりょくがいります。","example_meaning":"Công việc này cần thể lực."},{"example":"ビニール袋は要りません。","example_reading":"びにーるぶくろはいりません。","example_meaning":"Tôi không cần túi nilon."}]},{"word":"居る","reading":"いる","meaning":"có, ở (người, động vật)","example":"教室には、まだ五人の学生が居ます。","example_reading":"きょうしつには、まだごにんのがくせいがいます。","example_meaning":"Trong lớp học vẫn còn năm sinh viên.","examples":[{"example":"兄は、今東京に居ます。","example_reading":"あには、いまとうきょうにいます。","example_meaning":"Anh trai tôi bây giờ đang ở Tokyo."},{"example":"庭に、見たことのない鳥が居ました。","example_reading":"にわに、みたことのないとりがいました。","example_meaning":"Trong vườn có một con chim tôi chưa từng thấy."}]},{"word":"射る","reading":"いる","meaning":"bắn (cung tên)","example":"弓で矢を射ると、的に当たりました。","example_reading":"ゆみでやをいると、まとにあたりました。","example_meaning":"Bắn mũi tên bằng cung thì trúng đích.","examples":[{"example":"弓道部では、毎日、弓を射る練習をします。","example_reading":"きゅうどうぶでは、まいにち、ゆみをいるれんしゅうをします。","example_meaning":"Ở câu lạc bộ cung đạo, ngày nào cũng luyện bắn cung."},{"example":"彼女は、的の中心を見事に射ました。","example_reading":"かのじょは、まとのちゅうしんをみごとにいました。","example_meaning":"Cô ấy bắn trúng chính giữa tâm đích một cách xuất sắc."}]},{"word":"煎る","reading":"いる","meaning":"rang, sao khô","example":"ごまを煎ると、いい香りがします。","example_reading":"ごまをいると、いいかおりがします。","example_meaning":"Rang mè lên thì có mùi thơm.","examples":[{"example":"フライパンで、豆を弱火で煎ります。","example_reading":"ふらいぱんで、まめをよわびでいります。","example_meaning":"Rang đậu bằng chảo với lửa nhỏ."},{"example":"お茶の葉を煎って、ほうじ茶を作ります。","example_reading":"おちゃのはをいって、ほうじちゃをつくります。","example_meaning":"Rang lá trà để làm hojicha."}]}]},
{"label":"向く／剥く","note":"向く(むく): QUAY VỀ, HƯỚNG VỀ một phía; HỢP với, thích hợp (性格に向く). 剥く(むく): BÓC, GỌT vỏ (trái cây, rau củ).","items":[{"word":"向く","reading":"むく","meaning":"quay về, hướng về; hợp với","example":"名前を呼ばれて、後ろを向きました。","example_reading":"なまえをよばれて、うしろをむきました。","example_meaning":"Nghe gọi tên, tôi quay người lại phía sau.","examples":[{"example":"私の部屋は、南を向いています。","example_reading":"わたしのへやは、みなみをむいています。","example_meaning":"Phòng tôi quay về hướng nam."},{"example":"この仕事は、私には向いていないと思います。","example_reading":"このしごとは、わたしにはむいていないとおもいます。","example_meaning":"Tôi nghĩ công việc này không hợp với tôi."}]},{"word":"剥く","reading":"むく","meaning":"bóc, gọt vỏ","example":"りんごの皮を剥いてあげます。","example_reading":"りんごのかわをむいてあげます。","example_meaning":"Tôi gọt vỏ táo cho bạn.","examples":[{"example":"みかんを剥いて、みんなで食べました。","example_reading":"みかんをむいて、みんなでたべました。","example_meaning":"Chúng tôi bóc cam rồi cùng ăn."},{"example":"玉ねぎを剥くと、涙が出ます。","example_reading":"たまねぎをむくと、なみだがでます。","example_meaning":"Bóc hành tây là chảy nước mắt."}]}]},
{"label":"下げる／提げる","note":"下げる(さげる): HẠ XUỐNG, GIẢM, CÚI (đầu), DỌN (bát đĩa) đi. 提げる(さげる): XÁCH, TREO lủng lẳng (đồ cầm bằng tay, đeo bên hông).","items":[{"word":"下げる","reading":"さげる","meaning":"hạ xuống, giảm, cúi, dọn đi","example":"先生に、深く頭を下げました。","example_reading":"せんせいに、ふかくあたまをさげました。","example_meaning":"Tôi cúi đầu thật sâu chào thầy.","examples":[{"example":"暑いので、エアコンの温度を下げます。","example_reading":"あついので、えあこんのおんどをさげます。","example_meaning":"Nóng quá nên tôi hạ nhiệt độ máy lạnh xuống."},{"example":"食べ終わったお皿を、台所に下げました。","example_reading":"たべおわったおさらを、だいどころにさげました。","example_meaning":"Tôi đã dọn đĩa ăn xong vào bếp."}]},{"word":"提げる","reading":"さげる","meaning":"xách, treo lủng lẳng","example":"彼は、大きな紙袋を手に提げていました。","example_reading":"かれは、おおきなかみぶくろをてにさげていました。","example_meaning":"Anh ấy xách một túi giấy lớn trên tay.","examples":[{"example":"買い物かごを提げて、市場へ行きます。","example_reading":"かいものかごをさげて、いちばへいきます。","example_meaning":"Tôi xách giỏ đi chợ."},{"example":"腰に刀を提げた侍が、通りを歩いています。","example_reading":"こしにかたなをさげたさむらいが、とおりをあるいています。","example_meaning":"Chàng samurai đeo kiếm bên hông đang đi trên phố."}]}]},
{"label":"飛ぶ／跳ぶ","note":"飛ぶ(とぶ): BAY (chim, máy bay), văng đi, lao nhanh, bay mất. 跳ぶ(とぶ): NHẢY, BẬT lên khỏi mặt đất, nhảy qua chướng ngại.","items":[{"word":"飛ぶ","reading":"とぶ","meaning":"bay, văng đi","example":"鳥が空を飛んでいます。","example_reading":"とりがそらをとんでいます。","example_meaning":"Chim đang bay trên bầu trời.","examples":[{"example":"この飛行機は、東京から大阪まで一時間で飛びます。","example_reading":"このひこうきは、とうきょうからおおさかまでいちじかんでとびます。","example_meaning":"Chiếc máy bay này bay từ Tokyo đến Osaka trong một giờ."},{"example":"風で帽子が飛んでしまいました。","example_reading":"かぜでぼうしがとんでしまいました。","example_meaning":"Gió thổi bay mất chiếc mũ."}]},{"word":"跳ぶ","reading":"とぶ","meaning":"nhảy, bật lên","example":"子どもたちが、縄を跳んで遊んでいます。","example_reading":"こどもたちが、なわをとんであそんでいます。","example_meaning":"Bọn trẻ đang nhảy dây chơi.","examples":[{"example":"彼は、高さ二メートルのバーを跳びました。","example_reading":"かれは、たかさにめーとるのばーをとびました。","example_meaning":"Anh ấy đã nhảy qua xà cao hai mét."},{"example":"小さな川を、ひょいと跳んで渡りました。","example_reading":"ちいさなかわを、ひょいととんでわたりました。","example_meaning":"Tôi nhảy phắt qua con sông nhỏ."}]}]},
{"label":"乾く／渇く","note":"乾く(かわく): KHÔ, RÁO (quần áo, tóc, đất, không khí hết hơi nước). 渇く(かわく): KHÁT (cổ họng), nghĩa bóng là khao khát (tình thương).","items":[{"word":"乾く","reading":"かわく","meaning":"khô, ráo","example":"洗濯物が、天気がいいのですぐ乾きました。","example_reading":"せんたくものが、てんきがいいのですぐかわきました。","example_meaning":"Trời đẹp nên đồ giặt khô ngay.","examples":[{"example":"髪がまだ乾いていないので、外に出られません。","example_reading":"かみがまだかわいていないので、そとにでられません。","example_meaning":"Tóc chưa khô nên tôi chưa ra ngoài được."},{"example":"空気が乾く冬は、肌が荒れやすいです。","example_reading":"くうきがかわくふゆは、はだがあれやすいです。","example_meaning":"Mùa đông không khí khô nên da dễ bị thô ráp."}]},{"word":"渇く","reading":"かわく","meaning":"khát, khao khát","example":"走ったので、喉が渇きました。","example_reading":"はしったので、のどがかわきました。","example_meaning":"Vì chạy nên tôi khát nước.","examples":[{"example":"砂漠で、喉が渇いて死にそうでした。","example_reading":"さばくで、のどがかわいてしにそうでした。","example_meaning":"Ở sa mạc, tôi khát đến suýt chết."},{"example":"愛に渇いた子どもは、いつも寂しそうです。","example_reading":"あいにかわいたこどもは、いつもさびしそうです。","example_meaning":"Đứa trẻ khao khát tình thương lúc nào cũng trông cô đơn."}]}]},
{"label":"閉じる／綴じる","note":"閉じる(とじる): ĐÓNG, KHÉP (mắt, sách, ô, cuộc họp, tài khoản). 綴じる(とじる): ĐÓNG GÁY, ĐÓNG TẬP giấy tờ (bằng kim bấm, chỉ).","items":[{"word":"閉じる","reading":"とじる","meaning":"đóng, khép, nhắm","example":"眠いので、目を閉じました。","example_reading":"ねむいので、めをとじました。","example_meaning":"Buồn ngủ nên tôi nhắm mắt lại.","examples":[{"example":"本を閉じて、先生の話を聞いてください。","example_reading":"ほんをとじて、せんせいのはなしをきいてください。","example_meaning":"Hãy gấp sách lại và nghe thầy nói."},{"example":"傘を閉じてから、店に入りました。","example_reading":"かさをとじてから、みせにはいりました。","example_meaning":"Tôi đóng ô lại rồi mới vào cửa hàng."}]},{"word":"綴じる","reading":"とじる","meaning":"đóng tập, đóng gáy (giấy tờ)","example":"書類をホチキスで綴じてください。","example_reading":"しょるいをほちきすでとじてください。","example_meaning":"Hãy đóng hồ sơ bằng kim bấm.","examples":[{"example":"資料をファイルに綴じて、棚に置きました。","example_reading":"しりょうをふぁいるにとじて、たなにおきました。","example_meaning":"Tôi đóng tài liệu vào tập hồ sơ rồi đặt lên kệ."},{"example":"古い新聞を、一年分ずつ綴じています。","example_reading":"ふるいしんぶんを、いちねんぶんずつとじています。","example_meaning":"Tôi đóng báo cũ lại theo từng năm."}]}]},
{"label":"歌う／唄う／謳う","note":"歌う(うたう): HÁT (cách viết chung nhất). 唄う(うたう): HÁT dân ca, nhạc truyền thống (民謡, 小唄, 子守唄), mang sắc thái cổ. 謳う(うたう): NÊU RÕ, TUYÊN BỐ, QUẢNG CÁO (hiến pháp, hợp đồng, sản phẩm).","items":[{"word":"歌う","reading":"うたう","meaning":"hát","example":"カラオケで、好きな歌を歌いました。","example_reading":"からおけで、すきなうたをうたいました。","example_meaning":"Tôi đã hát bài yêu thích ở karaoke.","examples":[{"example":"妹は、歌うのが大好きです。","example_reading":"いもうとは、うたうのがだいすきです。","example_meaning":"Em gái tôi rất thích hát."},{"example":"みんなで誕生日の歌を歌いました。","example_reading":"みんなでたんじょうびのうたをうたいました。","example_meaning":"Mọi người cùng hát bài chúc mừng sinh nhật."}]},{"word":"唄う","reading":"うたう","meaning":"hát (dân ca, nhạc truyền thống)","example":"三味線に合わせて、民謡を唄いました。","example_reading":"しゃみせんにあわせて、みんようをうたいました。","example_meaning":"Tôi hát dân ca theo tiếng đàn shamisen.","examples":[{"example":"祖母は、昔の子守唄を唄ってくれました。","example_reading":"そぼは、むかしのこもりうたをうたってくれました。","example_meaning":"Bà đã hát cho tôi nghe bài ru ngày xưa."},{"example":"祭りで、おじいさんが小唄を唄っていました。","example_reading":"まつりで、おじいさんがこうたをうたっていました。","example_meaning":"Trong lễ hội, ông cụ đang hát điệu kouta."}]},{"word":"謳う","reading":"うたう","meaning":"nêu rõ, tuyên bố, quảng cáo","example":"この憲法は、平和主義を謳っています。","example_reading":"このけんぽうは、へいわしゅぎをうたっています。","example_meaning":"Hiến pháp này nêu rõ chủ nghĩa hòa bình.","examples":[{"example":"この商品は、「世界一軽い」と謳っています。","example_reading":"このしょうひんは、「せかいいちかるい」とうたっています。","example_meaning":"Sản phẩm này quảng cáo là \"nhẹ nhất thế giới\"."},{"example":"契約書には、守秘義務が謳われています。","example_reading":"けいやくしょには、しゅひぎむがうたわれています。","example_meaning":"Trong hợp đồng có ghi rõ nghĩa vụ giữ bí mật."}]}]},
{"label":"賭ける／懸ける／架ける","note":"賭ける(かける): ĐẶT CƯỢC, đánh cược (tiền, vận may, kết quả). 懸ける(かける): LIỀU, DỐC, ĐEM RA ĐÁNH ĐỔI (mạng sống, cả đời); TREO thưởng. 架ける(かける): BẮC, XÂY, CĂNG (cầu, dây điện) qua khoảng cách.","items":[{"word":"賭ける","reading":"かける","meaning":"đặt cược","example":"友達と、昼ご飯を賭けて勝負しました。","example_reading":"ともだちと、ひるごはんをかけてしょうぶしました。","example_meaning":"Tôi đã đấu với bạn, cược bữa trưa.","examples":[{"example":"彼は、最後の一枚に運を賭けました。","example_reading":"かれは、さいごのいちまいにうんをかけました。","example_meaning":"Anh ấy đặt cược vận may vào lá bài cuối cùng."},{"example":"競馬に、お金を賭けすぎてはいけません。","example_reading":"けいばに、おかねをかけすぎてはいけません。","example_meaning":"Không được đặt cược quá nhiều tiền vào đua ngựa."}]},{"word":"懸ける","reading":"かける","meaning":"dốc, liều, treo thưởng","example":"消防士は、人の命を救うために命を懸けています。","example_reading":"しょうぼうしは、ひとのいのちをすくうためにいのちをかけています。","example_meaning":"Lính cứu hỏa dốc cả tính mạng để cứu người.","examples":[{"example":"彼は、研究に人生を懸けています。","example_reading":"かれは、けんきゅうにじんせいをかけています。","example_meaning":"Anh ấy dốc cả đời cho nghiên cứu."},{"example":"警察は、犯人に賞金を懸けました。","example_reading":"けいさつは、はんにんにしょうきんをかけました。","example_meaning":"Cảnh sát đã treo thưởng cho tên tội phạm."}]},{"word":"架ける","reading":"かける","meaning":"bắc, xây, căng (cầu, dây)","example":"川に、新しい橋を架けました。","example_reading":"かわに、あたらしいはしをかけました。","example_meaning":"Người ta đã bắc một cây cầu mới qua sông.","examples":[{"example":"谷の両側に、つり橋を架ける工事をしています。","example_reading":"たにのりょうがわに、つりばしをかけるこうじをしています。","example_meaning":"Đang thi công bắc cầu treo qua hai bờ thung lũng."},{"example":"鉄塔の間に、電線を架けました。","example_reading":"てっとうのあいだに、でんせんをかけました。","example_meaning":"Họ đã căng dây điện giữa các cột điện cao thế."}]}]},
{"label":"吐く／掃く／履く","note":"吐く(はく): NHẢ, NÔN, THỞ RA (hơi thở, đồ ăn, lời than). 掃く(はく): QUÉT bằng chổi (sân, nhà, lá rụng). 履く(はく): MANG, MẶC (giày, tất, quần, váy phần dưới thân).","items":[{"word":"吐く","reading":"はく","meaning":"nôn, thở ra, nhả ra","example":"気分が悪くて、食べたものを吐きました。","example_reading":"きぶんがわるくて、たべたものをはきました。","example_meaning":"Tôi thấy khó chịu và đã nôn đồ vừa ăn.","examples":[{"example":"深く息を吸って、ゆっくり吐いてください。","example_reading":"ふかくいきをすって、ゆっくりはいてください。","example_meaning":"Hãy hít sâu rồi thở ra chậm rãi."},{"example":"彼は、弱音を吐かずに最後まで頑張りました。","example_reading":"かれは、よわねをはかずにさいごまでがんばりました。","example_meaning":"Anh ấy không than thở mà cố gắng đến cùng."}]},{"word":"掃く","reading":"はく","meaning":"quét (bằng chổi)","example":"毎朝、玄関の前を掃きます。","example_reading":"まいあさ、げんかんのまえをはきます。","example_meaning":"Mỗi sáng tôi quét trước cửa nhà.","examples":[{"example":"落ち葉を、ほうきで掃いて集めました。","example_reading":"おちばを、ほうきではいてあつめました。","example_meaning":"Tôi dùng chổi quét lá rụng gom lại."},{"example":"部屋を掃いてから、ぞうきんで拭きます。","example_reading":"へやをはいてから、ぞうきんでふきます。","example_meaning":"Quét phòng xong thì lau bằng giẻ."}]},{"word":"履く","reading":"はく","meaning":"mang, mặc (giày, tất, quần, váy)","example":"外に出るので、靴を履きました。","example_reading":"そとにでるので、くつをはきました。","example_meaning":"Tôi đi giày để ra ngoài.","examples":[{"example":"冬は、厚い靴下を二枚履きます。","example_reading":"ふゆは、あついくつしたをにまいはきます。","example_meaning":"Mùa đông tôi mang hai đôi tất dày."},{"example":"彼女は、短いスカートを履いています。","example_reading":"かのじょは、みじかいすかーとをはいています。","example_meaning":"Cô ấy đang mặc váy ngắn."}]}]},
{"label":"落ちる／堕ちる／墜ちる","note":"落ちる(おちる): RƠI, RỚT, TRƯỢT (kỳ thi), phai sạch (vết bẩn). 堕ちる(おちる): SA ĐỌA, SA NGÃ (đạo đức, địa ngục, thân phận). 墜ちる(おちる): RƠI từ trên cao xuống (máy bay, vệ tinh) và gặp nạn.","items":[{"word":"落ちる","reading":"おちる","meaning":"rơi, rớt, trượt, phai","example":"机から、ペンが落ちました。","example_reading":"つくえから、ぺんがおちました。","example_meaning":"Cây bút rơi khỏi bàn.","examples":[{"example":"試験に落ちて、とても残念でした。","example_reading":"しけんにおちて、とてもざんねんでした。","example_meaning":"Tôi trượt kỳ thi nên rất tiếc."},{"example":"洗っても、このしみは落ちません。","example_reading":"あらっても、このしみはおちません。","example_meaning":"Dù giặt cũng không sạch được vết bẩn này."}]},{"word":"堕ちる","reading":"おちる","meaning":"sa đọa, sa ngã","example":"悪い仲間と付き合って、不良に堕ちてしまいました。","example_reading":"わるいなかまとつきあって、ふりょうにおちてしまいました。","example_meaning":"Giao du với bạn xấu nên cậu ấy đã sa vào con đường hư hỏng.","examples":[{"example":"彼は、金の誘惑に負けて、堕ちていきました。","example_reading":"かれは、かねのゆうわくにまけて、おちていきました。","example_meaning":"Anh ta không cưỡng nổi cám dỗ tiền bạc nên ngày càng sa đọa."},{"example":"罪を犯した者は、地獄に堕ちると言われています。","example_reading":"つみをおかしたものは、じごくにおちるといわれています。","example_meaning":"Người ta nói kẻ phạm tội sẽ đọa xuống địa ngục."}]},{"word":"墜ちる","reading":"おちる","meaning":"rơi (từ trên cao), gặp nạn","example":"山の中に、飛行機が墜ちました。","example_reading":"やまのなかに、ひこうきがおちました。","example_meaning":"Một chiếc máy bay đã rơi giữa núi.","examples":[{"example":"ロケットの破片が、海に墜ちたそうです。","example_reading":"ろけっとのはへんが、うみにおちたそうです。","example_meaning":"Nghe nói mảnh vỡ của tên lửa đã rơi xuống biển."},{"example":"古い人工衛星が、地球に墜ちてきました。","example_reading":"ふるいじんこうえいせいが、ちきゅうにおちてきました。","example_meaning":"Vệ tinh nhân tạo cũ đã rơi xuống Trái Đất."}]}]},
{"label":"望む／臨む","note":"望む(のぞむ): MONG MUỐN, HY VỌNG; phóng tầm mắt nhìn ra xa (phong cảnh). 臨む(のぞむ): ĐỐI MẶT, BƯỚC VÀO, THAM DỰ (trận đấu, họp báo); quay mặt ra (biển, sông).","items":[{"word":"望む","reading":"のぞむ","meaning":"mong muốn; phóng tầm mắt nhìn","example":"私は、世界の平和を望んでいます。","example_reading":"わたしは、せかいのへいわをのぞんでいます。","example_meaning":"Tôi mong muốn hòa bình thế giới.","examples":[{"example":"親は、子どもの幸せだけを望んでいます。","example_reading":"おやは、こどものしあわせだけをのぞんでいます。","example_meaning":"Cha mẹ chỉ mong con cái được hạnh phúc."},{"example":"窓から、遠くに富士山を望むことができます。","example_reading":"まどから、とおくにふじさんをのぞむことができます。","example_meaning":"Từ cửa sổ có thể phóng tầm mắt nhìn thấy núi Phú Sĩ ở xa."}]},{"word":"臨む","reading":"のぞむ","meaning":"đối mặt, tham dự; quay ra","example":"選手たちは、決勝戦に臨みました。","example_reading":"せんしゅたちは、けっしょうせんにのぞみました。","example_meaning":"Các vận động viên đã bước vào trận chung kết.","examples":[{"example":"社長は、記者会見に臨みました。","example_reading":"しゃちょうは、きしゃかいけんにのぞみました。","example_meaning":"Giám đốc đã tham dự buổi họp báo."},{"example":"このホテルは、海に臨む丘の上にあります。","example_reading":"このほてるは、うみにのぞむおかのうえにあります。","example_meaning":"Khách sạn này nằm trên ngọn đồi quay ra biển."}]}]},
{"label":"木／気／黄","note":"木(き): CÂY, GỖ. 気(き): KHÍ, TÂM TRÍ, Ý CHÍ, cảm giác (気をつける, 気になる, 気がする). 黄(き): MÀU VÀNG (黄色, 黄色い; đứng riêng trong 黄に染まる, 黄信号).","items":[{"word":"木","reading":"き","meaning":"cây, gỗ","example":"庭に大きな木があります。","example_reading":"にわにおおきなきがあります。","example_meaning":"Trong vườn có một cái cây lớn.","examples":[{"example":"木で作った椅子は、温かい感じがします。","example_reading":"きでつくったいすは、あたたかいかんじがします。","example_meaning":"Chiếc ghế làm bằng gỗ cho cảm giác ấm áp."},{"example":"木の下で、友達とお弁当を食べました。","example_reading":"きのしたで、ともだちとおべんとうをたべました。","example_meaning":"Tôi ăn cơm hộp với bạn dưới gốc cây."}]},{"word":"気","reading":"き","meaning":"khí, tâm trí, ý chí, cảm giác","example":"気をつけて帰ってください。","example_reading":"きをつけてかえってください。","example_meaning":"Hãy cẩn thận khi về nhé.","examples":[{"example":"今日は、勉強する気が起きません。","example_reading":"きょうは、べんきょうするきがおきません。","example_meaning":"Hôm nay tôi chẳng có hứng học."},{"example":"彼女の言葉が気になって、眠れませんでした。","example_reading":"かのじょのことばがきになって、ねむれませんでした。","example_meaning":"Lời cô ấy nói cứ ám ảnh nên tôi không ngủ được."}]},{"word":"黄","reading":"き","meaning":"màu vàng","example":"信号が黄に変わったので、止まりました。","example_reading":"しんごうがきにかわったので、とまりました。","example_meaning":"Đèn chuyển sang vàng nên tôi đã dừng lại.","examples":[{"example":"秋になると、銀杏の葉が黄に染まります。","example_reading":"あきになると、いちょうのはがきにそまります。","example_meaning":"Mùa thu, lá bạch quả nhuộm một màu vàng."},{"example":"黄色いバナナは、甘くて食べごろです。","example_reading":"きいろいばななは、あまくてたべごろです。","example_meaning":"Chuối vàng thì ngọt và đang vừa độ ăn."}]}]},
{"label":"目／芽","note":"目(め): MẮT; cái nhìn, trải nghiệm (ひどい目に遭う). 芽(め): MẦM, CHỒI non (cây mới nảy); nghĩa bóng là mầm mống, khởi đầu.","items":[{"word":"目","reading":"め","meaning":"mắt","example":"私は、目が悪いので、眼鏡をかけています。","example_reading":"わたしは、めがわるいので、めがねをかけています。","example_meaning":"Mắt tôi kém nên phải đeo kính.","examples":[{"example":"赤ちゃんは、大きな目で私を見つめました。","example_reading":"あかちゃんは、おおきなめでわたしをみつめました。","example_meaning":"Em bé nhìn tôi chăm chú bằng đôi mắt to tròn."},{"example":"昨日、ひどい目に遭いました。","example_reading":"きのう、ひどいめにあいました。","example_meaning":"Hôm qua tôi đã gặp một chuyện thật tồi tệ."}]},{"word":"芽","reading":"め","meaning":"mầm, chồi","example":"春になると、木に新しい芽が出ます。","example_reading":"はるになると、きにあたらしいめがでます。","example_meaning":"Mùa xuân đến, cây nảy những mầm mới.","examples":[{"example":"植えた種から、小さな芽が出ました。","example_reading":"うえたたねから、ちいさなめがでました。","example_meaning":"Từ hạt giống đã gieo, một mầm nhỏ đã nhú lên."},{"example":"悪い芽は、早いうちに摘んでおきましょう。","example_reading":"わるいめは、はやいうちにつんでおきましょう。","example_meaning":"Hãy ngắt bỏ mầm xấu ngay từ sớm."}]}]},
{"label":"葉／歯／刃","note":"葉(は): LÁ cây. 歯(は): RĂNG. 刃(は): LƯỠI (dao, kiếm, kéo).","items":[{"word":"葉","reading":"は","meaning":"lá cây","example":"秋になると、桜の葉が赤くなります。","example_reading":"あきになると、さくらのはがあかくなります。","example_meaning":"Mùa thu, lá anh đào chuyển sang màu đỏ.","examples":[{"example":"この葉は、お茶に使われます。","example_reading":"このはは、おちゃにつかわれます。","example_meaning":"Loại lá này được dùng để pha trà."},{"example":"柳の葉が風に揺れています。","example_reading":"やなぎのはがかぜにゆれています。","example_meaning":"Lá liễu đang đung đưa trong gió."}]},{"word":"歯","reading":"は","meaning":"răng","example":"毎食後、歯を磨きます。","example_reading":"まいしょくご、はをみがきます。","example_meaning":"Sau mỗi bữa ăn, tôi đánh răng.","examples":[{"example":"歯が痛いので、歯医者に行きます。","example_reading":"はがいたいので、はいしゃにいきます。","example_meaning":"Tôi bị đau răng nên đi nha sĩ."},{"example":"子どもの歯が、一本抜けました。","example_reading":"こどものはが、いっぽんぬけました。","example_meaning":"Một chiếc răng của đứa bé đã rụng."}]},{"word":"刃","reading":"は","meaning":"lưỡi (dao, kiếm, kéo)","example":"このナイフは、刃がとても鋭いです。","example_reading":"このないふは、はがとてもするどいです。","example_meaning":"Con dao này có lưỡi rất sắc.","examples":[{"example":"包丁の刃が欠けてしまいました。","example_reading":"ほうちょうのはがかけてしまいました。","example_meaning":"Lưỡi dao làm bếp bị mẻ rồi."},{"example":"刃の部分に、手を触れないでください。","example_reading":"はのぶぶんに、てをふれないでください。","example_meaning":"Xin đừng chạm tay vào phần lưỡi dao."}]}]},
{"label":"日／火／陽","note":"日(ひ): NGÀY; MẶT TRỜI, ánh nắng. 火(ひ): LỬA. 陽(ひ): NẮNG, ÁNH MẶT TRỜI (陽が差す, 陽が当たる); thường viết bằng 日.","items":[{"word":"日","reading":"ひ","meaning":"ngày; mặt trời","example":"今日は、とてもいい日でした。","example_reading":"きょうは、とてもいいひでした。","example_meaning":"Hôm nay là một ngày rất tuyệt.","examples":[{"example":"日が長くなって、夕方でも明るいです。","example_reading":"ひがながくなって、ゆうがたでもあかるいです。","example_meaning":"Ngày dài ra nên chiều tối trời vẫn sáng."},{"example":"雨の日は、家で本を読みます。","example_reading":"あめのひは、いえでほんをよみます。","example_meaning":"Những ngày mưa, tôi ở nhà đọc sách."}]},{"word":"火","reading":"ひ","meaning":"lửa","example":"火を使うときは、気をつけてください。","example_reading":"ひをつかうときは、きをつけてください。","example_meaning":"Khi dùng lửa hãy cẩn thận.","examples":[{"example":"寒いので、火のそばに座りました。","example_reading":"さむいので、ひのそばにすわりました。","example_meaning":"Trời lạnh nên tôi ngồi gần lửa."},{"example":"台所の火を、消し忘れました。","example_reading":"だいどころのひを、けしわすれました。","example_meaning":"Tôi quên tắt lửa trong bếp."}]},{"word":"陽","reading":"ひ","meaning":"nắng, ánh mặt trời","example":"朝、窓から陽が差し込みます。","example_reading":"あさ、まどからひがさしこみます。","example_meaning":"Buổi sáng, ánh nắng chiếu vào qua cửa sổ.","examples":[{"example":"この部屋は、一日中、陽が当たります。","example_reading":"このへやは、いちにちじゅう、ひがあたります。","example_meaning":"Căn phòng này có nắng chiếu suốt cả ngày."},{"example":"陽が沈むと、あたりは急に暗くなりました。","example_reading":"ひがしずむと、あたりはきゅうにくらくなりました。","example_meaning":"Mặt trời lặn là xung quanh bỗng tối sầm."}]}]},
{"label":"足／脚","note":"足(あし): CHÂN (nói chung, cả bàn chân), cũng là phương tiện đi lại (足がない). 脚(あし): CẲNG, ĐÙI, đôi chân dài (dáng chân người), CHÂN của đồ vật (chân bàn, chân ghế).","items":[{"word":"足","reading":"あし","meaning":"chân (bàn chân), phương tiện đi lại","example":"長く歩いて、足が痛くなりました。","example_reading":"ながくあるいて、あしがいたくなりました。","example_meaning":"Đi bộ lâu nên chân tôi đau.","examples":[{"example":"靴を脱いで、足を洗いました。","example_reading":"くつをぬいで、あしをあらいました。","example_meaning":"Tôi cởi giày rồi rửa chân."},{"example":"終電が出て、帰る足がなくなりました。","example_reading":"しゅうでんがでて、かえるあしがなくなりました。","example_meaning":"Tàu cuối đã chạy nên tôi không còn phương tiện về nhà."}]},{"word":"脚","reading":"あし","meaning":"cẳng, đùi, chân (đồ vật)","example":"あのモデルは、脚が長くて、とても美しいです。","example_reading":"あのもでるは、あしがながくて、とてもうつくしいです。","example_meaning":"Cô người mẫu kia có đôi chân dài, rất đẹp.","examples":[{"example":"椅子の脚が一本、折れてしまいました。","example_reading":"いすのあしがいっぽん、おれてしまいました。","example_meaning":"Một chân ghế đã bị gãy mất."},{"example":"彼は、サッカーで鍛えた脚で、速く走ります。","example_reading":"かれは、さっかーできたえたあしで、はやくはしります。","example_meaning":"Anh ấy chạy rất nhanh nhờ đôi chân rèn luyện qua bóng đá."}]}]},
{"label":"秋／飽き／空き","note":"秋(あき): MÙA THU. 飽き(あき): SỰ CHÁN, NGÁN (飽きが来る, 飽きる). 空き(あき): CHỖ TRỐNG, khoảng trống, lịch rảnh (空き地, 空き缶, 空きがある).","items":[{"word":"秋","reading":"あき","meaning":"mùa thu","example":"秋は、涼しくて過ごしやすい季節です。","example_reading":"あきは、すずしくてすごしやすいきせつです。","example_meaning":"Mùa thu là mùa mát mẻ, dễ chịu.","examples":[{"example":"日本では、秋に紅葉を見に行きます。","example_reading":"にほんでは、あきにこうようをみにいきます。","example_meaning":"Ở Nhật, người ta đi ngắm lá đỏ vào mùa thu."},{"example":"秋の夜は、虫の声が聞こえます。","example_reading":"あきのよるは、むしのこえがきこえます。","example_meaning":"Đêm thu nghe thấy tiếng côn trùng kêu."}]},{"word":"飽き","reading":"あき","meaning":"sự chán, ngán","example":"毎日同じ料理だと、飽きが来ます。","example_reading":"まいにちおなじりょうりだと、あきがきます。","example_meaning":"Ngày nào cũng món giống nhau thì sẽ phát ngán.","examples":[{"example":"このゲームは、すぐに飽きがきてしまいました。","example_reading":"このげーむは、すぐにあきがきてしまいました。","example_meaning":"Trò chơi này tôi chán ngay."},{"example":"飽きの来ない味で、何度でも食べたくなります。","example_reading":"あきのこないあじで、なんどでもたべたくなります。","example_meaning":"Vị này ăn không bao giờ ngán, ăn bao nhiêu lần cũng muốn ăn tiếp."}]},{"word":"空き","reading":"あき","meaning":"chỗ trống, lịch rảnh","example":"この駐車場には、空きがありません。","example_reading":"このちゅうしゃじょうには、あきがありません。","example_meaning":"Bãi đậu xe này không còn chỗ trống.","examples":[{"example":"空き缶は、分別して捨ててください。","example_reading":"あきかんは、ぶんべつしてすててください。","example_meaning":"Hãy phân loại lon rỗng rồi hãy vứt."},{"example":"来週の火曜日に、空きはありますか。","example_reading":"らいしゅうのかようびに、あきはありますか。","example_meaning":"Thứ Ba tuần sau bạn còn lịch trống không?"}]}]},
{"label":"濃い／恋／鯉","note":"濃い(こい): ĐẬM, ĐẶC, DÀY (màu sắc, vị, sương, râu). 恋(こい): TÌNH YÊU đôi lứa, SI TÌNH (恋をする). 鯉(こい): CÁ CHÉP (cá koi, 鯉のぼり).","items":[{"word":"濃い","reading":"こい","meaning":"đậm, đặc, dày","example":"このスープは、味が濃いです。","example_reading":"このすーぷは、あじがこいです。","example_meaning":"Món súp này vị đậm.","examples":[{"example":"濃い青色の服が、よく似合います。","example_reading":"こいあおいろのふくが、よくにあいます。","example_meaning":"Bộ đồ màu xanh đậm rất hợp với bạn."},{"example":"濃い霧が出て、前がよく見えません。","example_reading":"こいきりがでて、まえがよくみえません。","example_meaning":"Sương mù dày đặc nên không nhìn rõ phía trước."}]},{"word":"恋","reading":"こい","meaning":"tình yêu, si tình","example":"彼は、同じクラスの女の子に恋をしています。","example_reading":"かれは、おなじくらすのおんなのこにこいをしています。","example_meaning":"Cậu ấy đang phải lòng một bạn nữ cùng lớp.","examples":[{"example":"二人の恋は、三年後に実りました。","example_reading":"ふたりのこいは、さんねんごにみのりました。","example_meaning":"Tình yêu của hai người đã đơm hoa kết trái sau ba năm."},{"example":"初恋の人を、今でも覚えています。","example_reading":"はつこいのひとを、いまでもおぼえています。","example_meaning":"Tôi vẫn nhớ người mối tình đầu của mình."}]},{"word":"鯉","reading":"こい","meaning":"cá chép","example":"池で、赤や白の鯉が泳いでいます。","example_reading":"いけで、あかやしろのこいがおよいでいます。","example_meaning":"Trong ao có những con cá chép đỏ trắng đang bơi.","examples":[{"example":"五月には、鯉のぼりを飾ります。","example_reading":"ごがつには、こいのぼりをかざります。","example_meaning":"Vào tháng Năm người ta treo cờ cá chép."},{"example":"公園の池の鯉に、えさをやりました。","example_reading":"こうえんのいけのこいに、えさをやりました。","example_meaning":"Tôi cho cá chép ở ao công viên ăn."}]}]},
{"label":"川／皮／革","note":"川(かわ): SÔNG, DÒNG SÔNG. 皮(かわ): VỎ, DA (của người, thú, trái cây, bánh). 革(かわ): DA THUỘC (đồ da: ví, giày, cặp).","items":[{"word":"川","reading":"かわ","meaning":"sông","example":"夏に、川で魚を釣りました。","example_reading":"なつに、かわでさかなをつりました。","example_meaning":"Mùa hè tôi đã câu cá ở sông.","examples":[{"example":"この川は、とても流れが速いです。","example_reading":"このかわは、とてもながれがはやいです。","example_meaning":"Con sông này dòng chảy rất nhanh."},{"example":"川の水が、きれいで透き通っています。","example_reading":"かわのみずが、きれいですきとおっています。","example_meaning":"Nước sông sạch và trong vắt."}]},{"word":"皮","reading":"かわ","meaning":"vỏ, da","example":"バナナの皮を剥いて、食べます。","example_reading":"ばななのかわをむいて、たべます。","example_meaning":"Tôi bóc vỏ chuối rồi ăn.","examples":[{"example":"日焼けして、背中の皮がむけました。","example_reading":"ひやけして、せなかのかわがむけました。","example_meaning":"Cháy nắng nên da lưng bị bong ra."},{"example":"この餃子は、皮がもちもちしています。","example_reading":"このぎょうざは、かわがもちもちしています。","example_meaning":"Món sủi cảo này có lớp vỏ dai mềm."}]},{"word":"革","reading":"かわ","meaning":"da thuộc","example":"父は、革の財布を使っています。","example_reading":"ちちは、かわのさいふをつかっています。","example_meaning":"Bố tôi dùng chiếc ví da.","examples":[{"example":"この革のかばんは、長く使うほどいい味が出ます。","example_reading":"このかわのかばんは、ながくつかうほどいいあじがでます。","example_meaning":"Chiếc cặp da này càng dùng lâu càng đẹp."},{"example":"革の靴は、手入れが大切です。","example_reading":"かわのくつは、ていれがたいせつです。","example_meaning":"Giày da cần được chăm sóc cẩn thận."}]}]},
{"label":"蜂／鉢／八","note":"蜂(はち): CON ONG (ong mật, ong bắp cày). 鉢(はち): CHẬU (chậu cây), TÔ, BÁT lớn. 八(はち): SỐ TÁM.","items":[{"word":"蜂","reading":"はち","meaning":"con ong","example":"蜂に刺されて、腕が腫れました。","example_reading":"はちにさされて、うでがはれました。","example_meaning":"Tôi bị ong đốt nên cánh tay sưng lên.","examples":[{"example":"蜂が花の蜜を集めています。","example_reading":"はちがはなのみつをあつめています。","example_meaning":"Ong đang hút mật hoa."},{"example":"庭の木に、蜂の巣ができていました。","example_reading":"にわのきに、はちのすができていました。","example_meaning":"Có một tổ ong trên cây trong vườn."}]},{"word":"鉢","reading":"はち","meaning":"chậu cây, tô lớn","example":"ベランダで、鉢にバジルを育てています。","example_reading":"べらんだで、はちにばじるをそだてています。","example_meaning":"Tôi trồng húng quế trong chậu ở ban công.","examples":[{"example":"大きな鉢に、サラダを盛りました。","example_reading":"おおきなはちに、さらだをもりました。","example_meaning":"Tôi xới salad ra một chiếc tô lớn."},{"example":"花が咲いたので、鉢を窓辺に置きました。","example_reading":"はながさいたので、はちをまどべにおきました。","example_meaning":"Hoa đã nở nên tôi đặt chậu ở bên cửa sổ."}]},{"word":"八","reading":"はち","meaning":"số tám","example":"八時に起きて、朝ごはんを食べます。","example_reading":"はちじにおきて、あさごはんをたべます。","example_meaning":"Tôi dậy lúc tám giờ rồi ăn sáng.","examples":[{"example":"八に二を足すと、十になります。","example_reading":"はちににをたすと、じゅうになります。","example_meaning":"Tám cộng hai bằng mười."},{"example":"私の誕生日は、八月です。","example_reading":"わたしのたんじょうびは、はちがつです。","example_meaning":"Sinh nhật của tôi vào tháng Tám."}]}]},
{"label":"雲／蜘蛛","note":"雲(くも): MÂY. 蜘蛛(くも): CON NHỆN (nhện giăng tơ, mạng nhện).","items":[{"word":"雲","reading":"くも","meaning":"mây","example":"空に、白い雲が浮かんでいます。","example_reading":"そらに、しろいくもがうかんでいます。","example_meaning":"Trên bầu trời có những đám mây trắng đang trôi.","examples":[{"example":"雲が出てきたので、雨が降りそうです。","example_reading":"くもがでてきたので、あめがふりそうです。","example_meaning":"Mây kéo đến nên có vẻ sắp mưa."},{"example":"飛行機の窓から、雲の海が見えました。","example_reading":"ひこうきのまどから、くものうみがみえました。","example_meaning":"Từ cửa sổ máy bay, tôi nhìn thấy biển mây."}]},{"word":"蜘蛛","reading":"くも","meaning":"con nhện","example":"部屋の隅に、蜘蛛が巣を作っています。","example_reading":"へやのすみに、くもがすをつくっています。","example_meaning":"Có con nhện đang giăng tơ ở góc phòng.","examples":[{"example":"朝、庭の蜘蛛の巣に、露がついていました。","example_reading":"あさ、にわのくものすに、つゆがついていました。","example_meaning":"Buổi sáng, trên mạng nhện trong vườn có đọng sương."},{"example":"私は、蜘蛛が苦手で、見ると逃げてしまいます。","example_reading":"わたしは、くもがにがてで、みるとにげてしまいます。","example_meaning":"Tôi sợ nhện nên cứ thấy là bỏ chạy."}]}]},
{"label":"糸／意図","note":"糸(いと): SỢI CHỈ, SỢI TƠ, dây (chỉ khâu, dây diều, dây câu). 意図(いと): Ý ĐỒ, DỤ Ý, mục đích đằng sau lời nói hay hành động.","items":[{"word":"糸","reading":"いと","meaning":"sợi chỉ, sợi tơ, dây","example":"針に糸を通して、ボタンを付けます。","example_reading":"はりにいとをとおして、ぼたんをつけます。","example_meaning":"Xỏ chỉ vào kim rồi đính cúc.","examples":[{"example":"凧の糸が切れて、空へ飛んでいきました。","example_reading":"たこのいとがきれて、そらへとんでいきました。","example_meaning":"Dây diều đứt nên chiếc diều bay lên trời."},{"example":"蜘蛛が、細い糸を出して巣を作ります。","example_reading":"くもが、ほそいいとをだしてすをつくります。","example_meaning":"Nhện nhả sợi tơ mảnh để giăng mạng."}]},{"word":"意図","reading":"いと","meaning":"ý đồ, dụ ý","example":"彼の発言の意図が、よく分かりません。","example_reading":"かれのはつげんのいとが、よくわかりません。","example_meaning":"Tôi không hiểu rõ ý đồ trong phát ngôn của anh ấy.","examples":[{"example":"相手を傷つける意図は、ありませんでした。","example_reading":"あいてをきずつけるいとは、ありませんでした。","example_meaning":"Tôi không có ý định làm tổn thương đối phương."},{"example":"筆者の意図を考えながら、文章を読みましょう。","example_reading":"ひっしゃのいとをかんがえながら、ぶんしょうをよみましょう。","example_meaning":"Hãy vừa đọc vừa suy nghĩ về ý đồ của tác giả."}]}]},
{"label":"竹／丈／岳","note":"竹(たけ): TRE. 丈(たけ): CHIỀU DÀI, CHIỀU CAO (độ dài váy, ống quần); nghĩa bóng là toàn bộ (思いの丈). 岳(たけ): NÚI CAO, đặt sau tên núi (八ヶ岳, 槍ヶ岳).","items":[{"word":"竹","reading":"たけ","meaning":"tre","example":"庭に、竹がたくさん生えています。","example_reading":"にわに、たけがたくさんはえています。","example_meaning":"Trong vườn có nhiều tre mọc.","examples":[{"example":"竹で作ったかごは、軽くて丈夫です。","example_reading":"たけでつくったかごは、かるくてじょうぶです。","example_meaning":"Chiếc giỏ làm bằng tre vừa nhẹ vừa bền."},{"example":"七夕には、竹に短冊を飾ります。","example_reading":"たなばたには、たけにたんざくをかざります。","example_meaning":"Vào lễ Tanabata, người ta treo những tờ giấy điều ước lên cây tre."}]},{"word":"丈","reading":"たけ","meaning":"chiều dài, chiều cao; toàn bộ","example":"このスカートは、丈が少し短いです。","example_reading":"このすかーとは、たけがすこしみじかいです。","example_meaning":"Chiếc váy này hơi ngắn.","examples":[{"example":"ズボンの丈を、三センチ詰めてもらいました。","example_reading":"ずぼんのたけを、さんせんちつめてもらいました。","example_meaning":"Tôi nhờ cắt ngắn ống quần đi ba xăng-ti-mét."},{"example":"彼は、思いの丈を手紙に書きました。","example_reading":"かれは、おもいのたけをてがみにかきました。","example_meaning":"Anh ấy đã viết hết nỗi lòng mình vào lá thư."}]},{"word":"岳","reading":"たけ","meaning":"núi cao (trong tên núi)","example":"夏休みに、八ヶ岳に登りました。","example_reading":"なつやすみに、やつがたけにのぼりました。","example_meaning":"Kỳ nghỉ hè tôi đã leo núi Yatsugatake.","examples":[{"example":"槍ヶ岳は、尖った形の山です。","example_reading":"やりがたけは、とがったかたちのやまです。","example_meaning":"Yarigatake là ngọn núi có hình dáng nhọn hoắt."},{"example":"地図で、名前に「岳」がつく山を探しました。","example_reading":"ちずで、なまえに「たけ」がつくやまをさがしました。","example_meaning":"Trên bản đồ, tôi tìm những ngọn núi có chữ 岳 trong tên."}]}]},
{"label":"影／陰","note":"影(かげ): BÓNG (do vật cản sáng đổ xuống, bóng người), hình bóng. 陰(かげ): BÓNG RÂM, CHỖ KHUẤT, phía sau lưng (木の陰, 陰で悪口を言う).","items":[{"word":"影","reading":"かげ","meaning":"bóng (do ánh sáng tạo ra)","example":"夕方になると、影が長くなります。","example_reading":"ゆうがたになると、かげがながくなります。","example_meaning":"Chiều tối là bóng dài ra.","examples":[{"example":"壁に、木の影がうつっています。","example_reading":"かべに、きのかげがうつっています。","example_meaning":"Bóng cây in trên bức tường."},{"example":"月の光で、道に私の影ができました。","example_reading":"つきのひかりで、みちにわたしのかげができました。","example_meaning":"Dưới ánh trăng, bóng tôi đổ xuống đường."}]},{"word":"陰","reading":"かげ","meaning":"bóng râm, chỗ khuất, sau lưng","example":"暑いので、木の陰で休みました。","example_reading":"あついので、きのかげでやすみました。","example_meaning":"Trời nóng nên tôi nghỉ dưới bóng cây.","examples":[{"example":"彼は、陰で人の悪口を言う人です。","example_reading":"かれは、かげでひとのわるくちをいうひとです。","example_meaning":"Anh ta là người hay nói xấu sau lưng người khác."},{"example":"建物の陰に、猫が隠れていました。","example_reading":"たてもののかげに、ねこがかくれていました。","example_meaning":"Có một con mèo nấp sau bóng của tòa nhà."}]}]},
{"label":"町／街","note":"町(まち): THỊ TRẤN, KHU PHỐ nhỏ (đơn vị hành chính, nơi sinh sống). 街(まち): PHỐ XÁ, KHU PHỐ SẦM UẤT (đường phố, khu mua sắm, khu giải trí).","items":[{"word":"町","reading":"まち","meaning":"thị trấn","example":"私が生まれた町は、小さくて静かです。","example_reading":"わたしがうまれたまちは、ちいさくてしずかです。","example_meaning":"Thị trấn nơi tôi sinh ra nhỏ và yên tĩnh.","examples":[{"example":"この町には、古いお寺がたくさんあります。","example_reading":"このまちには、ふるいおてらがたくさんあります。","example_meaning":"Thị trấn này có rất nhiều ngôi chùa cổ."},{"example":"隣の町まで、バスで三十分かかります。","example_reading":"となりのまちまで、ばすでさんじゅっぷんかかります。","example_meaning":"Đến thị trấn bên cạnh mất ba mươi phút đi xe buýt."}]},{"word":"街","reading":"まち","meaning":"phố xá, khu phố sầm uất","example":"週末は、街へ買い物に行きます。","example_reading":"しゅうまつは、まちへかいものにいきます。","example_meaning":"Cuối tuần tôi ra phố mua sắm.","examples":[{"example":"クリスマスの街は、きれいなライトで飾られています。","example_reading":"くりすますのまちは、きれいならいとでかざられています。","example_meaning":"Phố xá dịp Giáng sinh được trang trí bằng đèn lung linh."},{"example":"夜の街を、友達と散歩しました。","example_reading":"よるのまちを、ともだちとさんぽしました。","example_meaning":"Tôi đã đi dạo phố đêm cùng bạn."}]}]},
{"label":"玉／球／弾","note":"玉(たま): VIÊN, HẠT TRÒN (ngọc, giọt nước, cuộn tròn). 球(たま): QUẢ BÓNG (bóng chày, bi-a, bóng ném). 弾(たま): ĐẠN (súng, pháo).","items":[{"word":"玉","reading":"たま","meaning":"viên, hạt tròn, ngọc","example":"葉の上に、水の玉がころがっています。","example_reading":"はのうえに、みずのたまがころがっています。","example_meaning":"Trên chiếc lá có giọt nước tròn đang lăn.","examples":[{"example":"糸を巻いて、毛糸の玉を作りました。","example_reading":"いとをまいて、けいとのたまをつくりました。","example_meaning":"Tôi cuộn sợi len thành một cuộn tròn."},{"example":"首飾りには、宝石のような玉がついています。","example_reading":"くびかざりには、ほうせきのようなたまがついています。","example_meaning":"Chiếc vòng cổ có những viên ngọc tròn như đá quý."}]},{"word":"球","reading":"たま","meaning":"quả bóng","example":"彼は、速い球を投げるピッチャーです。","example_reading":"かれは、はやいたまをなげるぴっちゃーです。","example_meaning":"Anh ấy là cầu thủ ném những quả bóng nhanh.","examples":[{"example":"ビリヤードで、球を穴に落としました。","example_reading":"びりやーどで、たまをあなにおとしました。","example_meaning":"Tôi đã đánh quả bóng bi-a vào lỗ."},{"example":"子どもが投げた球を、犬が追いかけました。","example_reading":"こどもがなげたたまを、いぬがおいかけました。","example_meaning":"Con chó đuổi theo quả bóng mà đứa bé ném."}]},{"word":"弾","reading":"たま","meaning":"đạn","example":"銃から弾が飛び出しました。","example_reading":"じゅうからたまがとびだしました。","example_meaning":"Viên đạn bay ra từ khẩu súng.","examples":[{"example":"兵士は、弾を込めて、銃を構えました。","example_reading":"へいしは、たまをこめて、じゅうをかまえました。","example_meaning":"Người lính nạp đạn rồi giương súng."},{"example":"弾が当たらなくて、敵に逃げられました。","example_reading":"たまがあたらなくて、てきににげられました。","example_meaning":"Đạn bắn không trúng nên đã để địch chạy thoát."}]}]},
{"label":"型／肩／方","note":"型(かた): KHUÔN, MẪU, KIỂU (khuôn bánh, kiểu dáng, bài quyền kata). 肩(かた): VAI. 方(かた): NGƯỜI, VỊ (cách nói lịch sự thay cho 人, như あの方).","items":[{"word":"型","reading":"かた","meaning":"khuôn, mẫu, kiểu, bài quyền","example":"この型で、クッキーを抜きます。","example_reading":"このかたで、くっきーをぬきます。","example_meaning":"Tôi dùng khuôn này để cắt bánh quy.","examples":[{"example":"彼は、いつも決まった型のスーツを着ています。","example_reading":"かれは、いつもきまったかたのすーつをきています。","example_meaning":"Anh ấy lúc nào cũng mặc kiểu vest cố định."},{"example":"柔道の型を、毎日練習しています。","example_reading":"じゅうどうのかたを、まいにちれんしゅうしています。","example_meaning":"Tôi luyện các bài quyền (kata) judo mỗi ngày."}]},{"word":"肩","reading":"かた","meaning":"vai","example":"重い荷物を持って、肩が痛くなりました。","example_reading":"おもいにもつをもって、かたがいたくなりました。","example_meaning":"Xách hành lý nặng nên vai tôi bị đau.","examples":[{"example":"母の肩を叩いてあげました。","example_reading":"ははのかたをたたいてあげました。","example_meaning":"Tôi đấm vai cho mẹ."},{"example":"長い間パソコンを使って、肩がこりました。","example_reading":"ながいあいだぱそこんをつかって、かたがこりました。","example_meaning":"Dùng máy tính lâu nên tôi bị mỏi vai."}]},{"word":"方","reading":"かた","meaning":"người, vị (lịch sự)","example":"あちらの方が、田中先生です。","example_reading":"あちらのかたが、たなかせんせいです。","example_meaning":"Vị kia chính là thầy Tanaka.","examples":[{"example":"お困りの方は、係員にお声がけください。","example_reading":"おこまりのかたは、かかりいんにおこえがけください。","example_meaning":"Quý vị nào gặp khó khăn xin hãy gọi nhân viên."},{"example":"親切な方が、道を教えてくれました。","example_reading":"しんせつなかたが、みちをおしえてくれました。","example_meaning":"Một người tốt bụng đã chỉ đường cho tôi."}]}]},
{"label":"鶴／蔓／弦","note":"鶴(つる): CON HẠC, chim sếu (biểu tượng trường thọ). 蔓(つる): DÂY LEO, TUA CUỐN; GỌNG kính. 弦(つる): DÂY CUNG (cung tên); cũng đọc げん khi chỉ dây đàn.","items":[{"word":"鶴","reading":"つる","meaning":"con hạc, chim sếu","example":"折り紙で、鶴を折りました。","example_reading":"おりがみで、つるをおりました。","example_meaning":"Tôi đã gấp con hạc bằng giấy origami.","examples":[{"example":"鶴は、長生きの鳥として知られています。","example_reading":"つるは、ながいきのとりとしてしられています。","example_meaning":"Hạc được biết đến là loài chim trường thọ."},{"example":"湿原で、鶴が餌を探していました。","example_reading":"しつげんで、つるがえさをさがしていました。","example_meaning":"Ở đầm lầy, những con hạc đang tìm mồi."}]},{"word":"蔓","reading":"つる","meaning":"dây leo, gọng kính","example":"朝顔の蔓が、フェンスに巻き付いています。","example_reading":"あさがおのつるが、ふぇんすにまきついています。","example_meaning":"Dây leo của hoa bìm bìm đang quấn quanh hàng rào.","examples":[{"example":"眼鏡の蔓が折れたので、修理に出しました。","example_reading":"めがねのつるがおれたので、しゅうりにだしました。","example_meaning":"Gọng kính bị gãy nên tôi mang đi sửa."},{"example":"ぶどうの蔓を、棚に這わせて育てます。","example_reading":"ぶどうのつるを、たなにはわせてそだてます。","example_meaning":"Người ta cho dây nho bò lên giàn để trồng."}]},{"word":"弦","reading":"つる","meaning":"dây cung","example":"弓の弦を張って、矢を構えました。","example_reading":"ゆみのつるをはって、やをかまえました。","example_meaning":"Căng dây cung rồi giương tên.","examples":[{"example":"弦が切れた弓では、矢が飛びません。","example_reading":"つるがきれたゆみでは、やがとびません。","example_meaning":"Cung đứt dây thì tên không bay được."},{"example":"新しい弓に、弦を取り付けました。","example_reading":"あたらしいゆみに、つるをとりつけました。","example_meaning":"Tôi đã lắp dây cung vào cây cung mới."}]}]},
{"label":"帆／穂／歩","note":"帆(ほ): BUỒM (thuyền buồm). 穂(ほ): BÔNG (lúa, lúa mạch, lau sậy). 歩(ほ): BƯỚC CHÂN, đi bộ (歩を進める, 歩道, 歩行); khi đếm bước thì đọc いっぽ, にほ.","items":[{"word":"帆","reading":"ほ","meaning":"buồm","example":"風を受けて、船の帆がふくらみました。","example_reading":"かぜをうけて、ふねのほがふくらみました。","example_meaning":"Gió thổi làm cánh buồm căng phồng.","examples":[{"example":"船が帆を上げて、港を出ました。","example_reading":"ふねがほをあげて、みなとをでました。","example_meaning":"Thuyền kéo buồm lên rồi rời cảng."},{"example":"白い帆のヨットが、海に浮かんでいます。","example_reading":"しろいほのよっとが、うみにうかんでいます。","example_meaning":"Chiếc du thuyền buồm trắng đang nổi trên biển."}]},{"word":"穂","reading":"ほ","meaning":"bông (lúa, lau)","example":"秋になると、稲の穂が黄金色になります。","example_reading":"あきになると、いねのほがこがねいろになります。","example_meaning":"Mùa thu, bông lúa chuyển sang màu vàng óng.","examples":[{"example":"すすきの穂が、風に揺れています。","example_reading":"すすきのほが、かぜにゆれています。","example_meaning":"Những bông lau đang đung đưa trong gió."},{"example":"麦の穂が出て、畑が緑から黄色に変わりました。","example_reading":"むぎのほがでて、はたけがみどりからきいろにかわりました。","example_meaning":"Lúa mạch trổ bông, ruộng đổi từ xanh sang vàng."}]},{"word":"歩","reading":"ほ","meaning":"bước chân, đi bộ","example":"歩道を歩くときは、周りに気をつけましょう。","example_reading":"ほどうをあるくときは、まわりにきをつけましょう。","example_meaning":"Khi đi trên vỉa hè, hãy chú ý xung quanh.","examples":[{"example":"彼は、新しい人生への歩を進めました。","example_reading":"かれは、あたらしいじんせいへのほをすすめました。","example_meaning":"Anh ấy đã bước thêm một bước vào cuộc sống mới."},{"example":"歩行者は、信号が青になるまで待ちます。","example_reading":"ほこうしゃは、しんごうがあおになるまでまちます。","example_meaning":"Người đi bộ đợi cho đến khi đèn chuyển xanh."}]}]},
{"label":"身／実","note":"身(み): THÂN MÌNH, CƠ THỂ, bản thân (身につける); phần THỊT (cá, thịt trong vỏ). 実(み): QUẢ, TRÁI, HẠT; nghĩa bóng là thành quả (実を結ぶ).","items":[{"word":"身","reading":"み","meaning":"thân mình, bản thân; thịt (cá)","example":"魚の身を、きれいにほぐして食べます。","example_reading":"さかなのみを、きれいにほぐしてたべます。","example_meaning":"Tôi gỡ phần thịt cá thật sạch rồi ăn.","examples":[{"example":"先生の言葉が、身にしみました。","example_reading":"せんせいのことばが、みにしみました。","example_meaning":"Lời thầy thấm sâu vào lòng tôi."},{"example":"身につけた技術は、一生の宝です。","example_reading":"みにつけたぎじゅつは、いっしょうのたからです。","example_meaning":"Kỹ năng đã học được là báu vật cả đời."}]},{"word":"実","reading":"み","meaning":"quả, trái, hạt","example":"庭の柿の木に、たくさん実がなりました。","example_reading":"にわのかきのきに、たくさんみがなりました。","example_meaning":"Cây hồng trong vườn đã sai quả.","examples":[{"example":"長い努力が、やっと実を結びました。","example_reading":"ながいどりょくが、やっとみをむすびました。","example_meaning":"Sau bao nỗ lực dài, cuối cùng cũng đơm hoa kết trái."},{"example":"鳥が、赤い実をついばんでいます。","example_reading":"とりが、あかいみをついばんでいます。","example_meaning":"Chim đang mổ những quả chín đỏ."}]}]},
{"label":"席／咳／籍","note":"席(せき): CHỖ NGỒI, GHẾ, chỗ trong buổi tiệc hay cuộc họp. 咳(せき): CƠN HO. 籍(せき): HỘ TỊCH, TƯ CÁCH thành viên, tên trong sổ (籍を入れる, 国籍, 在籍).","items":[{"word":"席","reading":"せき","meaning":"chỗ ngồi, ghế","example":"電車で、お年寄りに席を譲りました。","example_reading":"でんしゃで、おとしよりにせきをゆずりました。","example_meaning":"Trên tàu, tôi đã nhường chỗ cho người lớn tuổi.","examples":[{"example":"窓側の席を、予約しました。","example_reading":"まどがわのせきを、よやくしました。","example_meaning":"Tôi đã đặt chỗ ngồi cạnh cửa sổ."},{"example":"会議の途中で、少し席を外します。","example_reading":"かいぎのとちゅうで、すこしせきをはずします。","example_meaning":"Tôi xin rời chỗ một lát giữa buổi họp."}]},{"word":"咳","reading":"せき","meaning":"cơn ho","example":"風邪をひいて、咳が止まりません。","example_reading":"かぜをひいて、せきがとまりません。","example_meaning":"Tôi bị cảm nên ho không dứt.","examples":[{"example":"夜になると、咳がひどくなります。","example_reading":"よるになると、せきがひどくなります。","example_meaning":"Về đêm, cơn ho nặng hơn."},{"example":"咳をするときは、口にハンカチを当てましょう。","example_reading":"せきをするときは、くちにはんかちをあてましょう。","example_meaning":"Khi ho hãy lấy khăn che miệng."}]},{"word":"籍","reading":"せき","meaning":"hộ tịch, tư cách thành viên","example":"二人は、先月、籍を入れました。","example_reading":"ふたりは、せんげつ、せきをいれました。","example_meaning":"Hai người đã đăng ký kết hôn vào tháng trước.","examples":[{"example":"彼は、日本の国籍を持っています。","example_reading":"かれは、にほんのこくせきをもっています。","example_meaning":"Anh ấy mang quốc tịch Nhật Bản."},{"example":"兄は、この大学に在籍しています。","example_reading":"あには、このだいがくにざいせきしています。","example_meaning":"Anh trai tôi đang là sinh viên của trường đại học này."}]}]},
{"label":"鐘／金","note":"鐘(かね): CHUÔNG (chuông chùa, chuông nhà thờ, chuông báo). 金(かね): TIỀN; cũng chỉ vàng bạc, kim loại. Hai từ khác nhau về trọng âm.","items":[{"word":"鐘","reading":"かね","meaning":"chuông","example":"大晦日の夜、お寺の鐘が鳴ります。","example_reading":"おおみそかのよる、おてらのかねがなります。","example_meaning":"Đêm giao thừa, chuông chùa vang lên.","examples":[{"example":"教会の鐘の音が、町中に響きました。","example_reading":"きょうかいのかねのおとが、まちじゅうにひびきました。","example_meaning":"Tiếng chuông nhà thờ vang khắp phố."},{"example":"朝六時に、遠くで鐘が鳴っています。","example_reading":"あさろくじに、とおくでかねがなっています。","example_meaning":"Lúc sáu giờ sáng, có tiếng chuông vang từ xa."}]},{"word":"金","reading":"かね","meaning":"tiền","example":"旅行のために、金を貯めています。","example_reading":"りょこうのために、かねをためています。","example_meaning":"Tôi đang để dành tiền để đi du lịch.","examples":[{"example":"友達に金を貸しましたが、まだ返してもらっていません。","example_reading":"ともだちにかねをかしましたが、まだかえしてもらっていません。","example_meaning":"Tôi đã cho bạn vay tiền nhưng vẫn chưa được trả."},{"example":"彼は、金にだらしない人です。","example_reading":"かれは、かねにだらしないひとです。","example_meaning":"Anh ta là người luộm thuộm chuyện tiền bạc."}]}]},
{"label":"以前／依然","note":"以前(いぜん): TRƯỚC ĐÂY, trước một mốc thời gian (以前住んでいた, 二年以前). 依然(いぜん): VẪN, VẪN NHƯ CŨ, không có gì thay đổi (依然として).","items":[{"word":"以前","reading":"いぜん","meaning":"trước đây, trước kia","example":"私は、以前ここに住んでいました。","example_reading":"わたしは、いぜんここにすんでいました。","example_meaning":"Trước đây tôi từng sống ở đây.","examples":[{"example":"以前より、日本語が上手になりました。","example_reading":"いぜんより、にほんごがじょうずになりました。","example_meaning":"Tiếng Nhật của tôi giỏi hơn trước."},{"example":"二年以前の記録は、もう残っていません。","example_reading":"にねんいぜんのきろくは、もうのこっていません。","example_meaning":"Hồ sơ từ hai năm trước thì không còn nữa."}]},{"word":"依然","reading":"いぜん","meaning":"vẫn, vẫn như cũ","example":"事故の原因は、依然として分かっていません。","example_reading":"じこのげんいんは、いぜんとしてわかっていません。","example_meaning":"Nguyên nhân tai nạn vẫn chưa được làm rõ.","examples":[{"example":"雨は、依然として降り続いています。","example_reading":"あめは、いぜんとしてふりつづいています。","example_meaning":"Mưa vẫn tiếp tục rơi."},{"example":"彼の態度は、依然変わりません。","example_reading":"かれのたいどは、いぜんかわりません。","example_meaning":"Thái độ của anh ấy vẫn không thay đổi."}]}]},
{"label":"移動／異動","note":"移動(いどう): DI CHUYỂN, DỜI CHỖ (người, vật, vị trí). 異動(いどう): ĐIỀU ĐỘNG NHÂN SỰ, thay đổi bộ phận hay chức vụ trong tổ chức.","items":[{"word":"移動","reading":"いどう","meaning":"di chuyển, dời chỗ","example":"会場まで、バスで移動します。","example_reading":"かいじょうまで、ばすでいどうします。","example_meaning":"Chúng tôi di chuyển đến hội trường bằng xe buýt.","examples":[{"example":"邪魔なので、机を窓の方へ移動しました。","example_reading":"じゃまなので、つくえをまどのほうへいどうしました。","example_meaning":"Vướng quá nên tôi dời cái bàn sang phía cửa sổ."},{"example":"台風が、ゆっくり北へ移動しています。","example_reading":"たいふうが、ゆっくりきたへいどうしています。","example_meaning":"Bão đang di chuyển chậm về phía bắc."}]},{"word":"異動","reading":"いどう","meaning":"điều động nhân sự","example":"四月に、大阪支店へ異動になりました。","example_reading":"しがつに、おおさかしてんへいどうになりました。","example_meaning":"Tháng Tư tôi được điều động sang chi nhánh Osaka.","examples":[{"example":"人事異動が、来週発表されます。","example_reading":"じんじいどうが、らいしゅうはっぴょうされます。","example_meaning":"Việc điều động nhân sự sẽ được công bố vào tuần sau."},{"example":"彼は、営業部から総務部に異動しました。","example_reading":"かれは、えいぎょうぶからそうむぶにいどうしました。","example_meaning":"Anh ấy đã được chuyển từ phòng kinh doanh sang phòng hành chính."}]}]},
{"label":"運行／運航","note":"運行(うんこう): VẬN HÀNH theo lịch trình (tàu điện, xe buýt, thiên thể). 運航(うんこう): CHẠY TUYẾN, KHAI THÁC (tàu thủy, máy bay).","items":[{"word":"運行","reading":"うんこう","meaning":"vận hành (tàu điện, xe buýt)","example":"大雪のため、電車の運行が止まりました。","example_reading":"おおゆきのため、でんしゃのうんこうがとまりました。","example_meaning":"Do tuyết lớn, tàu điện đã ngừng chạy.","examples":[{"example":"このバスは、一時間に二本運行しています。","example_reading":"このばすは、いちじかんににほんうんこうしています。","example_meaning":"Tuyến xe buýt này chạy hai chuyến mỗi giờ."},{"example":"休日は、ダイヤを変えて運行します。","example_reading":"きゅうじつは、だいやをかえてうんこうします。","example_meaning":"Ngày nghỉ, xe chạy theo lịch trình khác."}]},{"word":"運航","reading":"うんこう","meaning":"chạy tuyến, khai thác (tàu thủy, máy bay)","example":"台風で、飛行機の運航が中止になりました。","example_reading":"たいふうで、ひこうきのうんこうがちゅうしになりました。","example_meaning":"Do bão, chuyến bay đã bị hủy.","examples":[{"example":"この船は、島までの航路を運航しています。","example_reading":"このふねは、しままでのこうろをうんこうしています。","example_meaning":"Con tàu này chạy tuyến đường biển ra đảo."},{"example":"天気が悪いと、フェリーは運航しません。","example_reading":"てんきがわるいと、ふぇりーはうんこうしません。","example_meaning":"Thời tiết xấu thì phà không chạy."}]}]},
{"label":"改定／改訂","note":"改定(かいてい): SỬA ĐỔI, ĐIỀU CHỈNH quy định, mức giá, biểu phí (料金改定, 制度改定). 改訂(かいてい): SỬA ĐỔI NỘI DUNG sách, tài liệu, từ điển (改訂版).","items":[{"word":"改定","reading":"かいてい","meaning":"sửa đổi, điều chỉnh (quy định, giá)","example":"来月から、電車の料金が改定されます。","example_reading":"らいげつから、でんしゃのりょうきんがかいていされます。","example_meaning":"Từ tháng sau, giá vé tàu điện sẽ được điều chỉnh.","examples":[{"example":"会社の規則が、四月に改定されました。","example_reading":"かいしゃのきそくが、しがつにかいていされました。","example_meaning":"Nội quy công ty đã được sửa đổi vào tháng Tư."},{"example":"契約の条件を、改定することになりました。","example_reading":"けいやくのじょうけんを、かいていすることになりました。","example_meaning":"Đã quyết định sửa đổi các điều khoản hợp đồng."}]},{"word":"改訂","reading":"かいてい","meaning":"sửa đổi, tái bản (sách, từ điển)","example":"この辞書は、去年、改訂されました。","example_reading":"このじしょは、きょねん、かいていされました。","example_meaning":"Cuốn từ điển này đã được tái bản có sửa đổi vào năm ngoái.","examples":[{"example":"教科書の改訂版が、発売されました。","example_reading":"きょうかしょのかいていばんが、はつばいされました。","example_meaning":"Bản sửa đổi của sách giáo khoa đã được phát hành."},{"example":"古い情報を直して、本を改訂しました。","example_reading":"ふるいじょうほうをなおして、ほんをかいていしました。","example_meaning":"Tôi đã chỉnh lại thông tin cũ và sửa đổi cuốn sách."}]}]},
{"label":"科学／化学","note":"科学(かがく): KHOA HỌC (nói chung: tư duy khoa học, các ngành khoa học tự nhiên). 化学(かがく): HÓA HỌC (ngành nghiên cứu chất và phản ứng). Khi nói, 化学 đôi khi đọc là ばけがく để phân biệt.","items":[{"word":"科学","reading":"かがく","meaning":"khoa học","example":"科学の進歩で、生活が便利になりました。","example_reading":"かがくのしんぽで、せいかつがべんりになりました。","example_meaning":"Nhờ sự tiến bộ của khoa học, cuộc sống trở nên tiện lợi.","examples":[{"example":"兄は、科学雑誌を毎月読んでいます。","example_reading":"あには、かがくざっしをまいつきよんでいます。","example_meaning":"Anh tôi đọc tạp chí khoa học mỗi tháng."},{"example":"科学者は、実験を繰り返して、結果を確かめます。","example_reading":"かがくしゃは、じっけんをくりかえして、けっかをたしかめます。","example_meaning":"Nhà khoa học lặp lại thí nghiệm để kiểm chứng kết quả."}]},{"word":"化学","reading":"かがく","meaning":"hóa học","example":"大学で、化学を勉強しています。","example_reading":"だいがくで、かがくをべんきょうしています。","example_meaning":"Tôi đang học hóa học ở đại học.","examples":[{"example":"化学の実験で、二つの薬品を混ぜました。","example_reading":"かがくのじっけんで、ふたつのやくひんをまぜました。","example_meaning":"Trong thí nghiệm hóa học, chúng tôi đã trộn hai loại hóa chất."},{"example":"化学反応が起きて、液体の色が変わりました。","example_reading":"かがくはんのうがおきて、えきたいのいろがかわりました。","example_meaning":"Xảy ra phản ứng hóa học nên màu của chất lỏng đã đổi."}]}]},
{"label":"確立／確率","note":"確立(かくりつ): XÁC LẬP, XÂY DỰNG VỮNG CHẮC (phương pháp, địa vị, chế độ). 確率(かくりつ): XÁC SUẤT, khả năng xảy ra của một sự việc.","items":[{"word":"確立","reading":"かくりつ","meaning":"xác lập, xây dựng vững chắc","example":"彼は、独自の研究方法を確立しました。","example_reading":"かれは、どくじのけんきゅうほうほうをかくりつしました。","example_meaning":"Anh ấy đã xác lập phương pháp nghiên cứu riêng.","examples":[{"example":"この会社は、世界で確立した地位を持っています。","example_reading":"このかいしゃは、せかいでかくりつしたちいをもっています。","example_meaning":"Công ty này có vị thế đã được khẳng định trên thế giới."},{"example":"新しい制度を確立するには、時間がかかります。","example_reading":"あたらしいせいどをかくりつするには、じかんがかかります。","example_meaning":"Phải mất thời gian để xây dựng nên một chế độ mới."}]},{"word":"確率","reading":"かくりつ","meaning":"xác suất","example":"明日、雨が降る確率は、七十パーセントです。","example_reading":"あした、あめがふるかくりつは、ななじゅっぱーせんとです。","example_meaning":"Xác suất ngày mai có mưa là 70%.","examples":[{"example":"サイコロで一が出る確率は、六分の一です。","example_reading":"さいころでいちがでるかくりつは、ろくぶんのいちです。","example_meaning":"Xác suất ra mặt một khi gieo xúc xắc là một phần sáu."},{"example":"この薬が効く確率は、とても高いです。","example_reading":"このくすりがきくかくりつは、とてもたかいです。","example_meaning":"Xác suất thuốc này có tác dụng rất cao."}]}]},
{"label":"過程／課程／仮定／家庭","note":"過程(かてい): QUÁ TRÌNH, diễn tiến từ lúc bắt đầu đến kết quả. 課程(かてい): CHƯƠNG TRÌNH HỌC, khóa học (修士課程). 仮定(かてい): GIẢ ĐỊNH, giả sử. 家庭(かてい): GIA ĐÌNH, tổ ấm.","items":[{"word":"過程","reading":"かてい","meaning":"quá trình, diễn tiến","example":"結果だけでなく、過程も大切です。","example_reading":"けっかだけでなく、かていもたいせつです。","example_meaning":"Không chỉ kết quả mà quá trình cũng quan trọng.","examples":[{"example":"子どもが成長する過程を、写真に残しました。","example_reading":"こどもがせいちょうするかていを、しゃしんにのこしました。","example_meaning":"Tôi lưu lại quá trình lớn lên của con bằng ảnh."},{"example":"製品ができるまでの過程を、工場で見学しました。","example_reading":"せいひんができるまでのかていを、こうじょうでけんがくしました。","example_meaning":"Tôi đã tham quan quá trình sản phẩm được làm ra ở nhà máy."}]},{"word":"課程","reading":"かてい","meaning":"chương trình học, khóa học","example":"彼は、大学院の修士課程に進みました。","example_reading":"かれは、だいがくいんのしゅうしかていにすすみました。","example_meaning":"Anh ấy đã học lên chương trình thạc sĩ sau đại học.","examples":[{"example":"私は、来年、この課程を修了します。","example_reading":"わたしは、らいねん、このかていをしゅうりょうします。","example_meaning":"Sang năm tôi sẽ hoàn thành khóa học này."},{"example":"中学校の課程では、英語が必修です。","example_reading":"ちゅうがっこうのかていでは、えいごがひっしゅうです。","example_meaning":"Trong chương trình trung học cơ sở, tiếng Anh là môn bắt buộc."}]},{"word":"仮定","reading":"かてい","meaning":"giả định, giả sử","example":"地震が起きたと仮定して、避難訓練をします。","example_reading":"じしんがおきたとかていして、ひなんくんれんをします。","example_meaning":"Giả định có động đất xảy ra, chúng ta diễn tập sơ tán.","examples":[{"example":"もし宝くじが当たったと仮定したら、何をしますか。","example_reading":"もしたからくじがあたったとかていしたら、なにをしますか。","example_meaning":"Giả sử trúng xổ số thì bạn sẽ làm gì?"},{"example":"この仮定が正しいかどうか、調べてみましょう。","example_reading":"このかていがただしいかどうか、しらべてみましょう。","example_meaning":"Hãy thử kiểm tra xem giả định này có đúng không."}]},{"word":"家庭","reading":"かてい","meaning":"gia đình, tổ ấm","example":"彼は、あたたかい家庭で育ちました。","example_reading":"かれは、あたたかいかていでそだちました。","example_meaning":"Anh ấy lớn lên trong một gia đình ấm áp.","examples":[{"example":"家庭の事情で、学校を休みます。","example_reading":"かていのじじょうで、がっこうをやすみます。","example_meaning":"Vì hoàn cảnh gia đình nên tôi xin nghỉ học."},{"example":"来週、先生が家庭訪問に来ます。","example_reading":"らいしゅう、せんせいがかていほうもんにきます。","example_meaning":"Tuần sau, cô giáo sẽ đến thăm gia đình."}]}]},
{"label":"鑑賞／観賞／干渉／感傷","note":"鑑賞(かんしょう): THƯỞNG THỨC, CẢM THỤ nghệ thuật (tranh, phim, âm nhạc). 観賞(かんしょう): NGẮM, THƯỞNG NGOẠN vật đẹp (hoa, cá cảnh, thiên nhiên). 干渉(かんしょう): CAN THIỆP, xen vào việc của người khác. 感傷(かんしょう): SẦU CẢM, đa cảm, bồi hồi.","items":[{"word":"鑑賞","reading":"かんしょう","meaning":"thưởng thức nghệ thuật","example":"私の趣味は、映画を鑑賞することです。","example_reading":"わたしのしゅみは、えいがをかんしょうすることです。","example_meaning":"Sở thích của tôi là thưởng thức phim ảnh.","examples":[{"example":"休日に、美術館で絵画を鑑賞しました。","example_reading":"きゅうじつに、びじゅつかんでかいがをかんしょうしました。","example_meaning":"Ngày nghỉ tôi đã đi xem tranh ở bảo tàng mỹ thuật."},{"example":"クラシック音楽の鑑賞会に参加しました。","example_reading":"くらしっくおんがくのかんしょうかいにさんかしました。","example_meaning":"Tôi đã tham gia buổi thưởng thức nhạc cổ điển."}]},{"word":"観賞","reading":"かんしょう","meaning":"ngắm, thưởng ngoạn (hoa, cá cảnh)","example":"庭の池で、金魚を観賞します。","example_reading":"にわのいけで、きんぎょをかんしょうします。","example_meaning":"Tôi ngắm cá vàng trong ao ở vườn.","examples":[{"example":"この植物は、観賞用として人気があります。","example_reading":"このしょくぶつは、かんしょうようとしてにんきがあります。","example_meaning":"Loài cây này được ưa chuộng để làm cảnh."},{"example":"春になると、桜を観賞する人で公園がにぎわいます。","example_reading":"はるになると、さくらをかんしょうするひとでこうえんがにぎわいます。","example_meaning":"Mùa xuân, công viên đông đúc người đến ngắm hoa anh đào."}]},{"word":"干渉","reading":"かんしょう","meaning":"can thiệp, xen vào","example":"親が子どもの生活に干渉しすぎてはいけません。","example_reading":"おやがこどものせいかつにかんしょうしすぎてはいけません。","example_meaning":"Cha mẹ không nên can thiệp quá nhiều vào cuộc sống của con.","examples":[{"example":"他国の政治に干渉するのは、よくありません。","example_reading":"たこくのせいじにかんしょうするのは、よくありません。","example_meaning":"Can thiệp vào chính trị nước khác là không tốt."},{"example":"私のことに、干渉しないでください。","example_reading":"わたしのことに、かんしょうしないでください。","example_meaning":"Xin đừng can thiệp vào chuyện của tôi."}]},{"word":"感傷","reading":"かんしょう","meaning":"sầu cảm, đa cảm","example":"古い写真を見て、感傷にひたりました。","example_reading":"ふるいしゃしんをみて、かんしょうにひたりました。","example_meaning":"Nhìn những bức ảnh cũ, tôi chìm trong nỗi sầu cảm.","examples":[{"example":"秋の夕暮れは、人を感傷的にさせます。","example_reading":"あきのゆうぐれは、ひとをかんしょうてきにさせます。","example_meaning":"Chiều tà mùa thu khiến người ta trở nên đa sầu đa cảm."},{"example":"卒業式の日、感傷的な気分になりました。","example_reading":"そつぎょうしきのひ、かんしょうてきなきぶんになりました。","example_meaning":"Ngày lễ tốt nghiệp, tôi thấy lòng bồi hồi, đa cảm."}]}]},
{"label":"期限／起源／機嫌／紀元","note":"期限(きげん): THỜI HẠN, HẠN CHÓT. 起源(きげん): NGUỒN GỐC, KHỞI NGUYÊN (văn hóa, ngôn ngữ, sự sống). 機嫌(きげん): TÂM TRẠNG, KHÍ SẮC (機嫌がいい/悪い). 紀元(きげん): KỶ NGUYÊN (紀元前 = trước Công nguyên).","items":[{"word":"期限","reading":"きげん","meaning":"thời hạn, hạn chót","example":"レポートの提出期限は、金曜日です。","example_reading":"れぽーとのていしゅつきげんは、きんようびです。","example_meaning":"Hạn nộp báo cáo là thứ Sáu.","examples":[{"example":"この牛乳は、期限が切れています。","example_reading":"このぎゅうにゅうは、きげんがきれています。","example_meaning":"Hộp sữa này đã hết hạn."},{"example":"期限までに、お金を払わなければなりません。","example_reading":"きげんまでに、おかねをはらわなければなりません。","example_meaning":"Phải trả tiền trước thời hạn."}]},{"word":"起源","reading":"きげん","meaning":"nguồn gốc, khởi nguyên","example":"日本語の起源については、いろいろな説があります。","example_reading":"にほんごのきげんについては、いろいろなせつがあります。","example_meaning":"Về nguồn gốc của tiếng Nhật có nhiều giả thuyết.","examples":[{"example":"このお祭りの起源は、千年以上前にさかのぼります。","example_reading":"このおまつりのきげんは、せんねんいじょうまえにさかのぼります。","example_meaning":"Nguồn gốc của lễ hội này bắt nguồn từ hơn nghìn năm trước."},{"example":"生命の起源を、研究している学者がいます。","example_reading":"せいめいのきげんを、けんきゅうしているがくしゃがいます。","example_meaning":"Có nhà khoa học đang nghiên cứu về nguồn gốc của sự sống."}]},{"word":"機嫌","reading":"きげん","meaning":"tâm trạng, khí sắc","example":"父は、今日、とても機嫌がいいです。","example_reading":"ちちは、きょう、とてもきげんがいいです。","example_meaning":"Hôm nay bố tôi tâm trạng rất tốt.","examples":[{"example":"赤ちゃんの機嫌が悪くて、ずっと泣いています。","example_reading":"あかちゃんのきげんがわるくて、ずっとないています。","example_meaning":"Em bé đang cáu kỉnh nên khóc mãi."},{"example":"彼女の機嫌を取るために、花を買いました。","example_reading":"かのじょのきげんをとるために、はなをかいました。","example_meaning":"Tôi mua hoa để lấy lòng cô ấy."}]},{"word":"紀元","reading":"きげん","meaning":"kỷ nguyên","example":"紀元前三世紀に、この都市はできました。","example_reading":"きげんぜんさんせいきに、このとしはできました。","example_meaning":"Thành phố này hình thành vào thế kỷ thứ ba trước Công nguyên.","examples":[{"example":"歴史の授業で、紀元前の文明について学びました。","example_reading":"れきしのじゅぎょうで、きげんぜんのぶんめいについてまなびました。","example_meaning":"Trong giờ lịch sử, tôi đã học về các nền văn minh thời trước Công nguyên."},{"example":"西暦は、紀元一年から始まったとされています。","example_reading":"せいれきは、きげんいちねんからはじまったとされています。","example_meaning":"Dương lịch được cho là bắt đầu từ năm thứ nhất của kỷ nguyên."}]}]},
{"label":"気候／機構／寄稿／帰港","note":"気候(きこう): KHÍ HẬU (xu hướng thời tiết lâu dài của một vùng). 機構(きこう): CƠ CẤU, TỔ CHỨC (cấu trúc cơ quan; cơ chế của máy móc). 寄稿(きこう): GỬI BÀI, CỘNG TÁC bài viết cho báo, tạp chí. 帰港(きこう): VỀ CẢNG, tàu quay trở lại cảng.","items":[{"word":"気候","reading":"きこう","meaning":"khí hậu","example":"日本は、気候が温暖な国です。","example_reading":"にほんは、きこうがおんだんなくにです。","example_meaning":"Nhật Bản là đất nước có khí hậu ôn hòa.","examples":[{"example":"この地方は、夏でも気候が涼しいです。","example_reading":"このちほうは、なつでもきこうがすずしいです。","example_meaning":"Vùng này khí hậu mát mẻ ngay cả vào mùa hè."},{"example":"気候の変化で、作物の育ち方が変わっています。","example_reading":"きこうのへんかで、さくもつのそだちかたがかわっています。","example_meaning":"Do biến đổi khí hậu, cách cây trồng phát triển đang thay đổi."}]},{"word":"機構","reading":"きこう","meaning":"cơ cấu, tổ chức, cơ chế","example":"この機構は、国際的な問題を話し合う組織です。","example_reading":"このきこうは、こくさいてきなもんだいをはなしあうそしきです。","example_meaning":"Tổ chức này là nơi thảo luận các vấn đề quốc tế.","examples":[{"example":"会社の機構を、見直すことになりました。","example_reading":"かいしゃのきこうを、みなおすことになりました。","example_meaning":"Đã quyết định xem xét lại cơ cấu của công ty."},{"example":"時計の機構は、とても複雑です。","example_reading":"とけいのきこうは、とてもふくざつです。","example_meaning":"Cơ cấu của đồng hồ rất phức tạp."}]},{"word":"寄稿","reading":"きこう","meaning":"gửi bài, cộng tác bài viết","example":"先生は、新聞にエッセイを寄稿しました。","example_reading":"せんせいは、しんぶんにえっせいをきこうしました。","example_meaning":"Thầy đã gửi bài tiểu luận cho tờ báo.","examples":[{"example":"雑誌に寄稿するために、原稿を書いています。","example_reading":"ざっしにきこうするために、げんこうをかいています。","example_meaning":"Tôi đang viết bản thảo để gửi bài cho tạp chí."},{"example":"この記事は、専門家の寄稿です。","example_reading":"このきじは、せんもんかのきこうです。","example_meaning":"Bài viết này do một chuyên gia gửi đăng."}]},{"word":"帰港","reading":"きこう","meaning":"về cảng","example":"漁に出た船が、今朝、帰港しました。","example_reading":"りょうにでたふねが、けさ、きこうしました。","example_meaning":"Chiếc tàu ra khơi đánh cá đã về cảng sáng nay.","examples":[{"example":"台風を避けて、船は予定より早く帰港しました。","example_reading":"たいふうをさけて、ふねはよていよりはやくきこうしました。","example_meaning":"Tránh bão, con tàu đã về cảng sớm hơn dự định."},{"example":"船は、明日の夕方に帰港する予定です。","example_reading":"ふねは、あしたのゆうがたにきこうするよていです。","example_meaning":"Tàu dự kiến sẽ về cảng vào chiều mai."}]}]},
{"label":"気象／気性／起床／希少","note":"気象(きしょう): KHÍ TƯỢNG, thời tiết (hiện tượng trong khí quyển). 気性(きしょう): TÍNH KHÍ, tính tình (nóng nảy, hiền lành). 起床(きしょう): THỨC DẬY, rời khỏi giường. 希少(きしょう): HIẾM, ÍT CÓ (số lượng ít nên quý).","items":[{"word":"気象","reading":"きしょう","meaning":"khí tượng, thời tiết","example":"気象庁が、台風の情報を発表しました。","example_reading":"きしょうちょうが、たいふうのじょうほうをはっぴょうしました。","example_meaning":"Cơ quan khí tượng đã công bố thông tin về bão.","examples":[{"example":"最近は、異常な気象が続いています。","example_reading":"さいきんは、いじょうなきしょうがつづいています。","example_meaning":"Gần đây thời tiết bất thường kéo dài."},{"example":"彼は、気象の仕事に興味があります。","example_reading":"かれは、きしょうのしごとにきょうみがあります。","example_meaning":"Anh ấy hứng thú với công việc về khí tượng."}]},{"word":"気性","reading":"きしょう","meaning":"tính khí, tính tình","example":"彼女は、気性の激しい人です。","example_reading":"かのじょは、きしょうのはげしいひとです。","example_meaning":"Cô ấy là người có tính khí dữ dội.","examples":[{"example":"この犬は、気性がおだやかで、子どもにも優しいです。","example_reading":"このいぬは、きしょうがおだやかで、こどもにもやさしいです。","example_meaning":"Con chó này tính tình hiền, kể cả với trẻ con cũng dịu dàng."},{"example":"馬は、種類によって気性が違います。","example_reading":"うまは、しゅるいによってきしょうがちがいます。","example_meaning":"Tính khí của ngựa khác nhau tùy từng giống."}]},{"word":"起床","reading":"きしょう","meaning":"thức dậy","example":"毎朝、六時に起床します。","example_reading":"まいあさ、ろくじにきしょうします。","example_meaning":"Mỗi sáng tôi thức dậy lúc sáu giờ.","examples":[{"example":"合宿では、起床時間が決まっています。","example_reading":"がっしゅくでは、きしょうじかんがきまっています。","example_meaning":"Trong đợt tập huấn, giờ thức dậy được quy định sẵn."},{"example":"起床のラッパが鳴って、みんなが起きました。","example_reading":"きしょうのらっぱがなって、みんながおきました。","example_meaning":"Kèn báo thức vang lên và mọi người đều dậy."}]},{"word":"希少","reading":"きしょう","meaning":"hiếm, ít có","example":"この花は、数が少なく、希少な植物です。","example_reading":"このはなは、かずがすくなく、きしょうなしょくぶつです。","example_meaning":"Loài hoa này số lượng ít, là loài thực vật quý hiếm.","examples":[{"example":"希少な動物を守るために、法律ができました。","example_reading":"きしょうなどうぶつをまもるために、ほうりつができました。","example_meaning":"Luật pháp ra đời để bảo vệ các loài động vật quý hiếm."},{"example":"この切手は、数が少ないので希少価値があります。","example_reading":"このきってはかずがすくないのできしょうかちがあります。","example_meaning":"Con tem này số lượng ít nên có giá trị hiếm có."}]}]},
{"label":"規制／既製／既成／帰省","note":"規制(きせい): QUY ĐỊNH HẠN CHẾ, KIỂM SOÁT, cấm đoán (giao thông, quảng cáo, buôn bán). 既製(きせい): LÀM SẴN, MAY SẴN (既製服, 既製品). 既成(きせい): ĐÃ HÌNH THÀNH, ĐÃ THÀNH SỰ THỰC (既成事実, 既成概念). 帰省(きせい): VỀ QUÊ thăm gia đình (dịp Tết, nghỉ hè).","items":[{"word":"規制","reading":"きせい","meaning":"hạn chế, kiểm soát, quy định cấm","example":"事故のため、高速道路が規制されています。","example_reading":"じこのため、こうそくどうろがきせいされています。","example_meaning":"Do tai nạn, đường cao tốc đang bị hạn chế lưu thông.","examples":[{"example":"政府は、たばこの広告を規制しました。","example_reading":"せいふは、たばこのこうこくをきせいしました。","example_meaning":"Chính phủ đã quản chế quảng cáo thuốc lá."},{"example":"子どもの夜間の外出を、規制する町があります。","example_reading":"こどものやかんのがいしゅつを、きせいするまちがあります。","example_meaning":"Có những thị trấn hạn chế trẻ em ra ngoài vào ban đêm."}]},{"word":"既製","reading":"きせい","meaning":"làm sẵn, may sẵn","example":"既製のスーツを買って、少し直してもらいました。","example_reading":"きせいのすーつをかって、すこしなおしてもらいました。","example_meaning":"Tôi mua bộ vest may sẵn rồi nhờ sửa lại một chút.","examples":[{"example":"既製品は、安くてすぐに手に入ります。","example_reading":"きせいひんは、やすくてすぐにてにはいります。","example_meaning":"Hàng làm sẵn thì rẻ và mua được ngay."},{"example":"この店では、既製服だけでなく、オーダーメイドも作れます。","example_reading":"このみせでは、きせいふくだけでなく、おーだーめいどもつくれます。","example_meaning":"Cửa hàng này không chỉ bán đồ may sẵn mà còn may đo theo yêu cầu."}]},{"word":"既成","reading":"きせい","meaning":"đã hình thành, đã thành sự thật","example":"既成の考えにとらわれず、新しいことをしましょう。","example_reading":"きせいのかんがえにとらわれず、あたらしいことをしましょう。","example_meaning":"Đừng bị bó buộc bởi suy nghĩ có sẵn, hãy làm điều mới.","examples":[{"example":"彼は、既成事実を作って、みんなに認めさせました。","example_reading":"かれは、きせいじじつをつくって、みんなにみとめさせました。","example_meaning":"Anh ta tạo ra sự đã rồi để mọi người phải công nhận."},{"example":"既成の概念を破る芸術家が、注目されています。","example_reading":"きせいのがいねんをやぶるげいじゅつかが、ちゅうもくされています。","example_meaning":"Những nghệ sĩ phá bỏ khái niệm có sẵn đang được chú ý."}]},{"word":"帰省","reading":"きせい","meaning":"về quê","example":"お正月に、故郷へ帰省します。","example_reading":"おしょうがつに、ふるさとへきせいします。","example_meaning":"Dịp Tết, tôi về quê.","examples":[{"example":"夏休みは、帰省する人で新幹線が混みます。","example_reading":"なつやすみは、きせいするひとでしんかんせんがこみます。","example_meaning":"Kỳ nghỉ hè, tàu Shinkansen đông nghẹt người về quê."},{"example":"去年は忙しくて、帰省できませんでした。","example_reading":"きょねんはいそがしくて、きせいできませんでした。","example_meaning":"Năm ngoái bận quá nên tôi không về quê được."}]}]},
{"label":"奇跡／軌跡","note":"奇跡(きせき): PHÉP LẠ, ĐIỀU KỲ DIỆU (việc khó tin nhưng đã xảy ra). 軌跡(きせき): QUỸ TÍCH, ĐƯỜNG ĐI để lại của vật chuyển động; nghĩa bóng là chặng đường đã trải qua.","items":[{"word":"奇跡","reading":"きせき","meaning":"phép lạ, điều kỳ diệu","example":"事故に遭ったのに、無事だったのは奇跡です。","example_reading":"じこにあったのに、ぶじだったのはきせきです。","example_meaning":"Gặp tai nạn mà vẫn bình an là một điều kỳ diệu.","examples":[{"example":"彼のチームは、奇跡の逆転勝利を収めました。","example_reading":"かれのちーむは、きせきのぎゃくてんしょうりをおさめました。","example_meaning":"Đội của anh ấy đã giành chiến thắng ngược dòng kỳ diệu."},{"example":"医者も驚くほど、奇跡的に病気が治りました。","example_reading":"いしゃもおどろくほど、きせきてきにびょうきがなおりました。","example_meaning":"Bệnh khỏi một cách kỳ diệu đến mức bác sĩ cũng ngạc nhiên."}]},{"word":"軌跡","reading":"きせき","meaning":"quỹ tích, chặng đường đã qua","example":"流れ星が、空に美しい軌跡を描きました。","example_reading":"ながれぼしが、そらにうつくしいきせきをえがきました。","example_meaning":"Sao băng vạch trên trời một quỹ đạo đẹp đẽ.","examples":[{"example":"この本には、彼の努力の軌跡が書かれています。","example_reading":"このほんには、かれのどりょくのきせきがかかれています。","example_meaning":"Cuốn sách này ghi lại chặng đường nỗ lực của anh ấy."},{"example":"ロケットが飛んだ軌跡を、地図に記録しました。","example_reading":"ろけっとがとんだきせきを、ちずにきろくしました。","example_meaning":"Tôi đã ghi lại quỹ đạo bay của tên lửa trên bản đồ."}]}]},
{"label":"規定／既定／規程","note":"規定(きてい): QUY ĐỊNH, điều khoản đã đặt ra (規定に従う, 規定の時間). 既定(きてい): ĐÃ ĐỊNH SẴN, ĐÃ QUYẾT TỪ TRƯỚC (既定の方針). 規程(きてい): QUY CHẾ, bộ quy tắc văn bản của một tổ chức (就業規程, 利用規程).","items":[{"word":"規定","reading":"きてい","meaning":"quy định, điều khoản","example":"会社の規定で、副業は禁止されています。","example_reading":"かいしゃのきていで、ふくぎょうはきんしされています。","example_meaning":"Theo quy định của công ty, việc làm thêm bị cấm.","examples":[{"example":"規定の時間内に、書類を出してください。","example_reading":"きていのじかんないに、しょるいをだしてください。","example_meaning":"Hãy nộp hồ sơ trong khoảng thời gian quy định."},{"example":"規定に従って、手続きを進めます。","example_reading":"きていにしたがって、てつづきをすすめます。","example_meaning":"Chúng tôi tiến hành thủ tục theo đúng quy định."}]},{"word":"既定","reading":"きてい","meaning":"đã định sẵn","example":"計画は、既定の方針どおりに進んでいます。","example_reading":"けいかくは、きていのほうしんどおりにすすんでいます。","example_meaning":"Kế hoạch đang tiến triển đúng theo phương châm đã định.","examples":[{"example":"既定の路線を変えるのは、簡単ではありません。","example_reading":"きていのろせんをかえるのは、かんたんではありません。","example_meaning":"Thay đổi đường hướng đã định sẵn không hề dễ."},{"example":"会議で、既定の事実として報告されました。","example_reading":"かいぎで、きていのじじつとしてほうこくされました。","example_meaning":"Trong cuộc họp, việc này được báo cáo như một sự thật đã được xác định."}]},{"word":"規程","reading":"きてい","meaning":"quy chế","example":"社員は、就業規程を守らなければなりません。","example_reading":"しゃいんは、しゅうぎょうきていをまもらなければなりません。","example_meaning":"Nhân viên phải tuân thủ quy chế lao động.","examples":[{"example":"図書館の利用規程が、新しくなりました。","example_reading":"としょかんのりようきていが、あたらしくなりました。","example_meaning":"Quy chế sử dụng thư viện đã được làm mới."},{"example":"この規程には、会員の権利が書かれています。","example_reading":"このきていには、かいいんのけんりがかかれています。","example_meaning":"Quy chế này ghi rõ quyền lợi của hội viên."}]}]},
{"label":"究明／糾明","note":"究明(きゅうめい): TÌM RA, LÀM SÁNG TỎ đến cùng (nguyên nhân, sự thật). 糾明(きゅうめい): TRUY CỨU, TRUY XÉT (trách nhiệm, tội lỗi, hành vi sai trái).","items":[{"word":"究明","reading":"きゅうめい","meaning":"làm sáng tỏ, tìm ra đến cùng","example":"警察は、事故の原因を究明しています。","example_reading":"けいさつは、じこのげんいんをきゅうめいしています。","example_meaning":"Cảnh sát đang làm rõ nguyên nhân tai nạn.","examples":[{"example":"真実を究明するために、調査を続けます。","example_reading":"しんじつをきゅうめいするために、ちょうさをつづけます。","example_meaning":"Chúng tôi tiếp tục điều tra để làm sáng tỏ sự thật."},{"example":"病気の原因の究明には、時間がかかります。","example_reading":"びょうきのげんいんのきゅうめいには、じかんがかかります。","example_meaning":"Việc tìm ra nguyên nhân bệnh cần nhiều thời gian."}]},{"word":"糾明","reading":"きゅうめい","meaning":"truy cứu, truy xét (trách nhiệm)","example":"国会で、政治家の責任が糾明されました。","example_reading":"こっかいで、せいじかのせきにんがきゅうめいされました。","example_meaning":"Trách nhiệm của chính trị gia đã bị truy xét tại quốc hội.","examples":[{"example":"不正を糾明して、関係者を処分しました。","example_reading":"ふせいをきゅうめいして、かんけいしゃをしょぶんしました。","example_meaning":"Họ đã truy cứu hành vi gian lận và xử lý những người liên quan."},{"example":"事件の責任を、厳しく糾明するべきです。","example_reading":"じけんのせきにんを、きびしくきゅうめいするべきです。","example_meaning":"Cần truy cứu nghiêm khắc trách nhiệm trong vụ việc."}]}]},
{"label":"強行／強硬","note":"強行(きょうこう): CƯỠNG HÀNH, CỐ TÌNH THỰC HIỆN dù gặp khó khăn hay phản đối (強行する). 強硬(きょうこう): CỨNG RẮN, CƯƠNG QUYẾT (thái độ, lập trường, ý kiến).","items":[{"word":"強行","reading":"きょうこう","meaning":"cưỡng hành, cố thực hiện","example":"雨でも、運動会を強行しました。","example_reading":"あめでも、うんどうかいをきょうこうしました。","example_meaning":"Dù mưa, họ vẫn cố tổ chức hội thao.","examples":[{"example":"反対を押し切って、計画を強行しました。","example_reading":"はんたいをおしきって、けいかくをきょうこうしました。","example_meaning":"Họ gạt bỏ phản đối và cưỡng hành kế hoạch."},{"example":"彼は、台風の中、出発を強行しました。","example_reading":"かれは、たいふうのなか、しゅっぱつをきょうこうしました。","example_meaning":"Anh ấy vẫn cố xuất phát giữa lúc có bão."}]},{"word":"強硬","reading":"きょうこう","meaning":"cứng rắn, cương quyết","example":"相手は、強硬な態度を変えませんでした。","example_reading":"あいては、きょうこうなたいどをかえませんでした。","example_meaning":"Đối phương không thay đổi thái độ cứng rắn.","examples":[{"example":"組合は、会社に強硬に抗議しました。","example_reading":"くみあいは、かいしゃにきょうこうにこうぎしました。","example_meaning":"Công đoàn đã phản đối quyết liệt với công ty."},{"example":"強硬な意見ばかりで、話し合いが進みません。","example_reading":"きょうこうないけんばかりで、はなしあいがすすみません。","example_meaning":"Toàn là ý kiến cứng rắn nên cuộc thảo luận không tiến triển."}]}]},
{"label":"競争／競走／協奏","note":"競争(きょうそう): CẠNH TRANH, GANH ĐUA (giữa người, công ty, thí sinh). 競走(きょうそう): THI CHẠY, CHẠY ĐUA (徒競走). 協奏(きょうそう): HÒA TẤU (協奏曲 = concerto, nhạc cụ độc tấu cùng dàn nhạc).","items":[{"word":"競争","reading":"きょうそう","meaning":"cạnh tranh, ganh đua","example":"会社同士の競争が、激しくなっています。","example_reading":"かいしゃどうしのきょうそうが、はげしくなっています。","example_meaning":"Sự cạnh tranh giữa các công ty đang trở nên khốc liệt.","examples":[{"example":"受験は、他の学生との競争です。","example_reading":"じゅけんは、ほかのがくせいとのきょうそうです。","example_meaning":"Thi cử là cuộc cạnh tranh với các thí sinh khác."},{"example":"競争が激しい業界で、働いています。","example_reading":"きょうそうがはげしいぎょうかいで、はたらいています。","example_meaning":"Tôi đang làm việc trong một ngành có sự cạnh tranh khốc liệt."}]},{"word":"競走","reading":"きょうそう","meaning":"thi chạy, chạy đua","example":"運動会で、みんなで競走しました。","example_reading":"うんどうかいで、みんなできょうそうしました。","example_meaning":"Ở hội thao, mọi người đã thi chạy với nhau.","examples":[{"example":"弟は、徒競走で一位になりました。","example_reading":"おとうとは、ときょうそうでいちいになりました。","example_meaning":"Em trai tôi đã về nhất trong cuộc thi chạy."},{"example":"犬と競走して、負けてしまいました。","example_reading":"いぬときょうそうして、まけてしまいました。","example_meaning":"Tôi thi chạy với con chó và đã thua."}]},{"word":"協奏","reading":"きょうそう","meaning":"hòa tấu (協奏曲)","example":"ピアノ協奏曲を、オーケストラと演奏しました。","example_reading":"ぴあのきょうそうきょくを、おーけすとらとえんそうしました。","example_meaning":"Tôi đã biểu diễn bản concerto piano cùng dàn nhạc.","examples":[{"example":"この協奏曲は、バイオリンが主役です。","example_reading":"このきょうそうきょくは、ばいおりんがしゅやくです。","example_meaning":"Bản concerto này lấy violin làm nhân vật chính."},{"example":"彼は、協奏曲を弾くために、毎日練習しています。","example_reading":"かれは、きょうそうきょくをひくために、まいにちれんしゅうしています。","example_meaning":"Anh ấy luyện tập mỗi ngày để chơi bản concerto."}]}]},
{"label":"共同／協同","note":"共同(きょうどう): CÙNG NHAU, CHUNG (làm chung, dùng chung, sở hữu chung: 共同生活, 共同研究). 協同(きょうどう): HỢP TÁC, ĐỒNG LÒNG chung sức vì một mục tiêu (協同組合, 協同作業).","items":[{"word":"共同","reading":"きょうどう","meaning":"cùng nhau, chung","example":"友達と三人で、共同で部屋を借りています。","example_reading":"ともだちとさんにんで、きょうどうでへやをかりています。","example_meaning":"Tôi cùng hai người bạn thuê chung một căn phòng.","examples":[{"example":"二つの大学が、共同で研究を行います。","example_reading":"ふたつのだいがくが、きょうどうでけんきゅうをおこないます。","example_meaning":"Hai trường đại học cùng tiến hành nghiên cứu."},{"example":"このトイレは、共同で使っています。","example_reading":"このといれは、きょうどうでつかっています。","example_meaning":"Nhà vệ sinh này được dùng chung."}]},{"word":"協同","reading":"きょうどう","meaning":"hợp tác, đồng lòng chung sức","example":"みんなが協同して、文化祭を成功させました。","example_reading":"みんながきょうどうして、ぶんかさいをせいこうさせました。","example_meaning":"Mọi người đồng lòng hợp sức làm cho lễ hội văn hóa thành công.","examples":[{"example":"農家が集まって、協同組合を作りました。","example_reading":"のうかがあつまって、きょうどうくみあいをつくりました。","example_meaning":"Các hộ nông dân tập hợp lại lập nên hợp tác xã."},{"example":"協同の精神を、学校で学びます。","example_reading":"きょうどうのせいしんを、がっこうでまなびます。","example_meaning":"Ở trường, chúng ta học tinh thần hợp tác."}]}]},
{"label":"形成／形勢","note":"形成(けいせい): HÌNH THÀNH, TẠO NÊN (nhân cách, địa hình, dư luận). 形勢(けいせい): THẾ TRẬN, TÌNH THẾ, cục diện (形勢が逆転する, 形勢が不利).","items":[{"word":"形成","reading":"けいせい","meaning":"hình thành, tạo nên","example":"子どもの頃の経験が、性格を形成します。","example_reading":"こどものころのけいけんが、せいかくをけいせいします。","example_meaning":"Những trải nghiệm thuở nhỏ hình thành nên tính cách.","examples":[{"example":"川の流れが、広い平野を形成しました。","example_reading":"かわのながれが、ひろいへいやをけいせいしました。","example_meaning":"Dòng chảy của sông đã tạo nên một vùng đồng bằng rộng."},{"example":"世論の形成には、メディアの影響が大きいです。","example_reading":"よろんのけいせいには、めでぃあのえいきょうがおおきいです。","example_meaning":"Truyền thông có ảnh hưởng lớn đến sự hình thành dư luận."}]},{"word":"形勢","reading":"けいせい","meaning":"thế trận, tình thế","example":"試合は、後半に形勢が逆転しました。","example_reading":"しあいは、こうはんにけいせいがぎゃくてんしました。","example_meaning":"Trận đấu đã đảo ngược thế cờ vào hiệp hai.","examples":[{"example":"形勢が不利になったので、作戦を変えました。","example_reading":"けいせいがふりになったので、さくせんをかえました。","example_meaning":"Tình thế bất lợi nên họ đã đổi chiến thuật."},{"example":"相手の形勢をうかがってから、動きましょう。","example_reading":"あいてのけいせいをうかがってから、うごきましょう。","example_meaning":"Hãy xem xét tình thế của đối phương rồi hãy hành động."}]}]},
{"label":"検討／見当／健闘","note":"検討(けんとう): XEM XÉT, CÂN NHẮC kỹ lưỡng (検討中). 見当(けんとう): PHỎNG ĐOÁN, ĐỊNH HƯỚNG (見当がつく, 見当違い). 健闘(けんとう): CHIẾN ĐẤU HẾT SỨC, thi đấu xuất sắc dù chưa chắc thắng.","items":[{"word":"検討","reading":"けんとう","meaning":"xem xét, cân nhắc","example":"その案については、もう少し検討します。","example_reading":"そのあんについては、もうすこしけんとうします。","example_meaning":"Về phương án đó, chúng tôi sẽ cân nhắc thêm một chút.","examples":[{"example":"計画を実行する前に、よく検討しましょう。","example_reading":"けいかくをじっこうするまえに、よくけんとうしましょう。","example_meaning":"Trước khi thực hiện kế hoạch, hãy xem xét kỹ."},{"example":"値上げについては、現在検討中です。","example_reading":"ねあげについては、げんざいけんとうちゅうです。","example_meaning":"Về việc tăng giá, hiện đang trong giai đoạn xem xét."}]},{"word":"見当","reading":"けんとう","meaning":"phỏng đoán, định hướng","example":"彼女がなぜ怒っているのか、見当がつきません。","example_reading":"かのじょがなぜおこっているのか、けんとうがつきません。","example_meaning":"Tôi không đoán ra vì sao cô ấy giận.","examples":[{"example":"駅の場所は、だいたい見当がつきます。","example_reading":"えきのばしょは、だいたいけんとうがつきます。","example_meaning":"Tôi đại khái đoán được vị trí nhà ga."},{"example":"彼の予想は、完全に見当違いでした。","example_reading":"かれのよそうは、かんぜんにけんとうちがいでした。","example_meaning":"Dự đoán của anh ấy hoàn toàn sai hướng."}]},{"word":"健闘","reading":"けんとう","meaning":"chiến đấu hết mình","example":"小さなチームですが、決勝まで健闘しました。","example_reading":"ちいさなちーむですが、けっしょうまでけんとうしました。","example_meaning":"Tuy là đội nhỏ nhưng họ đã chiến đấu hết mình đến tận trận chung kết.","examples":[{"example":"負けたけれど、選手たちの健闘をたたえました。","example_reading":"まけたけれど、せんしゅたちのけんとうをたたえました。","example_meaning":"Dù thua nhưng mọi người vẫn ca ngợi sự nỗ lực của các vận động viên."},{"example":"皆さんの健闘を祈ります。","example_reading":"みなさんのけんとうをいのります。","example_meaning":"Chúc mọi người thi đấu hết mình."}]}]},
{"label":"好意／厚意／行為","note":"好意(こうい): THIỆN CẢM, cảm tình tốt (好意を持つ). 厚意(こうい): LÒNG TỐT, sự giúp đỡ tận tình (ご厚意に感謝). 行為(こうい): HÀNH VI, việc làm có chủ ý.","items":[{"word":"好意","reading":"こうい","meaning":"thiện cảm, cảm tình","example":"彼は、同じ会社の女性に好意を持っています。","example_reading":"かれは、おなじかいしゃのじょせいにこういをもっています。","example_meaning":"Anh ấy có cảm tình với một nữ đồng nghiệp trong công ty.","examples":[{"example":"初めて会った人に、好意を感じました。","example_reading":"はじめてあったひとに、こういをかんじました。","example_meaning":"Tôi có thiện cảm với người mới gặp lần đầu."},{"example":"彼女は、私に好意的な態度で接してくれます。","example_reading":"かのじょは、わたしにこういてきなたいどでせっしてくれます。","example_meaning":"Cô ấy đối xử với tôi bằng thái độ thiện cảm."}]},{"word":"厚意","reading":"こうい","meaning":"lòng tốt, sự giúp đỡ tận tình","example":"皆さんのご厚意に、心から感謝します。","example_reading":"みなさんのごこういに、こころからかんしゃします。","example_meaning":"Tôi chân thành cảm ơn tấm lòng tốt của mọi người.","examples":[{"example":"先輩の厚意で、安く部屋を借りられました。","example_reading":"せんぱいのこういで、やすくへやをかりられました。","example_meaning":"Nhờ lòng tốt của đàn anh, tôi đã thuê được phòng với giá rẻ."},{"example":"せっかくのご厚意ですが、今回は遠慮します。","example_reading":"せっかくのごこういですが、こんかいはえんりょします。","example_meaning":"Cảm ơn tấm lòng, nhưng lần này tôi xin phép từ chối."}]},{"word":"行為","reading":"こうい","meaning":"hành vi","example":"人に迷惑をかける行為は、やめましょう。","example_reading":"ひとにめいわくをかけるこういは、やめましょう。","example_meaning":"Hãy ngừng những hành vi làm phiền người khác.","examples":[{"example":"彼の行為は、法律に違反しています。","example_reading":"かれのこういは、ほうりつにいはんしています。","example_meaning":"Hành vi của anh ta vi phạm pháp luật."},{"example":"勇気ある行為が、ニュースで紹介されました。","example_reading":"ゆうきあるこういが、にゅーすでしょうかいされました。","example_meaning":"Hành động dũng cảm đó đã được đưa lên bản tin."}]}]},
{"label":"効果／硬貨／高価／降下","note":"効果(こうか): HIỆU QUẢ, TÁC DỤNG (薬の効果, 効果がある). 硬貨(こうか): TIỀN XU, đồng tiền kim loại. 高価(こうか): ĐẮT TIỀN, GIÁ CAO (trái nghĩa 安価). 降下(こうか): HẠ XUỐNG, đi xuống (máy bay, nhiệt độ, nhảy dù).","items":[{"word":"効果","reading":"こうか","meaning":"hiệu quả, tác dụng","example":"この薬は、すぐに効果が出ます。","example_reading":"このくすりは、すぐにこうかがでます。","example_meaning":"Thuốc này có hiệu quả ngay lập tức.","examples":[{"example":"毎日運動すると、ダイエットの効果があります。","example_reading":"まいにちうんどうすると、だいえっとのこうかがあります。","example_meaning":"Tập thể dục mỗi ngày thì có hiệu quả giảm cân."},{"example":"広告の効果で、売り上げが伸びました。","example_reading":"こうこくのこうかで、うりあげがのびました。","example_meaning":"Nhờ hiệu quả của quảng cáo, doanh thu đã tăng."}]},{"word":"硬貨","reading":"こうか","meaning":"tiền xu","example":"自動販売機に、硬貨を入れました。","example_reading":"じどうはんばいきに、こうかをいれました。","example_meaning":"Tôi bỏ đồng xu vào máy bán hàng tự động.","examples":[{"example":"財布の中に、硬貨がたくさんたまっています。","example_reading":"さいふのなかに、こうかがたくさんたまっています。","example_meaning":"Trong ví tích nhiều tiền xu."},{"example":"この機械は、千円札と硬貨が使えます。","example_reading":"このきかいは、せんえんさつとこうかがつかえます。","example_meaning":"Máy này dùng được cả tờ 1.000 yên lẫn tiền xu."}]},{"word":"高価","reading":"こうか","meaning":"đắt tiền, giá cao","example":"高価な宝石を、買うことができませんでした。","example_reading":"こうかなほうせきを、かうことができませんでした。","example_meaning":"Tôi đã không thể mua viên đá quý đắt tiền.","examples":[{"example":"この時計は、高価なので、大切に使っています。","example_reading":"このとけいは、こうかなので、たいせつにつかっています。","example_meaning":"Chiếc đồng hồ này đắt tiền nên tôi dùng rất cẩn thận."},{"example":"高価な品物は、鍵のかかる場所にしまいます。","example_reading":"こうかなしなものは、かぎのかかるばしょにしまいます。","example_meaning":"Đồ đắt tiền thì cất ở nơi có khóa."}]},{"word":"降下","reading":"こうか","meaning":"hạ xuống, giảm xuống","example":"飛行機は、ゆっくり高度を降下しました。","example_reading":"ひこうきは、ゆっくりこうどをこうかしました。","example_meaning":"Máy bay hạ độ cao từ từ.","examples":[{"example":"気温が急に降下して、寒くなりました。","example_reading":"きおんがきゅうにこうかして、さむくなりました。","example_meaning":"Nhiệt độ đột ngột giảm nên trời trở lạnh."},{"example":"兵士たちは、パラシュートで降下しました。","example_reading":"へいしたちは、ぱらしゅーとでこうかしました。","example_meaning":"Các binh sĩ đã nhảy dù xuống."}]}]},
{"label":"公開／後悔／航海","note":"公開(こうかい): CÔNG KHAI, TRÌNH CHIẾU, mở cửa cho công chúng. 後悔(こうかい): HỐI HẬN, TIẾC NUỐI việc đã làm hoặc không làm. 航海(こうかい): HÀNH TRÌNH TRÊN BIỂN, đi biển bằng tàu.","items":[{"word":"公開","reading":"こうかい","meaning":"công khai, công chiếu","example":"この映画は、来月から公開されます。","example_reading":"このえいがは、らいげつからこうかいされます。","example_meaning":"Bộ phim này sẽ được công chiếu từ tháng sau.","examples":[{"example":"大学が、研究の結果をインターネットで公開しました。","example_reading":"だいがくが、けんきゅうのけっかをいんたーねっとでこうかいしました。","example_meaning":"Trường đại học đã công bố kết quả nghiên cứu trên Internet."},{"example":"会社の工場が、一般に公開されています。","example_reading":"かいしゃのこうじょうが、いっぱんにこうかいされています。","example_meaning":"Nhà máy của công ty được mở cửa cho công chúng tham quan."}]},{"word":"後悔","reading":"こうかい","meaning":"hối hận, tiếc nuối","example":"あの時、勉強しなかったことを後悔しています。","example_reading":"あのとき、べんきょうしなかったことをこうかいしています。","example_meaning":"Tôi hối hận vì lúc đó đã không học.","examples":[{"example":"後悔しないように、よく考えて決めます。","example_reading":"こうかいしないように、よくかんがえてきめます。","example_meaning":"Tôi suy nghĩ kỹ rồi mới quyết định để khỏi hối hận."},{"example":"彼に謝らなかったことを、今でも後悔しています。","example_reading":"かれにあやまらなかったことを、いまでもこうかいしています。","example_meaning":"Đến giờ tôi vẫn tiếc vì đã không xin lỗi anh ấy."}]},{"word":"航海","reading":"こうかい","meaning":"hải trình, đi biển","example":"船は、三か月かけて世界を航海しました。","example_reading":"ふねは、さんかげつかけてせかいをこうかいしました。","example_meaning":"Con tàu đã mất ba tháng đi vòng quanh thế giới.","examples":[{"example":"嵐の中の航海は、とても危険でした。","example_reading":"あらしのなかのこうかいは、とてもきけんでした。","example_meaning":"Chuyến hải trình giữa cơn bão rất nguy hiểm."},{"example":"彼は、船長として長い航海に出ました。","example_reading":"かれは、せんちょうとしてながいこうかいにでました。","example_meaning":"Ông ấy làm thuyền trưởng và đã lên đường cho một chuyến đi biển dài."}]}]},
{"label":"交換／好感／交歓","note":"交換(こうかん): TRAO ĐỔI, ĐỔI (đồ vật, thông tin, ý kiến, linh kiện). 好感(こうかん): THIỆN CẢM, ấn tượng tốt (好感を持つ, 好感を与える). 交歓(こうかん): GIAO LƯU THÂN MẬT, vui vẻ với nhau (交歓会); dùng trong ngữ cảnh trang trọng.","items":[{"word":"交換","reading":"こうかん","meaning":"trao đổi, đổi","example":"友達と、お土産を交換しました。","example_reading":"ともだちと、おみやげをこうかんしました。","example_meaning":"Tôi đã trao đổi quà lưu niệm với bạn.","examples":[{"example":"古い電池を、新しいものに交換します。","example_reading":"ふるいでんちを、あたらしいものにこうかんします。","example_meaning":"Tôi thay pin cũ bằng pin mới."},{"example":"サイズが合わないので、商品を交換してもらいました。","example_reading":"さいずがあわないので、しょうひんをこうかんしてもらいました。","example_meaning":"Vì không vừa cỡ nên tôi đã nhờ đổi hàng."}]},{"word":"好感","reading":"こうかん","meaning":"thiện cảm, ấn tượng tốt","example":"彼の誠実な態度に、好感を持ちました。","example_reading":"かれのせいじつなたいどに、こうかんをもちました。","example_meaning":"Tôi có thiện cảm với thái độ chân thành của anh ấy.","examples":[{"example":"面接で、好感の持てる話し方を心がけました。","example_reading":"めんせつで、こうかんのもてるはなしかたをこころがけました。","example_meaning":"Trong buổi phỏng vấn, tôi chú ý cách nói chuyện để tạo ấn tượng tốt."},{"example":"明るい笑顔は、人に好感を与えます。","example_reading":"あかるいえがおは、ひとにこうかんをあたえます。","example_meaning":"Nụ cười tươi mang lại thiện cảm cho người khác."}]},{"word":"交歓","reading":"こうかん","meaning":"giao lưu thân mật","example":"両国の学生が、交歓会で楽しく話しました。","example_reading":"りょうこくのがくせいが、こうかんかいでたのしくはなしました。","example_meaning":"Sinh viên hai nước đã trò chuyện vui vẻ trong buổi giao lưu.","examples":[{"example":"運動会のあと、選手たちは交歓しました。","example_reading":"うんどうかいのあと、せんしゅたちはこうかんしました。","example_meaning":"Sau hội thao, các vận động viên đã giao lưu thân mật với nhau."},{"example":"国際交歓の場として、このイベントは長く続いています。","example_reading":"こくさいこうかんのばとして、このいべんとはながくつづいています。","example_meaning":"Sự kiện này đã kéo dài lâu năm như một nơi giao lưu quốc tế."}]}]},
{"label":"抗議／講義","note":"抗議(こうぎ): PHẢN ĐỐI, KHÁNG NGHỊ (bày tỏ bất mãn mạnh mẽ với người hay tổ chức). 講義(こうぎ): BÀI GIẢNG, GIỜ GIẢNG (chủ yếu ở đại học).","items":[{"word":"抗議","reading":"こうぎ","meaning":"phản đối, kháng nghị","example":"住民は、工場の建設に抗議しました。","example_reading":"じゅうみんは、こうじょうのけんせつにこうぎしました。","example_meaning":"Người dân đã phản đối việc xây dựng nhà máy.","examples":[{"example":"判定に納得できず、選手が審判に抗議しました。","example_reading":"はんていになっとくできず、せんしゅがしんぱんにこうぎしました。","example_meaning":"Không chấp nhận phán quyết, vận động viên đã phản đối trọng tài."},{"example":"店の対応が悪かったので、抗議の電話をかけました。","example_reading":"みせのたいおうがわるかったので、こうぎのでんわをかけました。","example_meaning":"Vì cách xử lý của cửa hàng không tốt nên tôi đã gọi điện phản đối."}]},{"word":"講義","reading":"こうぎ","meaning":"bài giảng, giờ giảng","example":"今日は、午前中に経済学の講義があります。","example_reading":"きょうは、ごぜんちゅうにけいざいがくのこうぎがあります。","example_meaning":"Hôm nay buổi sáng có giờ giảng kinh tế học.","examples":[{"example":"教授の講義は、難しいですが、とても面白いです。","example_reading":"きょうじゅのこうぎは、むずかしいですが、とてもおもしろいです。","example_meaning":"Bài giảng của giáo sư khó nhưng rất thú vị."},{"example":"講義のあとで、先生に質問しました。","example_reading":"こうぎのあとで、せんせいにしつもんしました。","example_meaning":"Sau giờ giảng, tôi đã hỏi thầy."}]}]},
{"label":"公正／校正／厚生／更生","note":"公正(こうせい): CÔNG BẰNG, CÔNG TÂM, không thiên vị. 校正(こうせい): HIỆU ĐÍNH, soát lỗi bản thảo hay bản in. 厚生(こうせい): PHÚC LỢI, đời sống của người lao động (福利厚生). 更生(こうせい): CẢI TẠO, LÀM LẠI CUỘC ĐỜI (người từng phạm lỗi).","items":[{"word":"公正","reading":"こうせい","meaning":"công bằng, công tâm","example":"審判は、公正な判断をしなければなりません。","example_reading":"しんぱんは、こうせいなはんだんをしなければなりません。","example_meaning":"Trọng tài phải đưa ra phán quyết công bằng.","examples":[{"example":"試験は、公正に行われました。","example_reading":"しけんは、こうせいにおこなわれました。","example_meaning":"Kỳ thi đã được tổ chức công bằng."},{"example":"公正な取引のために、ルールを作りました。","example_reading":"こうせいなとりひきのために、るーるをつくりました。","example_meaning":"Chúng tôi đặt ra quy tắc để giao dịch công bằng."}]},{"word":"校正","reading":"こうせい","meaning":"hiệu đính, soát lỗi","example":"本を出す前に、原稿を校正します。","example_reading":"ほんをだすまえに、げんこうをこうせいします。","example_meaning":"Trước khi xuất bản sách, tôi hiệu đính bản thảo.","examples":[{"example":"校正の仕事は、間違いを見つける仕事です。","example_reading":"こうせいのしごとは、まちがいをみつけるしごとです。","example_meaning":"Công việc hiệu đính là công việc tìm ra lỗi sai."},{"example":"新聞の記事を、何度も校正しました。","example_reading":"しんぶんのきじを、なんどもこうせいしました。","example_meaning":"Tôi đã soát lỗi bài báo nhiều lần."}]},{"word":"厚生","reading":"こうせい","meaning":"phúc lợi (người lao động)","example":"この会社は、福利厚生が充実しています。","example_reading":"このかいしゃは、ふくりこうせいがじゅうじつしています。","example_meaning":"Công ty này có chế độ phúc lợi đầy đủ.","examples":[{"example":"厚生労働省が、新しい制度を発表しました。","example_reading":"こうせいろうどうしょうが、あたらしいせいどをはっぴょうしました。","example_meaning":"Bộ Y tế, Lao động và Phúc lợi đã công bố chế độ mới."},{"example":"社員のために、厚生施設を作りました。","example_reading":"しゃいんのために、こうせいしせつをつくりました。","example_meaning":"Công ty đã xây cơ sở phúc lợi cho nhân viên."}]},{"word":"更生","reading":"こうせい","meaning":"cải tạo, làm lại cuộc đời","example":"罪を犯した人が、更生して社会に戻りました。","example_reading":"つみをおかしたひとが、こうせいしてしゃかいにもどりました。","example_meaning":"Người từng phạm tội đã cải tạo và trở lại xã hội.","examples":[{"example":"少年の更生を助ける施設が、増えています。","example_reading":"しょうねんのこうせいをたすけるしせつが、ふえています。","example_meaning":"Các cơ sở giúp thanh thiếu niên cải tạo đang tăng lên."},{"example":"彼は、更生を誓って、新しい仕事を始めました。","example_reading":"かれは、こうせいをちかって、あたらしいしごとをはじめました。","example_meaning":"Anh ấy thề sẽ làm lại cuộc đời và bắt đầu một công việc mới."}]}]},
{"label":"再会／再開","note":"再会(さいかい): GẶP LẠI người đã lâu không gặp, đoàn tụ. 再開(さいかい): MỞ LẠI, BẮT ĐẦU LẠI việc đã tạm dừng (工事を再開, 営業を再開).","items":[{"word":"再会","reading":"さいかい","meaning":"gặp lại, đoàn tụ","example":"十年ぶりに、友達と再会しました。","example_reading":"じゅうねんぶりに、ともだちとさいかいしました。","example_meaning":"Tôi gặp lại bạn sau mười năm.","examples":[{"example":"空港で、家族との再会を喜びました。","example_reading":"くうこうで、かぞくとのさいかいをよろこびました。","example_meaning":"Chúng tôi vui mừng được đoàn tụ với gia đình ở sân bay."},{"example":"では、また来年、再会しましょう。","example_reading":"では、またらいねん、さいかいしましょう。","example_meaning":"Vậy hẹn gặp lại nhau vào năm sau nhé."}]},{"word":"再開","reading":"さいかい","meaning":"mở lại, bắt đầu lại","example":"雨がやんで、試合が再開されました。","example_reading":"あめがやんで、しあいがさいかいされました。","example_meaning":"Mưa tạnh nên trận đấu được tiếp tục.","examples":[{"example":"工事は、来週から再開する予定です。","example_reading":"こうじは、らいしゅうからさいかいするよていです。","example_meaning":"Công trình dự kiến sẽ được tiếp tục từ tuần sau."},{"example":"閉まっていた店が、先月、営業を再開しました。","example_reading":"しまっていたみせが、せんげつ、えいぎょうをさいかいしました。","example_meaning":"Cửa hàng đã đóng cửa nay đã mở bán trở lại vào tháng trước."}]}]},
{"label":"資格／視覚／四角／死角","note":"資格(しかく): TƯ CÁCH, BẰNG CẤP, CHỨNG CHỈ. 視覚(しかく): THỊ GIÁC, giác quan nhìn. 四角(しかく): HÌNH VUÔNG, HÌNH TỨ GIÁC (四角い). 死角(しかく): GÓC CHẾT, ĐIỂM MÙ không nhìn thấy được.","items":[{"word":"資格","reading":"しかく","meaning":"tư cách, bằng cấp, chứng chỉ","example":"私は、介護の資格を取りました。","example_reading":"わたしは、かいごのしかくをとりました。","example_meaning":"Tôi đã lấy chứng chỉ điều dưỡng chăm sóc.","examples":[{"example":"この試験は、誰でも受ける資格があります。","example_reading":"このしけんは、だれでもうけるしかくがあります。","example_meaning":"Ai cũng có tư cách dự kỳ thi này."},{"example":"彼には、先生になる資格がありません。","example_reading":"かれには、せんせいになるしかくがありません。","example_meaning":"Anh ta không có tư cách làm giáo viên."}]},{"word":"視覚","reading":"しかく","meaning":"thị giác","example":"人は、視覚から多くの情報を得ます。","example_reading":"ひとは、しかくからおおくのじょうほうをえます。","example_meaning":"Con người nhận được nhiều thông tin qua thị giác.","examples":[{"example":"視覚に障害がある人のために、点字ブロックがあります。","example_reading":"しかくにしょうがいがあるひとのために、てんじぶろっくがあります。","example_meaning":"Có gạch dẫn đường dành cho người khiếm thị."},{"example":"このゲームは、視覚的にとても美しいです。","example_reading":"このげーむは、しかくてきにとてもうつくしいです。","example_meaning":"Trò chơi này rất đẹp về mặt thị giác."}]},{"word":"四角","reading":"しかく","meaning":"hình vuông, hình tứ giác","example":"四角い箱に、お菓子を入れました。","example_reading":"しかくいはこに、おかしをいれました。","example_meaning":"Tôi cho bánh kẹo vào chiếc hộp vuông.","examples":[{"example":"紙を四角に切って、折り紙を作ります。","example_reading":"かみをしかくにきって、おりがみをつくります。","example_meaning":"Cắt giấy thành hình vuông để làm origami."},{"example":"窓は、丸ではなく四角です。","example_reading":"まどは、まるではなくしかくです。","example_meaning":"Cửa sổ không tròn mà hình vuông."}]},{"word":"死角","reading":"しかく","meaning":"góc chết, điểm mù","example":"車の死角に、自転車がいて危なかったです。","example_reading":"くるまのしかくに、じてんしゃがいてあぶなかったです。","example_meaning":"Có chiếc xe đạp nằm trong điểm mù của ô tô nên rất nguy hiểm.","examples":[{"example":"運転するときは、死角に注意してください。","example_reading":"うんてんするときは、しかくにちゅういしてください。","example_meaning":"Khi lái xe, hãy chú ý đến điểm mù."},{"example":"この計画には、思わぬ死角がありました。","example_reading":"このけいかくには、おもわぬしかくがありました。","example_meaning":"Kế hoạch này có một điểm mù không ngờ tới."}]}]},
{"label":"思考／志向／嗜好／試行","note":"思考(しこう): TƯ DUY, SUY NGHĨ (hoạt động của đầu óc). 志向(しこう): KHUYNH HƯỚNG, Ý HƯỚNG hướng tới mục tiêu (安定志向, 上昇志向). 嗜好(しこう): SỞ THÍCH, KHẨU VỊ về ăn uống (嗜好品: cà phê, rượu, thuốc lá). 試行(しこう): THỬ NGHIỆM, thử làm (試行錯誤).","items":[{"word":"思考","reading":"しこう","meaning":"tư duy, suy nghĩ","example":"論理的に思考する練習をしています。","example_reading":"ろんりてきにしこうするれんしゅうをしています。","example_meaning":"Tôi đang luyện tập tư duy logic.","examples":[{"example":"彼は、ものごとを柔軟に思考できる人です。","example_reading":"かれは、ものごとをじゅうなんにしこうできるひとです。","example_meaning":"Anh ấy là người có thể tư duy linh hoạt về mọi việc."},{"example":"疲れていると、思考が止まってしまいます。","example_reading":"つかれていると、しこうがとまってしまいます。","example_meaning":"Mệt là đầu óc tôi ngừng suy nghĩ."}]},{"word":"志向","reading":"しこう","meaning":"khuynh hướng, ý hướng","example":"最近の若者は、安定志向が強いと言われます。","example_reading":"さいきんのわかものは、あんていしこうがつよいといわれます。","example_meaning":"Người ta nói giới trẻ gần đây có xu hướng chuộng sự ổn định.","examples":[{"example":"彼女は、海外で働くことを志向しています。","example_reading":"かのじょは、かいがいではたらくことをしこうしています。","example_meaning":"Cô ấy hướng tới việc làm việc ở nước ngoài."},{"example":"この会社は、品質志向の経営をしています。","example_reading":"このかいしゃは、ひんしつしこうのけいえいをしています。","example_meaning":"Công ty này quản lý theo định hướng chất lượng."}]},{"word":"嗜好","reading":"しこう","meaning":"sở thích, khẩu vị","example":"コーヒーや紅茶は、嗜好品です。","example_reading":"こーひーやこうちゃは、しこうひんです。","example_meaning":"Cà phê và trà đen thuộc nhóm đồ uống dùng theo sở thích.","examples":[{"example":"食べ物の嗜好は、人によって違います。","example_reading":"たべもののしこうは、ひとによってちがいます。","example_meaning":"Khẩu vị ăn uống của mỗi người mỗi khác."},{"example":"年を取って、味の嗜好が変わってきました。","example_reading":"としをとって、あじのしこうがかわってきました。","example_meaning":"Lớn tuổi rồi, khẩu vị của tôi đã thay đổi."}]},{"word":"試行","reading":"しこう","meaning":"thử nghiệm, thử làm","example":"新しいシステムを、一か月間試行します。","example_reading":"あたらしいしすてむを、いっかげつかんしこうします。","example_meaning":"Chúng tôi sẽ chạy thử hệ thống mới trong một tháng.","examples":[{"example":"試行錯誤を繰り返して、やっと成功しました。","example_reading":"しこうさくごをくりかえして、やっとせいこうしました。","example_meaning":"Thử đi thử lại nhiều lần, cuối cùng tôi cũng thành công."},{"example":"この制度は、まず試行の段階です。","example_reading":"このせいどは、まずしこうのだんかいです。","example_meaning":"Chế độ này trước hết đang ở giai đoạn thử nghiệm."}]}]},
{"label":"自信／自身／地震","note":"自信(じしん): TỰ TIN, niềm tin vào năng lực của mình. 自身(じしん): CHÍNH BẢN THÂN, tự mình (私自身, 自分自身). 地震(じしん): ĐỘNG ĐẤT.","items":[{"word":"自信","reading":"じしん","meaning":"tự tin","example":"私は、日本語のテストに自信があります。","example_reading":"わたしは、にほんごのてすとにじしんがあります。","example_meaning":"Tôi tự tin với bài kiểm tra tiếng Nhật.","examples":[{"example":"失敗が続いて、自信をなくしました。","example_reading":"しっぱいがつづいて、じしんをなくしました。","example_meaning":"Thất bại liên tiếp khiến tôi mất tự tin."},{"example":"彼は、自信たっぷりに発表しました。","example_reading":"かれは、じしんたっぷりにはっぴょうしました。","example_meaning":"Anh ấy thuyết trình với vẻ đầy tự tin."}]},{"word":"自身","reading":"じしん","meaning":"chính bản thân, tự mình","example":"これは、私自身の問題です。","example_reading":"これは、わたしじしんのもんだいです。","example_meaning":"Đây là vấn đề của chính bản thân tôi.","examples":[{"example":"自分自身を信じることが大切です。","example_reading":"じぶんじしんをしんじることがたいせつです。","example_meaning":"Điều quan trọng là tin vào chính mình."},{"example":"社長自身が、お客様に謝りに行きました。","example_reading":"しゃちょうじしんが、おきゃくさまにあやまりにいきました。","example_meaning":"Chính giám đốc đã tự mình đến xin lỗi khách hàng."}]},{"word":"地震","reading":"じしん","meaning":"động đất","example":"昨日の夜、大きな地震がありました。","example_reading":"きのうのよる、おおきなじしんがありました。","example_meaning":"Đêm qua đã có một trận động đất lớn.","examples":[{"example":"地震のときは、まず机の下に隠れます。","example_reading":"じしんのときは、まずつくえのしたにかくれます。","example_meaning":"Khi có động đất, trước hết hãy nấp dưới bàn."},{"example":"日本は、地震が多い国です。","example_reading":"にほんは、じしんがおおいくにです。","example_meaning":"Nhật Bản là đất nước có nhiều động đất."}]}]},
{"label":"指示／支持／師事","note":"指示(しじ): CHỈ THỊ, HƯỚNG DẪN, ra lệnh cho người khác làm gì. 支持(しじ): ỦNG HỘ, ĐỨNG VỀ PHÍA (ý kiến, chính sách, chính trị gia). 師事(しじ): THỌ GIÁO, theo học một người thầy.","items":[{"word":"指示","reading":"しじ","meaning":"chỉ thị, hướng dẫn","example":"先生の指示に従って、実験を始めました。","example_reading":"せんせいのしじにしたがって、じっけんをはじめました。","example_meaning":"Chúng tôi bắt đầu thí nghiệm theo chỉ dẫn của thầy.","examples":[{"example":"部長が、部下に仕事を指示しました。","example_reading":"ぶちょうが、ぶかにしごとをしじしました。","example_meaning":"Trưởng phòng đã giao việc cho cấp dưới."},{"example":"係員の指示があるまで、ここで待ってください。","example_reading":"かかりいんのしじがあるまで、ここでまってください。","example_meaning":"Hãy đợi ở đây cho đến khi có chỉ thị của nhân viên."}]},{"word":"支持","reading":"しじ","meaning":"ủng hộ","example":"多くの国民が、その政策を支持しています。","example_reading":"おおくのこくみんが、そのせいさくをしじしています。","example_meaning":"Nhiều người dân ủng hộ chính sách đó.","examples":[{"example":"あの政治家は、若い人に支持されています。","example_reading":"あのせいじかは、わかいひとにしじされています。","example_meaning":"Chính trị gia đó được giới trẻ ủng hộ."},{"example":"みんなが、私の意見を支持してくれました。","example_reading":"みんなが、わたしのいけんをしじしてくれました。","example_meaning":"Mọi người đã ủng hộ ý kiến của tôi."}]},{"word":"師事","reading":"しじ","meaning":"thọ giáo, theo học thầy","example":"彼は、有名な画家に師事しました。","example_reading":"かれは、ゆうめいながかにしじしました。","example_meaning":"Anh ấy đã theo học một họa sĩ nổi tiếng.","examples":[{"example":"私は、十年間、この先生に師事しています。","example_reading":"わたしは、じゅうねんかん、このせんせいにしじしています。","example_meaning":"Tôi đã theo học thầy này suốt mười năm."},{"example":"京都で、陶芸家に師事して、焼き物を学びました。","example_reading":"きょうとで、とうげいかにしじして、やきものをまなびました。","example_meaning":"Tôi đã theo học một nghệ nhân gốm ở Kyoto để học làm đồ sứ."}]}]},
{"label":"収集／収拾","note":"収集(しゅうしゅう): THU THẬP, SƯU TẦM, thu gom (đồ vật, thông tin, rác). 収拾(しゅうしゅう): THU XẾP, DẸP YÊN tình hình đang hỗn loạn (収拾がつかない).","items":[{"word":"収集","reading":"しゅうしゅう","meaning":"thu thập, sưu tầm, thu gom","example":"兄は、古い切手を収集しています。","example_reading":"あには、ふるいきってをしゅうしゅうしています。","example_meaning":"Anh tôi sưu tầm tem cũ.","examples":[{"example":"ごみの収集日は、毎週月曜日と木曜日です。","example_reading":"ごみのしゅうしゅうびは、まいしゅうげつようびともくようびです。","example_meaning":"Ngày thu gom rác là thứ Hai và thứ Năm hằng tuần."},{"example":"新しい商品の情報を、インターネットで収集しました。","example_reading":"あたらしいしょうひんのじょうほうを、いんたーねっとでしゅうしゅうしました。","example_meaning":"Tôi đã thu thập thông tin về sản phẩm mới trên Internet."}]},{"word":"収拾","reading":"しゅうしゅう","meaning":"thu xếp, dẹp yên tình hình","example":"会議が混乱して、収拾がつかなくなりました。","example_reading":"かいぎがこんらんして、しゅうしゅうがつかなくなりました。","example_meaning":"Cuộc họp rối loạn đến mức không dàn xếp nổi.","examples":[{"example":"社長は、騒ぎの収拾に努めました。","example_reading":"しゃちょうは、さわぎのしゅうしゅうにつとめました。","example_meaning":"Giám đốc đã nỗ lực dẹp yên vụ ồn ào."},{"example":"事態の収拾を図るため、緊急会議が開かれました。","example_reading":"じたいのしゅうしゅうをはかるため、きんきゅうかいぎがひらかれました。","example_meaning":"Một cuộc họp khẩn đã được triệu tập nhằm giải quyết tình hình."}]}]},
{"label":"習得／修得／拾得","note":"習得(しゅうとく): HỌC ĐƯỢC, NẮM VỮNG kỹ năng, ngôn ngữ, kỹ thuật. 修得(しゅうとく): HOÀN THÀNH, ĐẠT ĐƯỢC học vấn, tín chỉ (単位を修得). 拾得(しゅうとく): NHẶT ĐƯỢC của rơi (拾得物, 拾得者).","items":[{"word":"習得","reading":"しゅうとく","meaning":"học được, nắm vững (kỹ năng)","example":"外国語を習得するには、時間がかかります。","example_reading":"がいこくごをしゅうとくするには、じかんがかかります。","example_meaning":"Để thành thạo ngoại ngữ cần có thời gian.","examples":[{"example":"彼は、この技術を三年で習得しました。","example_reading":"かれは、このぎじゅつをさんねんでしゅうとくしました。","example_meaning":"Anh ấy đã nắm vững kỹ thuật này trong ba năm."},{"example":"料理の基本を、早く習得したいです。","example_reading":"りょうりのきほんを、はやくしゅうとくしたいです。","example_meaning":"Tôi muốn sớm nắm vững những điều cơ bản về nấu ăn."}]},{"word":"修得","reading":"しゅうとく","meaning":"hoàn thành, đạt được (học vấn, tín chỉ)","example":"卒業するには、百二十四単位を修得する必要があります。","example_reading":"そつぎょうするには、ひゃくにじゅうよんたんいをしゅうとくするひつようがあります。","example_meaning":"Muốn tốt nghiệp cần tích lũy đủ 124 tín chỉ.","examples":[{"example":"彼は、大学で必要な単位を修得しました。","example_reading":"かれは、だいがくでひつようなたんいをしゅうとくしました。","example_meaning":"Anh ấy đã hoàn thành các tín chỉ cần thiết ở đại học."},{"example":"学問を修得するために、留学しました。","example_reading":"がくもんをしゅうとくするために、りゅうがくしました。","example_meaning":"Anh ấy đi du học để học hỏi học vấn cho đến nơi đến chốn."}]},{"word":"拾得","reading":"しゅうとく","meaning":"nhặt được (của rơi)","example":"駅で拾得した財布を、交番に届けました。","example_reading":"えきでしゅうとくしたさいふを、こうばんにとどけました。","example_meaning":"Tôi mang chiếc ví nhặt được ở ga đến đồn cảnh sát.","examples":[{"example":"拾得者は、落とし主に謝礼を求める権利があります。","example_reading":"しゅうとくしゃは、おとしぬしにしゃれいをもとめるけんりがあります。","example_meaning":"Người nhặt được có quyền yêu cầu chủ sở hữu trả công."},{"example":"拾得物は、一定の期間、警察で保管されます。","example_reading":"しゅうとくぶつは、いっていのきかん、けいさつでほかんされます。","example_meaning":"Đồ nhặt được sẽ được cảnh sát bảo quản trong một thời hạn nhất định."}]}]},
{"label":"終了／修了","note":"終了(しゅうりょう): KẾT THÚC, chấm dứt (sự kiện, giờ học, thời gian, dịch vụ). 修了(しゅうりょう): HOÀN THÀNH khóa học, chương trình (修了証, 課程修了).","items":[{"word":"終了","reading":"しゅうりょう","meaning":"kết thúc, chấm dứt","example":"試験は、五時に終了します。","example_reading":"しけんは、ごじにしゅうりょうします。","example_meaning":"Kỳ thi kết thúc lúc năm giờ.","examples":[{"example":"今日の営業は、終了しました。","example_reading":"きょうのえいぎょうは、しゅうりょうしました。","example_meaning":"Hôm nay đã hết giờ kinh doanh."},{"example":"イベントは、予定より早く終了しました。","example_reading":"いべんとは、よていよりはやくしゅうりょうしました。","example_meaning":"Sự kiện đã kết thúc sớm hơn dự định."}]},{"word":"修了","reading":"しゅうりょう","meaning":"hoàn thành khóa học","example":"先月、日本語コースを修了しました。","example_reading":"せんげつ、にほんごこーすをしゅうりょうしました。","example_meaning":"Tháng trước tôi đã hoàn thành khóa tiếng Nhật.","examples":[{"example":"研修を修了した人に、修了証を渡します。","example_reading":"けんしゅうをしゅうりょうしたひとに、しゅうりょうしょうをわたします。","example_meaning":"Chúng tôi trao giấy chứng nhận cho những người đã hoàn thành khóa tập huấn."},{"example":"彼は、大学院の博士課程を修了しました。","example_reading":"かれは、だいがくいんのはかせかていをしゅうりょうしました。","example_meaning":"Anh ấy đã hoàn thành chương trình tiến sĩ sau đại học."}]}]},
{"label":"受賞／授賞","note":"受賞(じゅしょう): NHẬN GIẢI THƯỞNG (phía người được nhận). 授賞(じゅしょう): TRAO GIẢI (phía bên trao, 授賞式).","items":[{"word":"受賞","reading":"じゅしょう","meaning":"nhận giải thưởng","example":"彼の映画が、世界的な賞を受賞しました。","example_reading":"かれのえいがが、せかいてきなしょうをじゅしょうしました。","example_meaning":"Bộ phim của anh ấy đã nhận giải thưởng quốc tế.","examples":[{"example":"受賞のスピーチで、彼は感謝の言葉を述べました。","example_reading":"じゅしょうのすぴーちで、かれはかんしゃのことばをのべました。","example_meaning":"Trong bài phát biểu nhận giải, anh ấy gửi lời cảm ơn."},{"example":"兄の小説が、文学賞を受賞しました。","example_reading":"あにのしょうせつが、ぶんがくしょうをじゅしょうしました。","example_meaning":"Tiểu thuyết của anh tôi đã đoạt giải văn học."}]},{"word":"授賞","reading":"じゅしょう","meaning":"trao giải","example":"授賞式は、来月、東京で行われます。","example_reading":"じゅしょうしきは、らいげつ、とうきょうでおこなわれます。","example_meaning":"Lễ trao giải sẽ được tổ chức ở Tokyo vào tháng sau.","examples":[{"example":"委員会は、毎年、授賞する作品を選びます。","example_reading":"いいんかいは、まいとし、じゅしょうするさくひんをえらびます。","example_meaning":"Ủy ban hằng năm chọn ra tác phẩm được trao giải."},{"example":"協会は、毎年、優れた作家に授賞しています。","example_reading":"きょうかいは、まいとし、すぐれたさっかにじゅしょうしています。","example_meaning":"Hiệp hội hằng năm đều trao giải cho những tác giả xuất sắc."}]}]},
{"label":"消化／消火／昇華／唱歌","note":"消化(しょうか): TIÊU HÓA thức ăn; nghĩa bóng là tiêu hóa kiến thức, giải quyết hết khối lượng việc. 消火(しょうか): DẬP LỬA, CHỮA CHÁY. 昇華(しょうか): THĂNG HOA (hóa học); nghĩa bóng là nâng lên tầm cao hơn. 唱歌(しょうか): BÀI HÁT HỌC ĐƯỜNG, nhạc dạy hát ở trường.","items":[{"word":"消化","reading":"しょうか","meaning":"tiêu hóa; giải quyết hết (việc)","example":"食べ物は、胃と腸で消化されます。","example_reading":"たべものは、いとちょうでしょうかされます。","example_meaning":"Thức ăn được tiêu hóa ở dạ dày và ruột.","examples":[{"example":"夜遅く食べると、消化が悪くなります。","example_reading":"よるおそくたべると、しょうかがわるくなります。","example_meaning":"Ăn muộn buổi tối thì tiêu hóa kém."},{"example":"今月は、たまった仕事を消化するのに忙しいです。","example_reading":"こんげつは、たまったしごとをしょうかするのにいそがしいです。","example_meaning":"Tháng này tôi bận giải quyết cho xong đống việc tồn đọng."}]},{"word":"消火","reading":"しょうか","meaning":"dập lửa, chữa cháy","example":"消防士が、火事の現場で消火作業をしています。","example_reading":"しょうぼうしが、かじのげんばでしょうかさぎょうをしています。","example_meaning":"Lính cứu hỏa đang dập lửa tại hiện trường vụ cháy.","examples":[{"example":"ビルには、消火器が置いてあります。","example_reading":"びるには、しょうかきがおいてあります。","example_meaning":"Trong tòa nhà có đặt bình chữa cháy."},{"example":"近くの池の水で、消火しました。","example_reading":"ちかくのいけのみずで、しょうかしました。","example_meaning":"Họ đã dập lửa bằng nước từ cái ao gần đó."}]},{"word":"昇華","reading":"しょうか","meaning":"thăng hoa; nâng lên tầm cao hơn","example":"ドライアイスは、固体から気体へ昇華します。","example_reading":"どらいあいすは、こたいからきたいへしょうかします。","example_meaning":"Đá khô thăng hoa từ thể rắn sang thể khí.","examples":[{"example":"彼は、苦しい経験を作品に昇華させました。","example_reading":"かれは、くるしいけいけんをさくひんにしょうかさせました。","example_meaning":"Anh ấy đã nâng những trải nghiệm đau khổ thành tác phẩm."},{"example":"悲しみを、美しい音楽へと昇華しました。","example_reading":"かなしみを、うつくしいおんがくへとしょうかしました。","example_meaning":"Anh ấy đã chuyển hóa nỗi buồn thành âm nhạc đẹp đẽ."}]},{"word":"唱歌","reading":"しょうか","meaning":"bài hát học đường","example":"小学校で、昔の唱歌を習いました。","example_reading":"しょうがっこうで、むかしのしょうかをならいました。","example_meaning":"Ở trường tiểu học, tôi đã học những bài hát học đường ngày xưa.","examples":[{"example":"祖母は、子どものころの唱歌を今でも歌えます。","example_reading":"そぼは、こどものころのしょうかをいまでもうたえます。","example_meaning":"Bà tôi đến giờ vẫn hát được những bài hát học đường thuở nhỏ."},{"example":"「ふるさと」は、有名な唱歌のひとつです。","example_reading":"「ふるさと」は、ゆうめいなしょうかのひとつです。","example_meaning":"\"Furusato\" là một trong những bài hát học đường nổi tiếng."}]}]},
{"label":"証明／照明","note":"証明(しょうめい): CHỨNG MINH, xác nhận là đúng, là thật (証明書, chứng minh định lý). 照明(しょうめい): CHIẾU SÁNG, ÁNH SÁNG ĐÈN (thiết bị chiếu sáng, ánh sáng sân khấu).","items":[{"word":"証明","reading":"しょうめい","meaning":"chứng minh, xác nhận","example":"身分を証明するものを、見せてください。","example_reading":"みぶんをしょうめいするものを、みせてください。","example_meaning":"Xin hãy xuất trình giấy tờ chứng minh nhân thân.","examples":[{"example":"数学の授業で、定理の証明を習いました。","example_reading":"すうがくのじゅぎょうで、ていりのしょうめいをならいました。","example_meaning":"Trong giờ toán, tôi đã học cách chứng minh định lý."},{"example":"卒業証明書を、大学に申し込みました。","example_reading":"そつぎょうしょうめいしょを、だいがくにもうしこみました。","example_meaning":"Tôi đã đăng ký xin giấy chứng nhận tốt nghiệp ở trường đại học."}]},{"word":"照明","reading":"しょうめい","meaning":"chiếu sáng, ánh sáng đèn","example":"この部屋は、照明が暗すぎます。","example_reading":"このへやは、しょうめいがくらすぎます。","example_meaning":"Căn phòng này ánh sáng quá tối.","examples":[{"example":"舞台の照明が、とても美しかったです。","example_reading":"ぶたいのしょうめいが、とてもうつくしかったです。","example_meaning":"Ánh sáng sân khấu rất đẹp."},{"example":"読書をするときは、明るい照明が必要です。","example_reading":"どくしょをするときは、あかるいしょうめいがひつようです。","example_meaning":"Khi đọc sách cần có ánh đèn đủ sáng."}]}]},
{"label":"食料／食糧","note":"食料(しょくりょう): THỰC PHẨM, đồ ăn nói chung (食料品, 食料を買う). 食糧(しょくりょう): LƯƠNG THỰC, thức ăn chính nuôi sống người dân (gạo, lúa mì; 食糧危機, 食糧不足).","items":[{"word":"食料","reading":"しょくりょう","meaning":"thực phẩm, đồ ăn","example":"週末に、一週間分の食料を買います。","example_reading":"しゅうまつに、いっしゅうかんぶんのしょくりょうをかいます。","example_meaning":"Cuối tuần tôi mua thực phẩm đủ cho một tuần.","examples":[{"example":"登山には、食料と水を持っていきます。","example_reading":"とざんには、しょくりょうとみずをもっていきます。","example_meaning":"Khi leo núi, tôi mang theo thức ăn và nước."},{"example":"食料品売り場は、地下一階にあります。","example_reading":"しょくりょうひんうりばは、ちかいっかいにあります。","example_meaning":"Quầy thực phẩm ở tầng hầm một."}]},{"word":"食糧","reading":"しょくりょう","meaning":"lương thực","example":"世界では、食糧が足りない国があります。","example_reading":"せかいでは、しょくりょうがたりないくにがあります。","example_meaning":"Trên thế giới có những quốc gia thiếu lương thực.","examples":[{"example":"日本は、食糧の多くを輸入に頼っています。","example_reading":"にほんは、しょくりょうのおおくをゆにゅうにたよっています。","example_meaning":"Nhật Bản phụ thuộc vào nhập khẩu cho phần lớn lương thực."},{"example":"台風で、食糧の生産に被害が出ました。","example_reading":"たいふうで、しょくりょうのせいさんにひがいがでました。","example_meaning":"Bão đã gây thiệt hại cho việc sản xuất lương thực."}]}]},
{"label":"資料／史料／試料／飼料","note":"資料(しりょう): TÀI LIỆU, dữ liệu tham khảo (会議の資料). 史料(しりょう): SỬ LIỆU, tư liệu lịch sử. 試料(しりょう): MẪU THỬ, mẫu vật để phân tích, thí nghiệm. 飼料(しりょう): THỨC ĂN CHĂN NUÔI cho gia súc, cá.","items":[{"word":"資料","reading":"しりょう","meaning":"tài liệu, dữ liệu tham khảo","example":"会議で使う資料を、コピーしておきました。","example_reading":"かいぎでつかうしりょうを、こぴーしておきました。","example_meaning":"Tôi đã photo sẵn tài liệu dùng cho cuộc họp.","examples":[{"example":"レポートを書くために、図書館で資料を集めました。","example_reading":"れぽーとをかくために、としょかんでしりょうをあつめました。","example_meaning":"Tôi đã thu thập tài liệu ở thư viện để viết báo cáo."},{"example":"詳しい資料は、メールでお送りします。","example_reading":"くわしいしりょうは、めーるでおおくりします。","example_meaning":"Tôi sẽ gửi tài liệu chi tiết qua email."}]},{"word":"史料","reading":"しりょう","meaning":"sử liệu","example":"博物館で、江戸時代の史料を見ました。","example_reading":"はくぶつかんで、えどじだいのしりょうをみました。","example_meaning":"Tôi đã xem sử liệu thời Edo ở bảo tàng.","examples":[{"example":"歴史学者は、古い史料を読んで研究します。","example_reading":"れきしがくしゃは、ふるいしりょうをよんでけんきゅうします。","example_meaning":"Các nhà sử học nghiên cứu bằng cách đọc các sử liệu cổ."},{"example":"この手紙は、貴重な史料として保存されています。","example_reading":"このてがみは、きちょうなしりょうとしてほぞんされています。","example_meaning":"Bức thư này được bảo quản như một sử liệu quý giá."}]},{"word":"試料","reading":"しりょう","meaning":"mẫu thử, mẫu vật","example":"分析のために、川の水を試料として集めました。","example_reading":"ぶんせきのために、かわのみずをしりょうとしてあつめました。","example_meaning":"Tôi lấy nước sông làm mẫu để phân tích.","examples":[{"example":"研究室では、試料を顕微鏡で調べます。","example_reading":"けんきゅうしつでは、しりょうをけんびきょうでしらべます。","example_meaning":"Ở phòng nghiên cứu, người ta khảo sát mẫu thử bằng kính hiển vi."},{"example":"検査の試料は、冷蔵庫で保管してください。","example_reading":"けんさのしりょうは、れいぞうこでほかんしてください。","example_meaning":"Hãy bảo quản mẫu thử xét nghiệm trong tủ lạnh."}]},{"word":"飼料","reading":"しりょう","meaning":"thức ăn chăn nuôi","example":"農家は、牛に飼料を与えています。","example_reading":"のうかは、うしにしりょうをあたえています。","example_meaning":"Nhà nông cho bò ăn thức ăn chăn nuôi.","examples":[{"example":"飼料の値段が上がって、畜産農家は困っています。","example_reading":"しりょうのねだんがあがって、ちくさんのうかはこまっています。","example_meaning":"Giá thức ăn chăn nuôi tăng khiến các hộ chăn nuôi gặp khó khăn."},{"example":"魚の飼料には、栄養がたっぷり含まれています。","example_reading":"さかなのしりょうには、えいようがたっぷりふくまれています。","example_meaning":"Thức ăn nuôi cá chứa nhiều dinh dưỡng."}]}]},
{"label":"制約／誓約／製薬／成約","note":"制約(せいやく): RÀNG BUỘC, HẠN CHẾ, điều kiện giới hạn (時間の制約, 予算の制約). 誓約(せいやく): LỜI THỀ, CAM KẾT bằng lời hoặc văn bản (誓約書). 製薬(せいやく): SẢN XUẤT THUỐC (製薬会社). 成約(せいやく): CHỐT ĐƯỢC HỢP ĐỒNG, giao dịch thành công (成約率).","items":[{"word":"制約","reading":"せいやく","meaning":"ràng buộc, hạn chế","example":"時間の制約があって、全部は見られません。","example_reading":"じかんのせいやくがあって、ぜんぶはみられません。","example_meaning":"Vì bị giới hạn thời gian nên không xem hết được.","examples":[{"example":"この仕事は、多くの制約の中で進めています。","example_reading":"このしごとは、おおくのせいやくのなかですすめています。","example_meaning":"Công việc này đang được tiến hành giữa nhiều ràng buộc."},{"example":"予算の制約が、計画の大きな問題です。","example_reading":"よさんのせいやくが、けいかくのおおきなもんだいです。","example_meaning":"Giới hạn ngân sách là vấn đề lớn của kế hoạch."}]},{"word":"誓約","reading":"せいやく","meaning":"lời thề, cam kết","example":"入社するときに、秘密を守る誓約書を書きました。","example_reading":"にゅうしゃするときに、ひみつをまもるせいやくしょをかきました。","example_meaning":"Khi vào công ty, tôi đã ký bản cam kết giữ bí mật.","examples":[{"example":"彼は、二度としないと誓約しました。","example_reading":"かれは、にどとしないとせいやくしました。","example_meaning":"Anh ấy đã thề sẽ không bao giờ tái phạm."},{"example":"参加者は、ルールを守ることを誓約します。","example_reading":"さんかしゃは、るーるをまもることをせいやくします。","example_meaning":"Người tham gia cam kết tuân thủ quy tắc."}]},{"word":"製薬","reading":"せいやく","meaning":"sản xuất thuốc","example":"兄は、大きな製薬会社で働いています。","example_reading":"あには、おおきなせいやくがいしゃではたらいています。","example_meaning":"Anh tôi làm việc ở một công ty dược lớn.","examples":[{"example":"製薬の研究所で、新しい薬を開発しています。","example_reading":"せいやくのけんきゅうじょで、あたらしいくすりをかいはつしています。","example_meaning":"Họ đang phát triển thuốc mới tại viện nghiên cứu dược."},{"example":"製薬業界では、国際的な競争が激しくなっています。","example_reading":"せいやくぎょうかいでは、こくさいてきなきょうそうがはげしくなっています。","example_meaning":"Trong ngành dược, cạnh tranh quốc tế đang trở nên khốc liệt."}]},{"word":"成約","reading":"せいやく","meaning":"chốt hợp đồng, giao dịch thành công","example":"今月は、五件の商談が成約しました。","example_reading":"こんげつは、ごけんのしょうだんがせいやくしました。","example_meaning":"Tháng này có năm cuộc đàm phán đã chốt thành công.","examples":[{"example":"価格の交渉がまとまって、成約に至りました。","example_reading":"かかくのこうしょうがまとまって、せいやくにいたりました。","example_meaning":"Việc đàm phán giá đã ngã ngũ và đi đến ký kết."},{"example":"営業部は、成約率を上げるために努力しています。","example_reading":"えいぎょうぶは、せいやくりつをあげるためにどりょくしています。","example_meaning":"Phòng kinh doanh đang nỗ lực nâng tỷ lệ chốt hợp đồng."}]}]},
{"label":"想像／創造","note":"想像(そうぞう): TƯỞNG TƯỢNG, hình dung trong đầu điều chưa thấy hay chưa xảy ra. 創造(そうぞう): SÁNG TẠO, tạo ra cái mới chưa từng có.","items":[{"word":"想像","reading":"そうぞう","meaning":"tưởng tượng","example":"将来の生活を、想像してみました。","example_reading":"しょうらいのせいかつを、そうぞうしてみました。","example_meaning":"Tôi thử tưởng tượng cuộc sống tương lai.","examples":[{"example":"彼女が怒った顔は、想像できません。","example_reading":"かのじょがおこったかおは、そうぞうできません。","example_meaning":"Tôi không thể tưởng tượng được gương mặt tức giận của cô ấy."},{"example":"結果は、想像以上に良かったです。","example_reading":"けっかは、そうぞういじょうによかったです。","example_meaning":"Kết quả tốt hơn tôi tưởng tượng."}]},{"word":"創造","reading":"そうぞう","meaning":"sáng tạo","example":"芸術家は、新しい作品を創造します。","example_reading":"げいじゅつかは、あたらしいさくひんをそうぞうします。","example_meaning":"Nghệ sĩ sáng tạo ra tác phẩm mới.","examples":[{"example":"子どもの創造力を、伸ばしたいです。","example_reading":"こどものそうぞうりょくを、のばしたいです。","example_meaning":"Tôi muốn phát triển khả năng sáng tạo của trẻ."},{"example":"神が世界を創造したという話が、神話にあります。","example_reading":"かみがせかいをそうぞうしたというはなしが、しんわにあります。","example_meaning":"Trong thần thoại có câu chuyện về việc thần sáng tạo ra thế giới."}]}]},
{"label":"体制／態勢／体勢／大勢","note":"体制(たいせい): THỂ CHẾ, HỆ THỐNG tổ chức (政治体制, 管理体制). 態勢(たいせい): TƯ THẾ SẴN SÀNG, trạng thái chuẩn bị đối phó (受け入れ態勢, 警戒態勢). 体勢(たいせい): TƯ THẾ CƠ THỂ, thế đứng (体勢を崩す). 大勢(たいせい): XU THẾ CHUNG, đại cục (大勢が決まる); lưu ý 大勢 còn đọc おおぜい nghĩa là đông người.","items":[{"word":"体制","reading":"たいせい","meaning":"thể chế, hệ thống tổ chức","example":"この会社は、社員を守る体制が整っています。","example_reading":"このかいしゃは、しゃいんをまもるたいせいがととのっています。","example_meaning":"Công ty này có hệ thống bảo vệ nhân viên hoàn chỉnh.","examples":[{"example":"政府は、新しい体制で政治を行います。","example_reading":"せいふは、あたらしいたいせいでせいじをおこないます。","example_meaning":"Chính phủ điều hành chính trị theo một thể chế mới."},{"example":"災害に備えて、連絡の体制を作りました。","example_reading":"さいがいにそなえて、れんらくのたいせいをつくりました。","example_meaning":"Để chuẩn bị cho thiên tai, chúng tôi đã lập hệ thống liên lạc."}]},{"word":"態勢","reading":"たいせい","meaning":"tư thế sẵn sàng, trạng thái chuẩn bị","example":"店は、お客様を迎える態勢を整えました。","example_reading":"みせは、おきゃくさまをむかえるたいせいをととのえました。","example_meaning":"Cửa hàng đã chuẩn bị sẵn sàng để đón khách.","examples":[{"example":"警察は、厳しい警戒態勢を取っています。","example_reading":"けいさつは、きびしいけいかいたいせいをとっています。","example_meaning":"Cảnh sát đang trong tư thế cảnh giác cao độ."},{"example":"留学生を受け入れる態勢が、まだできていません。","example_reading":"りゅうがくせいをうけいれるたいせいが、まだできていません。","example_meaning":"Vẫn chưa sẵn sàng để tiếp nhận du học sinh."}]},{"word":"体勢","reading":"たいせい","meaning":"tư thế cơ thể","example":"転びそうになって、体勢を崩しました。","example_reading":"ころびそうになって、たいせいをくずしました。","example_meaning":"Suýt ngã nên tôi mất thăng bằng tư thế.","examples":[{"example":"楽な体勢で、リラックスしてください。","example_reading":"らくなたいせいで、りらっくすしてください。","example_meaning":"Hãy thả lỏng ở một tư thế thoải mái."},{"example":"選手は、すぐに体勢を立て直しました。","example_reading":"せんしゅは、すぐにたいせいをたてなおしました。","example_meaning":"Vận động viên đã nhanh chóng lấy lại tư thế."}]},{"word":"大勢","reading":"たいせい","meaning":"xu thế chung, đại cục","example":"試合の大勢は、もう決まりました。","example_reading":"しあいのたいせいは、もうきまりました。","example_meaning":"Xu thế chung của trận đấu đã ngã ngũ.","examples":[{"example":"世の中の大勢に、流されてはいけません。","example_reading":"よのなかのたいせいに、ながされてはいけません。","example_meaning":"Đừng để bị cuốn theo xu thế chung của xã hội."},{"example":"選挙の大勢が、判明しました。","example_reading":"せんきょのたいせいが、はんめいしました。","example_meaning":"Xu thế chung của cuộc bầu cử đã rõ ràng."}]}]},
{"label":"特性／特製","note":"特性(とくせい): ĐẶC TÍNH, tính chất riêng của sự vật (材料の特性, 動物の特性). 特製(とくせい): ĐẶC CHẾ, LÀM ĐẶC BIỆT (món ăn, đồ vật được làm riêng, công phu).","items":[{"word":"特性","reading":"とくせい","meaning":"đặc tính, tính chất riêng","example":"この金属は、熱を伝えやすい特性があります。","example_reading":"このきんぞくは、ねつをつたえやすいとくせいがあります。","example_meaning":"Kim loại này có đặc tính dẫn nhiệt dễ dàng.","examples":[{"example":"植物ごとの特性を知って、育てましょう。","example_reading":"しょくぶつごとのとくせいをしって、そだてましょう。","example_meaning":"Hãy tìm hiểu đặc tính của từng loại cây rồi mới trồng."},{"example":"犬の種類によって、特性が違います。","example_reading":"いぬのしゅるいによって、とくせいがちがいます。","example_meaning":"Mỗi giống chó có đặc tính khác nhau."}]},{"word":"特製","reading":"とくせい","meaning":"đặc chế, làm đặc biệt","example":"この店の特製ラーメンは、とても人気があります。","example_reading":"このみせのとくせいらーめんは、とてもにんきがあります。","example_meaning":"Món ramen đặc chế của tiệm này rất nổi tiếng.","examples":[{"example":"母が、特製のケーキを焼いてくれました。","example_reading":"ははが、とくせいのけーきをやいてくれました。","example_meaning":"Mẹ đã nướng cho tôi một chiếc bánh làm đặc biệt."},{"example":"当店特製のたれで、お召し上がりください。","example_reading":"とうてんとくせいのたれで、おめしあがりください。","example_meaning":"Xin mời quý khách dùng với nước sốt đặc chế của quán."}]}]},
{"label":"特徴／特長","note":"特徴(とくちょう): ĐẶC ĐIỂM nổi bật giúp nhận ra sự vật hay con người (không nhất thiết là điểm tốt). 特長(とくちょう): ƯU ĐIỂM, ĐIỂM MẠNH nổi trội (luôn mang nghĩa tốt).","items":[{"word":"特徴","reading":"とくちょう","meaning":"đặc điểm","example":"この犬の特徴は、長い耳です。","example_reading":"このいぬのとくちょうは、ながいみみです。","example_meaning":"Đặc điểm của chú chó này là đôi tai dài.","examples":[{"example":"犯人の特徴を、警察に伝えました。","example_reading":"はんにんのとくちょうを、けいさつにつたえました。","example_meaning":"Tôi đã báo cho cảnh sát đặc điểm của hung thủ."},{"example":"日本語の特徴のひとつは、敬語があることです。","example_reading":"にほんごのとくちょうのひとつは、けいごがあることです。","example_meaning":"Một trong những đặc điểm của tiếng Nhật là có kính ngữ."}]},{"word":"特長","reading":"とくちょう","meaning":"ưu điểm, điểm mạnh","example":"この製品の特長は、軽くて丈夫なことです。","example_reading":"このせいひんのとくちょうは、かるくてじょうぶなことです。","example_meaning":"Điểm mạnh của sản phẩm này là nhẹ mà bền.","examples":[{"example":"新しい機種の特長を、説明します。","example_reading":"あたらしいきしゅのとくちょうを、せつめいします。","example_meaning":"Tôi sẽ giải thích những ưu điểm của mẫu máy mới."},{"example":"彼の特長は、誰とでも仲良くなれることです。","example_reading":"かれのとくちょうは、だれとでもなかよくなれることです。","example_meaning":"Điểm mạnh của anh ấy là có thể thân thiết với bất kỳ ai."}]}]},
{"label":"破棄／覇気","note":"破棄(はき): HỦY BỎ, XÉ BỎ (hợp đồng, giấy tờ, bản án; 契約を破棄). 覇気(はき): KHÍ THẾ, CHÍ KHÍ, tinh thần quyết tâm tiến lên (覇気がない = thiếu sinh khí, thiếu nhuệ khí).","items":[{"word":"破棄","reading":"はき","meaning":"hủy bỏ, xé bỏ","example":"相手が約束を守らないので、契約を破棄しました。","example_reading":"あいてがやくそくをまもらないので、けいやくをはきしました。","example_meaning":"Vì đối phương không giữ lời hứa nên tôi đã hủy hợp đồng.","examples":[{"example":"裁判所は、前の判決を破棄しました。","example_reading":"さいばんしょは、まえのはんけつをはきしました。","example_meaning":"Tòa án đã hủy bản án trước."},{"example":"彼は、約束を破棄して、国を出ていきました。","example_reading":"かれは、やくそくをはきして、くにをでていきました。","example_meaning":"Anh ta xé bỏ lời hứa rồi rời khỏi đất nước."}]},{"word":"覇気","reading":"はき","meaning":"khí thế, chí khí","example":"彼は、若いのに覇気がありません。","example_reading":"かれは、わかいのにはきがありません。","example_meaning":"Anh ấy còn trẻ mà chẳng có chí khí.","examples":[{"example":"新しい社長は、覇気にあふれた人です。","example_reading":"あたらしいしゃちょうは、はきにあふれたひとです。","example_meaning":"Vị giám đốc mới là người tràn đầy khí thế."},{"example":"覇気のない返事に、先生は心配しました。","example_reading":"はきのないへんじに、せんせいはしんぱいしました。","example_meaning":"Thầy lo lắng trước câu trả lời thiếu sinh khí."}]}]},
{"label":"発行／発効／発酵／発光","note":"発行(はっこう): PHÁT HÀNH (sách, báo, hóa đơn, vé, thẻ). 発効(はっこう): CÓ HIỆU LỰC (luật, hiệp ước, hợp đồng bắt đầu có hiệu lực). 発酵(はっこう): LÊN MEN (nấm men, vi khuẩn; 発酵食品). 発光(はっこう): PHÁT SÁNG (đom đóm, đèn, sinh vật).","items":[{"word":"発行","reading":"はっこう","meaning":"phát hành","example":"この雑誌は、毎月十日に発行されます。","example_reading":"このざっしは、まいつきとおかにはっこうされます。","example_meaning":"Tạp chí này được phát hành vào ngày 10 hằng tháng.","examples":[{"example":"銀行で、新しいカードを発行してもらいました。","example_reading":"ぎんこうで、あたらしいかーどをはっこうしてもらいました。","example_meaning":"Tôi được ngân hàng cấp thẻ mới."},{"example":"領収書を発行してください。","example_reading":"りょうしゅうしょをはっこうしてください。","example_meaning":"Xin hãy xuất hóa đơn cho tôi."}]},{"word":"発効","reading":"はっこう","meaning":"có hiệu lực","example":"新しい法律は、来月一日に発効します。","example_reading":"あたらしいほうりつは、らいげつついたちにはっこうします。","example_meaning":"Luật mới sẽ có hiệu lực từ ngày 1 tháng sau.","examples":[{"example":"両国の条約が、ついに発効しました。","example_reading":"りょうこくのじょうやくが、ついにはっこうしました。","example_meaning":"Hiệp ước giữa hai nước cuối cùng đã có hiệu lực."},{"example":"契約は、署名した日から発効します。","example_reading":"けいやくは、しょめいしたひからはっこうします。","example_meaning":"Hợp đồng có hiệu lực kể từ ngày ký."}]},{"word":"発酵","reading":"はっこう","meaning":"lên men","example":"納豆は、大豆を発酵させて作ります。","example_reading":"なっとうは、だいずをはっこうさせてつくります。","example_meaning":"Natto được làm bằng cách cho đậu nành lên men.","examples":[{"example":"パン生地が、発酵して大きくふくらみました。","example_reading":"ぱんきじが、はっこうしておおきくふくらみました。","example_meaning":"Bột bánh mì đã lên men và nở phồng to."},{"example":"ヨーグルトやみそは、発酵食品です。","example_reading":"よーぐるとやみそは、はっこうしょくひんです。","example_meaning":"Sữa chua và miso là thực phẩm lên men."}]},{"word":"発光","reading":"はっこう","meaning":"phát sáng","example":"夏の夜、ホタルが青白く発光します。","example_reading":"なつのよる、ほたるがあおじろくはっこうします。","example_meaning":"Đêm hè, đom đóm phát ra ánh sáng xanh nhạt.","examples":[{"example":"この腕時計は、暗い所でも発光します。","example_reading":"このうでどけいは、くらいところでもはっこうします。","example_meaning":"Chiếc đồng hồ đeo tay này phát sáng cả ở nơi tối."},{"example":"深海には、自分で発光する魚がいます。","example_reading":"しんかいには、じぶんではっこうするさかながいます。","example_meaning":"Ở biển sâu có loài cá tự phát sáng."}]}]},
{"label":"不振／不審／不信","note":"不振(ふしん): TRÌ TRỆ, SA SÚT, không khởi sắc (成績不振, 食欲不振, 売り上げ不振). 不審(ふしん): ĐÁNG NGỜ, KHẢ NGHI (不審な人物, 不審に思う). 不信(ふしん): KHÔNG TIN TƯỞNG, mất lòng tin (不信感, 政治不信).","items":[{"word":"不振","reading":"ふしん","meaning":"trì trệ, sa sút","example":"売り上げが不振で、店を閉めることにしました。","example_reading":"うりあげがふしんで、みせをしめることにしました。","example_meaning":"Doanh thu sa sút nên chúng tôi quyết định đóng cửa tiệm.","examples":[{"example":"夏は、暑さのために食欲不振になります。","example_reading":"なつは、あつさのためにしょくよくふしんになります。","example_meaning":"Mùa hè, vì nóng nên tôi ăn không ngon miệng."},{"example":"チームは、成績不振が続いています。","example_reading":"ちーむは、せいせきふしんがつづいています。","example_meaning":"Đội liên tục có thành tích sa sút."}]},{"word":"不審","reading":"ふしん","meaning":"đáng ngờ, khả nghi","example":"家の前に、不審な男が立っていました。","example_reading":"いえのまえに、ふしんなおとこがたっていました。","example_meaning":"Có một gã đàn ông khả nghi đứng trước nhà.","examples":[{"example":"不審な荷物を見つけたら、すぐに連絡してください。","example_reading":"ふしんなにもつをみつけたら、すぐにれんらくしてください。","example_meaning":"Nếu thấy hành lý khả nghi, hãy liên lạc ngay."},{"example":"彼の話を聞いて、不審に思いました。","example_reading":"かれのはなしをきいて、ふしんにおもいました。","example_meaning":"Nghe anh ta nói, tôi thấy có điều đáng ngờ."}]},{"word":"不信","reading":"ふしん","meaning":"không tin tưởng, mất lòng tin","example":"嘘をつかれて、彼に不信感を持ちました。","example_reading":"うそをつかれて、かれにふしんかんをもちました。","example_meaning":"Bị nói dối nên tôi mất lòng tin vào anh ấy.","examples":[{"example":"政治への不信が、国民の間に広がっています。","example_reading":"せいじへのふしんが、こくみんのあいだにひろがっています。","example_meaning":"Sự mất niềm tin vào chính trị đang lan rộng trong người dân."},{"example":"友達同士の不信は、小さな誤解から始まります。","example_reading":"ともだちどうしのふしんは、ちいさなごかいからはじまります。","example_meaning":"Sự thiếu tin tưởng giữa bạn bè bắt đầu từ những hiểu lầm nhỏ."}]}]},
{"label":"保険／保健","note":"保険(ほけん): BẢO HIỂM (生命保険, 健康保険, 自動車保険; bồi thường khi gặp rủi ro). 保健(ほけん): BẢO VỆ SỨC KHỎE, y tế dự phòng (保健室, 保健所, 保健の授業).","items":[{"word":"保険","reading":"ほけん","meaning":"bảo hiểm","example":"車を買ったので、自動車保険に入りました。","example_reading":"くるまをかったので、じどうしゃほけんにはいりました。","example_meaning":"Mua xe xong, tôi đã tham gia bảo hiểm ô tô.","examples":[{"example":"日本では、みんなが健康保険に入っています。","example_reading":"にほんでは、みんながけんこうほけんにはいっています。","example_meaning":"Ở Nhật, mọi người đều tham gia bảo hiểm y tế."},{"example":"旅行に行くので、保険をかけました。","example_reading":"りょこうにいくので、ほけんをかけました。","example_meaning":"Vì đi du lịch nên tôi đã mua bảo hiểm."}]},{"word":"保健","reading":"ほけん","meaning":"bảo vệ sức khỏe, y tế dự phòng","example":"気分が悪くなって、保健室で休みました。","example_reading":"きぶんがわるくなって、ほけんしつでやすみました。","example_meaning":"Thấy khó chịu nên tôi đã nghỉ ở phòng y tế.","examples":[{"example":"保健所が、感染症の対策を発表しました。","example_reading":"ほけんじょが、かんせんしょうのたいさくをはっぴょうしました。","example_meaning":"Trung tâm y tế dự phòng đã công bố biện pháp đối phó bệnh truyền nhiễm."},{"example":"学校の保健の授業で、栄養について習いました。","example_reading":"がっこうのほけんのじゅぎょうで、えいようについてならいました。","example_meaning":"Trong giờ giáo dục sức khỏe ở trường, tôi đã học về dinh dưỡng."}]}]},
{"label":"有効／友好","note":"有効(ゆうこう): CÓ HIỆU LỰC, CÓ HIỆU QUẢ (còn dùng được: 有効期限; dùng có ích: 有効に使う). 友好(ゆうこう): HỮU NGHỊ, quan hệ thân thiện giữa người, tổ chức hay quốc gia (友好関係, 友好都市).","items":[{"word":"有効","reading":"ゆうこう","meaning":"có hiệu lực, có hiệu quả","example":"このクーポンは、今月末まで有効です。","example_reading":"このくーぽんは、こんげつまつまでゆうこうです。","example_meaning":"Phiếu giảm giá này có hiệu lực đến cuối tháng.","examples":[{"example":"時間を有効に使うために、計画を立てます。","example_reading":"じかんをゆうこうにつかうために、けいかくをたてます。","example_meaning":"Tôi lập kế hoạch để sử dụng thời gian hiệu quả."},{"example":"パスポートの有効期限が、切れそうです。","example_reading":"ぱすぽーとのゆうこうきげんが、きれそうです。","example_meaning":"Hộ chiếu của tôi sắp hết hạn hiệu lực."}]},{"word":"友好","reading":"ゆうこう","meaning":"hữu nghị, thân thiện","example":"日本とベトナムは、友好的な関係を結んでいます。","example_reading":"にほんとべとなむは、ゆうこうてきなかんけいをむすんでいます。","example_meaning":"Nhật Bản và Việt Nam duy trì quan hệ hữu nghị.","examples":[{"example":"二つの町は、友好都市になりました。","example_reading":"ふたつのまちは、ゆうこうとしになりました。","example_meaning":"Hai thị trấn đã trở thành thành phố kết nghĩa."},{"example":"学生の交流を通して、国の友好を深めます。","example_reading":"がくせいのこうりゅうをとおして、くにのゆうこうをふかめます。","example_meaning":"Thông qua giao lưu sinh viên, hai nước làm sâu sắc thêm tình hữu nghị."}]}]}
]
};
